INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11958, 'plPL', 'Nic nie może się zmarnować', 'Wolvary od zawsze były naszymi naturalnymi wrogami. Ale wtargnięcie waszych ludów na Wielkie Smocze Pustkowia zepchnęło je na niewielki skrawek polany na północy.$B$BDo tego dzisiejszego ranka ziemia się wzburzyła i stały się bardziej agresywne niż kiedykolwiek. Kilka razy napadły na nasze zapasy... rzeczy, których będziemy potrzebować, jeśli mamy przetrwać wędrówkę z naszego domu.$B$BNa znak dobrej woli i przyjaźni odzyskaj nasze towary od wolvarów z Polany Śniegospadu.', 'Odzyskaj od wolvarów 6 skradzionych towarów z Moa\'ki. Zanieś je starszemu Ko\'naniemu w Porcie Moa\'ki.', '', 'Wróć do starszego Ko\'naniego w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(11959, 'plPL', 'Zabij Loguhna', 'Sprawy idą od złego do gorszego. Jest tylko jedna droga... niestety, Loguhn musi zginąć!$B$BTo samiec alfa plemienia z Polany Śniegospadu i wyjątkowo paskudny wolvar. Ale tylko tak zyskamy krótką chwilę wytchnienia od ich napaści i złodziejskich wypadów.$B$B„Rozdzieracza ciał” znajdziesz przed jego norą na północnym wzniesieniu polany. Jest większy od pozostałych, trudno go przeoczyć. Zabij go i posmaruj się jego krwią – na znak zarówno dominacji, jak i szacunku.', 'Posmaruj się krwią Loguhna, a następnie wróć do starszego Ko\'naniego w Porcie Moa\'ki.', '', 'Wróć do starszego Ko\'naniego w Porcie Moa\'ki na Smoczych Pustkowiach.', 'Posmarowano się krwią Loguhna', '', '', '', 0),
(11960, 'plPL', 'Myśląc o przyszłości', 'Musimy zdecydowanie wystąpić przeciw wolvarom, jeśli mamy przetrwać. Obawiam się jednak, że w naszym zapale wybijemy ich zbyt wielu.$B$BWolvary z Polany Śniegospadu mają takie samo prawo do istnienia jak my. Ty i ja dopilnujemy, żeby dostały tę szansę.$B$BJeśli starszy Ko\'nani jeszcze cię o to nie poprosił, na pewno poprosi, żebyś się nimi $gzajął:zajęła;. Kiedy będziesz na polanie na północy, zapakuj do worka ich szczenięta i przynieś mi je.', 'Zbierz 12 szczeniąt z Polany Śniegospadu. Dostarcz je traperowi Mau\'i w Porcie Moa\'ki.', '', 'Wróć do trapera Mau\'i w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(11977, 'plPL', 'Taurenka wśród taunka', '<Wartook wskazuje na północny wschód.>$B$BJest bardzo życzliwa, wiesz? Gdyby nie wasza emisariuszka, ocaleli uchodźcy mogliby stracić nadzieję. Choć nie urodziła się wśród taunka, plemię na razie uznało ją za jedną ze starszych wioski.$B$BJeśli jesteś tym, za kogo cię uważam, odwiedź, proszę, emisariuszkę Jasne Kopyto w obozie uchodźców. Czeka na ciebie.', 'Odszukaj emisariuszkę Jasne Kopyto w Obozie Uchodźców Zachodniego Wiatru.', '', '', '', '', '', '', 0),
(11978, 'plPL', 'W szeregi Hordy', 'Zanim oficjalnie przyjmiemy tych taunka do Hordy, musimy odzyskać nasze uzbrojenie od nerubian Anub\'ar, którzy zalęgli się w pobliskich lasach. Uzbrojenie przepadło, gdy Plaga ostatniej nocy napadła na karawanę z Młota Agmara.$B$BWyrusz do lasów na wschód od Obozu Uchodźców Zachodniego Wiatru i odzyskaj to uzbrojenie, $N.', 'Emisariuszka Jasne Kopyto w Obozie Uchodźców Zachodniego Wiatru na Smoczych Pustkowiach chce, żebyś $godzyskał:odzyskała; 10 sztuk uzbrojenia Hordy.', '', 'Wróć do emisariuszki Jasne Kopyto w Obozie Uchodźców Zachodniego Wiatru na Smoczych Pustkowiach.', '', '', '', '', 0),
(11979, 'plPL', 'Taunka i taureni', 'Plaga przejęła kontrolę nad stolicą taunka, Wioską Lodowej Mgły! Wszyscy żywi taunka, którzy uniknęli rzezi, są pod ochroną w Obozie Uchodźców Zachodniego Wiatru na zachodniej granicy Smoczych Pustkowi.$B$BLord Piekłorycz uważa, że taunka muszą dołączyć do Hordy, jeśli mają przetrwać, i wysłał taureńską emisariuszkę do Zachodniego Wiatru, by umocnić nasze stosunki z zimowymi taurenami. Udaj się do Obozu Uchodźców Zachodniego Wiatru i odszukaj emisariuszkę Jasne Kopyto. Masz jej pomóc.', 'Odszukaj emisariuszkę Jasne Kopyto w Obozie Uchodźców Zachodniego Wiatru.$B', '', '', '', '', '', '', 0),
(11980, 'plPL', 'Duma Hordy', 'Byłem jednym ze strażników wybranych do eskorty karawany, która wiozła do obozu transport uzbrojenia. Atak nastąpił szybko i bez ostrzeżenia. Walczyliśmy i zabiliśmy dziesiątki tych bestii, ale było ich po prostu za dużo. Tor\'zin i ja ledwie uszliśmy z życiem...$B$BGdyby nie nasze rany, sami polowalibyśmy w lesie na te potwory. Pomożesz nam odzyskać utraconą dumę? Przeszukaj lasy na wschód stąd, znajdź nerubian Anub\'ar i zabij ich! Za Hordę!', 'Strażnik krwi Roh\'kill w Obozie Uchodźców Zachodniego Wiatru na Smoczych Pustkowiach chce, żebyś $gzabił:zabiła; 15 napastników Anub\'ar.$B', '', 'Wróć do strażnika krwi Roh\'killa w Obozie Uchodźców Zachodniego Wiatru na Smoczych Pustkowiach.', '', '', '', '', 0),
(11983, 'plPL', 'Krwawa przysięga Hordy', 'Są gotowi, $N. Wszyscy ci taunka z własnej woli dołączą do Hordy i oddadzą wszystko, co mają, by Plaga została przepędzona z tego świata.$B$B<Jasne Kopyto wręcza ci zwój z insygniami Hordy.>$B$BW tym zwoju znajdziesz krwawą przysięgę Hordy. Tradycja nakazuje, by nasi nowi bracia i siostry taunka wypowiedzieli zapisane w nim święte słowa.$B$BWeź zwój i zaprzysięż taunka do Hordy, dowódco. Gdy wypełnisz swój obowiązek, zwróć mi zwój.', 'Porozmawiaj z taunka w Obozie Uchodźców Zachodniego Wiatru i spraw, by 5 z nich przysięgło wierność Hordzie.$B$BGdy wykonasz to zadanie, zwróć krwawą przysięgę Hordy emisariuszce Jasne Kopyto.', '', 'Wróć do emisariuszki Jasne Kopyto w Obozie Uchodźców Zachodniego Wiatru na Smoczych Pustkowiach.', 'Taunka przyjęci do Hordy', '', '', '', 0),
(11995, 'plPL', 'Wzywają cię do Spoczynku Gwiazd', '$N, wiem, że ci kiełzarowie będą cię prosić o wiele przysług, ale musisz jak najszybciej dotrzeć do Spoczynku Gwiazd!$B$BDzisiejszy poranny wstrząs ziemi z pewnością będzie miał szersze skutki niż tylko kłopoty tubylców.$B$BSpoczynek Gwiazd leży na zachód, za skrzyżowaniem z drogą prowadzącą z portu na północ. Jest tam arcymagini imieniem Modera. Będzie na ciebie czekać.', 'Porozmawiaj z wizerunkiem arcymagini Modery w Spoczynku Gwiazd.', '', '', '', '', '', '', 0),
(11996, 'plPL', 'Wzywają cię do Młota Agmara', '$N, wiem, że ci kiełzarowie będą cię prosić o wiele przysług, ale musisz jak najszybciej dotrzeć do Młota Agmara!$B$BDzisiejszy poranny wstrząs ziemi z pewnością będzie miał szersze skutki niż tylko kłopoty tubylców.$B$BMłot leży na zachód, za skrzyżowaniem z drogą prowadzącą z portu na północ. Sam arcymag Aethas Słońcobójca będzie na ciebie czekał!', 'Porozmawiaj z wizerunkiem arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', '', '', '', '', '', 0),
(11999, 'plPL', 'Przeszukaj ciała', 'Ogrody Księżycowego Spoczynku na południowym zachodzie były miejscem wiecznego spoczynku grupy elfów Wysoko Urodzonych. Był tam też węzeł linii mocy.$B$BBłękitne Stado użyło magicznego urządzenia, które nazywają iglicą przypływu, by zniszczyć ten węzeł i uwolnić moc, którą mogą kierować wedle woli.$B$BChcę więcej informacji i ty mi je zdobędziesz!$B$BGdy ziemia w ruinach została zniszczona, duchy Wysoko Urodzonych powstały i wybiły połowę tamtejszych łowców magów. Przeszukaj ich zwłoki w poszukiwaniu wskazówek.', 'Znajdź plany Ogrodów Księżycowego Spoczynku i zanieś je wizerunkowi arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12000, 'plPL', 'Przeszukaj ciała', 'Ogrody Księżycowego Spoczynku na południowym zachodzie były miejscem wiecznego spoczynku szlachetnej grupy elfów Wysoko Urodzonych. Był tam też potężny węzeł linii mocy.$B$BBłękitne Stado użyło magicznego urządzenia, które nazywają iglicą przypływu, by zniszczyć ten węzeł i uwolnić moc, którą mogą kierować wedle woli.$B$BPotrzebuję więcej informacji i mam nadzieję, że mi je zdobędziesz.$B$BPo wstrząsie w ruinach duchy Wysoko Urodzonych powstały i wybiły połowę obecnych tam łowców magów. Przeszukaj ich zwłoki w poszukiwaniu wskazówek.', 'Znajdź plany Ogrodów Księżycowego Spoczynku i zanieś je wizerunkowi arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12004, 'plPL', 'Zapobiec porozumieniu', 'Upieczemy tu dwie pieczenie przy jednym ogniu, $N. Ty jesteś tym ogniem.$B$BNasze dwie pieczenie to handlarz wiatru Mu\'fah i Goramosh. Powinni być gdzieś w zachodniej części Ogrodów Księżycowego Spoczynku. Najpewniej w większym, piętrowym budynku z widokiem na wyrwę.$B$BPotrzebuję dowodu ich śmierci, jeśli łaska.', 'Dostarcz szczątki handlarza wiatru Mu\'faha i łuski Goramosha wizerunkowi arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12005, 'plPL', 'Zapobiec porozumieniu', 'Upieczemy tu dwie pieczenie przy jednym ogniu, $N. Ty jesteś tym ogniem.$B$BNasze dwie pieczenie to handlarz wiatru Mu\'fah i Goramosh. Powinni być gdzieś w zachodniej części Ogrodów Księżycowego Spoczynku. Najpewniej w większym, piętrowym budynku z widokiem na wyrwę.$B$BPotrzebuję dowodu ich śmierci, jeśli łaska.', 'Dostarcz szczątki handlarza wiatru Mu\'faha i łuski Goramosha wizerunkowi arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12006, 'plPL', 'Pomścij tę okropność!', 'Ci tak zwani łowcy magów przybyli tutaj i zniszczyli miejsce naszego spoczynku.$B$BPomścij nas albo dopilnuję, żeby twoją bazę opanowały duchy zmarłych!', 'Zabij w dowolnym połączeniu 15 łowców magów ze Smoczych Pustkowi, tropicieli z Księżycowego Spoczynku, czarowników z Iglicy Przypływu i czarodziejów z ogniska. Następnie wróć do Ethenial Księżycowego Cienia w Ogrodach Księżycowego Spoczynku.', '', 'Wróć do Ethenial Księżycowego Cienia w Ogrodach Księżycowego Spoczynku na Smoczych Pustkowiach.', 'Zabite siły Błękitnego Stada w Ogrodach Księżycowego Spoczynku', '', '', '', 0),
(12008, 'plPL', 'Młot Agmara', 'Dokładnie na wschód od tego obozu uchodźców stoi Młot Agmara – świadectwo potęgi Hordy na Smoczych Pustkowiach.$B$BNie wątpię, że nasi bracia i siostry z Hordy już widzą efekty twoich starań o przyjęcie taunka do Hordy, ale chcę, żebyś osobiście $gprzekazał:przekazała; nadrządcy Agmarowi wieść o swoim sukcesie.$B$BIdź, $N! Prześcignij wiatry! Na wschód, do Młota Agmara!$B', 'Udaj się do Młota Agmara na Smoczych Pustkowiach i porozmawiaj z nadrządcą Agmarem.$B', '', '', '', '', '', '', 0),
(12009, 'plPL', 'Pułapki na kraby Tua\'kei', 'Przez te wszystkie kłopoty straciłem pomocników. Zastanawiałem się, czy może $gmógłbyś:mogłabyś; mi pomóc?$B$BMam w porcie pod falami wiele pułapek na kraby. Wyciągniesz je dla mnie? Jestem już za stary na takie rzeczy, a wody bywają bardzo niebezpieczne.$B$BProszę, weź ten pęcherz. Pomoże ci oddychać tam na dole.', 'Zbierz 8 pułapek na kraby Tua\'kei i zanieś je mu do Portu Moa\'ki.', '', 'Wróć do Tua\'kei w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(12011, 'plPL', 'Oznaki wielkich wodnych kłopotów', 'Wygląda na to, że tę pułapkę na kraby zniszczyło coś znacznie większego niż krążące w pobliżu rekiny.$B$BMoże trzeba o tym powiedzieć Tua\'kei, rybakowi z Portu Moa\'ki?', 'Powiedz Tua\'kei w Porcie Moa\'ki o zniszczonej pułapce na kraby.', '', '', '', '', '', '', 0),
(12013, 'plPL', 'Koniec Arcanimusa', 'Mam dla ciebie ostatnie zadanie, $N. Zniszcz Arcanimusa!$B$BCzarownicy na zachodzie użyli tego olbrzymiego urządzenia na niebie, by wywiercić ogromną wyrwę w miejscu naszego spoczynku. W ten sposób uwolnili potworność!$B$BNie obchodziłoby mnie to, gdyby zagrażała tylko śmiertelnikom, ale Arcanimus żywi się duchami zmarłych.$B$BPołożysz temu kres, i to teraz!', 'Zniszcz Arcanimusa, a następnie wróć do Ethenial Księżycowego Cienia w Ogrodach Księżycowego Spoczynku.', '', 'Wróć do Ethenial Księżycowego Cienia w Ogrodach Księżycowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12016, 'plPL', 'Przynęta', 'Jestem tego pewien... nasz odwieczny wodny wróg, Tu\'u\'gwar, „Ten, Który Bawi się Jedzeniem”, powrócił. Musimy zastawić na niego pułapkę, ty i ja.$B$BJeśli Tu\'u\'gwar ma jakąś słabość, to swój żołądek. Jest jedno mięso, obok którego na pewno nie przejdzie obojętnie.$B$B„Dwa Wielkie Szczypce”, matka wszystkich krabów, Kili\'ua, przechadza się po swojej wyspie na wodach na południowym zachodzie. Musisz złożyć jej wizytę i wrócić z jej mięsem.', 'Zdobądź mięso „Dwóch Wielkich Szczypiec” i dostarcz je Tua\'kei w Porcie Moa\'ki.', '', 'Wróć do Tua\'kei w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(12017, 'plPL', 'Mięso na haczyku', 'Nadszedł czas, przyjacielu: trzeba rozprawić się z Tu\'u\'gwarem!$B$BPrzygotowałem mięso tak, że bestia na pewno przypłynie, gdy tylko założysz przynętę na hak, który mam w wodzie. Po prostu zejdź do niego wzdłuż żyłki.$B$BCokolwiek zrobisz, nie daj się Tu\'u\'gwarowi połknąć w całości, $N!', 'Zabij Tu\'u\'gwara, a następnie wróć do Tua\'kei w Porcie Moa\'ki.', '', 'Wróć do Tua\'kei w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(12018, 'plPL', 'Słodka zemsta', 'Hej, ty... wyglądasz na kogoś, kto lubi walczyć. Chcę słodkiej zemsty na Pladze, która zabiła moją rodzinę. Przynieś mi 2 kamienne kawały gargulca, żebym mógł rzucić je na ziemię i deptać je wściekle, aż rozpadną się na malusieńkie kamyczkowe okruszki.$b$bTak. Idź. Zabijaj.', 'Zdobądź 2 kamienne kawały gargulca od padlinowych gargulców we wschodniej części Pól Padliny. Po wykonaniu zadania wróć do lorda Bevisa.', '', '', '', '', '', '', 0),
(12021, 'plPL', 'List do domu', 'Wygląda na to, że ten list jest zaadresowany do mieszkańca Wichrogrodu przez jednego z nieżyjących już wieśniaków z Pól Padliny. Może któryś z ocalałych mieszkańców we wschodnim obozie zechce przekazać go adresatowi.', 'Zanieś list lady Alustrze we wschodniej części Pól Padliny.', '', '', '', '', '', '', 0),
(12023, 'plPL', 'Słodsza zemsta', 'Przyjemnie chrupiące. A teraz... ty... jakiś tam... na zboczu na południu kręci się plugastwo. Idź je zabić. Zabij je porządnie.', 'Zabij plugastwo na zboczu we wschodniej części Pól Padliny. Gdy rzeź dobiegnie końca, wróć do lorda Bevisa.', '', '', '', '', '', '', 0),
(12024, 'plPL', 'Spis poległych', 'Dziękuję, że $gprzyszedłeś:przyszłaś;, $N. Nie dostaliśmy żadnych wieści z Twierdzy Zimowej Straży. Jestem pewna, że wciąż walczą z Plagą, ale nie mogę uwierzyć, że zostawili nas samych na tę rzeź.$b$bMusimy zebrać imiona zmarłych, żeby powiadomić ich rodziny. Kiedy wojsko Przymierza nas tu przywiozło, wszyscy wypełniliśmy dokumenty osiedleńcze i musieliśmy nosić je przy sobie.$b$bPrzeszukaj zwłoki i przynieś mi wszystkie dokumenty, jakie znajdziesz, żebym mogła zacząć spisywać imiona.', 'Przeszukaj szkielety na Polach Padliny w poszukiwaniu dokumentów osiedleńczych Przymierza.', '', '', '', '', '', '', 0),
(12025, 'plPL', 'Szkarłatny wśród nas', 'Dobrze widzieć, że i ciebie nie zmasakrowała Plaga. Może zechcesz nam pomóc.$b$bSzkarłatna Krucjata zajęła posterunek na północy z oczywistym zamiarem walki z Plagą. Martwi mnie jednak to, że budowali go, zanim nas zaatakowano – musieli coś wiedzieć.$b$bMuszę się dowiedzieć, czy był w to zamieszany ktoś z naszych wieśniaków. Poszukaj dowodów przy tych z nas, których przywrócono do życia jako ghule. Jeśli coś znajdziesz, przynieś mi to.', 'Poszukaj dowodów powiązań ze Szkarłatną Krucjatą przy świeżo powstałych padlinowych ghulach we wschodniej części Pól Padliny. Wróć do lady Alustry ze wszystkim, co znajdziesz.', '', '', '', '', '', '', 0),
(12028, 'plPL', 'Duchowy wgląd', '$N, nie mamy wieści od naszych ludzi z Wioski Indu\'le, odkąd ziemia zadrżała i się rozstąpiła!$B$BCzy $gbyłeś:byłaś; kiedyś na duchowej wędrówce? $GPokonałeś:Pokonałaś; Loguhna, więc musisz dać sobie radę.$B$BDam ci specjalne kadzidło, które wsypiesz do mojego koksownika. Wdychaj głęboko jego opary, a twój duch wzniesie się w górę, by zobaczyć, co się stało w Indu\'le.$B$BGdy twój duch będzie szybował, będę mógł patrzeć twoimi oczami.', 'Gdy uzyskasz duchowy wgląd, porozmawiaj z Toalu\'u Mistykiem w Porcie Moa\'ki.', 'Uzyskano duchowy wgląd w sprawie Wioski Indu\'le.', 'Wróć do Toalu\'u Mistyka w Porcie Moa\'ki na Smoczych Pustkowiach.', '', '', '', '', 0),
(12030, 'plPL', 'Starszy Mana\'loa', 'Mój lud...$B$B<Mistyk jest bliski załamania.>$B$BGdy twój duch przelatywał nad wioską, wyczułem, że starszy Mana\'loa cię zauważył. $N, on chce z tobą porozmawiać. Czcimy kamiennych starszych jako źródła pradawnej mądrości.$B$BStarszy musi chcieć pomóc. Szukaj go w północno-zachodnim krańcu wioski.', 'Porozmawiaj z posągiem starszego Mana\'loi w Wiosce Indu\'le.', '', '', '', '', '', '', 0),
(12031, 'plPL', 'Wolność dla zagubionych', 'Święta ziemia elfów na zachodzie została rozdarta. Teraz ich magia płynie przez krainę i sieje zniszczenie wszędzie, dokąd dotrze.$B$BDusze Kalu\'ak są w niebezpieczeństwie, bo siły błękitnych smoków próbują zapanować nad tą magią.$B$BMoc wydobyła się przez jezioro i w jednej chwili zabiła większość mieszkańców wioski. Ci, którzy przeżyli, postradali zmysły.$B$B$N, musisz uwolnić te duchy, by mogły odejść. Oszalałych żywych zostaw w spokoju – z czasem mogą jeszcze odzyskać rozum.', 'Ukój w dowolnym połączeniu 15 rybaków, mistyków i wojowników z Indu\'le, a następnie wróć do starszego Mana\'loi w Wiosce Indu\'le.', '', 'Wróć do starszego Mana\'loi w Wiosce Indu\'le na Smoczych Pustkowiach.', 'Ukojone duchy z Indu\'le', '', '', '', 0),
(12032, 'plPL', 'Rozmowa z głębinami', 'Trzeba zasięgnąć rady wodnej bogini Oacha\'noi; tylko ona będzie wiedziała, jakie przeznaczenie czeka Kalu\'ak. A wezwać ją z mrocznych otchłani może tylko Perła Głębin.$B$BU wybrzeża, na południowym zachodzie, wznosi się Słony Szczyt. Na jego wierzchołku stoi ołtarz, na którym spoczywa perła.$B$BObcuj z ołtarzem, a Oacha\'noa na pewno usłyszy twoje wezwanie. Rób, co ci każe, bo inaczej ściągniesz na siebie jej gniew i zgubę na wszystkich kiełzarów.$B$BJeśli przeżyjesz, wróć do mistyka.', 'Obcuj z Perłą Głębin i wykonaj polecenia bogini morza Oacha\'noi.$B$BJeśli przetrwasz tę próbę, wróć do Toalu\'u Mistyka w Porcie Moa\'ki.', '', 'Wróć do Toalu\'u Mistyka w Porcie Moa\'ki na Smoczych Pustkowiach.', 'Spełniono wolę Oacha\'noi', '', '', '', 0),
(12033, 'plPL', 'Wiadomość z zachodu', '<Torvus ściska ci dłoń i przy okazji wręcza list.>$B$B<Torvus mówi półgłosem.>$B$BGraj dalej, $N.$B$BDobrze cię tu widzieć, żołnierzu! Lord Piekłorycz z pewnością wysłał do lorda Agmara swoich najsilniejszych wojowników!$B$B<Torvus mówi półgłosem.>$B$BPrzeczytaj go, a potem zniszcz w palenisku obok mnie.', 'Przeczytaj list od Zaurzykła, a następnie go zniszcz.$B$BGdy wykonasz to zadanie, porozmawiaj z posłańcem Torvusem.', 'List od Zaurzykła przeczytany i zniszczony', 'Porozmawiaj z posłańcem Torvusem w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12034, 'plPL', 'Zwycięstwo jest blisko...', 'Na naszej drodze stoją już tylko dwa główne zagrożenia. Jednym jest mroczna cytadela Naxxramas daleko na wschodzie, nad twierdzą Przymierza w Zimowej Straży, a drugim Czeluść Narjun, przez którą wychodzą nieumarłe armie Azjol-Nerub. To z Czeluści Narjun nerubianie Anub\'ar zaatakowali i ostatecznie zrównali z ziemią Wioskę Lodowej Mgły, osadę taunka.$B$BZniszczymy Anub\'ar i zamkniemy Czeluść Narjun.$B$BZgłoś się do starszego sierżanta Juktoka po rozkazy.', 'Porozmawiaj ze starszym sierżantem Juktokiem w Młocie Agmara.', '', '', '', '', '', '', 0),
(12036, 'plPL', 'Z głębin Azjol-Nerub', 'Nieumarli nerubianie, którzy zaatakowali Wioskę Lodowej Mgły, przyszli z gigantycznego zapadliska zwanego Czeluścią Narjun. Jeśli zostawimy te potwory w spokoju, z pewnością zajdą nasze siły pod Bramą Gniewu od flanki i zakończą nasz marsz ku zwycięstwu.$B$BPotrzebuję oczu na miejscu, $N. Udasz się na zachód i zbadasz Czeluść Narjun. Musimy znaleźć ich główne wyjście i je zamknąć! Znajdź mi to miejsce.$B', 'Zbadaj Czeluść Narjun i wróć ze swoimi ustaleniami do starszego sierżanta Juktoka w Młocie Agmara.', 'Zbadano Czeluść Narjun', 'Wróć do starszego sierżanta Juktoka w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12039, 'plPL', 'Czarna krew Yogg-Sarona', 'Angrathar, Brama Gniewu... Widziałem, jak metal, który spaja bramę, pulsuje i faluje, jakby był żywy! Przez 50 lat nie widziałem, żeby metal „oddychał”.$B$BJedyni, którzy coś o tym wiedzieli, to kiełzarowie. Nazywali to „czarną krwią Yogg-Sarona” i kazali mi trzymać się z daleka.$B$BZa Wioską Lodowej Mgły, na zachodzie, jest zapadlisko zwane Czeluścią Narjun. Słyszałem, że takie zapadliska obfitują w tę dziwną rudę. Jeśli będziesz w tamtych stronach, spróbujesz zdobyć dla mnie trochę próbek?', 'Borus Żelazogięt w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gzdobył:zdobyła; 10 próbek czarnej krwi Yogg-Sarona.', '', 'Wróć do Borusa Żelazogięta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12040, 'plPL', 'Wspólny wróg – Arthas', 'Toczy się wojna domowa. W sercu tego świata ostatni żyjący przedstawiciele mojego gatunku bronią się przed całkowitą zagładą. Król Lisz za wszelką cenę chce zawładnąć królestwem Azjol-Nerub. Ci, którzy się nie podporządkują, zostają okrzyknięci wrogami Plagi i skazani na śmierć.$B$BW Arthasie obaj mamy wroga...$B$BPrzyłącz się do naszej sprawy i oczyść to miejsce ze skazy Anub\'ar! Niech sam Anub\'arak usłyszy udrękę w ich śmiertelnych krzykach!', 'Kilix Rozplatacz w Czeluści Narjun na Smoczych Pustkowiach prosi, żebyś $gzabił:zabiła; 6 podziemnych władców Anub\'ar.$B', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', '', '', '', '', 0),
(12041, 'plPL', 'Utracone imperium', '$GUdowodniłeś:Udowodniłaś;, że chcesz wspierać Imperium Azjol w godzinie potrzeby, a zatem Imperium Azjol wesprze Hordę.$B$BZanieś ten zwój swojemu przywódcy. Opisuje mocne i słabe strony nerubian atakujących Wioskę Lodowej Mgły. Uznaj go za gest dobrej woli – dowód gotowości do pomocy twojemu ludowi. Wykorzystaj wiedzę z tych stron, by zmiażdżyć Anub\'ar, a oddasz przysługę nam wszystkim.$B$BBywaj, $N.$B', 'Dostarcz plan bitwy Kilixa nadrządcy Agmarowi w Młocie Agmara na wschodzie.', '', 'Wróć do nadrządcy Agmara w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12043, 'plPL', 'Obrona Rdzawej Dyszy', 'Ej, $N! Ci nieumarli na południe od nas bez przerwy przeszkadzają nam w robocie. Idź ich wykurzyć, co?', 'Zabij 12 kopaczy z pustkowi i 1 nadzorcę z pustkowi na wykopaliskach wokół Spoczynku Galakronda. Po wykonaniu zadania wróć do Narfa na Posterunku Rdzawej Dyszy.', '', 'Wróć do Narfa na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12044, 'plPL', 'Robimy zapasy', 'Witam, witam! Plaga na południu wykopuje jakieś starożytne smocze coś. Mało mnie obchodzi, po co to robią, ale przy okazji wywożą całe wózki rudy kompozytowej.$b$bIdź i podwędź mi sporo tej rudy. Przy całej tej broni, którą wykuwa Horda, powinna przynieść niezłą sumkę.$B', 'Zbierz 8 porcji rudy kompozytowej na wykopaliskach wokół Spoczynku Galakronda i przynieś je Xinkowi na Posterunek Rdzawej Dyszy.', '', 'Wróć do Xinka na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12045, 'plPL', 'Lodowe wiórki', 'Nigdy wcześniej cię nie widziałam... jesteś w Imadle $gnowy:nowa;? Miło cię widzieć. Przyda mi się każda para rąk.$b$bTy zdobędziesz materiały, ja skończę swoją maszynę, a potem sprzedamy ją tym dowódcom i wszyscy wrócimy do domu bogaci.$b$bWłaściwie mam już większość głównych podzespołów, potrzebuję tylko trochę materiałów na samą broń. Narf mówił, że poszarpane lodowe odłamki z tych żywiołaków na północy będą idealnymi odłamkami do moich bomb – idź i skombinuj trochę, co?$B', 'Zbierz 4 wiązki lodowych odłamków od lodowych żywiołaków na północy i przynieś je Zivlix na Posterunek Rdzawej Dyszy.', '', 'Wróć do Zivlix na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12046, 'plPL', 'Miękkie opakowanie', 'Potrzebuję nowego opakowania na bomby odłamkowe. Wszystko, co mam, jest za twarde i odłamki nie rozpryskują się przy wybuchu.$b$bPotrzebujemy naprawdę cienkiej zwierzęcej skóry. Może się nadać skóra jormungarów tunelarzy na zachodzie... albo kondorów grzebiących w smoczych kościach. Przynieś mi, co tylko znajdziesz.$B', 'Zbierz 12 cienkich skór zwierzęcych z jormungarów tunelarzy lub kondorów ze smoczych kości w pobliżu Posterunku Rdzawej Dyszy. Gdy zdobędziesz skóry, zanieś je Zivlix.', '', 'Wróć do Zivlix na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12047, 'plPL', 'Coś, co się nie topi', 'Nie, nie, nie! Te lodowe odłamki w ogóle się nie sprawdziły! Stopią się, zanim w ogóle zrobią jakąś szkodę. Ostatni raz ufam Narfowi w sprawie materiałów. To znaczy, że na odłamki potrzebujemy czegoś zupełnie innego.$b$bWiem! Jestem genialna. Drzazgi z kości.$b$bWszędzie tu leżą kości, które jormungary porządnie obgryzły. Idź je obejrzeć i sprawdź, czy znajdziesz mi jakieś odłamane kawały kości, których mogłabym użyć.', 'Przeszukaj smocze kości na wschód od Posterunku Rdzawej Dyszy i znajdź 12 odłamanych kawałów kości.', '', 'Wróć do Zivlix na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12048, 'plPL', 'Uzbrojenie Plagi', 'Nic nie mogę zrobić z tej przeklętej rudy. Po prostu się nie trzyma! Mimo moich najlepszych starań metal Plagi nie chce się giąć!$B$BGdybym miał próbki wykutego uzbrojenia Plagi, może udałoby mi się odtworzyć proces, w którym powstają te przedmioty.$B$BW Wiosce Lodowej Mgły roi się od opancerzonych nerubian Plagi. Idź tam i zdobądź dla mnie uzbrojenie Plagi! Z twoją pomocą może naprawdę uda mi się coś stworzyć z tej rudy.$B$BWioskę Lodowej Mgły znajdziesz na zachodzie.', 'Borus Żelazogięt w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gprzyniósł:przyniosła; mu 8 sztuk uzbrojenia Plagi.', '', 'Wróć do Borusa Żelazogięta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12049, 'plPL', 'Ciężkie do przełknięcia', 'Te oddziały na pewno potrzebują solidnych zapasów jedzenia w brzuchach.$B$BZdradzę ci mały sekret, o którym ktoś tak wybredny jak ty nigdy by się nie dowiedział... te robale jormungary smakują zupełnie jak kurczak.$b$bIdź i sprowokuj jednego z tych olbrzymich, potężnych jormungarów na wschodzie. Raczej nie zabijesz go od razu, więc po prostu wrzuć mu to do gardła, kiedy szeroko otworzy paszczę. Przynieś mi tyle płatów mięsa, ile zdołasz udźwignąć.', 'Walcz z potężnym jormungarem na wschód od Posterunku Rdzawej Dyszy, aż otworzy paszczę, a wtedy wrzuć mu do gardła silny ładunek wybuchowy. Gdy wybuchnie, zbierz z ziemi 6 płatów przypieczonego mięsa jormungara i zanieś je Xinkowi.', '', 'Wróć do Xinka na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12050, 'plPL', 'Wyrąb po goblińsku', 'Teraz musimy nazwozić trochę drewna na te wszystkie wieże, które buduje Przymierze. Na południu rosną jakieś cienkie drzewa, ale te, na których gnieżdżą się harpie na północy, wyglądają na znacznie lepsze do budowy.$b$bWeź to. Kiedy dotrzesz do lęgowisk harpii, użyj sterownika, a jeden z moich rozdrabniaczy powinien do ciebie przyjść. Zbierz tyle drewna, ile zdoła unieść. Harpie na pewno nie będą zachwycone, że ścinasz ich domy – po prostu rozpraw się z nimi, jak trzeba.$b$bDo roboty!', 'Gdy dotrzesz do Lęgowisk Harpii na północy, użyj urządzenia sterującego rozdrabniaczem Xinka, by przywołać rozdrabniacz. Zbierz 50 wiązek drewna z tamtejszych drzew, a następnie wróć do Xinka na Posterunek Rdzawej Dyszy.$B$BJeśli zgubisz urządzenie sterujące rozdrabniaczem Xinka, porozmawiaj z Xinkiem na Posterunku Rdzawej Dyszy, by dostać nowe.', '', 'Wróć do Xinka na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', '', '', '', 0),
(12051, 'plPL', 'Nastroszone pióra', 'Te harpie dość już uszczupliły nasze zyski! Zabij je wszystkie.', 'Zabij 20 harpii na północny zachód od Posterunku Rdzawej Dyszy dla Narfa z Posterunku Rdzawej Dyszy.', '', 'Wróć do Narfa na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', 'Harpie Zimnego Wiatru', '', '', '', 0),
(12052, 'plPL', 'Harpiom na pohybel!', '$N, widzisz to? To harpia, która prowadzi ataki na nasze transporty do bramy! Widziałem ją już w głębi Wyżyn Zimnego Wiatru.$B$BTe harpie dość już uszczupliły nasze zyski! Zabij je wszystkie.', 'Zabij Panią Zimnego Wiatru i 15 harpii Zimnego Wiatru w górach na północny zachód od Posterunku Rdzawej Dyszy. Po wykonaniu zadania wróć do Narfa.$B$BJeśli potrzebujesz urządzenia sterującego rozdrabniaczem Xinka, porozmawiaj z Xinkiem na Posterunku Rdzawej Dyszy.', '', 'Wróć do Narfa na Posterunku Rdzawej Dyszy na Smoczych Pustkowiach.', '', 'Harpie Zimnego Wiatru', '', '', 0),
(12053, 'plPL', 'Potęga Hordy', 'Taunka są teraz naszymi towarzyszami broni. Musimy okazać solidarność i odbić Wioskę Lodowej Mgły.$B$BWioskę Lodowej Mgły znajdziesz na zachód od Młota Agmara, u podnóża gór. Udaj się tam i rzuć wyzwanie nerubianom Anub\'ar! Zatknij nasz ukochany sztandar Hordy w Wiosce Lodowej Mgły i zniszcz wszystkich, którzy ośmielą się go zerwać!$B$BNiech Anub\'ar poczują prawdziwą potęgę Hordy! Niech nasz sztandar bojowy będzie ostatnią rzeczą, jaką zobaczą przed śmiercią!', 'Starszy sierżant Juktok w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gużył:użyła; sztandaru bojowego Wojennej Pieśni w Wiosce Lodowej Mgły i $gobronił:obroniła; go przed napastnikami.$B$BPo wszystkim zwróć sztandar bojowy Wojennej Pieśni.', 'Sztandar bojowy Wojennej Pieśni obroniony', 'Wróć do starszego sierżanta Juktoka w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12055, 'plPL', 'Dziwne urządzenie', 'Gdy podnosisz to dziwne urządzenie, masz pewność, że jest magiczne. Niestety, nic nie wskazuje na to, do czego służy.$B$BMoże arcymagini w Spoczynku Gwiazd, na wschód od Ogrodów Księżycowego Spoczynku, potrafiłaby powiedzieć, do czego się go używa?', 'Dostarcz dziwne urządzenie Goramosha wizerunkowi arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12056, 'plPL', 'Znamię śmierci: arcykultysta Zangus', 'Widziałem jego zdradę na własne oczy! Ten zdrajca poprowadził atak Anub\'ar na tę twierdzę i wybił kilku moich najlepszych żołnierzy.$B$B<Gort kręci głową.>$B$BCały czas współpracował z Plagą, a my nie mieliśmy o tym pojęcia! Ilu jeszcze takich jak Zangus jest wśród nas? Znajdziemy ich wszystkich, a kiedy już znajdziemy...$B$B<Gort przeciąga palcem po szyi.>$B$BPierwszy na liście jest Zangus. Nasi zwiadowcy donoszą, że ukrywa się w Czeluści Narjun, na zachód stąd. Znajdź go, zabij i przynieś mi jego głowę.$B', 'Zabij arcykultystę Zangusa i zanieś jego głowę kapitanowi Gortowi w Młocie Agmara na Smoczych Pustkowiach.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12057, 'plPL', 'Księga w oprawie z ciała', 'Księga jest oprawiona w ciało i wygląda, jakby krwawiła. Przeglądając ją, odkrywasz strona za stroną dziwne symbole, które wydają się zapisane krwią.$B$BWiedza ukryta na stronach tej księgi może być ważna. Zanieś ją kapitanowi Gortowi w Młocie Agmara, na wschód od Wioski Lodowej Mgły.', 'Zanieś księgę w oprawie z ciała kapitanowi Gortowi w Młocie Agmara.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12059, 'plPL', 'Dziwne urządzenie', 'Gdy podnosisz to dziwne urządzenie, masz pewność, że jest magiczne. Niestety, nic nie wskazuje na to, do czego służy.$B$BMoże arcymag w Młocie Agmara, na północny wschód od Ogrodów Księżycowego Spoczynku, potrafiłby powiedzieć, do czego się go używa?', 'Dostarcz dziwne urządzenie Goramosha wizerunkowi arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12060, 'plPL', 'Projekcje i plany', 'To urządzenie teleportacyjne. Gdybym miała zgadywać, powiedziałabym, że prowadzi na platformę iglicy przypływu, która unosi się nad Ogrodami Księżycowego Spoczynku na zachodzie.$B$BUżyj go, żeby sprawdzić, co jest tam na górze. Wygląda na to, że urządzenie działa w obie strony, więc nie powinno być potrzeby skakać.$B$BSpodziewam się, że gdy przeniesiesz się na szczyt iglicy przypływu, znajdziesz tam jakąś aparaturę, której trzeba się przyjrzeć.$B$BTeleportu powinno dać się użyć z dowolnego miejsca w ogrodach.', 'Podejdź blisko i przyjrzyj się projekcji na szczycie Iglicy Przypływu unoszącej się nad Ogrodami Księżycowego Spoczynku.$B$BNastępnie wróć z tymi informacjami do wizerunku arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Obiekt na Iglicy Przypływu zbadany', '', '', '', 0),
(12061, 'plPL', 'Projekcje i plany', 'To urządzenie teleportacyjne. Gdybym miał zgadywać, powiedziałbym, że prowadzi na platformę iglicy przypływu, która unosi się nad Ogrodami Księżycowego Spoczynku na południowym zachodzie.$B$B$N, użyj go, żeby sprawdzić, co jest tam na górze. Wygląda na to, że urządzenie działa w obie strony, więc nie powinno być potrzeby skakać.$B$BSpodziewam się, że gdy przeniesiesz się na szczyt iglicy przypływu, znajdziesz tam jakąś aparaturę, której trzeba się przyjrzeć.$B$BTeleportu powinno dać się użyć z dowolnego miejsca w ogrodach.', 'Podejdź blisko i przyjrzyj się projekcji na szczycie Iglicy Przypływu unoszącej się nad Ogrodami Księżycowego Spoczynku.$B$BNastępnie wróć z tymi informacjami do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', 'Obiekt na Iglicy Przypływu zbadany', '', '', '', 0),
(12063, 'plPL', 'Siła Lodowej Mgły', '<Wszechmatka Lodowa Mgła kłania się.>$B$BTo zaszczyt cię poznać, bohaterze. To dzięki tobie wielu z nas jest teraz tutaj, żywych i gotowych do walki z Plagą.$B$BTak wiele dla nas $gzrobiłeś:zrobiłaś;, że wstyd mi znów prosić cię o pomoc. Mimo moich błagań mój jedyny syn, Banthok, odszedł stąd, by szukać swojego ojca, najwyższego wodza Lodowej Mgły. Ostatnio widziano go, jak szedł na zachód, w stronę Wioski Lodowej Mgły. Proszę, odnajdź Banthoka. Nie wiem, co bym zrobiła, gdybym straciła syna.', 'Odnajdź Banthoka Lodową Mgłę w Wiosce Lodowej Mgły.', '', '', '', '', '', '', 0),
(12064, 'plPL', 'Łańcuchy Anub\'ar', 'Trzymają mojego ojca w magicznych łańcuchach pośrodku Wioski Lodowej Mgły. Z tego, czego zdołałem się dowiedzieć, więzieniem władają trzej potężni magowie Anub\'ar – każdy ma fragment klucza.$B$BPrzeszukaj Wioskę Lodowej Mgły i znajdź tych magów. Zabij ich i zabierz im fragmenty klucza. Mając wszystkie trzy, może zdołamy uwolnić mojego ojca. A gdy już będzie wolny...$B$BOdwet nadejdzie szybko.', 'Banthok Lodowa Mgła w Wiosce Lodowej Mgły na Smoczych Pustkowiach prosi, żebyś $gprzyniósł:przyniosła; mu fragment klucza Anok\'ry, fragment klucza Tivaxa i fragment klucza Sinoka.$B', '', 'Wróć do Banthoka Lodowej Mgły w Wiosce Lodowej Mgły na Smoczych Pustkowiach.', '', '', '', '', 0),
(12065, 'plPL', 'Ognisko na plaży', 'Siły łowców magów działają na Lśniącym Wybrzeżu, na południe od Ogrodów Księżycowego Spoczynku. Zgaduję, że znajdziesz na plaży pilnie strzeżone ognisko i kapitana, który nim dowodzi.$B$BKapitan z pewnością ma przy sobie jakieś urządzenie sterujące. Zdobądź je i użyj go na ognisku.$B$BJeśli dopisze nam szczęście, dowiemy się więcej o tym, co tam naprawdę knują.', 'Zdobądź pierścień kontroli ogniska linii mocy i użyj go, by uzyskać informacje z ogniska linii mocy na Lśniącym Wybrzeżu.$B$BNastępnie wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', '', '', '', 0),
(12066, 'plPL', 'Ognisko na plaży', 'Siły łowców magów działają na Lśniącym Wybrzeżu, na południe od Ogrodów Księżycowego Spoczynku. Zgaduję, że znajdziesz na plaży pilnie strzeżone ognisko i kapitana, który nim dowodzi.$B$BKapitan tamtejszych sił z pewnością ma przy sobie jakieś urządzenie sterujące. Zdobądź je i użyj go na ognisku.$B$BJeśli wykażesz się choć odrobiną umiejętności, dowiemy się więcej o tym, co tam naprawdę knują.', 'Zdobądź pierścień kontroli ogniska linii mocy i użyj go, by uzyskać informacje z ogniska linii mocy na Lśniącym Wybrzeżu.$B$BNastępnie wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', '', '', '', 0),
(12067, 'plPL', 'List do domu', 'W podszewce jej szaty znajdujesz ukryty list. Brzmi on:$B$B„Tato,$B$Bprzepraszam, że tak zniknęłam. Jeśli czytasz ten list, to znaczy, że nie żyję.$B$BZmuszono mnie do pracy dla armii Malygosa pod groźbą, że jeśli odmówię, zabiją naszą rodzinę. Tak bardzo się wstydzę.$B$BJeśli możesz cokolwiek zrobić, by z nimi walczyć, nie martw się o mnie. Oszukuję ich i sabotuję ich działania od środka.$B$BKocham cię, tatusiu!$B$BEm”$B$BKomendantka Saia Lazurowa Stal musi to zobaczyć!', 'Dostarcz list kapitan Malin komendantce Sai Lazurowej Stali w Spoczynku Gwiazd.', '', 'Wróć do komendantki Sai Lazurowej Stali w Lasach Lothalor na Smoczych Pustkowiach.', '', '', '', '', 0),
(12069, 'plPL', 'Powrót najwyższego wodza', '<Banthok wręcza ci klucz do więzienia.>$B$BMusisz się spieszyć, $N. Weź klucz i użyj go, by uwolnić mojego ojca z łańcuchów więzienia Anub\'ar. Gdy będzie wolny, pomóż mu zniszczyć przywódcę Anub\'ar, Podziemnego Króla Anub\'et\'kana. Gdy Podziemny Król padnie, odłup kawałek jego chitynowego pancerza jako trofeum dla Hordy w Młocie Agmara. Niech Agmar ujrzy potęgę najwyższego wodza!', 'Uwolnij najwyższego wodza Lodową Mgłę za pomocą klucza do Więzienia Anub\'ar i pomóż mu pokonać Podziemnego Króla Anub\'et\'kana.$B$BZdobądź fragment pancerza Anub\'et\'kana i zanieś go nadrządcy Agmarowi w Młocie Agmara na Smoczych Pustkowiach.', '', 'Wróć do nadrządcy Agmara w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12071, 'plPL', 'Atak z powietrza! ', 'Poznali potęgę Hordy na lądzie, teraz muszą ją poczuć z powietrza! Masz natychmiast zgłosić się do Valnoka Wściekłego Wichru! Znajdziesz go tutaj, w Młocie Agmara.$B$BValnok został już poinformowany o twojej misji i czeka na ciebie.$B', 'Porozmawiaj z Valnokiem Wściekłym Wichrem w Młocie Agmara.', '', '', '', '', '', '', 0),
(12072, 'plPL', 'Do diabła z plagobestiami!', 'Na pewno $gwidziałeś:widziałaś; armię plagobestii Anub\'ar, którą budują w Wiosce Lodowej Mgły. Anub\'ar zamierzają wysłać te potwory przeciw naszym żołnierzom pod Bramą Gniewu. Do tego nie może dojść!$B$BWyrusz na zachód do Wioski Lodowej Mgły z tą rakietnicą i użyj jej, by przywołać jednego z moich jeźdźców wojennych. Wsiądź mu na grzbiet i każ mu zniszczyć plagobestie, których nie da się dosięgnąć z ziemi!$B$BGdy przetrzebisz ich siły powietrzne, wróć do mnie po nagrodę!', 'Użyj rakietnicy Valnoka, by przywołać jeźdźca wojennego Kor\'kronu w Wiosce Lodowej Mgły. Dosiądź jeźdźca wojennego Kor\'kronu i zabij z jego pomocą 25 plagobestii Anub\'ar!$B$BPo wykonaniu misji wróć do Valnoka Wściekłego Wichru w Młocie Agmara.', '', 'Wróć do Valnoka Wściekłego Wichru w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12075, 'plPL', 'Marne resztki', 'Zimno tu, prawda, $N?$B$BKo\'char odmówił spotkania ze mną. Wygląda na to, że ma na głowie pilniejsze sprawy – a mianowicie jormungary, które atakują jego ludzi z pieczary poniżej. Może pomożesz mi przekonać Ko\'chara, że jestem po dobrej stronie?$b$bWidziałem, jak kilka tych robali pożerało olbrzyma przy wejściu do pieczary na północ stąd... Wciąż nie rozumiem, jak te robale tak łatwo je zabijają. Przynieś mi próbkę z jednej z jego ran.', 'Zbierz próbkę skalnego ciała ze zwłok lodowego olbrzyma przy wejściu do pieczary w Kryształowym Imadle, na północ od miejsca, gdzie stoi Zort. Po wykonaniu tego zadania wróć do Zorta w pobliżu środka kanionu.', '', 'Wróć do Zorta w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12076, 'plPL', 'Paskudna robota', 'Już na pierwszy rzut oka próbka, którą $gprzyniosłeś:przyniosłaś;, nosi wyraźne ślady jakiejś żrącej śliny. Można by przypuszczać, że ta sama substancja, której te robale używają do drążenia ziemi, daje im groźną broń przeciw lodowym olbrzymom.$b$bWeź ten skrobak i wdaj się w walkę z kilkoma robalami. Kiedy na ciebie plują, zeskrob to skrobakiem i przynieś mi.$B$BZdobądź dla mnie kilka próbek – użyję jej jako bazy do eliksiru.', 'Zbierz 2 fiolki żrącej śliny jormungarów, używając skrobaka na sobie. Po wykonaniu zadania zanieś fiolki Zortowi w Kryształowym Imadle.', '', 'Wróć do Zorta w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12077, 'plPL', 'Stosować dwa razy dziennie', 'Ten eliksir powinien chronić przed ich śliną. Zaoferuj go ode mnie Ko\'charowi, dobrze? Powiedz mu, że mam tego znacznie więcej, jeśli odwdzięczy się przysługą.', 'Zaoferuj eliksir przygotowany przez Zorta Ko\'charowi Niezłomnemu.', '', 'Wróć do Ko\'chara Niezłomnego w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12078, 'plPL', 'Poskramiacz robali', 'Niech będzie. Skoro olbrzymy nie przyjdą nam z pomocą, może zrobimy użytek z tych robali. Na pewno w pieczarze poniżej są jakieś młode przy swojej matce miotu. Weź tę skrzynkę, złap 3 z tych młodych i przynieś mi je.$b$bGdzie zawodzi dyplomacja, zniewolenie jest w pełni rozsądną alternatywą.', 'Wejdź do pieczar w Kryształowym Imadle i zamknij 3 pomioty jormungara w solidnych skrzyniach. Pamiętaj, żeby podnieść skrzynie, gdy pomioty jormungara znajdą się w środku!$B$BZanieś schwytane pomioty jormungara Zortowi w Kryształowym Imadle.', '', 'Wróć do Zorta w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12079, 'plPL', 'Plac do deptania', 'Witaj, mała istoto. Nie wiem, jakie szaleństwo sprowadziło cię do Kryształowego Imadła, ale w mojej obecności jesteś mile $gwidziany:widziana;.$b$bTe lodowe robale... te jormungary zasmakowały w pożeraniu moich braci. Wątpię, czy w tym czasie walki moi pobratymcy okażą ci jakąkolwiek życzliwość, ale jeśli przybywasz pomóc z robalami, zamieniam się w słuch.$b$bJeśli mamy odbić pieczarę, najpierw musimy oczyścić kanion z tych żerujących jormungarów. Przyłącz się do nas w walce, $N!', 'Zagłęb się w pieczarę na północnym krańcu Kryształowego Imadła i zabij 8 żerujących jormungarów z Lodowego Serca dla Ko\'chara Niezłomnego.', '', 'Wróć do Ko\'chara Niezłomnego w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12080, 'plPL', 'Naprawdę wielki robal', 'Jormungary mają w pieczarach poniżej matkę pomiotu. Nazywamy ją Grzechoświder – to imię nadał jej poszukiwacz przygód z Plagowisk. Mignęła mi tylko przez chwilę, gdy odpierałem ich pierwszy atak – jest tak wielka, że nawet moje lodowe kości przechodzi dreszcz. Ta pieczara nie będzie nasza, dopóki jej stamtąd nie usuniemy.$b$bZbierz przyjaciół i skończ z tym.', 'Wejdź do Pieczary Lodowego Serca i zabij Grzechoświder. Jeśli wciąż masz ochronny eliksir Zorta, użyj go, by chronić się przed żrącą śliną jormungarów.$B$BPo wykonaniu zadania wróć do Ko\'chara Niezłomnego w Kryształowym Imadle.', '', 'Wróć do Ko\'chara Niezłomnego w Kryształowym Imadle na Smoczych Pustkowiach.', '', '', '', '', 0),
(12083, 'plPL', 'Na szczycie lasów', 'Jestem przekonana, że musi być więcej takich ognisk i każde z nich po kolei przekierowuje energię linii mocy. Wciąż jednak nie wiemy, co dokładnie robią z całą tą mocą.$B$BSądzę, że kolejne znajdziesz na szczycie Lasów Lothalor na południowym wschodzie. Znów $gbędziesz musiał:będziesz musiała; znaleźć dowódcę i zabrać mu urządzenie sterujące, które ma przy sobie, bo jestem pewna, że każde ognisko ma własne.$B$BUważaj, $N, te lasy są bardzo niebezpieczne.', 'Zdobądź amulet kontroli ogniska linii mocy i użyj go, by uzyskać informacje z ogniska linii mocy w Lasach Lothalor.$B$BNastępnie wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', '', '', '', 0),
(12084, 'plPL', 'Na szczycie lasów', 'Jestem przekonany, że musi być więcej takich ognisk i każde z nich po kolei przekierowuje energię linii mocy. Wciąż jednak nie wiemy, co dokładnie robią z całą tą mocą.$B$BSądzę, że kolejne znajdziesz na szczycie Lasów Lothalor na południu. Znów $gbędziesz musiał:będziesz musiała; znaleźć dowódcę i zabrać mu urządzenie sterujące, które ma przy sobie, bo jestem pewien, że każde ognisko ma własne.$B$BNie ociągaj się, $N. Czuję, że czasu może zabraknąć.', 'Zdobądź amulet kontroli ogniska linii mocy i użyj go, by uzyskać informacje z ogniska linii mocy w Lasach Lothalor.$B$BNastępnie wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', '', '', '', 0),
(12085, 'plPL', 'List do domu', 'W podszewce jego szaty znajdujesz ukryty list. Brzmi on:$B$B„Deino,$B$BTa\'zinni przeprasza, że tak zniknąć. Jak ty czytać ten list, to ja być martwy.$B$BJa musieć pracować dla armii Malygosa, bo oni grozić, że zabić rodzinę, jak ja nie. Ta\'zinni nie pozwolić na to!$B$BNie martw się o mnie, tylko pilnuj swoich dzieci. Ja ich oszukać i sabotować ich od środka.$B$BKocham cię, siostra!$B$BTa\'zinni”$B$BNadrządca Agmar na pewno zechce to zobaczyć!', 'Dostarcz list porucznika Ta\'zinniego nadrządcy Agmarowi w Młocie Agmara.', '', 'Wróć do nadrządcy Agmara w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12089, 'plPL', 'Poszukiwany: magister Keldonus', 'Z rozkazu nadrządcy Agmara:$B$BCel: magister Keldonus$B$BZbrodnia: zdrada$B$BStatus: żywy$B$BMagister Keldonus, niegdyś dowódca magów Młota Agmara, ma zostać zabity na miejscu w imię Hordy.$B$BKeldonusa ostatnio widziano, jak zmierzał na południowy zachód, do Ogrodów Księżycowego Spoczynku, by dołączyć do Błękitnego Stada w jego kampanii przeciw magii.$B$BZbliżaj się ostrożnie, bo Keldonus to potężny mag. Nie atakuj w pojedynkę!$B$BWszystkie nagrody wypłaca kapitan Gort w Młocie Agmara.', 'Zabij magistra Keldonusa i wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12090, 'plPL', 'Poszukiwany: Gigantaur', 'Z rozkazu nadrządcy Agmara:$B$BCel: Gigantaur$B$BZbrodnia: napaści na Hordę; „bycie szpetnym”$B$BStatus: żywy$B$BLord magnataurów, Gigantaur, jest poszukiwany w związku z szeregiem napaści na żołnierzy i placówki Hordy na Smoczych Pustkowiach.$B$BGigantaura ostatnio widziano, jak krążył po lasach i drogach na południowy wschód od Młota Agmara.$B$BGigantaura należy uważać za uzbrojonego i skrajnie niebezpiecznego. Nie atakuj w pojedynkę!$B$BWszystkie nagrody wypłaca kapitan Gort w Młocie Agmara.', 'Zabij Gigantaura i wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.$B', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12091, 'plPL', 'Poszukiwany: Grozoszpon', 'Z rozkazu nadrządcy Agmara:$B$BCel: Grozoszpon$B$BZbrodnia: napaści na Hordę$B$BStatus: żywy$B$BGrozoszpon jest poszukiwany za liczne napaści na karawany Hordy zmierzające do Jadozłości i z powrotem.$B$BGrozoszpon gnieździ się na urwisku z widokiem na Rubinową Smoczą Świątynię, na wschód od Młota Agmara. Należy się do niego zbliżać z najwyższą ostrożnością. Nie atakuj w pojedynkę!$B$BWszystkie nagrody wypłaca kapitan Gort w Młocie Agmara.', 'Zabij Grozoszpona i wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12092, 'plPL', 'Wzmocnić pradrzewce', 'Nie tylko twoja rasa ucierpiała przez to, co zrobiły siły Błękitnego Stada. Dotknęło to również pradrzewce z Lasów Lothalor na południowym wschodzie.$B$BNiektóre zostały skażone – za wszelką cenę ich unikaj – ale większość wciąż można ocalić. Za to drzewce z tych lasów wydają się odporne na magię przesączającą się przez ziemię i na tajemne żmije, które przyszły razem z nią.$B$BPoproś drzewce o korę i nakarm nią pradrzewce. Oby to wystarczyło, żeby je ocalić.', 'Użyj Kory Wędrowców, by wzmocnić 3 pradrzewce z Lothalor, a następnie wróć do Sarendryany w Spoczynku Gwiazd.', '', 'Wróć do Sarendryany w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Wzmocniony pradrzewiec z Lothalor', '', '', '', 0),
(12095, 'plPL', 'Do Upadku Smoka', 'Na wschód stąd, w sercu Smoczych Pustkowi, jest pole, na którym nie ma nic poza smoczymi kośćmi i śniegiem. Plaga rozbiła kilka obozów w środkowej tundrze i wskrzesza żmije mrozu, żeby posłać je przeciw naszym siłom pod Bramą Gniewu. Rokhan i jego smoczy łowcy łatwo radzą sobie z większością tych żmijów, ale jeden z nich okazuje się sporym problemem.$B$BIdź na północny wschód i odszukaj Rokhana przy Upadku Smoka. Pomóż jemu i jego ludziom zgładzić Sarathstrę, a zostaniesz sowicie $gnagrodzony:nagrodzona;!', 'Porozmawiaj z Rokhanem przy Upadku Smoka na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12096, 'plPL', 'Wzmocnić pradrzewce', 'Pradrzewce z Lasów Lothalor na południu są skażane przez tajemne żmije... żmije, które wyszły spod ziemi!$B$BTe już skażone są śmiertelnie groźne i na nic nam się nie zdadzą, ale większość wciąż można ocalić. Na szczęście drzewce z tych lasów wydają się odporne na wszystko, co się tam dzieje.$B$BPoproś drzewce o korę, a gdy ją zdobędziesz, nakarm nią pradrzewce. To powinno je wzmocnić.$B$BA teraz zostaw mnie z moimi sprawami! Muszę mieć oko na tych aptekarzy.', 'Użyj Kory Wędrowców, by wzmocnić 3 pradrzewce z Lothalor, a następnie wróć do strażnika ziemi Grife\'a w Młocie Agmara.', '', 'Wróć do strażnika ziemi Grife\'a w Młocie Agmara na Smoczych Pustkowiach.', 'Wzmocniony pradrzewiec z Lothalor', '', '', '', 0),
(12097, 'plPL', 'Sarathstra, postrach Północy', 'Moi łowcy być martwi albo zamarznięci, $N. Tylko ty i sojusznicy, co ich przyprowadzisz – więcej pomocy nie być. Dalej chcesz to zrobić? Powiedz słowo, a ja znów wezwać smoka.$B$BJak go zabijesz, weź zamarznięte serce bestii do Młota Agmara i daj Gortowi. On na pewno dobrze cię nagrodzić, mon.', 'Porozmawiaj z Rokhanem, by przywołać żmija mrozu Sarathstrę.$B$BZabij Sarathstrę i dostarcz zamarznięte serce Sarathstry kapitanowi Gortowi w Młocie Agmara.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12098, 'plPL', 'Przeszukaj Wioskę Indu\'le', 'Jestem pewna, że następne ognisko linii mocy znajdziesz gdzieś w ruinach Wioski Indu\'le na południowym wschodzie. Kłopot w tym, że nie dostaliśmy żadnych meldunków, by tam jakieś było.$B$BJeśli możesz, przeszukaj wioskę w poszukiwaniu śladów ogniska albo łowców magów i ich dowódcy.$B$BW razie potrzeby nie zapomnij przeszukać jeziora.', 'Odszukaj dowódcę sił łowców magów w Wiosce Indu\'le i nad Jeziorem Indu\'le.', '', '', '', '', '', '', 0),
(12100, 'plPL', 'Powstrzymać zgniliznę', 'Wraz z Plagą przychodzą śmierć i choroba. Często zapominamy, że zwierzęta na ziemiach opanowanych przez Plagę są niszczone i w końcu unicestwiane przez zgniliznę i zarazę.$B$BDla większości rodzimych zwierząt Smoczych Pustkowi jest już za późno. Ropiejąca choroba, którą niesie Plaga, zaraziła już te zwierzęta i teraz są wściekłe i gniją.$B$BMusisz wyruszyć na zachód, w stronę Czeluści Narjun, i przetrzebić zarażoną zwierzynę. Przeszukaj ich truchła w poszukiwaniu zachowanego organu, bo potrzebujemy go, by opracować szczepionkę.', 'Soar Jastrzębia Furia w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gzabił:zabiła; 15 sztuk zarażonej zwierzyny i $gzdobył:zdobyła; organ odporny na gnicie.', '', 'Wróć do Soara Jastrzębiej Furii w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12101, 'plPL', 'Dobry doktor...', 'Nasi sojusznicy, Porzuceni, przysłali tu swój korpus aptekarzy, by pomógł nam niszczyć Plagę pod Bramą Gniewu. Jeden z nich, doktor Sintar Malefious, dobrze zna się na zgniliźnie Plagi i sposobach powstrzymywania jej rozprzestrzeniania. Wcześniej zawarłem z nim umowę w sprawie opracowania szczepionki dla zwierząt. Od tamtej pory czeka na organ.$B$BDostarcz ten organ odporny na gnicie doktorowi Malefiousowi i powiedz mu, że to ode mnie. Wskaże ci następne zadanie.', 'Dostarcz organ odporny na gnicie doktorowi Sintarowi Malefiousowi w Młocie Agmara.$B', '', 'Wróć do doktora Sintara Malefiousa w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12102, 'plPL', 'W poszukiwaniu rubinowego bzu', 'Cóż za szczęśliwy traf, że Rubinowa Smocza Świątynia leży tuż na wschodzie. To tam znajdziesz kwiat zwany rubinowym bzem. Ta życiodajna roślina to wszystko, czego potrzebuję, by przyrządzić szczepionkę dla nieskażonych zwierząt tego regionu.$B$BUdaj się na wschód i poszukaj bzu w Rubinowej Smoczej Świątyni.$B$BJeszcze jedno: ta smocza świątynia, jak wszystkie smocze świątynie na tym przeklętym pustkowiu, jest oblężona przez Plagę. Uważaj, gdzie stąpasz. Nie chcielibyśmy, żeby pożarł cię jakiś żarożmij.$B$B<Sintar się śmieje.>', 'Doktor Sintar Malefious w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gzebrał:zebrała; 1 rubinowy bez.', '', 'Wróć do doktora Sintara Malefiousa w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12104, 'plPL', 'Powrót do Soara', '<Doktor Malefious wręcza ci fiolkę pełną mętnego płynu.>$B$BProszę bardzo, $N. Zanieś to z powrotem tej krowie i powiedz mu, że wszystkie długi zostały spłacone. Jesteśmy oficjalnie „kwita”.$B$BA teraz zostaw mnie, zanim poszczuję cię Jenningsem.', 'Dostarcz szczepionkę Sintara Soarowi Jastrzębiej Furii w Młocie Agmara.', '', 'Wróć do Soara Jastrzębiej Furii w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12106, 'plPL', 'Przeszukaj Wioskę Indu\'le', 'Jestem pewien, że następne ognisko linii mocy znajdziesz gdzieś w ruinach Wioski Indu\'le na południowym wschodzie. Kłopot w tym, że nie dostałem żadnych meldunków, by tam jakieś było.$B$BMusisz przeszukać wioskę w poszukiwaniu śladów ogniska albo łowców magów i ich dowódcy.$B$BJeśli trzeba, przeszukaj jezioro!', 'Odszukaj dowódcę sił łowców magów w Wiosce Indu\'le i nad Jeziorem Indu\'le.', '', '', '', '', '', '', 0),
(12107, 'plPL', 'Koniec linii', 'W jego szatach znajdujesz dwie interesujące rzeczy.$B$BJedną jest talizman, bez wątpienia urządzenie sterujące ogniskiem. Drugą są rozkazy od kogoś imieniem Sidragos, które ostatecznie miały trafić do dowódcy w Ogrodach Księżycowego Spoczynku.$B$BZ przemoczonego pergaminu wynika, że Goramosh ma przenieść wszystkie siły łowców magów na wschód, do Lazurowej Smoczej Świątyni.$B$BMoże warto zdobyć z ogniska tyle informacji, ile się da, a potem udać się na wschód i obserwować smoczą świątynię z jej zachodniej półki skalnej.', 'Użyj talizmanu kontroli ogniska linii mocy, by uzyskać informacje z ogniska linii mocy pod Jeziorem Indu\'le. Następnie udaj się na wschód do Lazurowej Smoczej Świątyni w południowej części środkowych Smoczych Pustkowi i z zachodniej półki skalnej obserwuj, co się tam dzieje.$B$BPotem wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', 'Lazurowa Smocza Świątynia zbadana', '', '', 0),
(12110, 'plPL', 'Koniec linii', 'W jego szatach znajdujesz dwie interesujące rzeczy.$B$BJedną jest talizman, bez wątpienia urządzenie sterujące ogniskiem. Drugą są rozkazy od kogoś imieniem Sidragos, które ostatecznie miały trafić do dowódcy w Ogrodach Księżycowego Spoczynku.$B$BZ kruchego, przemoczonego pergaminu wynika, że Goramosh ma przenieść wszystkie siły łowców magów na wschód, do Lazurowej Smoczej Świątyni.$B$BMoże warto zdobyć z ogniska tyle informacji, ile się da, a potem udać się na wschód i obserwować smoczą świątynię z jej zachodniej półki skalnej.', 'Użyj talizmanu kontroli ogniska linii mocy, by uzyskać informacje z ogniska linii mocy pod Jeziorem Indu\'le. Następnie udaj się na wschód do Lazurowej Smoczej Świątyni w południowej części środkowych Smoczych Pustkowi i z zachodniej półki skalnej obserwuj, co się tam dzieje.$B$BPotem wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', 'Informacje z ogniska linii mocy uzyskane', 'Lazurowa Smocza Świątynia zbadana', '', '', 0),
(12111, 'plPL', 'Tam, gdzie żyją dzikie stwory', 'W tej paczce jest kilka fiolek ze szczepionką, którą przygotował Sintar. Teraz chcę, żebyś $gprzeszukał:przeszukała; pobliskie lasy w poszukiwaniu łosi ze Śniegospadu i arktycznych grizli. Gdy znajdziesz zwierzęta, stań w bezpiecznej odległości i rzuć fiolkę w ich stronę. Fiolka się roztrzaska i uwolni delikatny gaz, który zadziała jak szczepionka. Wystarczy, że zwierzęta wejdą w gaz, a zostaną zaszczepione – i ostatecznie ocalone.$B$BZaszczep tyle zwierząt, ile zdołasz, i wróć do mnie.$B', 'Soar Jastrzębia Furia w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gużył:użyła; paczki szczepionek, by zaszczepić 5 łosi ze Śniegospadu i 5 arktycznych grizli.', '', 'Wróć do Soara Jastrzębiej Furii w Młocie Agmara na Smoczych Pustkowiach.', 'Zaszczepiony łoś ze Śniegospadu', 'Zaszczepiony arktyczny grizli', '', '', 0),
(12112, 'plPL', 'Twarde negocjacje', 'No, wygląda na to, że jednak na coś się $gprzydałeś:przydałaś;. Z mojego doświadczenia niewielu takich jak ty się do czegoś nadaje.$b$bNie mamy tu już dla ciebie roboty. Idź do Imadła i zobacz, czy mój brat Zort nie potrzebuje pomocy. Poszedł sprawdzić, czy uda mu się naciągnąć olbrzymy, żeby oddały życie za nas. Nigdy nie słynął z tego, że to on w rodzinie ma rozum.', 'Odszukaj Zorta w środkowej części Kryształowego Imadła, na północny wschód od Posterunku Rdzawej Dyszy.', '', '', '', '', '', '', 0),
(12115, 'plPL', 'Koltira i język śmierci', 'Jest ktoś, kto niedawno przyłączył się do naszej sprawy i może zdołać odczytać tę księgę. Wyzwolony rycerz śmierci, Koltira Tkacz Śmierci, tymczasowo zamieszkał tu, w Młocie Agmara. Ponieważ był kiedyś rycerzem śmierci Arthasa i członkiem Plagi, może potrafi przetłumaczyć język umarłych.$B$BZanieś księgę w oprawie z ciała Koltirze i poproś go, by przetłumaczył jej strony.$B', 'Zanieś księgę w oprawie z ciała Koltirze Tkaczowi Śmierci.', '', 'Wróć do Koltiry Tkacza Śmierci w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12119, 'plPL', 'Uzyskać posłuchanie', '$N, musisz jak najszybciej udać się do Świątyni Żmijowego Spoczynku i przedstawić ten list zarządcy, Tariolstraszowi.$B$BŚwiątynia stoi w samym sercu Smoczych Pustkowi. Idź drogą na wschód aż do jej końca, a potem przejdź przez Pustkowia Smoków.$B$BGdy zarządca przeczyta twój list polecający, z pewnością dopilnuje, żebyś $guzyskał:uzyskała; posłuchanie u królowej Alexstrazy. Możemy tylko mieć nadzieję, że nie jest za późno.$B$BDziękuję za wszystko, co dla nas $gzrobiłeś:zrobiłaś;. Szczęśliwej podróży!', 'Dostarcz list polecający do Świątyni Żmijowego Spoczynku Tariolstraszowi w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Tariolstrasza na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(12122, 'plPL', 'Uzyskać posłuchanie', '$N, musisz jak najszybciej udać się do Świątyni Żmijowego Spoczynku i przedstawić ten list zarządcy, Tariolstraszowi.$B$BŚwiątynia stoi w samym sercu Smoczych Pustkowi. Idź drogą na wschód aż do jej końca, a potem przejdź przez Pustkowia Smoków.$B$BGdy zarządca przeczyta twój list polecający, z pewnością dopilnuje, żebyś $guzyskał:uzyskała; posłuchanie u królowej Alexstrazy. Możemy tylko mieć nadzieję, że nie jest za późno.$B$BDziękuję za wszystko, co dla nas $gzrobiłeś:zrobiłaś;. Szczęśliwej podróży!', 'Dostarcz list polecający do Świątyni Żmijowego Spoczynku Tariolstraszowi w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Tariolstrasza w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12123, 'plPL', 'Wieści dla królowej', '<Smoczy zarządca wyciąga z rękawa twój list polecający.>$B$BTak... tak, myślę, że możesz już stanąć przed królową.$B$BGdy będziesz $ggotów:gotowa;, porozmawiaj ze mną ponownie, a dopilnuję, żeby jeden z tych smokowców bezpiecznie zaniósł cię na szczyt świątyni. Musisz osobiście przedstawić swój list królowej Alexstrazie.', 'Dostarcz list polecający do Świątyni Żmijowego Spoczynku Alexstrazie Życiodajnej w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Alexstrazy Życiodajnej w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12124, 'plPL', 'Wieści dla królowej', '<Smoczy zarządca wyciąga z rękawa twój list polecający.>$B$BTak... tak, myślę, że możesz już stanąć przed królową.$B$BGdy będziesz $ggotów:gotowa;, porozmawiaj ze mną ponownie, a dopilnuję, żeby jeden z tych smokowców bezpiecznie zaniósł cię na szczyt świątyni. Musisz osobiście przedstawić swój list królowej Alexstrazie.', 'Dostarcz list polecający do Świątyni Żmijowego Spoczynku Alexstrazie Życiodajnej w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Alexstrazy Życiodajnej w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12125, 'plPL', 'W służbie krwi', 'Niegdyś pragnienie ostrza gaszono krwią niewinnych. Niestety, nie mam już takiej możliwości.$B$B<Koltira przerywa, by się zastanowić.>$B$BMusimy improwizować. Na południe stąd, na wysokich urwiskach, leży wioska kiełzarów Indu\'le. Niedawno ogarnęła ją chaotyczna magia Błękitnego Stada i mieszkający tam kiełzarowie postradali zmysły.$B$BWeź ten klejnot krwi i użyj go na obłąkanym mieszkańcu wioski. Skoro nie mogę wziąć krwi niewinnych, wezmę krew bezbronnych!', 'Koltira Tkacz Śmierci w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gużył:użyła; klejnotu krwi na obłąkanym mieszkańcu Indu\'le i $gwrócił:wróciła; do niego z napełnionym klejnotem krwi.', '', 'Wróć do Koltiry Tkacza Śmierci w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12126, 'plPL', 'W służbie bezbożności', 'Moc bezbożności jest pożądana wśród mojego rodzaju. Stanowi samą tkankę naszego istnienia i sprowadza śmierć na tych, którzy ośmielają się z niej drwić! Na szczęście jest źródło, z którego mogę czerpać w potrzebie.$B$BWeź ten bezbożny klejnot i udaj się do Rubinowej Smoczej Świątyni na wschód stąd. Znajdziesz tam księcia Vallenhala, rycerza śmierci Arthasa. Osłab go w walce i uwolnij na nim moc klejnotu. To go dobije i wykradnie jego bezbożną energię!$B', 'Koltira Tkacz Śmierci w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gużył:użyła; bezbożnego klejnotu na księciu Vallenhalu i $gwrócił:wróciła; do niego z napełnionym bezbożnym klejnotem.', '', 'Wróć do Koltiry Tkacza Śmierci w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12127, 'plPL', 'W służbie mrozu', 'Przenikliwy chłód chroni rycerza śmierci i odpiera jego wrogów. Kto włada mocą mrozu, może wzniecić chaos i zniszczenie!$B$BWeź ten mroźny klejnot i wyrusz daleko przez otwartą tundrę Smoczych Pustkowi, aż dotrzesz do Lustra Świtu na wschód od Świątyni Żmijowego Spoczynku. Tam masz stoczyć walkę z zastępami lodowych zjaw, które mieszkają na tafli jeziora, i odebrać im esencję mrozu. Użyj mocy klejnotu, gdy będą osłabione, $N!', 'Koltira Tkacz Śmierci w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gużył:użyła; mroźnego klejnotu na lodowych zjawach i $gwrócił:wróciła; do niego z napełnionym mroźnym klejnotem.', '', 'Wróć do Koltiry Tkacza Śmierci w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12132, 'plPL', 'Moc niszczenia', 'Choć wiele dla mnie $gzrobiłeś:zrobiłaś;, zostało jeszcze jedno zadanie.$B$BObok świata, który znasz, istnieje inny świat. To z tamtego świata, świata cieni, atakują mnie moi dręczyciele. Choć jestem bezsilny wobec własnych demonów, ty możesz położyć kres ich rządom terroru. Masz dość siły, widziałem to na własne oczy.$B$BWkrocz do świata cieni i staw czoła demonom, które mnie dręczą!$B$BZrób to, a przetłumaczę księgę, tak jak obiecałem.', 'Koltira Tkacz Śmierci w Młocie Agmara na Smoczych Pustkowiach chce, żebyś $gwkroczył:wkroczyła; do świata cieni i $gpokonał:pokonała; 6 cienistych dręczycieli.$B$BJeśli musisz ponownie wejść do świata cieni, porozmawiaj z Koltirą Tkaczem Śmierci.', '', 'Wróć do Koltiry Tkacza Śmierci w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12136, 'plPL', 'Przetłumaczona księga', 'Proszę, $N. Przetłumaczyłem wszystko, co zapisano na stronach tej księgi. Znajdziesz w niej listę imion członków Kultu Potępionych z całego kontynentu.$B$BIch sieć szpiegów i agentów robi, delikatnie mówiąc, wrażenie.$B$BŻegnaj, $gprzyjacielu:przyjaciółko;. Niech ta księga dobrze służy tobie i twojemu ludowi.', 'Dostarcz przetłumaczoną księgę w oprawie z ciała kapitanowi Gortowi w Młocie Agmara.', '', 'Wróć do kapitana Gorta w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12140, 'plPL', 'Chwała Roanaukowi!', 'Podobnie jak taureni, Porzuceni, trolle i krwawe elfy, także taunka potrzebują przywódcy z własnej krwi. Tym przywódcą będzie ten, którego $gocaliłeś:ocaliłaś; w Lodowej Mgle – Roanauk.$B$B<Nadrządca Agmar wręcza ci pergamin.>$B$BDaję ci coś znajomego – krwawą przysięgę Hordy.$B$BZanieś przysięgę Roanaukowi Lodowej Mgle i przyjmij go do Hordy jako przywódcę taunka.$B$BNie każmy mu czekać.$B$B<Agmar kiwa głową.>$B', 'Odszukaj Roanauka Lodową Mgłę w Młocie Agmara i przyjmij go do Hordy jako jej członka i przywódcę jej sił.$B$BPo wykonaniu zadania wróć do nadrządcy Agmara z krwawą przysięgą Hordy.$B', '', 'Wróć do nadrządcy Agmara w Młocie Agmara na Smoczych Pustkowiach.', 'Roanauk Lodowa Mgła przyjęty', '', '', '', 0),
(12142, 'plPL', 'Tępienie szkodników', 'Ech! Jeden z tych małych snoboldzkich kurdupli zdemolował nam obóz, kiedy zajmowaliśmy się tym ostatnim smokiem. Nękają nas, gdy tylko się odwrócimy... Mam dość!$B$BNa południu znajdziesz snoboldy chowające się pod spódnicami miejscowych magnataurów. Idź i wyrżnij je.$B$BJeśli magnataury wstawią się za swoimi niewolnikami, zabij i je.', 'Duane na Froncie 7. Legionu chce, żebyś $gzabił:zabiła; 10 snoboldów Śnieżnej Równiny i 3 magnataury ze Smoczych Pustkowi w obozach magnataurów wokół Żmijowego Spoczynku.', '', 'Wróć do Duane\'a na Froncie 7. Legionu na Smoczych Pustkowiach.', 'Snoboldy Śnieżnej Równiny', 'Magnataury ze Smoczych Pustkowi', '', '', 0),
(12143, 'plPL', 'Pościg w kanionie', 'Nie wierzę! Kolejna banda tych szkodników właśnie próbowała zwiać z następną porcją naszych zapasów. Uciekają w stronę tamtego północnego kanionu, ruszaj za nimi i rozpraw się z tym, do kogo biegną!', 'Duane chce, żebyś $gścigał:ścigała; snoboldy w kanionie na północny wschód od Frontu 7. Legionu i $grozprawił:rozprawiła; się z ich przywódcą.', '', 'Wróć do Duane\'a na Froncie 7. Legionu na Smoczych Pustkowiach.', '', '', '', '', 0),
(12144, 'plPL', 'Tępienie szkodników', 'Ej, mon! Jeden z tych małych snoboldzkich kurdupli zdemolował nam obóz przy ostatnim ataku smoka. Nękać nas, jak tylko się odwrócimy, i ja mieć dość.$b$bNa wschodzie znajdziesz snoboldy, co chowają się pod spódnicami miejscowych magnataurów. Idź je wyrżnąć. Jak magnataury wstawią się za swoimi niewolnikami, zabij i je.', 'Kontokanis przy Upadku Smoka chce, żebyś $gzabił:zabiła; 10 snoboldów Śnieżnej Równiny i 3 magnataury ze Smoczych Pustkowi w obozach magnataurów wokół Żmijowego Spoczynku.', '', 'Wróć do Kontokanisa przy Upadku Smoka na Smoczych Pustkowiach.', 'Snoboldy Śnieżnej Równiny', 'Magnataury ze Smoczych Pustkowi', '', '', 0),
(12145, 'plPL', 'Pościg w kanionie', 'Ja nie wierzyć! Kolejna banda tych szkodników właśnie próbować zwiać z następną porcją naszych zapasów. Teraz uciekać w dół kanionu, ruszaj za nimi i rozpraw się z tym, do kogo biegną!', 'Kontokanis chce, żebyś $gścigał:ścigała; snoboldy w kanionie na południe od Upadku Smoka i $grozprawił:rozprawiła; się z ich przywódcą.', '', 'Wróć do Kontokanisa przy Upadku Smoka na Smoczych Pustkowiach.', '', '', '', '', 0),
(12146, 'plPL', 'Niepokojące wnioski', 'Na spodzie rogu widnieje herbowa pieczęć z młotem i błyskawicą. Coś w tym rogu wydaje się zupełnie nie pasować do magnataura.$b$bZanieś róg na południe, Ścieżką Tytanów, do Żmijowego Spoczynku i odszukaj kogoś, kogo mogą zainteresować te groźne wnioski.', 'Zanieś herbowy róg bojowy do Żmijowego Spoczynku i odszukaj kogoś, kto zechce ocenić potencjalne zagrożenie.', '', 'Wróć do Aurastraszy na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(12147, 'plPL', 'Niepokojące wnioski', 'Na spodzie rogu widnieje herbowa pieczęć z młotem i błyskawicą. Coś w tym rogu wydaje się zupełnie nie pasować do magnataura.$b$bZanieś róg na wschód, przez Pustkowia Smoków, do Żmijowego Spoczynku i odszukaj kogoś, kogo mogą zainteresować te groźne wnioski.', 'Zanieś herbowy róg bojowy do Żmijowego Spoczynku i odszukaj kogoś, kto zechce ocenić potencjalne zagrożenie.', '', 'Wróć do Aurastraszy na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(12148, 'plPL', 'Jedyny w swoim rodzaju', 'Cóż za dziwna pieczęć u magnataurów... świadczy o niezwykłym stopniu zorganizowania.$B$BMagnataury rzadko odkładają na bok swoją agresywną naturę, by ze sobą współpracować. Podejrzewam, że upatrzyły sobie do napadu jakąś dużą osadę.$b$bBardzo wątpię, żeby ten róg był jedyny, i chcę, żebyś $gudowodnił:udowodniła;, że się mylę. W kanionie na północny zachód od Lazurowej Smoczej Świątyni znajdziesz Kościołama. Rzuć mu wyzwanie i przynieś mi wszelkie dowody, które mogą potwierdzić moje obawy.', 'Odnajdź i zabij Kościołama w kanionie na północny zachód od Lazurowej Smoczej Świątyni lub w jego pobliżu. Wszelkie znalezione dowody zanieś Aurastraszy w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Aurastraszy w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12149, 'plPL', 'Potężne magnataury', 'Magnataury to potwornie brutalne stworzenia... głównie dlatego rzadko widujemy, by zbierały się w większej liczbie i się nawzajem nie pozabijały. Gdzieś wśród nich pojawił się potężny przywódca i musimy go wytropić, jeśli mamy powstrzymać to zagrożenie.$B$BZacznę wypytywać. W międzyczasie chcę, żebyś jak najbardziej $gzakłócał:zakłócała; ich działania.$B$BNa wschód stąd wznoszą się 3 pochodnie. W ich pobliżu są 3 dominujące magnataury – zabij je, żebyśmy zyskali trochę czasu na wytropienie przywódcy.', 'Wytrop i zabij Krwawą Ucztę, Lodokrusza i Smoczą Rzeź na wschód od Żmijowego Spoczynku.$B$BKrwawa Uczta przebywa w południowo-wschodnim krańcu Pustkowi Smoków, tuż na północ od Szmaragdowej Smoczej Świątyni. Lodokrusz patroluje północny brzeg Lustra Świtu. Smocza Rzeź krąży u stóp klifów na zachód od Brązowej Smoczej Świątyni.$B$BGdy zabijesz magnataury, wróć do Aurastraszy w Żmijowym Spoczynku.', '', 'Wróć do Aurastraszy w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12150, 'plPL', 'Runomistrz samotnik', 'Dregmar Runiczne Piętno to magnataurski runomistrz... rzadki okaz. Zwykle trzyma się na uboczu, ale od dłuższego czasu wiadomo, że zadaje się z potężniejszymi i bardziej wpływowymi magnataurami na Smoczych Pustkowiach. Będzie wiedział, kim jest ten nowy przywódca.$b$bPrzy rosnących kłopotach z Plagą i błękitnym stadem raczej nikt nam nie pomoże, więc musisz wydobyć te informacje od Dregmara wszelkimi dostępnymi sposobami.$B$BPowiedziano mi, że można go znaleźć wśród klifów z widokiem na Lustro Świtu.', 'Odszukaj Dregmara Runiczne Piętno w pobliżu jego jaskini, na ścieżce prowadzącej na klify nad Lustrem Świtu. Rzuć mu wyzwanie i wszelkimi sposobami wydobądź imię przywódcy magnataurów. Gdy zdobędziesz tę informację, wróć do Aurastraszy w Żmijowym Spoczynku.', 'Imię wodza wojennego magnataurów', 'Wróć do Aurastraszy w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', 'Imię wodza wojennego magnataurów', '', '', '', 0),
(12151, 'plPL', 'Rozpasany wódz', 'Nie ma powodu podejrzewać, że słowa Dregmara są nieprawdziwe. Czy Grom\'thar pokona ciebie, czy ty jego, Dregmar umywa od tego ręce.$b$bPostąp według jego wskazówek... weź róg, który wcześniej mi $gprzyniosłeś:przyniosłaś;, udaj się do kręgu pochodni na południe od Lazurowej Smoczej Świątyni i zadmij w niego, by rzucić wyzwanie.$B$BGdy przybędzie Grom\'thar Zwiastun Gromu, zabij go i przynieś mi jego głowę.', 'Udaj się do kręgu pochodni na południe od Lazurowej Smoczej Świątyni i zadmij w herbowy róg bojowy. Pokonaj Grom\'thara Zwiastuna Gromu i zanieś jego głowę Aurastraszy w Żmijowym Spoczynku.', '', 'Wróć do Aurastraszy w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12166, 'plPL', 'Płynny ogień Eluny', '$N, pomożesz mi?$B$BPlaga wkroczyła do Lodowej Mgły na północy. Gdziekolwiek się pojawi, szerzy swoje skażenie, a stworzenia tej ziemi cierpią.$B$BWeź tę fiolkę, napełnioną płynnym ogniem Eluny z księżycowej studni. Proszę, użyj go, by oczyścić zwłoki zarażonych zwierząt, które znajdziesz.', 'Nadzorczyni Jodi Księżycowa Pieśń w Spoczynku Gwiazd prosi, żebyś $gużył:użyła; płynnego ognia Eluny, by oczyścić zwłoki 6 zarażonych łosi i 6 wściekłych grizli.', '', 'Wróć do nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Oczyszczone zwłoki zarażonego łosia', 'Oczyszczone zwłoki wściekłego grizli', '', '', 0),
(12167, 'plPL', 'Zabij kultystów', 'Kultyści Anub\'ar pośrednio odpowiadają za zarazę wśród zwierząt i musimy położyć temu kres!$B$BOpary wydobywające się ze strojów kultystów przenikają wszystko, do czego się zbliżą, i zatruwają i skażają otoczenie.$B$BMusisz udać się na północ, do Wioski Lodowej Mgły, i ich zabić. Przynieś wszystkie stroje, które przetrwają twój atak, a dopilnuję, by zostały odpowiednio zniszczone.', 'Zbierz 5 działających strojów kultystów dla nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd.', '', 'Wróć do nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12168, 'plPL', 'Łaska Zangusa', 'Na odwrocie podarunku widnieje napis:$B$B„Mojemu ulubionemu uczniowi,$B$Bjeśli nadal będziesz dobrze się zapowiadać, nauczę cię cudów przekraczających twoje wyobrażenia.$B$BJeśli nie, każę cię zniszczyć!$B$BJak zawsze,$B$Barcykultysta Zangus”$B$BNadzorczyni w Spoczynku Gwiazd z pewnością zechce to zobaczyć.', 'Dostarcz Łaskę Zangusa nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd.', '', 'Wróć do nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12169, 'plPL', 'Arcykultysta', 'Śniłam już o Zangusie, ale bez tego, co $godkryłeś:odkryłaś;, nie wiedziałam, co to znaczy. $GWyjaśniłeś:Wyjaśniłaś; wizję, którą zesłała mi bogini, i teraz wiem, że można go znaleźć w Czeluści Narjun na północy.$B$BZnasz swój cel, $N. Jeśli cierpienie tej ziemi ma się skończyć, arcykultysta musi zginąć!', 'Nadzorczyni Jodi Księżycowa Pieśń w Spoczynku Gwiazd prosi, żebyś $gzabił:zabiła; arcykultystę Zangusa.', '', 'Wróć do nadzorczyni Jodi Księżycowej Pieśni w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12171, 'plPL', 'O zdrajcach i zdradzie', 'Listę, którą mam, trzeba dostarczyć wielkiemu komendantowi Halfordowi Zmorze Żmijów. Dowodzi 7. Legionem, stacjonującym w Twierdzy Zimowej Straży na wschodnich rubieżach Smoczych Pustkowi.$B$BJeśli którykolwiek ze zdrajców z tej listy stacjonuje w Zimowej Straży... skutki mogą być katastrofalne.$B$BPospiesz się, $N. Pokaż dokument Palenie Srebrnej Chmurze tu, w Spoczynku Gwiazd, i wyjaśnij, na czym polega twoja misja. Posadzi cię na swoim najszybszym hipogryfie do Zimowej Straży!', 'Pokaż wiadomość Przymierza Palenie Srebrnej Chmurze w Spoczynku Gwiazd.', '', 'Wróć do Paleny Srebrnej Chmury w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', 0),
(12172, 'plPL', 'Dostrojenie do Dalaranu', 'Witaj, $gmagu:magini;.$B$BZapewne zastanawiasz się już, gdzie jest Dalaran i jak się tam dostać. Pomogę ci.$B$BZanim jednak nauczę cię teleportować się do naszego wielkiego miasta, musisz dostroić się do linii mocy Północnej Grani. Inaczej ryzykujesz, że w trakcie $gsam:sama; się unicestwisz.$B$BWeź ten kryształ dostrojenia i użyj go w wyrwie pod iglicą przypływu w Ogrodach Księżycowego Spoczynku na zachodzie. Wtedy będziesz $ggotów:gotowa; nauczyć się zaklęcia.', 'Wizerunek arcymagini Modery w Spoczynku Gwiazd prosi, żebyś $gdostroił:dostroiła; się do linii mocy Północnej Grani.', '', 'Wróć do wizerunku arcymagini Modery w Spoczynku Gwiazd na Smoczych Pustkowiach.', 'Dostrojenie do linii mocy Północnej Grani', '', '', '', 0),
(12173, 'plPL', 'Dostrojenie do Dalaranu', 'Witaj, $gmagu:magini;.$B$BZapewne zastanawiasz się już, gdzie jest Dalaran i jak się tam dostać. Mogę ci w tym pomóc, jeśli przetrwasz prostą próbę.$B$BZanim nauczę cię teleportować się do naszego wielkiego miasta, musisz dostroić się do linii mocy Północnej Grani. Inaczej w trakcie $gsam:sama; się unicestwisz!$B$BWeź ten kryształ dostrojenia i użyj go w wyrwie pod iglicą przypływu w Ogrodach Księżycowego Spoczynku na południowym zachodzie. Wtedy będziesz $ggotów:gotowa; nauczyć się tego, czego mam cię nauczyć.', 'Wizerunek arcymaga Aethasa Słońcobójcy w Młocie Agmara prosi, żebyś $gdostroił:dostroiła; się do linii mocy Północnej Grani.', '', 'Wróć do wizerunku arcymaga Aethasa Słońcobójcy w Młocie Agmara na Smoczych Pustkowiach.', 'Dostrojenie do linii mocy Północnej Grani', '', '', '', 0),
(12174, 'plPL', 'Wielki komendant Halford Zmora Żmijów', '<Palena oddaje ci wiadomość.>$B$BŚnieżyca zaniesie cię do Zimowej Straży, $N. Gwarantuję ci, że to będzie najszybszy lot w twoim życiu. Leć już!$B', 'Dostarcz Wiadomość Przymierza Wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży we wschodniej części Smoczych Pustkowi.$B', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12188, 'plPL', 'Zaraza Porzuconych a ty: jak nie umrzeć', 'Szczegóły działania zarazy nie są szczególnie ważne. Musisz wiedzieć tylko tyle, że robi to, do czego ją stworzono. Udało mi się zsyntetyzować obojętny szczep zarazy.$B$B<Middleton odkorkowuje fiolkę i wdycha jej zawartość.>$B$BWidzisz, moje ciało jest wciąż, w większości, w jednym kawałku. A teraz wystarczy to zmieszać z czynnikiem reaktywnym, a wszyscy zmienilibyśmy się w bezkształtne kupki mazi.$B$BNa plaży na południe stąd znajdziesz żałosne widma dawnych żołnierzy Przymierza. Zabij je i przynieś mi ektoplazmatyczny osad.', 'Główny siewca zarazy Middleton w Jadozłości na Smoczych Pustkowiach chce, żebyś $gprzyniósł:przyniosła; mu 10 porcji ektoplazmatycznego osadu.', '', 'Wróć do głównego siewcy zarazy Middletona w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12189, 'plPL', 'Wszędzie sami imbecyle!', 'Transport z Nowego Agamandu miał dotrzeć do Jadozłości w zeszłym tygodniu, a po kilku prostych próbach polowych trafić do mnie. To sprawa najwyższej wagi dla Hordy – ostatni element „układanki zwycięstwa”.$B$B<Sintar wzdycha.>$B$BTo doprawdy przygnębiające, gdy człowiek jest otoczony przez imbecyli i niekompetentnych głupków!$B$BMusisz udać się do Jadozłości, w pobliżu wschodniej granicy Smoczych Pustkowi. Znajdź tego błazna Middletona i powiedz mu, że czekam na przesyłkę.', 'Udaj się do Jadozłości na Smoczych Pustkowiach i porozmawiaj z głównym siewcą zarazy Middletonem.$B', '', '', '', '', '', '', 0),
(12200, 'plPL', 'Łzy szmaragdowych smoków', 'Mamy już obojętną próbkę związku zarazy i czynnik aktywujący, brakuje tylko odpowiedniej powłoki, w której zamkniemy składniki.$B$BNa południowy zachód stąd, na brzegach środkowych Smoczych Pustkowi, znajdziesz Szmaragdową Smoczą Świątynię. W świątyni natrafisz na stwardniałe pozostałości łez zielonego smoka. Nie znam całej historii, ale podobno przed śmiercią dużo płaczą. Kto by pomyślał.$B$BIdź do Szmaragdowej Smoczej Świątyni i zbierz łzy.', 'Główny siewca zarazy Middleton w Jadozłości na Smoczych Pustkowiach chce, żebyś $gzebrał:zebrała; 8 łez szmaragdowego smoka.', '', 'Wróć do głównego siewcy zarazy Middletona w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12205, 'plPL', 'Poszukiwani: Szkarłatny Szturm', 'Z rozkazu najwyższego egzekutora Wrotha wszyscy członkowie nielegalnej organizacji zwanej Szkarłatnym Szturmem mają zostać natychmiast straceni.$B$BNie wolno okazywać litości, a ci, którzy przystąpią do wykonania tego rozkazu, powinni wiedzieć, że każdy pojmany przez ludzi zostanie pozostawiony na śmierć albo spotka go coś gorszego!$B$BJak rzekł najwyższy egzekutor: „Zbarwcie śnieg na czerwono ich krwią!”', 'Zabij 20 członków Szkarłatnego Szturmu i zamelduj się u najwyższego egzekutora Wrotha w Jadozłości.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', 'Zabici członkowie Szkarłatnego Szturmu', '', '', '', 0),
(12206, 'plPL', 'Ostatnia posługa z zarazą', '$GCzytałeś:Czytałaś; list gończy? Co ten najwyższy egzekutor sobie myśli?!$B$B<Vicky rozgląda się i kontynuuje ściszonym głosem.>$B$BNie możemy przecież pozwolić, żeby tych idiotów ze Szkarłatnego Szturmu wskrzeszali ich kapłani albo, co gorsza, żeby powstawali jako Plaga, prawda?$B$BNie, całkowicie się z tobą zgadzam, musimy coś zrobić z tymi zwłokami.$B$BMam coś w sam raz. Weź tę zarazę, którą właśnie stworzyliśmy, i wypróbuj ją na więźniu w tej klatce.$B$BBez bałaganu, bez zamieszania, bez powracających wrogów.', 'Aptekarka Vicky Levine w Jadozłości prosi, żebyś $gwypróbował:wypróbowała; flaszkę zarazy na więźniu Szkarłatnego Szturmu.', '', 'Wróć do aptekarki Vicky Levine w Jadozłości na Smoczych Pustkowiach.', 'Flaszka zarazy wypróbowana', '', '', '', 0),
(12209, 'plPL', 'Łupy wojenne', 'Ach, dobrze, świeże mięso. Chcesz się wykazać, świeże mięso?$B$BSzkarłatny Szturm, najbardziej fanatyczni i rasistowscy członkowie Szkarłatnej Krucjaty, siedzą nam tuż pod bokiem, na południu. Jeśli mamy z nimi walczyć, będziemy potrzebować więcej zbroi i broni, niż zdołam wykonać w tak krótkim czasie.$B$BCzemu by nie zabrać ich?$B$BA ściślej mówiąc, czemu TY $gmiałbyś:miałabyś; ich nie zabrać?', 'Kwatermistrz Bartlett w Jadozłości prosi, żebyś $gukradł:ukradła; 8 zbroi Szkarłatnego Szturmu i 8 sztuk broni Szkarłatnego Szturmu.', '', 'Wróć do kwatermistrza Bartletta w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12211, 'plPL', 'Niech nie powstaną!', 'Nie rozumiem tego. Zaraza powinna była zadziałać!$B$BNie ma co się teraz tym martwić.$B$B<Aptekarka z jakiegoś powodu wydaje się odczuwać ulgę.>$B$BChoć z jakiegoś dziwnego powodu nie działa na Szturm, wciąż musimy powstrzymać ich kapłanów przed wskrzeszaniem poległych.$B$BMam inny pomysł, przed którym ich zwłoki nie powinny mieć żadnej ochrony.$B$B$N, weź pojemnik z moimi szczurami i wypuść je na wszystkie zwłoki członków Szturmu, na jakie natrafisz w Nowym Żagiewiu. Głodzę te szkodniki, więc powinny być żarłoczne!', 'Aptekarka Vicky Levine w Jadozłości prosi, żebyś $gużył:użyła; jej pojemnika ze szczurami, by ogryzły do czysta zwłoki 15 członków Szkarłatnego Szturmu w Nowym Żagiewiu.', '', 'Wróć do aptekarki Vicky Levine w Jadozłości na Smoczych Pustkowiach.', 'Zwłoki członków Szkarłatnego Szturmu ogryzione do czysta', '', '', '', 0),
(12214, 'plPL', 'Świeże wierzchowce', 'Dzień dobry. Jestem Hansel. Miło mi cię poznać, $gpanie:pani;.$B$BPrzyszedł do mnie najwyższy egzekutor i powiedział: „Hansel, zdobądź nam nowe wierzchowce”.$B$BA skąd on myśli, że biorą się upiorne rumaki? Z ziemi?$B$B<szeptem> Właściwie tak, jeśli znajdzie się cmentarz koni.$B$BAle takiego nie mamy, więc musisz pójść na południe do Nowego Żagiewia, zabić rycerzy, zabrać im szpicruty i ukraść ich konie bojowe.$B$BPrzyjedź tu do mnie na koniu i oddaj mi wodze, jeśli łaska.', 'Hansel Bauer w Jadozłości prosi, żebyś $gukradł:ukradła; 3 konie bojowe Szturmu i $gdostarczył:dostarczyła; mu je, przekazując przy tym wodze.', '', 'Wróć do Hansela Bauera w Jadozłości na Smoczych Pustkowiach.', 'Wodze koni bojowych Szkarłatnego Szturmu przekazane', '', '', '', 0),
(12218, 'plPL', 'Nieś dobrą nowinę', 'Zanim wyślę cię z dobrą nowiną do doktora Malefiousa, musisz przeprowadzić prostą próbę polową zarazy z moimi poprawkami.$B$BWygłodniałe trupy wylewają się z tego, co zostało ze Starej Zimowej Straży. Przejmij pojazd przy wschodniej bramie i jedź nim na północny wschód przez Przełęcz Zemsty, aż dotrzesz do bliźniaczych wież na południowo-wschodnim skraju Zimowej Straży. Zrzuć bombę zarazy na nieumarłych, którzy pokrywają okolicę. Wróć do mnie z wynikami!', 'Główny siewca zarazy Middleton w Jadozłości na Smoczych Pustkowiach chce, żebyś $gużył:użyła; bomby zarazy roznosiciela zarazy Porzuconych, by zniszczyć 30 wygłodniałych trupów na obrzeżach Pól Padliny.', '', 'Wróć do głównego siewcy zarazy Middletona w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12221, 'plPL', 'Zaraza Porzuconych', 'Przygotowałem przesyłkę, którą trzeba dostarczyć doktorowi Sintarowi Malefiousowi w Młocie Agmara. W przesyłce jest ostateczna próbka zarazy wraz z instrukcją przygotowania i próbkami czynnika reaktywnego.$B$BMłot Agmara znajdziesz w zachodniej części Smoczych Pustkowi. Wypatruj po prostu czarnych, najeżonych metalem orczych budowli – to będzie Młot Agmara.$B', 'Dostarcz zarazę Porzuconych doktorowi Sintarowi Malefiousowi w Młocie Agmara.', '', 'Wróć do doktora Sintara Malefiousa w Młocie Agmara na Smoczych Pustkowiach.', '', '', '', '', 0),
(12224, 'plPL', 'Awangarda Kor\'kronu!', 'Dobrze się $gspisałeś:spisałaś;, $gbracie:siostro;. Wszystkiemu, z czym się $gzmierzyłeś:zmierzyłaś;, $gstawiałeś:stawiałaś; czoła jako $gobrońca:obrończyni; Hordy. Splugawieni przez Plagę Anub\'ar z Azjol-Nerub zmiażdżeni pod twoją stopą! Taunka, dzielni i potężni nowi członkowie Hordy – dzięki tobie! Nasza superbroń przeciw Pladze, wypróbowana i udoskonalona przez ciebie!$B$BNadszedł czas, nadeszła ta chwila – nasi elitarni żołnierze pod Bramą Gniewu cię potrzebują. Syn Zaurzykła czeka na ciebie w Awangardzie Kor\'kronu. Ruszaj teraz na północny wschód, do Bramy Gniewu.', 'Zamelduj się u Zaurzykła Młodszego w Awangardzie Kor\'kronu.', '', '', '', '', '', '', 0),
(12230, 'plPL', 'Kradzież u kowali oblężniczych', 'Mam za zadanie zniszczyć balisty Szkarłatnego Szturmu. Niestety, nie zgadzam się z aptekarzami co do wykorzystania naszych zasobów, więc nie mam ich czym zniszczyć!$B$BNa północny wschód stąd leżą Pola Padliny. Tamtejsi kowale oblężniczy Plagi przy swojej kuźni i wozach z mięsem to mistrzowie wyburzania.$B$BNa nasze szczęście zostawiają swoje bomby gdzie popadnie.$B$BChcę, żebyś mi je $gzdobył:zdobyła; – z ziemi albo od kowali oblężniczych, wszystko jedno.', 'Strażnik śmierci Molder w Jadozłości prosi, żebyś $gzdobył:zdobyła; 6 bomb kowala oblężniczego.', '', 'Wróć do strażnika śmierci Moldera w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12232, 'plPL', 'Zbombarduj balisty', 'Wreszcie mamy okazję uderzyć w ich machiny oblężnicze! Nie spartacz tego.$B$BŻartuję.$B$BTrochę.$B$B$N, zbombarduj tymi bombami balisty Nowego Żagiewia.$B$BPokażemy Królewskim Zakładom Chemicznym, jak to się robi po staremu. Żadne mikstury nie są potrzebne!', 'Strażnik śmierci Molder w Jadozłości prosi, żebyś $gużył:użyła; bomb kowala oblężniczego, by zbombardować 5 balist Nowego Żagiewia.', '', 'Wróć do strażnika śmierci Moldera w Jadozłości na Smoczych Pustkowiach.', 'Zbombardowana balista Nowego Żagiewia', '', '', '', 0),
(12234, 'plPL', 'Muszę wiedzieć', 'Muszę wiedzieć, co knuje Nowe Żagiewie.$B$BChcę, żebyś $gukradł:ukradła; ich rozkazy dzienne, żebym mogła się tego dowiedzieć.$B$BIdź na południe i znajdź te dzienne plany w ich opactwie, w koszarach i na plaży!$B$BGdyby coś ci się myliło: koszary to duży budynek tuż obok kuźni.', 'Mistrzyni szpiegów Repine w Jadozłości prosi, żebyś $gukradł:ukradła; rozkazy dzienne Szkarłatnego Szturmu: opactwo, rozkazy dzienne Szkarłatnego Szturmu: koszary i rozkazy dzienne Szkarłatnego Szturmu: plaża.', '', 'Wróć do mistrzyni szpiegów Repine w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12235, 'plPL', 'Naxxramas i upadek Zimowej Straży', 'Lord Fordragon poprowadził miażdżący atak na Arthasa pod Bramą Gniewu. W odpowiedzi na tę zniewagę Arthas zesłał na nas Naxxramas. Podczas gdy Kel\'Thuzad kryje się w unoszącej się cytadeli, jego dowódca sił lądowych, Thel\'zan, oblega Twierdzę Zimowej Straży. Dolna wioska jest już stracona, a szanse na wydostanie ocalałych z ruin maleją z każdą minutą.$B$BMusimy działać szybko! Natychmiast zamelduj się u dowódcy gryfów Urika na stacji gryfów! Wprowadzi cię w sytuację.$B$BZostaw mnie!$B', 'Porozmawiaj z dowódcą gryfów Urikiem na stacji gryfów w Twierdzy Zimowej Straży.', '', '', '', '', '', '', 0),
(12237, 'plPL', 'Lot obrońcy Zimowej Straży', 'Tym gwizdkiem możesz przywołać gryfa Zimowej Straży. Dosiądź go i leć w stronę ruin Wioski Zimowej Straży, zwanych teraz Polami Padliny, na południowy wschód stąd. Gdy dotrzesz na pola, wypatruj bezradnych mieszkańców Zimowej Straży. Gdy któregoś zauważysz, zniż lot i zabierz go za pomocą gryfa. Przywieź uratowanego mieszkańca tutaj, na stację gryfów.$B$BWszędzie roi się od Plagi, więc musisz zachować czujność, bohaterze. Powodzenia!', 'Uratuj 10 bezradnych mieszkańców Zimowej Straży i wróć do dowódcy gryfów Urika w Twierdzy Zimowej Straży.', '', 'Wróć do dowódcy gryfów Urika w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Uratowany bezradny mieszkaniec', '', '', '', 0),
(12239, 'plPL', 'Szpieg w Nowym Żagiewiu', 'Mam szpiega w szeregach Szkarłatnego Szturmu. Musisz jej dostarczyć te rozkazy dzienne, żeby mogła zaplanować następny etap naszego natarcia.$B$BPosługuje się imieniem Agentka Skully i dzięki magicznemu przebraniu wygląda jak dozorczyni cmentarza Szturmu.$B$BProszę, zanieś jej te rozkazy, a potem zrób, o co cię poprosi. Cmentarz znajdziesz z boku opactwa.', 'Dostarcz rozkazy dzienne Szkarłatnego Szturmu agentce Skully w Nowym Żagiewiu.', '', 'Wróć do agentki Skully na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(12240, 'plPL', 'Środek do celu', 'W ostatniej dostawie dostałam od siostry z Barykady, z domu, kilka beczek termitów. Myślę, że przydadzą się do czegoś, co dla ciebie zaplanowałam.$B$BTartak w Nowym Żagiewiu sprawia nam kłopoty, ale jak dotąd nie udało nam się nikogo tam przemycić, żeby załatwił ich brygadzistę.$B$BMyślę, że gdybyś $gwypuścił:wypuściła; te termity na jego ukochane drewniane konstrukcje, na pewno przybiegłby w te pędy.$B$B$GGotów:Gotowa;, żeby go załatwić, $N?', 'Aptekarka Vicky Levine z Jadozłości prosi cię o użycie termitów rodziny Levine, by wywabić brygadzistę Kaleikiego z kryjówki i go zabić.', '', 'Wróć do aptekarki Vicky Levine w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12243, 'plPL', 'Ogień na wodach', 'Mam dla ciebie kolejną misję.$B$BUdało mi się przerobić trochę zarazy i uwarzyć z niej moją słynną na cały świat płonącą wodę. Weź ją i podpal żagle Szaleństwa Grzesznika!$B$BUżyj jej z pomostu. Gdy żagle zajmą się ogniem, majtkowie rzucą się do gaszenia, a ty wślizgniesz się pod pokład, by „odzyskać” locje kapitana.$B$BStatek znajdziesz przy Przystani Krzyżowca, u stóp Nowego Żagiewia, na południe od niego. Kajuty kapitana szukaj na pierwszym dolnym pokładzie, za schodami.', 'Aptekarka Vicky Levine z Jadozłości prosi cię o podpalenie żagli Szaleństwa Grzesznika za pomocą jej płonącej wody aptekarza.$B$BGdy majtkowie będą zajęci gaszeniem ognia, zejdź pod pokład i zabierz kapitanowi locje kapitana Shely\'ego.', '', 'Wróć do aptekarki Vicky Levine w Jadozłości na Smoczych Pustkowiach.', 'Podpalone żagle Szaleństwa Grzesznika', '', '', '', 0),
(12245, 'plPL', 'Bez litości dla pojmanych', 'Mamy dla ciebie kolejnych głupców do zabicia.$B$BMoi agenci donoszą, że kilku naszych zacnych obywateli raczyło wpaść w ręce Szkarłatnego Szturmu.$B$BTak być nie może.$B$BWróć do Nowego Żagiewia i zlikwiduj strażniczkę śmierci Schneider, starszego skrybę Barrigę, inżyniera Burke\'a i kanclerza Amai.$B$BZ tego, co słyszę, są rozproszeni po całej okolicy. Bez wątpienia trzymają ich w klatkach, gdzie czekają na tortury.$B$BPorozmawiaj z nimi, a potem ich zabij!', 'Mistrzyni szpiegów Repine poleciła ci zabić strażniczkę śmierci Schneider, starszego skrybę Barrigę, inżyniera Burke\'a i kanclerza Amai.$B$BGdy wykonasz to zadanie, zamelduj o sukcesie najwyższemu egzekutorowi Wrothowi w Jadozłości.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12251, 'plPL', 'Powrót do wielkiego komendanta', 'Natychmiast wróć do wielkiego komendanta Halforda Zmory Żmijów, $N. Przekaż mu, że twoja misja zakończyła się sukcesem, a nieliczni uratowani mieszkańcy wrócili do pracy.', 'Porozmawiaj z wielkim komendantem Halfordem Zmorą Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12252, 'plPL', 'Tortury dla oprawcy', 'Dość! Chcę, żebyś $gpołożył:położyła; kres torturom moich ludzi!$B$BOprawca Szturmu, LeCraft, wyciska informacje z każdego, kto wpadnie w łapy tych potworów! Muszę wiedzieć to, co oni wiedzą.$B$BMoje źródła donoszą, że urządził się w piwnicy ich koszar, tuż obok kuźni.$B$BPożyczę ci moje osobiste żelazo do piętnowania, żeby robota została wykonana jak należy.$B$BZnajdź go i wydobądź te informacje.', 'Najwyższy egzekutor Wroth z Jadozłości chce, żebyś 5 razy $gprzypalił:przypaliła; oprawcę LeCrafta żelazem do piętnowania i $gwydobył:wydobyła; z niego informacje. Następnie go zabij.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', 'Oprawca LeCraft w pełni przesłuchany', '', '', '', 0),
(12253, 'plPL', 'Ratunek na Rynku', 'Tą ścieżką w dół dojdziesz do rynku Zimowej Straży. Niegdyś tętnił życiem mieszkańców, dziś to pole bitwy pełne morderczych fantomów, żądnych zemsty na żywych.$B$BW budynkach wokół rynku są uwięzieni mieszkańcy, których trzeba uratować! Wiele od ciebie wymagam, $N, ale jesteś jedynym żołnierzem, którego mogę tam posłać. Uwolnij naszych ludzi. Zejdź tą ścieżką na rynek i wejdź do tamtych domów. Zabij wszystko, co stanie ci na drodze! Jeśli przeżyjesz, wróć do mnie.', 'Wielki komendant Halford Zmora Żmijów z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $guratował:uratowała; 6 uwięzionych mieszkańców Zimowej Straży.', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Uratowani mieszkańcy Zimowej Straży', '', '', '', 0),
(12254, 'plPL', 'Bez modlitwy', 'Z tych planów wynika, że szykuje się coś, co nastąpi lada chwila.$B$BNajpierw jednak trzeba się zająć tą dziwną ochroną, którą cieszą się siły Szturmu. Jeśli Jadozłość ma się z nimi rozprawić raz na zawsze, musimy się dowiedzieć, kto za tym stoi, i go wyeliminować.$B$BZauważyłam, że biskup z kaplicy na drugim końcu Nowego Żagiewia, naprzeciwko tartaku, coraz częściej błogosławi żołnierzy. Zabij go i ukradnij jego modlitewnik.$B$BMoże znajdziemy w nim jakąś wskazówkę.', 'Agentka Skully z Nowego Żagiewia prosi cię o zdobycie modlitewnika biskupa Streeta.', '', 'Wróć do agentki Skully w Nowym Żagiewiu na Smoczych Pustkowiach.', '', '', '', '', 0),
(12258, 'plPL', 'Los umarłych', 'Rynek, w dole tej ścieżki, roi się od nieumarłych mieszkańców Zimowej Straży! Nasza własna krypta dostarcza Pladze pozornie niewyczerpany zapas żołnierzy, których rzuca przeciwko nam. Nie okazuj im jednak litości, $N. Choć niegdyś byli śmiertelnikami zdolnymi do współczucia i myślenia, teraz to siejący spustoszenie nieumarli o jednym celu: naszej zagładzie.$B$BRuszaj na rynek i poślij mściwe fantomy do ich stwórcy. Daj im ukojenie.', 'Komendantka Lynore Uderzenie Wiatru z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $gzabił:zabiła; 15 mściwych fantomów.$B', '', 'Wróć do komendantki Lynore Uderzenia Wiatru w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12260, 'plPL', 'Doskonała maskarada', 'Pewnie się zastanawiasz, jak utrzymuję to przebranie. Używam magicznego lustra, które pożyczyła mi mistrzyni szpiegów.$B$BMa ograniczoną moc, ale chyba wystarczy dla nas obojga. Masz, weź je. Użyj go, by podszyć się pod jednego z kapłanów Kruka Szturmu.$B$BPośpiesz się... Nie mam pojęcia, jak długo utrzyma się moja iluzja, kiedy lustro będzie u ciebie.$B$BPamiętaj, że twoje przebranie nie od razu będzie doskonałe, więc nie licz na to, że jest niezawodne, dopóki nie będę mogła ci pomóc.', 'Agentka Skully z Nowego Żagiewia prosi cię o przejęcie wizerunku kapłana Kruka Szturmu. Gdy to zrobisz, zwróć jej magiczne lustro banshee.', '', 'Wróć do agentki Skully w Nowym Żagiewiu na Smoczych Pustkowiach.', 'Wizerunek kapłana Kruka Szturmu przejęty', '', '', '', 0),
(12261, 'plPL', 'Nie ma dokąd uciec', 'Czerpią moc z kości moich martwych braci...$B$BNie darzę kultu sympatią, ale ich zuchwałość wprawia mnie w osłupienie. Nie okażę im litości... zresztą nigdy bym jej nie okazał.$B$BDopilnuj, by nie mieli dokąd uciec, gdy zacznie się rzeź. Umieść niszczycielską osłonę na końcu ścieżki wychodzącej ze świątyni... tam, gdzie droga ustępuje śniegowi. Broń jej, dopóki w pełni się nie naładuje.', 'Umieść niszczycielską osłonę na końcu ścieżki wychodzącej z Obsydianowej Smoczej Świątyni, tam, gdzie droga ustępuje śniegowi. Chroń osłonę, dopóki w pełni się nie naładuje, a potem wróć do Serinara.', '', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', 'Niszczycielska osłona w pełni naładowana', '', '', '', 0),
(12262, 'plPL', 'Nikt cię nie ocali', 'Nikogo nie oszczędzimy.$B$BNa zewnątrz nędzni nekrolici i ich szkieletowi słudzy hańbią moją ziemię swoją obecnością. Wyrżnij ich wszystkich.', 'Zabij 6 nekrolitów z Płonących Głębin i 10 tlących się szkieletów przed Obsydianową Smoczą Świątynią. Po wykonaniu zadania wróć do Serinara.', '', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', '', '', '', '', 0),
(12263, 'plPL', 'Najlepsze zamiary', 'Kult Potępionych nie przybył tu tylko po to, by wydobywać moc z martwych smoków. Podejrzewam, co knują, ale potrzebuję, żebyś $gpotwierdził:potwierdziła; moje przypuszczenia.$B$BNadam ci postać tego martwego nekrolity. Udaj się w głąb jaskini i sprawdź, po co przybyli do tego świętego miejsca. Będę patrzył twoimi oczami.$B$BUważaj, $N, każda odniesiona rana może rozwiać tę kruchą iluzję.', 'Poczekaj, aż Serinar nada ci wygląd nekrolity z Płonących Głębin, a następnie udaj się w głąb Paszczy Neltharionu i odkryj, co robi tam Kult Potępionych. Wróć do Serinara ze szczegółami na temat ich zamiarów.', 'Odkryj komorę wskrzeszeń magmowego żmija', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', '', '', '', '', 0),
(12264, 'plPL', 'Przetrzebienie Potępionych', 'Jaskinia w głębi roiła się od plugastw Kultu. Z takimi stworami można się rozprawić tylko w jeden sposób... wiesz, co robić.', 'Zabij 3 nekromantów z Płonących Głębin, 6 tlących się konstruktów i 6 tlących się fantomów w Paszczy Neltharionu, a następnie wróć do Serinara.', '', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', '', '', '', '', 0),
(12265, 'plPL', 'Profanacja profanatorów', 'Wyczułem wielkie nagromadzenie magii w runach, które widzieliśmy podczas twojego zwiadu w jaskini. Nie pozwolę ci bawić się w wydobywanie tej magii... najprostsze rozwiązanie często jest najskuteczniejsze.$B$BZniszcz runy... zadepcz je i dopilnuj, by Kult nie miał dostępu do mocy, jaką tam zgromadził.', 'Odnajdź i zadepcz 8 nekromanckich run wyrysowanych na podłodze w Paszczy Neltharionu. Po wykonaniu zadania wróć do Serinara.', '', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', 'Zniszczone nekromanckie runy', '', '', '', 0),
(12266, 'plPL', 'Opowieści o zniszczeniu', 'Możesz już odejść.$B$BIdź i powiedz Nalice, że ominęła ją wspaniała rzeź.', 'Wróć do Świątyni Żmijowego Spoczynku i przekaż Nalice, że zadanie Serinara zostało wykonane.', '', '', '', '', '', '', 0),
(12267, 'plPL', 'Płomień Neltharionu', 'Skoro szeregi kultu są przerzedzone, a część jego mocy odebrana, pora uderzyć w źródło skażenia.$B$BRothin Gnijący wskrzesza czarne smoki jako magmożmije w głębi jaskini. Udaj się do komory przywołań i oczyść pozostałe kości jedynym sposobem, który zagwarantuje, że nikt już nigdy nie będzie się nimi bawił... ogniem.$B$BPalenie kości z pewnością przyciągnie uwagę Rothina. Dopilnuj, by i on został zniszczony.$B$BMagia z tej fiolki powinna wystarczyć.', 'Użyj Płomienia Neltharionu, by oblać nim miejsce przywołań w głębi Paszczy Neltharionu. Gdy zwrócisz na siebie uwagę Rothina Gnijącego, zabij go, a następnie wróć do Serinara u wejścia do jaskini.', '', 'Wróć do Serinara w Paszczy Neltharionu na Smoczych Pustkowiach.', 'Miejsce przywołań oczyszczone', '', '', '', 0),
(12269, 'plPL', 'Nie w naszej kopalni', 'Ta przeklęta nekropolia zaskoczyła nas znienacka! W wyniku jej ataku straciliśmy Kopalnię Zimowej Straży. Co gorsza, akolici Kel\'Thuzada wskrzesili poległych górników jako sługi Plagi i każą im dostarczać swoim kowalom oblężniczym materiały z naszej kopalni!$B$BTrzeba przerwać tę linię zaopatrzenia, a naszym utraconym braciom dać wieczny spoczynek.$B$BUdaj się do Kopalni Zimowej Straży, na północny wschód stąd, na Polach Padliny, i zniszcz powstałych górników. Przynieś mi ich karty górnicze, abym mógł odnotować ich śmierć w naszym rejestrze.', 'Najwyższy lord Leoric Von Zeldig z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $godzyskał:odzyskała; 10 kart górnika z Zimowej Straży.', '', 'Wróć do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12271, 'plPL', 'Różdżka przymusu', 'Z martwej dłoni LeCrafta wypada różdżka. Na całej jej długości pulsują magiczne runy.$B$BCzy to w ten sposób wymuszał zeznania?$B$BLepiej pokazać ją najwyższemu egzekutorowi.', 'Dostarcz różdżkę oprawcy najwyższemu egzekutorowi Wrothowi w Jadozłości.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12272, 'plPL', 'Krwawiąca ruda', 'Na kilka godzin przed inwazją Naxxramas jeden z górników natrafił na ciemną rudę, z której sączył się lepki płyn. W chaosie ewakuacji kopalni straciliśmy próbki pobrane z tego obcego złoża. Teraz Plaga wydobywa tę rudę na potrzeby swoich machin śmierci.$B$BMusisz wrócić do Kopalni Zimowej Straży, prosto na północny wschód stąd, na Polach Padliny, i zdobyć dziwną rudę. To kluczowe dla powodzenia naszej misji!', 'Inżynier oblężniczy Quarterflash z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $gzdobył:zdobyła; 10 próbek dziwnej rudy z Kopalni Zimowej Straży.', '', 'Wróć do inżyniera oblężniczego Quarterflasha w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12273, 'plPL', 'Wyrzeczenie', 'Czas całkowicie zdemoralizować siły Szturmu!$B$BWeź różdżkę i użyj jej na czterech ich przywódcach: komendancie Jordanie na piętrze koszar, głównym artylerzyście Zierhucie w dole południowo-wschodniej rampy z widokiem na plażę, kowalu Goodmanie w kuźni i stajennym Mercerze w stajniach.$B$BPoddaj ich mocy różdżki, skup się na tym, by wyrzekli się Szturmu, a potem ich zabij!', 'Najwyższy egzekutor Wroth z Jadozłości zlecił ci użycie różdżki przymusu na komendancie Jordanie, głównym artylerzyście Zierhucie, kowalu Goodmanie i stajennym Mercerze.$B$BGdy użyjesz na nich różdżki, zabij każdego z nich, by ich ostatnimi słowami było wyrzeczenie się Szkarłatnego Szturmu.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', 'Wyrzeczenie i śmierć komendanta Jordana', 'Wyrzeczenie i śmierć głównego artylerzysty Zierhuta', 'Wyrzeczenie i śmierć kowala Goodmana', 'Wyrzeczenie i śmierć stajennego Mercera', 0),
(12274, 'plPL', 'Upadek z łaski', 'Potrzebujemy więcej informacji od wielkiego opata, a skoro mamy już wizerunek jednego z kapłanów Kruka, chyba zdołamy cię do niego podprowadzić na rozmowę.$B$BNiestety, musimy go odciągnąć od ochroniarzy, inaczej niczego z niego nie wyciągniesz.$B$B<Agentka opiera się na łopacie i przez chwilę się zastanawia.>$B$BMam! W przebraniu wejdź na szczyt opactwa i uderz w dzwon. To powinno ściągnąć biegiem ochroniarzy opata, a wtedy zejdziesz na dół i z nim porozmawiasz.', 'Agentka Skully z Nowego Żagiewia prosi cię, abyś $guderzył:uderzyła; w dzwon opactwa, a potem $gporozmawiał:porozmawiała; z wielkim opatem i $gwydobył:wydobyła; z niego informacje.', '', 'Wróć do agentki Skully w Nowym Żagiewiu na Smoczych Pustkowiach.', 'Dzwon opactwa rozbrzmiał', 'Rozmowa z wielkim opatem', '', '', 0),
(12275, 'plPL', 'Gnom-saper', 'Quarterflash niedawno zażądał od mojego oddziału specjalisty, którego mógłby wysłać na zwiad do Kopalni Zimowej Straży. Posłałem mu więc Slinkina, mojego sapera. Głupio sądziłem, że po wykonaniu misji dla Quarterflasha Slinkin zdoła zamknąć tę otchłań potępienia, co dałoby nam kolejne zwycięstwo nad Plagą.$B$BMinął już cały dzień, a Slinkin nie wrócił. Chcę odpowiedzi! Porozmawiaj z inżynierem oblężniczym Quarterflashem i odnajdź mojego zaginionego agenta!', 'Porozmawiaj z inżynierem oblężniczym Quarterflashem w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12276, 'plPL', 'Poszukiwania Slinkina', 'Choć nie mam wieści od Slinkina ani nie wiem, jaki los go spotkał, może zdołam pomóc go odnaleźć.$B$B<Quarterflash unosi maleńką mechaniczną zabawkę.>$B$BTo nie zabawka, $gmój nowy towarzyszu:moja nowa towarzyszko;. To w istocie mój najnowszy mechaniczny wynalazek. Maszynę stworzono wyłącznie po to, by odnajdywała to, co zaginęło. Okoliczności są niefortunne, ale ta maszyna to twoja największa szansa na odnalezienie Slinkina.$B$BGdy $gbędziesz gotów:będziesz gotowa; rozpocząć poszukiwania, postaw bota na ziemi obok mnie.', 'Odnajdź Slinkina Gnoma-sapera w Kopalni Zimowej Straży. Jeśli potrzebujesz pomocy w odnalezieniu kopalni, użyj samonaprowadzającego bota Quarterflasha.', '', '', '', '', '', '', 0),
(12277, 'plPL', 'Nie zostawiaj niczego przypadkowi', 'Jeśli masz dobre serce i czyste sumienie, czytaj dalej.$B$BW tej kopalni, przy rusztowaniu brygadzisty, leży spory ładunek dynamitu. Idź tam, weź kilka wiązek materiału wybuchowego i skieruj się ku wejściu do kopalni. Na miejscu podłóż dynamit i wysadź wejście. Pamiętaj, by zrobić to przy górnym i dolnym wejściu do Kopalni Zimowej Straży.$B$BNie możesz niczego zostawić przypadkowi. Zło, które tu mieszka, nigdy nie może wydostać się na zewnątrz. Niech Światłość cię prowadzi.', 'Zdobądź bombę z Kopalni Zimowej Straży i użyj jej, by wysadzić górny szyb Kopalni Zimowej Straży i dolny szyb Kopalni Zimowej Straży. Po wykonaniu zadania zamelduj się u inżyniera oblężniczego Quarterflasha w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do inżyniera oblężniczego Quarterflasha w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Górny szyb Kopalni Zimowej Straży zniszczony', 'Dolny szyb Kopalni Zimowej Straży zniszczony', '', '', 0),
(12281, 'plPL', 'Zrozumieć machinę wojenną Plagi', 'Musimy się pocieszać tym, że śmierć Slinkina, choć tragiczna, posłużyła większemu dobru. Jego odkrycie, twoje bohaterstwo w kopalni i przyniesione przez ciebie próbki przybliżają nas o krok do zrozumienia machiny wojennej Plagi.$B$BZanieś tę paczkę wielkiemu komendantowi Halfordowi Zmorze Żmijów. Zawiera próbkę dziwnej rudy i moją analizę.', 'Dostarcz paczkę Quarterflasha wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży.', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12282, 'plPL', 'Piętno przeszłości', 'Wspomnienia przeszłości nawiedzają tę krainę, $N. Słyszę, jak krzyki poległych niosą się echem po Północnej Grani – wzywają mnie.$B$BArthas odcisnął straszliwe piętno na wszystkim, czego dotknął. Po jego przejściu zostały jedynie uwiąd i rozkład. Dlatego tak ważne jest, byśmy badali przeszłość i lepiej poznali naszego wroga. Być może wyjdą na jaw nieznane prawdy, które pomogą nam w tej kampanii.$B$BNajpierw musisz odzyskać moją wróżebną kulę z ratusza, $N. Wyjdź z tej wieży i skręć w lewo, w dół ścieżki, by dotrzeć do rynku.', 'Zelig Wizjoner z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $godzyskał:odzyskała; jego wróżebną kulę.', '', 'Wróć do Zeliga Wizjonera w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12283, 'plPL', 'Prawda wyjdzie na jaw', 'Musimy się dowiedzieć, co tu się dzieje. Potrzebujemy pamiętnika generał!$B$BJestem prawie pewna, że znajdziesz go na nocnym stoliku na piętrze jej domu. To ten obok kościoła, naprzeciwko stajni i tartaku.$B$BGdy zdobędziesz pamiętnik, zanieś go najwyższemu egzekutorowi w Jadozłości.$B$BTym razem musisz to zrobić staromodnym sposobem; lustro ma już mało mocy i wystarczy jej tylko dla mnie.$B$B<Agentka uśmiecha się z przekąsem.>', 'Agentka Skully prosi cię o zdobycie pamiętnika najwyższej generał Abbendis i dostarczenie go najwyższemu egzekutorowi Wrothowi w Jadozłości.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12285, 'plPL', 'Jak ty komu, tak on tobie', 'Ich atak jest nieuchronny, $N. Musisz się tam dostać i ściąć głowę Szkarłatnego Szturmu – dosłownie!$B$BNie będzie łatwo... Abbendis z pewnością otacza wielu jej ludzi. Radzę ci zabrać ze sobą co najmniej paru przyjaciół.$B$BPrzynieś mi jej głowę, a dopilnuję, byś $gzostał godnie nagrodzony:została godnie nagrodzona; za ocalenie Jadozłości.$B$BJeśli zawiedziesz, nawet nie wracaj!', 'Najwyższy egzekutor Wroth z Jadozłości rozkazał ci wrócić z głową najwyższej generał.', '', 'Wróć do najwyższego egzekutora Wrotha w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12287, 'plPL', 'Orik Prawe Serce i Zapomniany Brzeg', 'Wpatrywałem się w kulę i ujrzałem ścieżkę, którą musisz podążyć, $N.$B$BWiele lat temu na brzegach Smoczych Pustkowi dokonano okrucieństwa. Sam czyn wciąż spowija ciemność, ale jestem pewien, że twoje przeznaczenie leży na południu, pośród ruin Zapomnianego Brzegu.$B$BRuszaj drogą na południowy wschód przez spustoszony rynek. Podążaj szlakiem, aż dotrzesz do Zasięgu Brzasku. Spotkasz tam mojego starego przyjaciela, Orika Prawe Serce. Będzie na ciebie czekał.', 'Poszukaj pomocy Orika Prawego Serca w Zasięgu Brzasku na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12290, 'plPL', 'Eliksir z mrocznego zielska', 'Duchy potępionych nawiedzają wybrzeże. Za życia byli dzielnymi i szlachetnymi żołnierzami Przymierza, lecz po śmierci ciąży na nich klątwa – są przykuci do tego świata aż do końca dni. Jeśli mamy ich uwolnić, musimy odkryć źródło ich udręki!$B$BNa południowym wschodzie, na Niesamowitych Wyżynach, znajdziesz rzadkie zioło zwane mrocznym zielskiem. Przyrządzę z niego eliksir, który pozwoli ci na krótko wkroczyć do świata zapomnianych. Idź teraz i zbierz to zielsko.', 'Orik Prawe Serce z Zasięgu Brzasku na Smoczych Pustkowiach chce, abyś $gzebrał:zebrała; 5 sztuk mrocznego zielska na Niesamowitych Wyżynach.', '', 'Wróć do Orika Prawego Serca w Zasięgu Brzasku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12291, 'plPL', 'Zapomniana opowieść', 'Toksyny zawarte w eliksirze z mrocznego zielska pozbawią cię przytomności. Działanie mrocznego zielska jest tak silne, że nawet twój duch da się oszukać, co pozwoli ci na krótko wkroczyć do świata umarłych.$B$BJako duch musisz porozmawiać z widmowymi mieszkańcami Zapomnianego Brzegu. Odkryj przyczynę ich udręki i wróć do mnie.$B$BPamiętaj, $N, te duchy były niegdyś żołnierzami Przymierza. Traktuj je z szacunkiem, czcią i godnością.$B$BA teraz, z eliksirem w ręku, wyrusz na południe, na Zapomniany Brzeg.', 'Orik Prawe Serce z Zasięgu Brzasku na Smoczych Pustkowiach chce, abyś $gwysłuchał:wysłuchała; opowieści zapomnianego chłopa, zapomnianego strzelca, zapomnianego rycerza i zapomnianego piechura.', '', 'Wróć do Orika Prawego Serca w Zasięgu Brzasku na Smoczych Pustkowiach.', 'Zapomniany chłop wypytany', 'Zapomniany strzelec wypytany', 'Zapomniany rycerz wypytany', 'Zapomniany piechur wypytany', 0),
(12301, 'plPL', 'Prawda nas wyzwoli', 'Zelig dał mi tę kryształową kulę przed laty, z dokładnymi wskazówkami, jak jej używać. Przez pięć lat – za każdym razem, gdy odczuwałem gniew, niepokój lub smutek z powodu wydarzeń, które tu zaszły – miałem skupiać myśli na kuli.$B$BTeraz rozumiem, dlaczego Zelig mi ją dał.$B$BZanieś moją kryształową kulę na Zapomniany Brzeg. Odnajdź ruiny mojej dawnej bazy w górnej części plaży i umieść kulę w środku osady. Niech zapomniani ujrzą świat oczami mojego serca i duszy.', 'Orik Prawe Serce z Zasięgu Brzasku na Smoczych Pustkowiach chce, abyś $gużył:użyła; kryształowej kuli Orika w ruinach na Zapomnianym Brzegu, by odkupić Zapomnianych.', 'Zapomniani odkupieni', 'Wróć do Orika Prawego Serca w Zasięgu Brzasku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12303, 'plPL', 'Fundusze na wojnę', '<Kwatermistrz zniża głos i szepcze do ciebie.>$B$BPotrzebuję twojej pomocy; nasze skarbce są puste. Awangarda Kor\'kronu przy Bramie Gniewu zabrała całą naszą gotówkę na tamtejszą walkę.$B$BAle słyszałem pogłoski, że wśród wraków na Zapomnianym Brzegu, na południowym wschodzie, można znaleźć skarby.$B$BMusimy szybko coś zrobić, bo inaczej nie zdołamy dalej walczyć ze Szkarłatnym Szturmem. Wojna nie jest tania, wiesz!', 'Kwatermistrz Bartlett z Jadozłości prosi cię o zdobycie 6 zapomnianych skarbów.', '', 'Wróć do kwatermistrza Bartletta w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', 0),
(12304, 'plPL', 'Działka z widokiem na morze', 'Czas, by Jadozłość się rozrosła!$B$BSzturmem zajmiemy się w swoim czasie, ale chcę, żebyś $gpoprowadził:poprowadziła; nasze działania na Zapomnianym Brzegu. Ta działka ma ogromny potencjał, a do tego ten widok!$B$BNiestety, roi się tam od ludzkich duchów, rozbitków i im podobnych, którzy jeszcze nie całkiem pojęli, że nie żyją.$B$BOczyść plażę i wody przybrzeżne, a może niedługo porozmawiamy o budowie przytulnego, nowego mauzoleum na dole.', 'Mierniczy Hansen, przebywający tuż na północ od Zapomnianego Brzegu, prosi cię o zabicie 20 zapomnianych duchów.', '', 'Wróć do mierniczego Hansena na Zapomnianym Brzegu na Smoczych Pustkowiach.', 'Zabite zapomniane duchy', '', '', '', 0),
(12305, 'plPL', 'Myśli na pożegnanie', '$GUhonorowałeś:Uhonorowałaś; mnie i pamięć setek weteranów Przymierza, $N. Zelig mądrze zrobił, przysyłając cię tutaj. Proszę, wróć do niego i przekaż mu moje podziękowania. Ucieszy się, gdy usłyszy, co wydarzyło się na Zapomnianym Brzegu.$B$BNie mam daru jasnowidzenia jak Zelig, ale jestem pewien, że czekają cię wielkie rzeczy, $gprzyjacielu:przyjaciółko;.$B$BŻegnaj.$B', 'Wróć do Zeliga Wizjonera w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12309, 'plPL', 'Odnajdź Durkona!', 'Gdy Plaga przełamała południowy mur, rozkazałem kawalerzyście Durkonowi zbadać miejską kryptę. Przed chwilą doręczono mi jego raport.$B$BNieumarli, którzy nas nękają, przybywają z dwóch źródeł: z ruin Zimowej Straży, które stały się wylęgarnią Plagi, i z naszej własnej miejskiej krypty! W chaosie i zamieszaniu Plaga zdołała wprowadzić do krypty nekrowładcę.$B$BW swojej wiadomości Durkon poprosił o wsparcie. Odnajdziesz go i pomożesz mu, $N. Krypta znajduje się na zachodnim skraju rynku.', 'Odszukaj kawalerzystę Durkona w Krypcie Zimowej Straży na Smoczych Pustkowiach.$B', '', '', '', '', '', '', 0),
(12311, 'plPL', 'Krypta możnych', 'W zimnych kamiennych murach tej krypty spoczywają szczątki szlachciców i dostojników, którzy zmarli w Północnej Grani. W samym jej sercu zasiadł teraz nekrowładca, który wskrzesza zwłoki jako sługi Plagi.$B$BMusisz dotrzeć na samo dno Krypty Zimowej Straży i zabić nekrowładcę Amariona. Dopiero wtedy ustanie atak od środka!$B$BI jeszcze jedno, $N: rozglądaj się za wszelkimi informacjami, które mogą leżeć w komnacie, w której przebywa Amarion.$B', 'Kawalerzysta Durkon z Twierdzy Zimowej Straży chce, abyś $gzabił:zabiła; nekrowładcę Amariona.', '', 'Wróć do kawalerzysty Durkona przy Krypcie Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12312, 'plPL', 'Sekrety Plagi', 'Na oprawionych w ciało rozdziałach tej księgi nagryzmolono dziwne symbole i kształty, które wyglądają, jakby wydrapano je na stronach ostrzem. Nie masz pojęcia, co tu napisano, ale masz pewność, że cokolwiek to jest, musi być ważne.$B$BDostarcz księgę kawalerzyście Durkonowi, który trzyma straż na powierzchni przy Krypcie Zimowej Straży.', 'Dostarcz księgę w oprawie z ciała kawalerzyście Durkonowi w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do kawalerzysty Durkona przy Krypcie Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12319, 'plPL', 'Tajemnica księgi', 'Co to może być, $N? Ten przeklęty lisz z pewnością nie rzucił na ciebie zwykłej klątwy!$B$B<Durkon kartkuje makabryczne stronice księgi.>$B$BNie wiem nawet, czy dobrze ją trzymam. Musimy się dowiedzieć, jakie informacje kryje ta księga!$B$B<Durkon oddaje ci księgę.>$B$BWielki komendant będzie wiedział, co robić. Zanieś mu księgę w oprawie z ciała i opowiedz dokładnie, co się tu wydarzyło.', 'Zanieś księgę w oprawie z ciała wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12320, 'plPL', 'Zrozumieć język śmierci', 'Weź księgę i idź ścieżką prowadzącą w górę do koszar. W koszarach zejdź schodami do więzienia. Znajdziesz tam inkwizytora Hallarda i naszego burmistrza, Godfreya. Sądzę, że Godfrey może być brakującym elementem tej układanki, a Hallard – człowiekiem, który złoży ją w całość.$B$BRuszaj!', 'Zanieś księgę w oprawie z ciała inkwizytorowi Hallardowi w więzieniu Twierdzy Zimowej Straży.', '', 'Wróć do inkwizytora Hallarda w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12321, 'plPL', 'Prawe kazanie', 'Godfrey Goodard, niegdyś prawy człowiek i burmistrz Zimowej Straży, jest teraz agentem Plagi. Jego przemiana z człowieka w nieśmiertelnego ghula dokonywała się powoli, z czasem. Słyszy teraz zew Króla Lisza i żyje tylko po to, by służyć swemu panu.$B$BAle jak każdy sługa Plagi, Godfrey zna język śmierci i przy odpowiedniej motywacji powie nam, co musimy wiedzieć o tej księdze.$B$BGdy usłyszysz to, co trzeba, wróć do wielkiego komendanta na linię frontu. Ja tu w razie potrzeby posprzątam.', 'Zaczekaj, aż inkwizytor Hallard skończy swoje prawe kazanie, i wróć z uzyskanymi informacjami do wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Prawe kazanie wysłuchane', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12325, 'plPL', 'Na wrogie terytorium', 'Wiele $gzrobiłeś:zrobiłaś; dla naszej walki z Plagą, $N. Co więcej, morale każdego, kto się z tobą zetknie, szybuje pod niebiosa! Taki masz wpływ na żołnierzy i mieszkańców Zimowej Straży, $gsojuszniku:sojuszniczko;.$B$BI to dzięki tobie jesteśmy teraz gotowi przejść do ofensywy! Zgłoś się do księcia Augusta Wrogomłota, po drugiej stronie Pól Padliny, w Posterunku Thorsona na wschód stąd. Dowódca gryfów Urik ze stanowiska gryfów przygotował specjalnego gryfa, który zrzuci cię za liniami wroga. Ruszaj!', 'Porozmawiaj z dowódcą gryfów Urikiem, by załatwić sobie lot do Posterunku Thorsona. Po przybyciu do Posterunku Thorsona na Smoczych Pustkowiach zgłoś się do księcia Augusta Wrogomłota.$B', '', '', '', '', '', '', 0),
(12326, 'plPL', 'Parowa niespodzianka', 'To misja typu „znajdź i zniszcz”. Poprowadzisz czołg na Pola Padliny, by rozbić wozy zarazy Plagi. Z czołgiem jedzie trzyosobowa załoga żołnierzy 7. Legionu. Wszyscy muszą przeżyć, jeśli misja ma się powieść!$B$BMusisz podjechać blisko wozu zarazy, by wypuścić swojego inżyniera. Niech zrobi swoje, a ty ruszaj do następnego. Gdy na polach nie będzie już wozów zarazy, jedź do mauzoleum przed zrujnowaną twierdzą i wysadź resztę załogi. W środku spotkasz się z Ambo Cashem.', 'Użyj parowego czołgu Przymierza, by zniszczyć 6 wozów zarazy i dowieźć elitarnych żołnierzy 7. Legionu do Mauzoleum Zimowej Straży. Jeśli ci się uda, porozmawiaj z Ambo Cashem w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', 'Porozmawiaj z Ambo Cashem w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', 'Wóz zarazy unieszkodliwiony', 'Elita 7. Legionu bezpiecznie dowieziona', '', '', 0),
(12372, 'plPL', 'Obrona Świątyni Żmijowego Spoczynku', 'Rozzuchwalone nadmiarem magii, która teraz płynie przez Lazurową Smoczą Świątynię, Błękitne Stado odważyło się zaatakować samą Świątynię Żmijowego Spoczynku!$B$BProszę, dosiądź jednego z naszych obrońców i ruszaj do boju, by zabijać ich smoki i smokowce oraz atakować wybuch energii linii mocy w samej smoczej świątyni, aby ją zdestabilizować.$B$BNa wschodnim i zachodnim tarasie znajdziesz obrońców Żmijowego Spoczynku. Porozmawiaj z jednym z nich, by ruszyć na nim do boju.$B$BBez twojej pomocy, $N, z pewnością przegramy.', 'Afrasastrasz ze Świątyni Żmijowego Spoczynku prosi cię, abyś na grzbiecie obrońcy Żmijowego Spoczynku $gzabił:zabiła; 3 lazurowe smoki i 5 lazurowych smokowców oraz $gzdestabilizował:zdestabilizowała; Lazurową Smoczą Świątynię.', '', 'Wróć do lorda Afrasastrasza w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', 'Zdestabilizuj Lazurową Smoczą Świątynię', '', 0),
(12416, 'plPL', 'Gorąca bitwa', 'Plaga opanowała świątynię. Opiekunki świątyni, Dahlii Muśniętej Słońcem, nigdzie nie ma. Czerwone żmije, które poległy w obronie świątyni, nękają nas teraz jako wypaczone, szkieletowe żarożmije. Sytuacja jest rozpaczliwa.$B$BKapitan Iskandar dowodzi grupą twoich pobratymców, którzy powstrzymują napływ Plagi ze świątyni.$B$BIdź mu z pomocą... ale proszę, trzymaj się za jego ludźmi. Plaga napływa bez końca, a nie chcę cię stracić w którymś z tych poszarpanych kanionów.', 'Pomóż kapitanowi Iskandarowi utrzymać kaniony, biorąc udział w zabiciu 12 atakujących lodowatych ghuli, 8 atakujących lodowatych fantomów i 1 atakującego lodowatego plugastwa.$B$BPo wykonaniu zadania wróć do Ceristrasza.', '', 'Wróć do Ceristrasza na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(12417, 'plPL', 'Powrót do ziemi', 'Mam kolejne zadanie, które wymaga uwagi. Moi bracia padają w bitwie na niebie i jeśli nie zadziałamy szybko, zasilą tylko szeregi żarożmijów.$B$BWejdź do świątyni jedną z pozostałych przełęczy na południu lub północy... tam Plagi powinno być mniej.$B$BPrzeszukaj świątynię w poszukiwaniu rubinowych żołędzi, które spadły z drzewa, i zasadź je przy ciałach mojego poległego rodu. W ten sposób dadzą nowe życie... to dumny los dla każdego z mojego gatunku.', 'Wejdź do Rubinowej Smoczej Świątyni przez jedną z północnych lub południowych przełęczy i poszukaj rubinowych żołędzi. Użyj rubinowych żołędzi na poległych czerwonych smokach, by zwrócić ich ciała ziemi. Po wykonaniu zadania wróć do Ceristrasza.', '', 'Wróć do Ceristrasza na Pustkowiach Smoków na Smoczych Pustkowiach.', 'Rubinowy opiekun zwrócony ziemi', '', '', '', 0),
(12418, 'plPL', 'Przez pola ognia', 'Mam dla ciebie ostatnie zadanie... takie, które powinno odwrócić losy tej walki.$B$BWróć do świątyni i zabij nekromantów, którzy podsycają to natarcie. Gdy zginą, powinniśmy zdołać odeprzeć te siły i w końcu odbić świątynię.$B$BMusisz też odnaleźć źródło skażenia pod świątynią i położyć mu kres.$B$BWiem, że wiele od ciebie wymagam, ale jeśli zrobisz to dla mnie, wygramy tę bitwę.', 'Wejdź do Rubinowej Smoczej Świątyni przez jedną z północnych lub południowych przełęczy, a następnie zabij 6 lodowatych nekromantów i usuń źródło skażenia pod świątynią. Po wykonaniu zadania wróć do Ceristrasza.', '', 'Wróć do Ceristrasza na Pustkowiach Smoków na Smoczych Pustkowiach.', '', 'Rubinowe splugawienie oczyszczone', '', '', 0),
(12419, 'plPL', 'Los Rubinowej Smoczej Świątyni', 'Gdy podnosisz broszę, jej słaby blask nieco się rozjaśnia.$B$BKrasus zechce poznać los Dahlii. Zanieś mu broszę do Żmijowego Spoczynku.', 'Zanieś rubinową broszę Dahlii Muśniętej Słońcem Krasusowi w komnacie Rady Rządzącej w Żmijowym Spoczynku i powiadom go o losie Dahlii.', '', 'Wróć do Krasusa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12435, 'plPL', 'Zgłoś się do lorda Afrasastrasza', 'Brzydzę się odbieraniem życia... jakiegokolwiek życia. Ale nie będę bezczynnie patrzeć, jak Malygos nas zabija i bezcześci świątynię!$B$BMianowałam lorda Afrasastrasza dowódcą obrony Żmijowego Spoczynku.$B$BPorozmawiaj z Torastraszą, by polecieć do niego na smokowcu.$B$BProszę, wesprzyj go, $N. Twój udział w obronie Żmijowego Spoczynku będzie kluczowy dla naszego zwycięstwa nad Błękitnym Stadem.', 'Porozmawiaj z lordem Afrasastraszem w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12438, 'plPL', 'Poszukiwany: Kreug Łamacz Przysiąg', 'Ogłasza: Illusia Lune$B$BOlbrzym z ciała należący do Plagi, znany jako Kreug Łamacz Przysiąg, odpowiada za śmierć mojego męża, dzieci i moich drogich przyjaciół, Whisperveilów. Ci, którzy odważą się podjąć tego zlecenia, znajdą Kreuga w południowo-wschodniej części Pól Padliny.$B$BŻądam sprawiedliwości! Zabijcie Kreuga Łamacza Przysiąg!$B$BNa wypadek jego śmierci zebrałam pieniądze i przedmioty i przekazałam je najwyższemu lordowi Leoricowi Von Zeldigowi, by wręczył je jako nagrodę.$B$BProszę, pomścijcie nas!', 'Zabij Kreuga Łamacza Przysiąg i wróć po nagrodę do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12439, 'plPL', 'Zakłócenia na zachodzie', 'Kolejna siła grozi zniszczeniem wszystkiego, na co pracowaliśmy, $N. Musisz udać się na zachód, do Spoczynku Gwiazd. Arcymagini Modera wyczuła wielkie zakłócenie w magicznych liniach mocy naszego świata, którym trzeba się natychmiast zająć!$B$BRuszaj, $N! Porozmawiaj z Rodneyem Wellsem na stanowisku gryfów tutaj, w Zimowej Straży, i wyjaśnij mu, na czym polega twoja misja. Posadzi cię na swoim najszybszym gryfie, który zaniesie cię do Spoczynku Gwiazd. Po przybyciu porozmawiaj z arcymaginią Moderą.', 'Porozmawiaj z Rodneyem Wellsem w Twierdzy Zimowej Straży, by załatwić sobie lot do Spoczynku Gwiazd na zachodzie Smoczych Pustkowi.', '', '', '', '', '', '', 0),
(12440, 'plPL', 'Do Spoczynku Gwiazd!', 'Gdy $gbędziesz gotów:będziesz gotowa;, posadzę cię na moim najszybszym gryfie lecącym do Spoczynku Gwiazd. Na miejscu odszukaj arcymaginię Moderę i z nią porozmawiaj.$B$BPowodzenia, $gsojuszniku:sojuszniczko;!', 'Porozmawiaj z wizerunkiem arcymagini Modery w Spoczynku Gwiazd na zachodzie Smoczych Pustkowi.$B', '', '', '', '', '', '', 0),
(12441, 'plPL', 'Poszukiwany: Wielki szaman Krwawa Łapa', 'Ogłasza: Drolfy$B$BGdy byłem z kuzynami, Skrotee i Brote, na Niesamowitych Wyżynach, napadła nas okrutna banda wolvarów z plemienia Krwawej Łapy. Próbowaliśmy uciec, ale obawiam się, że dopadli Skrotee i Brote.$B$BŻądam odwetu! Czy znajdzie się ktoś dość odważny, by wyruszyć w południowo-wschodnie rejony Smoczych Pustkowi, na Niesamowite Wyżyny, i zabić wielkiego szamana Krwawą Łapę oraz jego kompanów?$B$BPrzekazałem pokaźną sumę złota najwyższemu lordowi Leoricowi Von Zeldigowi, by wypłacił ją każdemu, kto odbierze tę nagrodę!', 'Zabij wielkiego szamana Krwawą Łapę i wróć po nagrodę do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12442, 'plPL', 'Poszukiwany: Komendant Szturmu Iustus', 'Ogłasza: najwyższy lord Leoric Von Zeldig$B$BNa północno-wschodniej drodze z Zimowej Straży batalion 7. Legionu wpadł w zasadzkę i został wybity przez komendanta Szturmu Iustusa i armię bezmyślnych fanatyków Szkarłatnego Szturmu. Na tak zimne i wyrachowane czyny trzeba odpowiedzieć siłą!$B$BZimowa Straż żąda sprawiedliwości! Odszukajcie komendanta Szturmu Iustusa w Obozie Szturmu na północnym wschodzie i zakończcie jego nędzny żywot.$B$BWręczę nagrodę każdemu, kto odważy się podjąć tego zadania!$B', 'Zabij komendanta Szturmu Iustusa i wróć po nagrodę do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.$B', '', 'Wróć do najwyższego lorda Leorica Von Zeldiga w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12447, 'plPL', 'Obsydianowa Smocza Świątynia', 'Plaga nadchodzi. Korialstrasz wzywa sojuszników w daremnej próbie ratowania ich Rubinowej Smoczej Świątyni, ale najwyraźniej łaskawość Czerwonego Stada nie obejmuje ratowania świątyń innych stad.$B$BZaskoczenie? Mnie to nie dziwi.$B$BInny z mojego rodu wyruszył, by oczyścić naszą Obsydianową Smoczą Świątynię z nieumarłego robactwa, które ją opanowało. Wystarczy szybka wycieczka i kilka machnięć ostrzem, a udowodnisz, że jesteś $gszlachetniejszy i sprawiedliwszy:szlachetniejsza i sprawiedliwsza; niż sama Alexstraza.$B$BBawi mnie to.', 'Udaj się do Obsydianowej Smoczej Świątyni na północny zachód od Żmijowego Spoczynku, tuż na zachód od Bramy Gniewu. Odnajdź Serinara w świątyni i zaoferuj mu pomoc.', '', '', '', '', '', '', 0),
(12448, 'plPL', 'Gorąca bitwa', 'Plaga opanowała świątynię. Opiekunki świątyni, Dahlii Muśniętej Słońcem, nigdzie nie ma. Czerwone żmije, które poległy w obronie świątyni, nękają nas teraz jako wypaczone, szkieletowe żarożmije. Sytuacja jest rozpaczliwa.$B$BKapitan Drayzen dowodzi grupą twoich pobratymców, którzy powstrzymują napływ Plagi ze świątyni.$B$BIdź mu z pomocą... ale proszę, trzymaj się za jego ludźmi. Plaga napływa bez końca, a nie chcę cię stracić w którymś z tych poszarpanych kanionów.', 'Pomóż kapitanowi Drayzenowi utrzymać kaniony, biorąc udział w zabiciu 12 atakujących lodowatych ghuli, 8 atakujących lodowatych fantomów i 1 atakującego lodowatego plugastwa.$B$BPo wykonaniu zadania wróć do Vargastrasza.', '', 'Wróć do Vargastrasza na Smoczych Pustkowiach.', '', '', '', '', 0),
(12449, 'plPL', 'Powrót do ziemi', 'Mam kolejne zadanie, które wymaga uwagi. Moi bracia padają w bitwie na niebie i jeśli nie zadziałamy szybko, zasilą tylko szeregi żarożmijów.$B$BWejdź do świątyni przez przełęcz na południu... tam Plagi powinno być mniej.$B$BPrzeszukaj świątynię w poszukiwaniu rubinowych żołędzi, które spadły z drzewa, i zasadź je przy ciałach mojego poległego rodu. W ten sposób dadzą nowe życie... to dumny los dla każdego z mojego gatunku.', 'Wejdź do Rubinowej Smoczej Świątyni przez południową przełęcz i poszukaj rubinowych żołędzi. Użyj rubinowych żołędzi na poległych czerwonych smokach, by zwrócić ich ciała ziemi. Po wykonaniu zadania wróć do Vargastrasza.', '', 'Wróć do Vargastrasza na Smoczych Pustkowiach.', 'Rubinowy opiekun zwrócony ziemi', '', '', '', 0),
(12450, 'plPL', 'Przez pola ognia', 'Mam dla ciebie ostatnie zadanie... takie, które powinno odwrócić losy tej walki.$B$BWróć do świątyni i zabij nekromantów, którzy podsycają to natarcie. Gdy zginą, powinniśmy zdołać odeprzeć te siły i w końcu odbić świątynię.$B$BMusisz też odnaleźć źródło skażenia pod świątynią i położyć mu kres.$B$BWiem, że wiele od ciebie wymagam, ale jeśli zrobisz to dla mnie, wygramy tę bitwę.', 'Wejdź do Rubinowej Smoczej Świątyni przez południową przełęcz, a następnie zabij 6 lodowatych nekromantów i usuń źródło skażenia pod świątynią. Po wykonaniu zadania wróć do Vargastrasza.', '', 'Wróć do Vargastrasza na Smoczych Pustkowiach.', '', 'Rubinowe splugawienie oczyszczone', '', '', 0),
(12452, 'plPL', 'zzOLD Los Rubinowej Smoczej Świątyni', '', 'Zanieś rubinową broszę Dahlii Ceristraszowi i powiadom go o jej losie.', '', '', '', '', '', '', 0),
(12454, 'plPL', 'Krąg życia', 'Ysera śpi w Szmaragdowym Śnie, czuwając zarówno nad Snem, jak i nad Azeroth. Ale w Śnie zapanował straszliwy koszmar i obawiam się, że zaczyna on wpływać na Yserę.$B$BNiedawno poprosiłam ją o pomoc w walce z Plagą, która wskrzesza żmije mrozu w innych smoczych świątyniach. Źle mnie zrozumiała.$B$BZamiast tego kazała obrońcom naszej smoczej świątyni traktować jak wrogów wszystkich spoza Zielonego Stada.$B$BMusisz zabić kilka szponów niebios. Świątynia musi odzyskać równowagę.', 'Nishera Strażniczka Ogrodu ze Szmaragdowej Smoczej Świątyni prosi cię o zabicie 5 szmaragdowych szponów niebios.', '', 'Wróć do Nishery Strażniczki Ogrodu w Szmaragdowej Smoczej Świątyni na Smoczych Pustkowiach.', '', '', '', '', 0),
(12455, 'plPL', 'Rozwiane na wietrze', 'Zrzut amunicji się nie udał, $gprzyjacielu:przyjaciółko;. Transport amunicji z Twierdzy Zachodniej Straży przechwyciły żmije mrozu krążące w górze. Maszyny latające rozerwano w kilka sekund, a ich ładunek rozwiało na wietrze. Większość wciąż leży na powierzchni – na Polach Padliny.$B$BMusisz wrócić na górę i zebrać skrzynie z amunicją rozrzucone po całym tym przeklętym miejscu.$B$BPośpiesz się! Nie zaczniemy ofensywy bez broni i amunicji, $gkolego:panienko;!', 'Ambo Cash z Mauzoleum Zimowej Straży na Smoczych Pustkowiach chce, abyś $godzyskał:odzyskała; 8 skrzyń amunicji Zimowej Straży.', '', 'Wróć do Ambo Casha w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12456, 'plPL', 'Pióropusz Alystrosa', 'Czuję, że świątynia nie odzyskała w pełni równowagi. Nasze działania rozgniewały zielonego strażnika i wyczuwam, że nie posłucha głosu rozsądku.$B$BAlystros to ogromny szpon niebios, który przesiaduje na południowym krańcu Szmaragdowej Smoczej Świątyni. To on odpowiada za powietrzną obronę smoczej świątyni. Obawiam się, że będziemy musieli się nim zająć.$B$BWeź te wylinki szpona niebios i połóż je na ziemi tam, gdzie je zobaczy. Przyleci. Przynieś mi jego pióropusz.', 'Nishera Strażniczka Ogrodu ze Szmaragdowej Smoczej Świątyni prosi cię o zdobycie pióropusza Alystrosa.', '', 'Wróć do Nishery Strażniczki Ogrodu w Szmaragdowej Smoczej Świątyni na Smoczych Pustkowiach.', '', '', '', '', 0),
(12457, 'plPL', 'Działko łańcuchowe i ty', 'Ustawiliśmy działka łańcuchowe i barykady tuż na wschodzie i zachodzie. Nasi ranni żołnierze ukrywają się w obu salach – starają się, jak mogą, nie zwrócić na siebie uwagi bezmyślnych ghuli.$B$BSkoro mamy już amunicję, obsadź jedno z działek łańcuchowych i utoruj nim drogę naszym żołnierzom! Gdy zajmiesz stanowisko, wywołaj żołnierza z kryjówki, a potem prowadź ciężki ostrzał, by trzymać Plagę z dala od niego!$B$BRuszaj się!', 'Ambo Cash z Mauzoleum Zimowej Straży na Smoczych Pustkowiach chce, abyś $guratował:uratowała; 8 rannych żołnierzy 7. Legionu.', '', 'Wróć do Ambo Casha w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', 'Ranny żołnierz 7. Legionu uratowany', '', '', '', 0),
(12458, 'plPL', 'Nasiona smagaczy', 'Potrzebujemy więcej broni w walce z Plagą. Odpowiedzią mogą być naturalne właściwości Szmaragdowej Smoczej Świątyni na południowym wschodzie.$B$BKażda nieżywa istota – poza tymi, których odkupiła Sylwana – która postawi stopę w smoczej świątyni, obraca się w proch.$B$BChcę sprawdzić pewną teorię, a ty, $gmłody przyjacielu:młoda przyjaciółko;, będziesz w tym moim narzędziem. Udaj się do Szmaragdowej Smoczej Świątyni i zabierz nasiona rosnącym tam szmaragdowym smagaczom.', 'Lord Itharius ze szczytu Świątyni Żmijowego Spoczynku prosi cię o przyniesienie 3 nasion smagacza.', '', 'Wróć do lorda Ithariusa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12459, 'plPL', 'Co tworzy, może też niszczyć', 'Skoro mamy tylko trzy nasiona, musimy je jak najlepiej wykorzystać.$B$BTwoje cele to jeden z ożywionych żmijów mrozu krążących na północy w pobliżu Spoczynku Galakronda, Turgid Plugawy w zrujnowanych koszarach na Polach Padliny na wschodzie oraz nadzorca Śmiertelny Wzrok w Jintha\'kalar daleko na północnym wschodzie.$B$BO ile pomniejszego sługę Plagi nasiona zniszczyłyby od razu, o tyle tę trójkę znacznie osłabią. Na tyle, że poradzisz sobie z nimi w pojedynkę.', 'Lord Itharius ze szczytu Świątyni Żmijowego Spoczynku prosi cię o zniszczenie osłabionego ożywionego żmija mrozu, osłabionego Turgida Plugawego i osłabionego nadzorcy Śmiertelnego Wzroku.', '', 'Wróć do lorda Ithariusa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12460, 'plPL', 'Zgłoś się do Rubinowej Smoczej Świątyni', 'Potrzebujemy cię w Rubinowej Smoczej Świątyni.$B$BSmoki są osaczone ze wszystkich stron przez Błękitne Stado i Plagę... są w nie lepszym położeniu niż my. Sytuacja wydaje się rozpaczliwa, ale daje nam rzadką okazję do zawarcia cennego sojuszu.$B$BZałatwiłam regiment, który wesprze Czerwone Stado w walce z Plagą w Rubinowej Smoczej Świątyni. Jeśli masz w sobie ducha walki, odszukaj Ceristrasza na grani na wschód od świątyni i pomóż mu, jak tylko możesz.', 'Zgłoś się do Ceristrasza na grani na wschód od Rubinowej Smoczej Świątyni, na zachód od Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12461, 'plPL', 'Zgłoś się do Rubinowej Smoczej Świątyni', 'Wyruszasz do Rubinowej Smoczej Świątyni. To nie jest prośba.$B$BSmoki są osaczone ze wszystkich stron przez Błękitne Stado i Plagę... są w nie lepszym położeniu niż my. Nieczęsto mamy okazję odkupić przewiny naszych przodków.$B$BZałatwiłem regiment, który wesprze Czerwone Stado w walce z Plagą w Rubinowej Smoczej Świątyni. Dołącz do nich i zmiażdż Plagę pod butami!$B$BZa Hordę!', 'Zgłoś się do Vargastrasza na grani przed Rubinową Smoczą Świątynią, tuż na wschód od Młota Agmara.', '', '', '', '', '', '', 0),
(12462, 'plPL', 'Urwij sobie kawałek', 'Tuż za schodami leży brama do potępienia: Plaga, jak okiem sięgnąć, i z każdą chwilą jej przybywa. Te skąpe informacje, które zdołaliśmy zebrać, wskazują, że dwaj nekrowładcy Plagi gorączkowo opróżniają pierwsze dwie krypty na dole. Zanim przebijemy się do wewnętrznej komnaty Thel\'zana, musimy się zająć tymi dwoma błaznami i ich kompanami z Naxxramas.$B$BZejdź do mauzoleum i wykończ nekrowładców oraz gwardzistów grozy i cienie z Naxxramas.', 'Yord „Katastrofa” Lodobrody z Mauzoleum Zimowej Straży na Smoczych Pustkowiach chce, abyś $gzabił:zabiła; nekrowładcę X\'aviusa, nekrowładcę Horusa i 15 sług Plagi z Naxxramas.$B', '', 'Wróć do Yorda „Katastrofy” Lodobrodego w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', '', 'Zabici słudzy Plagi z Naxxramas', '', 0),
(12463, 'plPL', 'Trzeba odnaleźć Łupobrodego!', 'Mówi się o tunelu wykopanym przez Plagę, który łączy komory balsamowania w mauzoleum z wielkimi kryptami, odkopanymi teraz przez Thel\'zana i jego sługi. Niedawno wysłałem mojego najlepszego łotrzyka, Łupobrodego, żeby czegoś się dowiedział, ale wciąż nie mam od niego wieści. Gdybym był hazardzistą, postawiłbym na to, że już po nim.$B$BZejdź tymi schodami, przejdź prosto przez komorę balsamowania i poszukaj Łupobrodego. Żywy czy martwy, będzie miał odpowiedzi.$B', 'Ambo Cash z Mauzoleum Zimowej Straży na Smoczych Pustkowiach chce, abyś $godnalazł:odnalazła; Łupobrodego.', '', '', '', '', '', '', 0),
(12464, 'plPL', 'Mój stary wróg', 'Mój stary wróg, najwyższa generał Abbendis, przybyła do Północnej Grani.$B$BJakimś cudem przeżyła ataki na Dłoń Tyra i sprowadziła niewielkie siły na północ. Założyli Nowe Żagiewie na południu.$B$BChoć mogliby się przydać w walce z Plagą, sama Abbendis to zbyt przebiegła przeciwniczka, by darować jej życie. Uwierz mi, jeśli pozwolimy im przetrwać, skoczy nam do gardeł, zanim opadnie kurz.$B$BDlatego pozbawimy ich przywództwa i zajmiemy się swoimi sprawami. Przynieś mi jej głowę jako dowód.', 'Dostarcz głowę najwyższej generał dowódcy Eligorowi Zwiastunowi Świtu w Twierdzy Zimowej Straży.', '', 'Wróć do dowódcy Eligora Zwiastuna Świtu w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12465, 'plPL', 'Dziennik Łupobrodego', 'Trzeba odzyskać to, co było zapisane na pozostałych stronach dziennika Łupobrodego. Przeszukaj komnaty po drugiej stronie tego tunelu i znajdź napastników Łupobrodego. To pewnie oni wyrwali strony z dziennika!$B$BJeśli odzyskasz brakujące strony, zanieś je Ambo Cashowi przy wejściu do Mauzoleum Zimowej Straży.', 'Odzyskaj stronę 4 dziennika Łupobrodego, stronę 5 dziennika Łupobrodego, stronę 6 dziennika Łupobrodego i stronę 7 dziennika Łupobrodego, a następnie zanieś je Ambo Cashowi w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do Ambo Casha w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12466, 'plPL', 'W pogoni za Lodową Burzą: Front 7. Legionu', 'Musisz dotrzeć na Front 7. Legionu na północy Smoczych Pustkowi. Wróć do Twierdzy Zimowej Straży i wyjdź z miasta północną bramą. Kieruj się na północ, aż trafisz na drogę. Skręć na niej w lewo i idź nią aż do granicy śniegu. Stamtąd kieruj się na zachód, aż dotrzesz do Ścieżki Tytanów. Idź nią na północ, a zaprowadzi cię prosto na Front 7. Legionu.$B$BNa miejscu porozmawiaj z komendantem Legionu Tyralionem. Będzie na ciebie czekał.$B$BI, $N... to była przyjemność. Żegnaj.', 'Zgłoś się do komendanta Legionu Tyraliona na Froncie 7. Legionu w środkowej części Smoczych Pustkowi.', '', '', '', '', '', '', 0),
(12467, 'plPL', 'W pogoni za Lodową Burzą: Filakteria Thel\'zana', 'Twój żmij mrozu jest tam.$B$B<Tyralion wskazuje na zachód.>$B$BI to wielki okaz!$B$BGdy $gbędziesz gotów:będziesz gotowa; do walki, porozmawiaj z „Przynętą na żmije”. On ją „przyprowadzi”. Gdy Lodowa Burza podleci dość blisko, przykujemy ją łańcuchami do ziemi i wykończymy! Miejmy nadzieję, że z twoją pomocą zdołamy ją powalić i zdobyć dla ciebie tę filakterię.$B$BGdy zdobędziesz filakterię, wróć do Twierdzy Zimowej Straży i zgłoś się do wielkiego komendanta Halforda Zmory Żmijów. Przygotowuje się do ostatecznej rozprawy z Thel\'zanem.', 'Odbierz Lodowej Burzy filakterię Thel\'zana i zanieś ją wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży.$B', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12469, 'plPL', 'Zwrot do nadawcy', 'Po bliższych oględzinach widać, że goblin niósł przez pustkowia plecak pełen materiałów wybuchowych do dostarczenia. Pióra harpii na wpół zagrzebane w śniegu nieopodal sugerują, jak spotkał go marny koniec.$B$BWygląda na to, że goblin niósł materiały wybuchowe skądś ze wschodu w stronę Bramy Gniewu. Najrozsądniej będzie pójść granią z powrotem na wschód i powiadomić nadawcę o losie jego gońca.', 'Idź granią na wschód i dostarcz plecak z materiałami wybuchowymi Xinkowi w Posterunku Rdzawej Dyszy na północy Smoczych Pustkowi.', '', 'Wróć do Xinka na Wyżynach Zimnego Wiatru na Smoczych Pustkowiach.', '', '', '', '', 0),
(12470, 'plPL', 'Tajemnica Nieskończonych', 'Burza czasu w Brązowej Smoczej Świątyni na północnym wschodzie nie pozwala wejść nieśmiertelnym.$B$BNieskończone Stado walczy tam z obrońcami o kontrolę nad smoczą świątynią. Musimy wykorzystać tę okazję, by zdobyć informacje.$B$BTy nie jesteś $gnieśmiertelny:nieśmiertelna;. Możesz wejść do smoczej świątyni i użyć klepsydry wieczności. Chroń klepsydrę wystarczająco długo, a przywódca Nieskończonego Stada powinien się ujawnić.$B$BUwaga: Nieskończone Stado spróbuje cię powstrzymać!', 'Chromie ze szczytu Świątyni Żmijowego Spoczynku prosi cię, abyś $gudał:udała; się do Brązowej Smoczej Świątyni. W środku postaw klepsydrę wieczności na ziemi.$B$BChroń klepsydrę, dopóki działa, a potem wróć do Chromie z informacjami, które zdobędziesz.', 'Klepsydra wieczności ochroniona', 'Wróć do Chromie w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12472, 'plPL', 'Kres', 'Dzięki twojemu bohaterstwu lord Fordragon wydał rozkaz przypuszczenia pełnego ataku na Thel\'zana. 7. Legion dotarł do komnaty przywołań w mauzoleum i odnalazł coś, co wygląda na wrota do piekła. Brakuje już tylko ciebie.$B$BWeź filakterię i zgłoś się do komendanta Legionu Yorika w Mauzoleum Zimowej Straży.$B$BTuż za twierdzą jest tunel wykopany przez Plagę, którym szybko dotrzesz do Yorika. Ruszaj, $N! Poprowadź nas do zwycięstwa!', 'Zanieś filakterię Thel\'zana komendantowi Legionu Yorikowi w Mauzoleum Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do komendanta Legionu Yorika na Polach Padliny na Smoczych Pustkowiach.', '', '', '', '', 0),
(12473, 'plPL', 'Koniec i początek', 'Każda dobra opowieść ma początek i koniec, $N. Choć twoja opowieść jeszcze się nie skończyła, niech mnie licho, jeśli już teraz nie staje się materiałem na legendę! Bez względu na to, co się z nami stanie, gdy to wszystko się skończy, o tym, czego $gdokonałeś:dokonałaś; w Zimowej Straży, będą opowiadać jeszcze przez długie lata.$B$BA teraz, $gsojuszniku:sojuszniczko;, gdy $gbędziesz gotów:będziesz gotowa;, użyję filakterii, by wywabić Thel\'zana z kryjówki.$B$BJeśli jakimś cudem nam się uda, zamelduj o zwycięstwie wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży.', 'Pokonaj Thel\'zana Niosącego Zmrok i zamelduj się u wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Thel\'zan Niosący Zmrok pokonany', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12474, 'plPL', 'Do Warowni Fordragona!', 'Skoro machina wojenna Naxxramas stanęła w miejscu, nadszedł czas, byś $gwsparł:wsparła; nasze siły w Angrathar, przy Bramie Gniewu. U stóp góry na północy Smoczych Pustkowi leży nasza baza operacyjna, Warownia Fordragona. To tam lord Fordragon czeka na twoje przybycie! Ruszaj, $N!$B$BWyjdź z miasta północną bramą i kieruj się na północny północny zachód, aż dotrzesz do celu.$B$BNiech Światłość cię chroni!', 'Udaj się do Warowni Fordragona na Smoczych Pustkowiach i porozmawiaj z najwyższym lordem Bolvarem Fordragonem.$B', '', '', '', '', '', '', 0),
(12475, 'plPL', 'Jakie sekrety skrywają ludzie', 'Po zdradzie na Zapomnianym Brzegu książę Arthas – z Muradinem u boku – rozpoczął poszukiwania Ostrza Mrozu. Czy jaskinia, w której znaleziono Ostrze Mrozu, może być blisko? Jakie sekrety może skrywać? Choć kula nie zna odpowiedzi na te pytania, coś mi jednak pokazuje.$B$BNa północny wschód od Twierdzy Zimowej Straży znajduje się posterunek wzniesiony przez Szkarłatny Szturm. Gdzieś w tym posterunku jest mapa. Kula mówi mi, że ta mapa bardzo nam się przyda.$B$BZdobądź ją!', 'Zelig Wizjoner z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $godnalazł:odnalazła; mapę Szturmu i $gprzyniósł:przyniosła; mu ją.', '', 'Wróć do Zeliga Wizjonera w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12476, 'plPL', 'Powrót Krucjaty?', 'Na północny wschód od Twierdzy Zimowej Straży znajduje się nowo zbudowany obóz, założony przez Szkarłatną Krucjatę – a raczej przez Szkarłatny Szturm, jak się teraz nazywają. Choć nie wiemy, po co przybyli do Północnej Grani, z pewnością nie są mniej groźni niż dawniej. Wczoraj w nocy Szkarłatny Szturm zabił dwunastu naszych żołnierzy. Trzeba dać im nauczkę, $N.$B$BUdaj się do Obozu Szturmu i przerzedź ich szeregi.$B', 'Komendantka Lynore Uderzenie Wiatru z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $gzabił:zabiła; 20 członków Szkarłatnego Szturmu w Obozie Szturmu.', '', 'Wróć do komendantki Lynore Uderzenia Wiatru w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Zabici członkowie Szkarłatnego Szturmu', '', '', '', 0),
(12477, 'plPL', 'Ścieżka odkupienia', '„Ścieżka odkupienia” – $gsłyszałeś:słyszałaś; o niej? To podobno dziennik zawierający proroczy bełkot najwyższej generał Abbendis ze Szkarłatnego Szturmu. W tej księdze można znaleźć motywacje i cele szkarłatnych fanatyków – nie wspominając o całej masie szaleństwa.$B$BUdaj się do Obozu Szturmu, na północny wschód od Twierdzy Zimowej Straży, i zdobądź egzemplarz „Ścieżki odkupienia” od jednego z żołnierzy Szturmu.', 'Dostarcz „Ścieżkę odkupienia” wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12478, 'plPL', 'Grota Ostrza Mrozu', 'Nazwali tę jaskinię Grotą Ostrza Mrozu. Nie wiadomo, dlaczego Szkarłatny Szturm interesuje się takimi rzeczami, ale z tego, co widać, okolice jaskini są silnie strzeżone. Mimo to musimy działać!$B$BWeź tę wróżebną kulę i wyjdź z miasta na północ, a potem kieruj się na północny zachód w stronę Szkarłatnego Punktu. Wejdź do jaskini i przebij się na samo dno. Tam użyj kuli. Wróć tu z tym, czego się dowiesz.', 'Zelig Wizjoner z Twierdzy Zimowej Straży na Smoczych Pustkowiach chce, abyś $gużył:użyła; wróżebnej kuli Zeliga na dnie Groty Ostrza Mrozu. Odkryj sekrety przeszłości!', '', 'Wróć do Zeliga Wizjonera w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', 'Sekrety przeszłości odkryte', '', '', '', 0),
(12487, 'plPL', 'Do Warowni Podboju, ale ostrożnie!', 'Dostałem prośbę o pomoc z naszej bazy na Wzgórzach Grizli. Wysyłam cię do zdobywczyni Krenny.$B$B<Najwyższy egzekutor macha plikiem pergaminów, jakby zupełnie nie obchodziło go, co na nich napisano.>$B$BPróbuje zabezpieczyć wszystkie zasoby naturalne czy coś w tym rodzaju. Tylko pilnuj przy niej pleców. Podobno jest agresywna nawet jak na orczycę.$B$BIdź drogą na wschód, a potem na południowy wschód. Przejdź przez most nad Dopływem Smoczego Grzbietu i od Faktorii Wiecznej Zieleni kieruj się na wschód.', 'Zgłoś się do zdobywczyni Krenny w Warowni Podboju na Wzgórzach Grizli.', '', '', '', '', '', '', 0),
(12488, 'plPL', 'Najwyższy egzekutor cię potrzebuje', 'Dobrze, że przechwyciłem tę prośbę od najwyższego egzekutora Wrotha, zanim dotarła do nadrządcy Agmara. Co ten Wroth sobie myśli?$B$B<Sierżant drze trzymany list.>$B$BSprawdź, czego chce najwyższy egzekutor.$B$BIdź drogą na wschód przez Pustkowia Smoków. Po południowo-wschodniej stronie pustkowi znajdziesz ścieżkę prowadzącą w górę, a miasto Porzuconych, Jadozłość, ukaże się przed tobą po południowej stronie góry.', 'Porozmawiaj z najwyższym egzekutorem Wrothem w Jadozłości na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12495, 'plPL', 'Audiencja u smoczej królowej', 'Nasz atak na Angrathar zachwiał Plagą, ale ta nie ustępuje. Z góry wysyła swoje żmije mrozu, by ostrzeliwały pole bitwy, co uniemożliwia natarcie na samą bramę. Ataki żmijów mrozu trzeba powstrzymać, ale zanim zbezcześcimy kości starożytnych smoków, musimy uzyskać zgodę ich królowej.$B$BUdaj się na południowy wschód do Świątyni Żmijowego Spoczynku i odszukaj królową Alexstrazę. Powiedz jej, co musimy zrobić, i poproś ją o radę.$B$BRuszaj, $N!', 'Odszukaj Alexstrazę Życiodajną w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12496, 'plPL', 'Audiencja u smoczej królowej', 'Choć wiem, że pragniesz zniszczyć Plagę, która stoi przed nami przy Bramie Gniewu, najpierw musimy się rozprawić z zagrożeniem nad naszymi głowami. Dopóki nie powstrzymamy nalotów żmijów mrozu, nie możemy ruszyć naprzód.$B$BAle zanim zaatakujemy smocze cmentarzysko, musimy najpierw otrzymać zgodę. Udaj się teraz do uświęconych sal smoczego rodu: do Świątyni Żmijowego Spoczynku. Na miejscu odszukaj królową Alexstrazę.$B$BW drogę, $N! Na południowy wschód, do Żmijowego Spoczynku!', 'Odszukaj Alexstrazę Życiodajną w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12497, 'plPL', 'Galakrond i Plaga', 'Na szczycie Nikczemnego Zwoju wielki nekrowładca Plagi, Antiok, siedzi na ramionach odtworzonego lorda olbrzymów burzy, Thiassiego. Stamtąd rozkazuje armiom nieumarłych, by dniem i nocą odkopywały potężne kości Galakronda. Jeśli zdołają wskrzesić Galakronda, wszystkie wasze wysiłki pójdą na marne.$B$BChoć nie mogę rzucić do boju całej furii Czerwonego Stada, by wsparła cię w tej wyprawie, udzielę ci swojego błogosławieństwa. Idź teraz i porozmawiaj z moją majordomą, Torastraszą.', 'Porozmawiaj z Torastraszą w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12498, 'plPL', 'Na rubinowych skrzydłach', 'Użyj tego sygnału, by przywołać pogromcę Żmijowego Spoczynku. Wespnij się na jego grzbiet i leć na północ do Spoczynku Galakronda. Na miejscu rozkaż smokowi zniszczyć padlinożerców Plagi, którzy odkopują Galakronda. Gdy okolica zostanie oczyszczona, leć na Nikczemny Zwój, górujący nad Spoczynkiem Galakronda, by zniszczyć wielkiego nekrowładcę Antioka i odebrać mu kosę, którą steruje żmijami.$B$BZrób to i wróć do królowej Alexstrazy po nagrodę godną bohatera!$B$B$N, strzeż się gnijących olbrzymów burzy, które krążą po okolicy!', 'Zniszcz 30 padlinożerców z pustkowi i zdobądź kosę Antioka. Po wykonaniu zadania wróć do Alexstrazy Życiodajnej w Świątyni Żmijowego Spoczynku.', '', 'Wróć do Alexstrazy Życiodajnej w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(12499, 'plPL', 'Powrót do Angrathar', 'Skoro Antiok nie żyje, a kosa jest w naszych rękach, ataki żmijów mrozu na wasze siły w Angrathar ustaną. Żmije, które pozostały na Smoczych Pustkowiach, zostaną wytropione i zniszczone, a ich kości wrócą do ziemi.$B$BNadszedł czas ostatecznej rozprawy, $N. Wróć do Warowni Fordragona i powiadom najwyższego lorda Fordragona.$B', 'Porozmawiaj z najwyższym lordem Bolvarem Fordragonem w Warowni Fordragona i opowiedz mu o swoim zwycięstwie nad Plagą.$B', '', '', '', '', '', '', 0),
(12500, 'plPL', 'Powrót do Angrathar', 'Skoro Antiok nie żyje, a kosa jest w naszych rękach, ataki żmijów mrozu na wasze siły w Angrathar ustaną. Żmije, które pozostały na Smoczych Pustkowiach, zostaną wytropione i zniszczone, a ich kości wrócą do ziemi.$B$BNadszedł czas ostatecznej rozprawy, $N. Wróć do Awangardy Kor\'kronu i powiadom Zaurzykła Młodszego.', 'Porozmawiaj z Zaurzykłem Młodszym w Awangardzie Kor\'kronu i opowiedz mu o swoim zwycięstwie nad Plagą.', '', '', '', '', '', '', 0),
(12511, 'plPL', 'Wzgórza nas mają', 'Podczas gdy my skupiamy się na utrzymaniu pozycji w Zimowej Straży i śledzimy rozwój wydarzeń przy Bramie Gniewu, bataliony z tak dalekich stron jak Zachodni Skraj przedzierają się przez gęste zarośla i nieprzyjaznych mieszkańców Wzgórz Grizli. Wszystko w nadziei na znalezienie innej drogi do Lodowej Korony.$B$BPorucznik Dumont, stacjonujący w Chacie Bursztynowej Sosny, werbuje zdolnych do walki ochotników gotowych ryzykować życie i zdrowie na niezbadanych dzikich ziemiach. Podejmiesz to wyzwanie?', 'Zgłoś się do porucznika Dumonta w Chacie Bursztynowej Sosny w zachodniej części Wzgórz Grizli.$B', '', '', '', '', '', '', 0),
(12542, 'plPL', 'Wezwanie Krucjaty', '$N! Krucjata Argentu szuka zdolnych do walki żołnierzy, gotowych odłożyć na bok dzielące ich różnice i połączyć siły w walce z wojskami Króla Lisza. Przyłączysz się do naszej sprawy?$B$BJeśli cię to interesuje, udaj się na północ do Ufności Światłości i porozmawiaj z krzyżowcem Valusem.$B$BUfność Światłości znajdziesz pośród ruin splądrowanego miasta trolli Jintha\'kalar – na granicy z Zul\'Drakiem.$B$BŻegnaj.', 'Zgłoś się do krzyżowca Valusa w Ufności Światłości na Smoczych Pustkowiach.$B', '', '', '', '', '', '', 0),
(12545, 'plPL', 'Oczyszczenie Jintha\'kalar', 'Odbiliśmy tę starożytną świątynię Drakkarów z rąk roju najeźdźców z Plagi. Niecałe sto kroków stąd leży zrujnowane miasto Jintha\'kalar. Nekromanci Plagi szaleją tam bez opamiętania, zmieniając żyjących jeszcze trolli Drakkarów w sługi Króla Lisza.$B$BWszyscy są już straceni dla Światłości. Wszystkich trzeba oczyścić.$B$B<Valus patrzy na ciebie surowo.>$B$BWszystkich.', 'Krzyżowiec Valus z Ufności Światłości na Smoczych Pustkowiach prosi cię o zabicie 15 sług Plagi w Jintha\'kalar.', '', 'Wróć do krzyżowca Valusa w Ufności Światłości na Smoczych Pustkowiach.', 'Zabici słudzy Plagi w Jintha\'kalar', '', '', '', 0),
(12766, 'plPL', 'Porozmawiaj ze swoim ambasadorem', '<Smok w elfiej postaci bierze twój list polecający, przegląda go przez chwilę, po czym chowa go w rękawie.>$B$BWszystko wydaje się w porządku. Jeśli jednak nie masz nic przeciwko, prosiłbym o rozmowę z twoją ambasador tutaj, w świątyni.$B$BMa dla ciebie coś niezwykle ważnego, czym trzeba się zająć, zanim poślemy cię na górę do królowej.$B$B<Klepie list schowany w rękawie.>$B$BPrzechowam go dla ciebie do twojego powrotu.', 'Porozmawiaj z Lauriel Prawym Ostrzem w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12767, 'plPL', 'Porozmawiaj ze swoim ambasadorem', '<Smok w elfiej postaci bierze twój list polecający, przegląda go przez chwilę, po czym chowa go w rękawie.>$B$BWszystko wydaje się w porządku. Jeśli jednak nie masz nic przeciwko, prosiłbym o rozmowę z twoim ambasadorem tutaj, w świątyni.$B$BMa dla ciebie coś niezwykle ważnego, czym trzeba się zająć, zanim poślemy cię na górę do królowej.$B$B<Klepie list schowany w rękawie.>$B$BPrzechowam go dla ciebie do twojego powrotu.', 'Porozmawiaj z Golluckiem Skalną Pięścią w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12768, 'plPL', 'Zarządca Świątyni Żmijowego Spoczynku', '$GUdowodniłeś:Udowodniłaś;, że można ci ufać, i to nie tylko.$B$BWróć do Świątyni Żmijowego Spoczynku i jeszcze raz porozmawiaj z zarządcą, Tariolstraszem, $N.', 'Porozmawiaj z Tariolstraszem w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12769, 'plPL', 'Zarządca Świątyni Żmijowego Spoczynku', '$GUdowodniłeś:Udowodniłaś;, że można ci ufać, i to nie tylko.$B$BWróć do Świątyni Żmijowego Spoczynku i jeszcze raz porozmawiaj z zarządcą, Tariolstraszem, $N.', 'Porozmawiaj z Tariolstraszem w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(12789, 'plPL', 'Do wyłomu!', 'Przygotuj się, $N. Wysyłam cię do Wyłomu Światłości, na północny wschód stąd.$b$bDoszły mnie wieści, że Plaga próbuje przejąć Zul\'Drak.$b$b<Valus patrzy ci prosto w oczy.>$b$bDo tego nie dojdzie.$b$bWeź udział w niszczeniu tamtejszej Plagi. Światłość tego wymaga.$b$bOdmaszerować.', 'Krzyżowiec Valus z Ufności Światłości chce, abyś $gzgłosił:zgłosiła; się do sierżant Riannah w Wyłomie Światłości w Zul\'Draku.', '', '', '', '', '', '', 0),
(13014, 'plPL', 'Nestor Morthie', '', '', '', '', '', '', '', '', 0),
(13019, 'plPL', 'Nestor Thoim', '', '', '', '', '', '', '', '', 0),
(13031, 'plPL', 'Nestor Strażnik Nieba', '', '', '', '', '', '', '', '', 0),
(13077, 'plPL', 'Dotyk Aspektu', 'Smocza królowa, Alexstraza, włada magią nad wszelkim życiem. W przeszłości używała potężnego ognia, by spopielać nieumarłych i w ich miejsce wskrzeszać nowe życie. Być może jej moc zdoła ocalić również naszego Bridenbrada.$B$BAlexstraza przebywa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach – proszę, udaj się do niej i w moim imieniu pokornie poproś o pomoc.', 'Poproś o pomoc Alexstrazę Życiodajną w Świątyni Żmijowego Spoczynku.', '', '', '', '', '', '', 0),
(13078, 'plPL', 'Łzy Dahlii', 'W tych mrocznych czasach nie opuszczę bojownika Światłości.$B$BBy mieć choć cień nadziei na ocalenie waszego Bridenbrada, będziemy potrzebować czegoś świętego... pozostałości pobożnej istoty, która padła ofiarą tej samej zarazy.$B$BUdaj się teraz na świętą ziemię przełęczy przed moją Rubinową Smoczą Świątynią, gdzie toczy się bitwa. Gdy moi rubinowi opiekunowie zlecą w dół i podpalą ziemię pod stopami nieumarłych, ujrzysz, jak wyrasta nowe życie. Wśród niego znajdziesz Łzy Dahlii – przynieś mi je.', 'Alexstraza Życiodajna ze Świątyni Żmijowego Spoczynku prosi cię o zebranie Łez Dahlii z ziemi świeżo oczyszczonej płomieniami rubinowego opiekuna.', '', 'Wróć do Alexstrazy Życiodajnej w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(13079, 'plPL', 'Dar Alexstrazy', 'Musisz zrozumieć, $gmłody przyjacielu:młoda przyjaciółko;, że oczyszczenie ciała na rzecz nowego życia leży w moim zasięgu... usunięcie zarazy nieżycia bez naruszania ciała wykracza jednak poza moc, którą władam.$B$BJeśli ten Bridenbrad jest takim światłem przewodnim, za jakie go uważasz, może przetrwa takie oczyszczenie i rozkwitnie, ale nie mogę z pewnością orzec, że to ocalenie, którego szukasz. Weź to i idź z całym moim błogosławieństwem.', 'Zanieś oddech Alexstrazy krzyżowcowi Bridenbradowi przy Cichym Czuwaniu w Lodowej Koronie.', '', 'Wróć do krzyżowca Bridenbrada przy Cichym Czuwaniu w Lodowej Koronie.', '', '', '', '', 0),
(13111, 'plPL', 'Jedyny w swoim rodzaju', 'Słuchaj, mon.$b$bNa pierwszy rzut oka to ta sama stara historia – trolle sięgają po zakazaną moc, niszcząc te same istoty, które powinny czcić.$b$bTo prawda, ale jest w tych Drakkarach coś szczególnego. Jeśli to, czego się dowiedziałam, jest prawdą, to w Gundraku jest wyjątkowy golem – taki, jakiego nikt jeszcze nie stworzył!$b$bChcesz przygody, mon? Idź do Gundraku i przynieś mi kawałek tego golema do zbadania.', 'Kronikarka Bah\'Kini w Dubra\'Jin chce, żebyś $gwszedł:weszła; do Gundraku i $gzdobył:zdobyła; kawałek Kolosa Drakkarów.', '', 'Wróć do kronikarki Bah\'Kini w Dubra\'Jin w Zul\'Draku.', '', '', '', '', 0),
(13167, 'plPL', 'Śmierć królowi zdrajcy', 'Anub\'arak, król zdrajca, rezyduje w niegdyś dumnym podziemnym królestwie Azjol-Nerub.$b$bOd czasu swojej zdrady wypaczył i splugawił naszą ojczyznę, zmieniając ją w nędzną ruinę, jaką jest dziś. Włada armią nieumarłych nerubian, którzy tak jak ich przywódca przysięgli służyć Królowi Liszowi.$b$bPołóż kres panowaniu króla zdrajcy, $N. Oddasz wielką przysługę obu naszym ludom.$b$bJeśli zdołasz odnieść sukces tam, gdzie wszyscy inni zawiedli, przynieś mi pancerz Anub\'araka.', 'Kilix Rozplatacz z Czeluści Narjun zlecił ci pokonanie Anub\'araka w Azjol-Nerub. Masz wrócić do Kilixa z pękniętym pancerzem Anub\'araka.', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', '', '', '', '', 0),
(13182, 'plPL', 'Nie zapomnij o jajach!', 'W całym Azjol-Nerub przemienieni przez Plagę nerubianie troskliwie pielęgnują jaja, z których wkrótce się wyklują nowe pokolenia, jeszcze bardziej zwiększając ich liczebność.$b$bNa niewiele by się zdało oczyszczenie jaskiń z plugawiących je nieumarłych, gdyby z tych skażonych jaj wykluły się kolejne i zajęły ich miejsce.$b$bPrzemierzając obszar, który niegdyś był Azjol-Nerub, oczyść naszą pradawną ojczyznę ze wszystkich jaj Plagi, jakie znajdziesz.', 'Kilix Rozplatacz z Czeluści Narjun chce, abyś $gwszedł:weszła; do Azjol-Nerub i $gzniszczył:zniszczyła; 6 nerubiańskich jaj Plagi.', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', 'Zniszczone nerubiańskie jaja Plagi', '', '', '', 0),
(13187, 'plPL', 'Beztwarzowi', 'W walce mojego ludu z siłami nieumarłych kopaliśmy coraz głębiej, w miarę jak traciliśmy teren. W desperacji dokopaliśmy się zbyt głęboko.$b$bNieświadomie odsłoniliśmy mackę woli Przedwiecznego, która przybrała postać istot znanych jedynie jako Beztwarzowi.$b$bOstatecznie nie zdołaliśmy walczyć na dwóch frontach z tak potężnymi wrogami. To nieszczęście kosztowało nas wojnę z nieumarłymi, a w końcu i nasz dom.$b$bWejdź do Ahn\'kahet, $N, i oczyść nasz dawny dom z tych beztwarzowych potworności.', 'Kilix Rozplatacz z Czeluści Narjun chce, abyś $gzabił:zabiła; herolda Volazja i trzech Zapomnianych, którzy mu towarzyszą w Ahn\'kahet.', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', 'Zapomniani zniszczeni', 'Herold Volazj pokonany', '', '', 0),
(13190, 'plPL', 'Wszystko w swoim czasie', 'Ahn\'kahet, skąd przybyliśmy...$b$bMarzę, że pewnego dnia przezwyciężymy śmierć i ciemność, które trzymają w uścisku nasz pradawny dom. W tym celu mam plan, jak osłabić determinację naszych wrogów.$b$bIch cenni Strażnicy muszą spłonąć!$b$bZabierz ich zwłoki i połóż je na kadzielnicy w głębi miasta. Woń ich spalonych szczątków będzie unosić się w powietrzu, przypominając naszym wrogom o ich słabości.$b$bUważaj, $N! Ich nieumarłe zwłoki są bardzo kruche i szybko się rozkładają.', 'Kilix Rozplatacz z Czeluści Narjun chce, abyś $gzdobył:zdobyła; zwłoki strażnika Ahn\'kahar i $gpołożył:położyła; je na kadzielnicy Ahn\'kahet w Ahn\'kahet.$b$bTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', 'Zwłoki strażnika Ahn\'kahar spalone', '', '', '', 0),
(13204, 'plPL', 'Grzybowe dziwactwa', 'Z wyjątkowo cuchnącego, pokrytego szlamem fragmentu cielska jaskiniowej bestii odpada bezkształtny kawałek grzybopodobnej narośli. Gdy mu się przyglądasz, jego przytłaczający smród budzi w tobie gwałtowne obrzydzenie.$b$bZastanawiasz się, czy nerubianie mogliby uznać coś takiego za smakowite. Wkładasz lepki organizm do plecaka i postanawiasz to sprawdzić...', 'Zbierz 6 groteskowych grzybów z dzikich jaskiniowych bestii w Ahn\'kahet i dostarcz je Kilixowi Rozplataczowi w Czeluści Narjun.', '', 'Wróć do Kilixa Rozplatacza w Czeluści Narjun na Smoczych Pustkowiach.', '', '', '', '', 0),
(13343, 'plPL', 'Tajemnica Nieskończonych – powtórka', 'Tu jesteś! A może dopiero co rozmawialiśmy?$B$B<Chromie rozmyśla nad możliwościami, jakie daje czas.>$B$BW każdym razie Nieskończeni na ciebie polują! No, nie tyle na ciebie, co na twoją dawną wersję, która broniła klepsydry wieczności. Pamiętasz, prawda?$B$BTo $gbyłeś:byłaś; wtedy ty, tylko że teraz to też ty. Chwila, to nieważne. Ważne jest, żebyś $gwrócił:wróciła; do Brązowej Smoczej Świątyni i $gobronił:obroniła; siebie i klepsydrę przed ich atakami, zanim $gzostaniesz wymazany:zostaniesz wymazana; z historii!', 'Chromie ze szczytu Świątyni Żmijowego Spoczynku prosi cię, abyś raz jeszcze $gudał:udała; się do Brązowej Smoczej Świątyni.$B$BW środku postaw klepsydrę wieczności na ziemi i pomóż swojemu dawnemu „ja” ochronić ją przed siłami Nieskończonego Stada.', 'Klepsydra wieczności ochroniona przed Nieskończonym Stadem.', 'Wróć do Chromie w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(13372, 'plPL', 'Klucz do Skupiającej Tęczówki', 'Z klejnotu w kształcie oka, który wypadł ze szponów Szafirona, bije potężne magiczne dudnienie, które można usłyszeć i poczuć. Dla śmiertelnych uszu przebywanie w pobliżu kamienia jest niemal bolesne.$B$BTak potężny i ważny przedmiot z pewnością należy zanieść królowej smoków, Alexstrazie Życiodajnej. Poproś ją o radę na szczycie Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', 'Dostarcz klucz do Skupiającej Tęczówki Alexstrazie Życiodajnej na szczycie Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', 'Wróć do Alexstrazy Życiodajnej na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(13375, 'plPL', 'Heroiczny klucz do Skupiającej Tęczówki', 'Z klejnotu w kształcie oka, który wypadł ze szponów Szafirona, bije potężne magiczne dudnienie, które można usłyszeć i poczuć. Dla śmiertelnych uszu przebywanie w pobliżu kamienia jest niemal bolesne.$B$BTak potężny i ważny przedmiot z pewnością należy zanieść królowej smoków, Alexstrazie Życiodajnej. Poproś ją o radę na szczycie Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', 'Dostarcz heroiczny klucz do Skupiającej Tęczówki Alexstrazie Życiodajnej na szczycie Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', 'Wróć do Alexstrazy Życiodajnej na Pustkowiach Smoków na Smoczych Pustkowiach.', '', '', '', '', 0),
(13384, 'plPL', 'Sąd w Oku Wieczności', 'Skoro masz już dostęp do Skupiającej Tęczówki, czas zrobić użytek z tego klucza.$B$BChoć bardzo chciałbym, by Malygos powrócił do nas, na tym etapie po prostu do tego nie dojdzie. Wobec tego, co jest stawką, pozostałe smocze Aspekty orzekły, że Tkacza Zaklęć trzeba unicestwić.$B$B<Krasus wypowiada te ostatnie słowa z wielkim niepokojem.>$B$B$N, udaj się do Oka Wieczności, zmierz się z Malygosem i wróć z sercem magii.', 'Krasus ze szczytu Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach chce, abyś $gwrócił:wróciła; z sercem magii.$B$BTo zadanie jest przeznaczone dla trybu normalnego, 10-osobowej wersji Oka Wieczności.', '', 'Wróć do Krasusa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(13385, 'plPL', 'Heroiczny sąd w Oku Wieczności', 'Skoro masz już dostęp do Skupiającej Tęczówki, czas zrobić użytek z tego klucza.$B$BChoć bardzo chciałbym, by Malygos powrócił do nas, na tym etapie po prostu do tego nie dojdzie. Wobec tego, co jest stawką, pozostałe smocze Aspekty orzekły, że Tkacza Zaklęć trzeba unicestwić.$B$B<Krasus wypowiada te ostatnie słowa z wielkim niepokojem.>$B$B$N, udaj się do Oka Wieczności, zmierz się z Malygosem i wróć z sercem magii.', 'Krasus ze szczytu Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach chce, abyś $gwrócił:wróciła; z sercem magii.$B$BTo zadanie jest przeznaczone dla trybu heroicznego, 25-osobowej wersji Oka Wieczności.', '', 'Wróć do Krasusa w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(24872, 'plPL', 'Wytchnienie dla udręczonej duszy', 'Weź ten kryształ życia i niech twoi towarzysze też wezmą po jednym. Zawiera potężne energie z zielonej Smoczej Świątyni na Smoczych Pustkowiach i był moim sekretem, dzięki któremu tak długo opierałam się mrocznej magii tego miejsca.$B$BGdy staniesz do walki z Sindragosą, walcz z nią, dopóki nie osłabnie, a potem niech twoi towarzysze użyją tych kryształów, by wywabić uśpioną w niej esencję. Jeśli ją wtedy pokonasz, zdołasz odzyskać esencję i zanieść ją do Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', 'Użyj kryształów życia, by zachować esencję Sindragosy.', '', 'Dostarcz esencję Sindragosy Kalegosowi w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(24880, 'plPL', 'Wytchnienie dla udręczonej duszy', 'Weź ten kryształ życia i niech twoi towarzysze też wezmą po jednym. Zawiera potężne energie z zielonej Smoczej Świątyni na Smoczych Pustkowiach i był moim sekretem, dzięki któremu tak długo opierałam się mrocznej magii tego miejsca.$B$BGdy staniesz do walki z Sindragosą, walcz z nią, dopóki nie osłabnie, a potem niech twoi towarzysze użyją tych kryształów, by wywabić uśpioną w niej esencję. Jeśli ją wtedy pokonasz, zdołasz odzyskać esencję i zanieść ją do Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', 'Użyj kryształów życia, by zachować esencję Sindragosy.', '', 'Dostarcz esencję Sindragosy Kalegosowi w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(26012, 'plPL', 'Kłopoty w Żmijowym Spoczynku', 'Mój stary przyjaciel Krasus donosi o niepokojących wydarzeniach w Żmijowym Spoczynku na Smoczych Pustkowiach. Jego wiadomość była krótka, ale wygląda na to, że doszło do jakiegoś ataku na Rubinowe Sanktuarium pod świątynią.$B$BPilne sprawy tu, w Dalaranie, nie pozwalają mi zająć się tym osobiście, ale słyszałem o twoich wyczynach w Cytadeli Króla Lisza i z pewnością podołasz temu zadaniu – może zechcesz pomóc Krasusowi w moim zastępstwie?', 'Porozmawiaj z Krasusem w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', 'Porozmawiaj z Krasusem w Świątyni Żmijowego Spoczynku na Smoczych Pustkowiach.', '', '', '', '', 0),
(26013, 'plPL', 'Atak na Sanktuarium', 'W Rubinowym Sanktuarium pod świątynią wydarzyło się coś strasznego.$B$BWejście do Sanktuarium leży w gruzach, a jego strażnicy zostali brutalnie zabici. Wysłaliśmy zwiadowców, by to zbadali, ale nie wrócili. Nie mogę oprzeć się najgorszym obawom.$B$BWejdź do Rubinowego Sanktuarium i dowiedz się, co spotkało dom mojego stada. Gdy będziemy wiedzieć więcej, zaplanujemy kolejne kroki.', 'Zbadaj Rubinowe Sanktuarium pod Świątynią Żmijowego Spoczynku.', '', 'Zbadaj Rubinowe Sanktuarium pod Świątynią Żmijowego Spoczynku.', '', '', '', '', 0),
(26034, 'plPL', 'Niszczyciel Zmierzchu', 'To nie był lekkomyślny atak, lecz starannie zaplanowane uderzenie w samo serce Czerwonego Stada.$B$BZarithrian, na tamtym urwisku, nadzoruje natarcie, ale prawdziwym przywódcą tych sił jest zuchwały i potężny smok zmierzchu imieniem Halion. Od czasów Dargonaxa nie widziano w pełni dorosłego pomiotu wypaczonych eksperymentów Sinestry.$B$BZabij go, $N, a gdy inwazja zostanie całkowicie odparta, zdaj Krasusowi relację ze wszystkiego, co tu $gwidziałeś:widziałaś;.', 'Pokonaj Haliona i odeprzyj inwazję na Rubinowe Sanktuarium.', '', 'Zamelduj się u Krasusa na szczycie Świątyni Żmijowego Spoczynku.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11958, 'plPL', 'Nie powiem, że cieszy mnie to, że muszę prosić cię o takie rzeczy w naszym imieniu. Ledwie nadążamy z przygotowaniami do odejścia, choć jeszcze nie wiemy, dokąd pójdziemy.$B$BMoi czarownicy mówią, że przybywasz, by ocalić tę ziemię przed Tym, Który Kroczy w Cieniu.$B$BUfam, że ocalisz również ludy tej ziemi.', 0),
(11959, 'plPL', 'Honorowa ofiara, jaką Loguhn złożył z twojej ręki, to dokładnie to, czego potrzebuje mój lud. Teraz wykorzystamy walki wolvarów o jego miejsce.$B$BMusi nam to wystarczyć.', 0),
(11960, 'plPL', 'No cóż, $gocaliłeś:ocaliłaś; ich całkiem sporo. Dziękuję ci, $N.$B$BTeraz wolvary będą miały szansę przetrwać razem z nami. O ile w ogóle przetrwamy.$B$BMyślisz, że $gmógłbyś:mogłabyś; wrócić jutro, żebyśmy ocalili więcej szczeniąt?', 0),
(11977, 'plPL', 'To, co tu widzisz, to wszystko, co zostało z taunka z Boreańskiej Tundry i Smoczych Pustkowi. To złamany lud... poturbowany i doprowadzony przez Plagę na skraj zagłady.$B$B<Jasne Kopyto kręci głową.>$B$BTylko Horda może ich teraz ocalić. Tylko Horda może uleczyć ich złamanego ducha. Przywrócimy im pełnię sił, a oni w zamian wzmocnią Hordę w Północnej Grani.', 0),
(11978, 'plPL', 'Właśnie tego nam trzeba, $N! Broń Hordy w dłoniach podniesie ich na duchu i da im ochronę, jakiej potrzebują przeciw Pladze.$B$BJesteś $ggotów:gotowa; na ceremonię przyjęcia?$B$B<Jasne Kopyto kiwa głową.>$B$BTo ty przyjmiesz naszych nowych sojuszników do Hordy.', 0),
(11979, 'plPL', 'To, co tu widzisz, to wszystko, co zostało z taunka z Boreańskiej Tundry i Smoczych Pustkowi. To złamany lud... poturbowany i doprowadzony na skraj zagłady.$B$B<Jasne Kopyto kręci głową.>$B$BTylko Horda może ich teraz ocalić. Tylko Horda może uleczyć ich złamanego ducha. Przywrócimy im pełnię sił, a oni w zamian wzmocnią Hordę w Północnej Grani.', 0),
(11980, 'plPL', '<Roh\'kill salutuje ci.>$B$B$GOcaliłeś:Ocaliłaś; nasz honor, $N. Tor\'zin i ja dziękujemy ci za ten bezinteresowny czyn!', 0),
(11983, 'plPL', 'Dziękuję, że to $gzrobiłeś:zrobiłaś;, dowódco $N. Nie mieli już nic. $gDałeś:Dałaś; im cel, a z celem przychodzi nadzieja... nadzieja na nowe jutro... na nowe życie.', 0),
(11995, 'plPL', 'Oczekiwałam cię, $N. Mamy wiele pracy, ty i ja.', 0),
(11996, 'plPL', 'Czemu tak długo? Czas czeka tylko na Aspekty, $N.$B$BMamy wiele pracy, ty i ja.', 0),
(11999, 'plPL', 'Ciekawe, zabiegają o porozumienie z Eterium. Eteryczni mogą okazać się potężnym sojusznikiem Malygosa w jego szaleństwie.$B$BTak być nie może!', 0),
(12000, 'plPL', 'Ciekawe, zabiegają o porozumienie z Eterium. Eteryczni mogą okazać się potężnym sojusznikiem Malygosa w jego szaleństwie.$B$BTak być nie może!', 0),
(12004, 'plPL', 'Szkoda, że według Goramosha porozumienie zostało już zawarte.$B$BTak czy inaczej, mamy o dwa robaki mniej na głowie. Zajmijmy się ważniejszymi sprawami.', 0),
(12005, 'plPL', 'W porządku, $N, po prostu połóż je tam na ziemi, przed tronem Agmara.$B$B<Na wizerunku arcymaga widać cień uśmiechu.>$B$BSzkoda, że według Goramosha porozumienie zostało już zawarte.$B$BTak czy inaczej, mamy o dwa robaki mniej na głowie. Przejdźmy do ważniejszych spraw.', 0),
(12006, 'plPL', 'Niech będzie, $gspełniłeś:spełniłaś; moją prośbę, jeśli nic więcej.$B$BDziękuję ci, $N.', 0),
(12008, 'plPL', 'Choć bez wątpienia $gwalczyłeś:walczyłaś; za sprawę Hordy gdzie indziej, wielu innych pracowało nad tym, by nasze wpływy sięgnęły głębiej w Północną Grań. Nawet teraz nasze siły zakładają bazy w zamarzniętych rubieżach tego posępnego pustkowia.$B$BOtaczamy Plagę ze wszystkich stron. Zwycięstwo jest blisko, bo nasze armie gromadzą się u stóp Angrathara, Bramy Gniewu. Wkrótce zburzymy bramę i wedrzemy się do Lodowej Korony.$B$BAle zostało jeszcze wiele do zrobienia...$B$BNajpierw powstrzymamy nerubian!', 0),
(12009, 'plPL', 'Jestem zwykłym traperem. Świat nagle stanął na głowie. To nie ma sensu.$B$BMam nadzieję, że zdołasz znów go poukładać.', 0),
(12011, 'plPL', 'Nie takie wieści chciałem usłyszeć, $N.$B$BNie, nie... dobrze, że mi $gpowiedziałeś:powiedziałaś;, ale obawiam się, że mój dawny wróg wrócił na te wody.', 0),
(12013, 'plPL', 'Masz moją najgłębszą wdzięczność, $N.$B$BJeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, ostrzeż swoich przełożonych przed niebezpieczeństwem, które uwolniło Błękitne Stado. Rozsadzając kotwicę linii mocy pod ogrodami, sprowadzają zagładę na nas wszystkich!', 0),
(12016, 'plPL', 'Udało ci się zabić Kili\'uę... może z Tu\'u\'gwarem zrobisz to samo.$B$BA może nie.', 0),
(12017, 'plPL', 'Będziemy świętować twój sukces, mój młody przyjacielu! W wodzie jest krew i to krew naszego wroga!$B$BMasz dozgonną wdzięczność tego starego rybaka, a z pewnością i wszystkich Kalu\'ak, gdy tylko rozniosę wieść!$B$BProszę, nalegam, weź coś w nagrodę.', 0),
(12028, 'plPL', 'Duchy i bełkoczące szaleństwo? To niemożliwe!$B$BMusimy szukać dalszych wskazówek.', 0),
(12030, 'plPL', 'Czekałem na ciebie, $N. Widziałem, jak przelatuje twój duch, i wyczułem mistyka, który patrzył twoimi oczami.$B$BTwój los i los Kalu\'ak są teraz ze sobą splecione.', 0),
(12031, 'plPL', 'Nie było to najprzyjemniejsze zadanie, ale konieczne i miłosierne.$B$BA teraz czeka cię jeszcze coś, co przeznaczone ci jest zrobić dla Kalu\'ak.', 0),
(12032, 'plPL', '$GRozmawiałeś:Rozmawiałaś; z Oacha\'noą?!$B$BJeśli jej wolą jest, byśmy stanęli u boku twojego ludu, niech tak będzie. Starszy Ko\'nani przyjmie to jako nasze przeznaczenie, na dobre i na złe.$B$BMój lud wierzy, że wszystkie dusze są jednym z magią świata. Musimy przeciwstawić się próbom zawładnięcia magią przez błękitne smoki, inaczej wszyscy jesteśmy zgubieni!$B$BNigdy nie sądziłem, że obrońcą Kalu\'ak zostanie ktoś taki jak ty, ale $gudowodniłeś:udowodniłaś;, że się myliłem. W imieniu mojego ludu dziękuję ci, $N.$B$BNiech bogowie ci sprzyjają i mają cię w swojej opiece.', 0),
(12033, 'plPL', '<Torvus kiwa ci głową.>$B$BWięc się rozumiemy? Wrócę do mojego pana i powiem mu, że $gprzyjąłeś:przyjęłaś;.', 0),
(12034, 'plPL', 'Z lądu i z powietrza – tak skończymy z zagrożeniem ze strony Anub\'ar.', 0),
(12036, 'plPL', 'To przeklęte zapadlisko musi łączyć się bezpośrednio z Azjol-Nerub. Jest gorzej, niż myślałem.$B$B<Juktok przez chwilę się zastanawia.>$B$BZnaleźć i zniszczyć... To będzie nasz następny krok.', 0),
(12039, 'plPL', 'Jakie lekkie... Jakby w ogóle nic nie ważyło! Potrzebuję czasu, żeby przeanalizować ten metal i sprawdzić, czy da się z nim coś zrobić! Testy! Muszę przeprowadzić testy!$B$BBędziemy w kontakcie, $N. Jeśli coś z tego wyjdzie, dowiesz się $gpierwszy:pierwsza;.', 0),
(12040, 'plPL', 'Są ich tysiące i wylewają się z każdej mrocznej szczeliny w Północnej Grani. W pojedynkę nie masz szans, ale razem... Może...', 0),
(12041, 'plPL', '<Nadrządca Agmar przegląda dokument.>$B$BCzy to jest to, co myślę? Dzięki informacjom z tych stron ZMIAŻDŻYMY natarcie Anub\'ar!$B$BDobrze, że $gprzyniosłeś:przyniosłaś; mi ten dokument, $N. Może będzie ci dane obserwować ostateczną bitwę pod Angratharem, a nawet w niej walczyć! LOK\'TAR!', 0),
(12043, 'plPL', 'A! No tak, nieumarli. Masz tu swoje monety i spadaj.', 0),
(12044, 'plPL', 'Ha! Ale ładunek! Plecy cię nie bolą?', 0),
(12045, 'plPL', 'Świetnie! Są nawet ostrzejsze, niż się spodziewałam. Zakopię je w śniegu, dopóki bomba nie będzie gotowa.$b$bZobaczmy... co dalej...\n', 0),
(12046, 'plPL', 'Dobrze... dobrze... te powinny się nadać. Bomby odłamkowe są prawie gotowe.$b$bZaraz... co się stało z moimi lodowymi odłamkami? Narf mówił, że odłamki z tych żywiołaków powinny być zaczarowane, a one topią się dokładnie tak jak te, które zwisają z gburowatego podbródka Narfa!', 0),
(12047, 'plPL', 'Świetnie! To powinna być ostatnia rzecz, jakiej potrzebuję, żeby przetestować nowe bomby. Chwileczkę, zaraz to wypróbuję!', 0),
(12048, 'plPL', 'Są w doskonałym stanie, $N. Od razu biorę się do pracy. Jeśli coś z tego wyjdzie, dowiesz się $gpierwszy:pierwsza;!', 0),
(12049, 'plPL', 'Ha, ha! Jeden z tych płatów mięsa wylądował aż tutaj! Dobra robota!\n', 0),
(12050, 'plPL', 'Jeśli w lesie przewróci się drzewo, a ty nie usłyszysz tego przez wizg piły, to czy naprawdę wydało jakiś dźwięk?', 0),
(12052, 'plPL', 'To powinno dać tym maszkarom do myślenia. Masz... bierz nagrodę i zmykaj.', 0),
(12053, 'plPL', 'Zmiażdżyliśmy ich na lądzie! Wkrótce zmiażdżymy ich z powietrza!', 0),
(12055, 'plPL', '$N, jeśli się nie mylę, $godkryłeś:odkryłaś; klucz, dzięki któremu dowiemy się, co dokładnie knują siły łowców magów!', 0),
(12056, 'plPL', '<Gort unosi głowę i wpatruje się w jej martwe oczy.>$B$BMówiłem, że cię dopadniemy...$B$BOto twoja nagroda, $N. Mamy o jeden ból głowy mniej.', 0),
(12057, 'plPL', '<Gort bierze od ciebie księgę.>$B$BDzikusy... Oprawiona w ciało twojej rasy... Ten język... Nigdy nie udowodniono, że istnieje. To język śmierci... Mowa Plagi.', 0),
(12059, 'plPL', '$N, jeśli się nie mylę, $godkryłeś:odkryłaś; klucz, dzięki któremu dowiemy się, co dokładnie knują siły łowców magów!', 0),
(12060, 'plPL', 'To, co opisujesz... to projekcja Arkanomikonu!$B$B<Troska na twarzy arcymaga szybko znika za obojętną maską.>$B$BArkanomikon to mapa wszystkich magicznych skrzyżowań linii mocy na świecie. Błękitne Stado używa go, by odnajdywać i niszczyć „kotwice” linii mocy i odsyłać magiczną moc z powrotem do Nexusa.$B$BPytanie tylko, dlaczego szlak zniszczenia prowadzi na wschód, skoro powinien biec na zachód?', 0),
(12061, 'plPL', 'To, co opisujesz... to projekcja Arkanomikonu!$B$B<Troska na twarzy arcymaga szybko znika za obojętną maską.>$B$BArkanomikon to mapa wszystkich magicznych skrzyżowań linii mocy na świecie. Błękitne Stado używa go, by odnajdywać i niszczyć „kotwice” linii mocy i odsyłać magiczną moc z powrotem do Nexusa.$B$BPytanie tylko, dlaczego szlak zniszczenia prowadzi na wschód, skoro powinien biec na zachód?', 0),
(12063, 'plPL', 'Mój ojciec wciąż żyje! Musimy go ocalić! Sam nie dam rady, $N. Musisz mi pomóc!', 0),
(12064, 'plPL', 'Tak, to zadziała.$B$B<Banthok zręcznie składa fragmenty klucza.>$B$BProszę, $N. Tym kluczem uwolnimy mojego ojca z więzienia Anub\'ar.', 0),
(12065, 'plPL', 'Jakie to dziwne, że przekazało ci te informacje za pomocą magii.$B$BWiemy więc nie tylko, że przekierowali przepływ mocy wypływającej z Ogrodów Księżycowego Spoczynku, ale też że ta moc jest celowo w jakiś sposób zmieniana. Co oni zamierzają zrobić z całą tą magią?$B$BNie podoba mi się, dokąd to zmierza, $N, ani trochę!', 0),
(12066, 'plPL', 'Jakie to dziwne, że przekazało ci te informacje za pomocą magii.$B$BWiemy więc nie tylko, że przekierowali przepływ mocy wypływającej z Ogrodów Księżycowego Spoczynku, ale też że ta moc jest celowo w jakiś sposób zmieniana. Co oni zamierzają zrobić z całą tą magią?$B$BNie podoba mi się, dokąd to zmierza, $N.', 0),
(12067, 'plPL', 'O nie... a przecież wysłaliśmy cię tam, żebyś ją $gzabił:zabiła;, prawda?$B$B<Komendantka kręci głową i wzdycha.>$B$BPrzykro mi. Dopilnuję, żeby list natychmiast trafił do jej ojca, arcymaga Malina w Wichrogrodzie. Nie martw się, nikt cię w to nie wplącze... to nie była twoja wina.$B$BSpróbuj o tym nie myśleć. Nie $gmogłeś:mogłaś; tego wiedzieć, $N.', 0),
(12069, 'plPL', 'Jesteś $gdzielny:dzielna;, $N. Ratując najwyższego wodza, $goddałeś:oddałaś; Hordzie wielką przysługę.', 0),
(12071, 'plPL', '<Valnok salutuje.>$B$BWięc to ty jesteś tym asem, co?', 0),
(12072, 'plPL', '<Valnok salutuje.>$B$BA teraz zmiażdżyliśmy ich z powietrza! Może wkrótce zostaniesz $gwezwany:wezwana; pod Angrathar, bohaterze!', 0),
(12075, 'plPL', 'Idealna. Dziękuję, $N.', 0),
(12076, 'plPL', 'Jeszcze świeża. Chwileczkę, zmieszam to z resztą eliksiru, który przygotowałem.', 0),
(12077, 'plPL', 'Powiem wprost, mała istoto – nie ufam tej miksturze i nie będę jej używał. Zatrzymaj ją... jeśli bardziej ufasz temu zielonemu konusowi niż ja, może ci się przyda.', 0),
(12078, 'plPL', 'Świetnie się nadadzą. Może gdy wyhoduję te bestie do pełnych rozmiarów, przyprowadzę je z powrotem i osobiście przedstawię olbrzymom.$b$bBanda bezużytecznych kamieni, jeśli chcesz znać moje zdanie.', 0),
(12079, 'plPL', 'Zadowalający pokaz rzezi.', 0),
(12080, 'plPL', 'Więc nie żyje. Tak jak powinno być. Twoje zamiary okazują się naprawdę szlachetniejsze niż zamiary tego konusa.$B$BPrzez północny kanion dojdziesz do Lasu Kryształowej Pieśni. To przeklęte i niebezpieczne miejsce, $N. Jeśli to twój następny cel, zachowaj ostrożność.$b$bWeź to za swój trud, mała istoto, i opuść tę skłóconą krainę z moim błogosławieństwem.', 0),
(12083, 'plPL', 'Wzmacniają nią swoje siły? To nie ma sensu; łowcy magów nie są aż tak potężni.$B$BTo musi znaczyć, że wykorzystują magię dopiero u celu, dokądkolwiek przekierowali linię mocy.$B$BBędziemy potrzebować więcej informacji, jeśli mamy mieć szansę ich znaleźć i powstrzymać!', 0),
(12084, 'plPL', 'Wzmacniają nią swoje siły? To nie ma żadnego sensu; łowcy magów nie są aż tak potężni!$B$BTo musi znaczyć, że wykorzystują magię dopiero u celu, dokądkolwiek przekierowali linię mocy.$B$BBędziemy potrzebować więcej informacji, jeśli mam obmyślić plan, jak ich powstrzymać!', 0),
(12085, 'plPL', 'Ahahahaha... buu, huu, jakie to wzruszające.$B$B<W gardłowym śmiechu nadrządcy aż czuć pogardę.>$B$BCo mówiłem? Zdrajcy! Ale kiedyś znałem Deino. Ona przynajmniej jest trollem z honorem!$B$BDopilnuję, żeby dowiedziała się, co się stało z jej bratem. Nawet zapomnę jej powiedzieć, że to ty go $gzabiłeś:zabiłaś;.$B$B<Agmar mierzy cię wyrachowanym spojrzeniem.>$B$BAle od teraz jesteś $gmoim dłużnikiem:moją dłużniczką;, $N!', 0),
(12089, 'plPL', 'Nie był pierwszym z tych mięczaków od czarów, który nas zdradził, i na pewno nie ostatnim. Szkoda, do licha... Był jednym z naszych najlepszych magów. Przywoływał taki bufet, że ślinka ciekła, a serce skakało z radości...$B$BBAH!', 0),
(12090, 'plPL', '$GDopadłeś:Dopadłaś; tego szpetnego syna kobyły, co? No, nasi żołnierze mają jeden kłopot mniej na tych zamarzniętych pustkowiach.', 0),
(12091, 'plPL', 'Najwyższy czas, żeby ktoś położył kres morderczemu szałowi tej plugawej bestii! Dobra robota, $N.', 0),
(12092, 'plPL', 'Dziękuję ci, $N! Tak wiele już straciliśmy. Dzięki tobie nie stracimy najbardziej majestatycznych dzieci Północnej Grani.$B$BWkrótce wyruszę porozmawiać z pradrzewcami, które $gocaliłeś:ocaliłaś;, i sprawdzę, czy pomogą nam w godzinie potrzeby.', 0),
(12095, 'plPL', 'Co ty myśleć, że tobie się udać tam, gdzie Rokhan nie dać rady?', 0),
(12096, 'plPL', 'Dziękuję ci, $N.$B$BGdy tylko skończę obserwować, co knują ci obrzydliwi aptekarze, wyruszę do lasu i spróbuję przekonać pradrzewce, żeby stanęły po naszej stronie.$B$BA jeśli nic innego się nie uda, przekonam je przynajmniej, żeby nie atakowały tych, którzy je ocalili!', 0),
(12097, 'plPL', 'HA! Udało ci się! Żołnierze pod Bramą Gniewu mają u ciebie dług, $N! Dzięki temu kilku z nich na pewno pożyje o dzień dłużej.', 0),
(12098, 'plPL', 'Znajdujesz tu zwłoki dowódcy łowców magów.$B$BSądząc po jego wyglądzie i stanie otaczających go oddziałów, nie utonęli. Raczej gdy przywołali tu ognisko, nie spodziewali się, że zaatakują ich żywiołaki, które wyłoniły się ze szczelin w dnie jeziora.$B$BWygląda na to, że siły łowców magów same zgotowały sobie zgubę.', 0),
(12100, 'plPL', 'Boli mnie, gdy muszę zabijać zwierzęta, ale ktoś musi to zrobić. Teraz przejdźmy do następnego kroku: szczepienia.', 0),
(12101, 'plPL', 'Ten niezdarny krowoczłek naprawdę zdobył organ odporny na gnicie? Do licha... Byłem pewien, że to zadanie zajmie jego pokraczny umysł aż do następnego tysiąclecia.$B$BNo dawaj go, $Gchłopcze:dziewczyno;. Mam mnóstwo roboty i nie potrzebuję, żeby twoje żałosne potrzeby mi przeszkadzały.', 0),
(12102, 'plPL', 'Nie było to takie trudne, prawda?$B$BA teraz daj mi chwilę na przygotowanie szczepionki.', 0),
(12104, 'plPL', '<Soar unosi fiolkę ku niebu i przygląda się jej zawartości.>$B$BZostała już tylko jedna rzecz do zrobienia.', 0),
(12106, 'plPL', 'Znajdujesz tu zwłoki dowódcy łowców magów.$B$BSądząc po jego wyglądzie i stanie otaczających go oddziałów, nie utonęli. Raczej gdy przywołali tu ognisko, nie spodziewali się, że zaatakują ich żywiołaki, które wyłoniły się ze szczelin w dnie jeziora.$B$BWygląda na to, że siły łowców magów same zgotowały sobie zgubę.', 0),
(12107, 'plPL', 'CO?!$B$B<Obraz przed tobą na chwilę się zniekształca, gdy arcymagini próbuje odzyskać panowanie nad sobą.>$B$BOczywiście, powinniśmy byli się domyślić, że o to im od początku chodziło. Szybko, nie ma czasu do stracenia.$B$BTrzeba ostrzec Żmijowy Spoczynek!', 0),
(12110, 'plPL', 'CO?!$B$B<Obraz przed tobą na chwilę się zniekształca, gdy arcymag próbuje odzyskać panowanie nad sobą.>$B$BOczywiście, powinniśmy byli się domyślić, że o to im od początku chodziło. Szybko, nie ma czasu do stracenia.$B$BTrzeba ostrzec Żmijowy Spoczynek!', 0),
(12111, 'plPL', '$GPostąpiłeś:Postąpiłaś; honorowo, $N. Proszę, wybierz nagrodę.', 0),
(12112, 'plPL', 'Przychodzi mi do głowy kilka zastosowań dla ciebie, zostań tu na trochę.', 0),
(12115, 'plPL', 'Są tylko dwie rzeczy w życiu, które mnie interesują, pachołku, i żadna z nich nie polega na tłumaczeniu dla ciebie księgi Plagi.$B$BJednak... może dojdziemy do porozumienia korzystnego dla nas obu.$B$B<Koltira dobywa broni.>$B$BTo moje runiczne ostrze, Byfrost. Byfrost łaknie krwi Króla Lisza i jego sług, ale najpierw muszę wyryć na nim runy mocy: symbole mrozu, krwi i cienia. Przynieś mi odpowiednie źródła mocy, a przetłumaczę twoją księgę.', 0),
(12119, 'plPL', 'List polecający na spotkanie z królową? Pokaż.$B$BCokolwiek cię sprowadza, mam nadzieję, że to ważne. Niebo roi się dziś od atakujących błękitnych!', 0),
(12122, 'plPL', 'List polecający na spotkanie z królową? Pokaż.$B$BCokolwiek cię sprowadza, mam nadzieję, że to ważne. Niebo roi się dziś od atakujących błękitnych!', 0),
(12123, 'plPL', 'Wykazujesz wielką odwagę, przynosząc nam te informacje. Zaczynałam się zastanawiać, dlaczego Błękitne Stado tak śmiało zaatakowało samą świątynię. Teraz wiemy, że używają ogromnych ilości tej samej magii, którą uważają za tak wielkie zagrożenie dla Azeroth.$B$B<Królowa kręci głową, jakby z rezygnacją.>$B$BTo hipokryzja, ale niech tak będzie. Jeśli Malygos nie odzyska rozsądku, nie mamy wyboru – musimy odpowiedzieć na ich napaść.', 0),
(12124, 'plPL', 'Wykazujesz wielką odwagę, przynosząc nam te informacje. Zaczynałam się zastanawiać, dlaczego Błękitne Stado tak śmiało zaatakowało samą świątynię. Teraz wiemy, że używają ogromnych ilości tej samej magii, którą uważają za tak wielkie zagrożenie dla Azeroth.$B$B<Królowa kręci głową, jakby z rezygnacją.>$B$BTo hipokryzja, ale niech tak będzie. Jeśli Malygos nie odzyska rozsądku, nie mamy wyboru – musimy odpowiedzieć na ich napaść.', 0),
(12125, 'plPL', 'Proste zadanie dla prostaka. Twoje wyniki mieszczą się w moich oczekiwaniach.', 0),
(12126, 'plPL', '<Oczy Koltiry rozszerzają się.>$B$BImponujące. $GPokonałeś:Pokonałaś; rycerza śmierci Arthasa... Z pewnością nie $gbyłeś sam:byłaś sama;... ale mimo to...', 0),
(12127, 'plPL', 'Już czuję, jak przepływa przeze mnie chłód, $N.', 0),
(12132, 'plPL', 'Moc, którą władam, ma wysoką cenę, $N. Wielu rycerzy, zarówno światła, jak i ciemności, straciło życie w ostatecznej bitwie pod Kaplicą Świetlistej Nadziei. Przyszłość rysuje się ponuro, ale przynajmniej wiem teraz, z czym się mierzę. Król Lisz nigdy nie rozluźni uścisku i już choćby za to musi zginąć!', 0),
(12136, 'plPL', '<Gort bierze od ciebie księgę i zaczyna czytać.>$B$BCO?! To niemożliwe. Niektórych z tych orków znam od lat!$B$BZostaw mnie, $N. Mam mnóstwo pracy i wielu zdrajców do stracenia.$B$BWeź jeden z tych przedmiotów za swój trud. $GOddałeś:Oddałaś; dziś Hordzie wielką przysługę.', 0),
(12140, 'plPL', 'Z pomocą tak potężnego szamana na pewno zwyciężymy pod Bramą Gniewu!', 0),
(12142, 'plPL', 'No i dobrze.', 0),
(12143, 'plPL', 'Mroźny Kieł, co? Słyszałem już o nim. Dobra robota, $N. Oby teraz udało nam się wrócić do smoczego zagrożenia.', 0),
(12144, 'plPL', 'No i dobrze, mon.', 0),
(12145, 'plPL', 'Lodowa Pięść, co? Słyszałem już o nim. Dobra robota, mon. Oby teraz my, Mroczne Włócznie, móc wrócić do tego smoczego zagrożenia.', 0),
(12146, 'plPL', 'To doprawdy dziwne, że magnataur nosił przy sobie taki przedmiot... i bardzo niepokojące. Cieszę się, że mi go $gpokazałeś:pokazałaś;.', 0),
(12147, 'plPL', 'To doprawdy dziwne, że magnataur nosił przy sobie taki przedmiot... i bardzo niepokojące. Cieszę się, że mi go $gpokazałeś:pokazałaś;.', 0),
(12148, 'plPL', 'A więc to prawda. Nie mogły lepiej wybrać chwili na taki atak... przez Plagę i błękitne stado raczej nikt jeszcze tego nie zauważył.', 0),
(12149, 'plPL', 'Świetna robota. Nikt nie potrafił mi powiedzieć, kim może być ten przywódca, ale udało mi się poznać imię kogoś, kto zna odpowiedź.', 0),
(12150, 'plPL', 'Grom\'thar Zwiastun Gromu. Dobrze. Skończmy z wszelkim zagrożeniem ze strony tych magnataurów tu i teraz.', 0),
(12151, 'plPL', 'Doprawdy, jesteś groźnym przeciwnikiem.$B$BSkoro Grom\'thara Zwiastuna Gromu już nie ma, możemy zostawić pozostałe magnataury, by walczyły między sobą, i znów zająć się poważniejszymi zagrożeniami.$B$BImponująca robota, $N.', 0),
(12166, 'plPL', 'Zrobiliśmy, co w naszej mocy, dla stworzeń tej ziemi. Teraz musimy wystąpić bezpośrednio przeciw tym, którzy do tego doprowadzili!', 0),
(12167, 'plPL', 'Dobra robota.$B$BPozbędę się tych plugawych szat – oczyszczę je w księżycowej studni i zniszczę mocą bogini!', 0),
(12168, 'plPL', 'A więc przywódca kultystów się ujawnił. Mamy imię.$B$BPróżność i duma go zgubią!', 0),
(12169, 'plPL', 'Gdy arcykultysta nie żyje, resztki jego sił można wyłapać, a ziemia i jej stworzenia odżyją.$B$BDziękuję, $N. Niech bogini oświetla ci drogę.', 0),
(12171, 'plPL', '<Palena czyta wiadomość.>$B$BWeźmiesz mojego najszybszego hipogryfa, $N! Te informacje muszą natychmiast trafić do wielkiego komendanta Zmory Żmijów!', 0),
(12172, 'plPL', 'Dobrze więc. Skoro ty jesteś $ggotów:gotowa;, to ja też.', 0),
(12173, 'plPL', 'Dobrze więc. Skoro uważasz, że jesteś $ggotów:gotowa;, nie marnujmy więcej mojego czasu.', 0),
(12174, 'plPL', '<Wielki komendant czyta wiadomość, a potem ją zgniata.>$B$BWiesz, gdzie są teraz ludzie z tej listy? Wyjrzyj na zewnątrz, przy głównej bramie. To ci, którzy wiszą na łukach.$B$BPrzynęta na ghule...', 0),
(12188, 'plPL', 'To się świetnie nada, $N. Te żałosne szczeniaki stawiały opór, czy tylko obsypały cię upiornymi łzami żalu?$B$BAch, one są takie uczuciowe...', 0),
(12189, 'plPL', 'Natknęliśmy się na mały – MALUTKI – problem. Każdy, kto próbował obchodzić się z zarazą, wyparował. Pracujemy nad drobną korektą formuły, żeby nie zabijała od razu za krzywe spojrzenie. Dobra wiadomość jest taka, że chyba już prawie mi się udało!', 0),
(12200, 'plPL', 'Sądzę, że zaraza jest teraz gotowa do próby polowej. Szczęśliwie się składa, że mroczna cytadela Naxxramas oblega Twierdzę Zimowej Straży. Spod samej ziemi, na której zbudowano Zimową Straż, powstają żywe trupy, skore wypełniać rozkazy Kel\'Thuzada.$B$BPrzymierze ma oczywiście za mało ludzi i za mało broni. Ci, których złożono do spoczynku w Mauzoleum Zimowej Straży, budzą się, łaknąc ciała!$B$BMoże damy im posmakować zarazy, co?', 0),
(12205, 'plPL', 'Bardzo dobrze, $N. Ufam, że przy zabijaniu $gbyłeś pomysłowo okrutny:byłaś pomysłowo okrutna;?$B$BZobaczmy, ile mogę ci dać z grobowca... ee, wybacz, ze skarbca?', 0),
(12206, 'plPL', 'CO?! To niemożliwe! Udoskonaliliśmy zarazę. Ma stuprocentową śmiertelność.$B$B<Aptekarka załamuje ręce, a na jej nieumarłym obliczu pojawia się niepokój. Wyraźnie sfrustrowana, mówi dalej gniewnym tonem.>$B$BTo naprawdę dziwne. Podaj mi tę flaszkę, $N. Nie będę tą aptekarką, która wszystko zepsuła!', 0),
(12209, 'plPL', 'Nie pachniesz już tak świeżo, świeże mięso.$B$BDobrze, wszystko to się przyda. Jak mam się do ciebie zwracać?', 0),
(12211, 'plPL', 'O, dobrze! Przez chwilę myślałam, że będę musiała wypróbować szczury na kimś, żeby się upewnić, że nie są wadliwe.$B$BWreszcie jakiś postęp!', 0),
(12214, 'plPL', 'Ach, nic mnie tak nie cieszy jak dobrze wykonana robota.$B$BZdobywając te konie, $goddałeś:oddałaś; Jadozłości wielką przysługę, $N.', 0),
(12218, 'plPL', 'Choć irytuje mnie, że być może pomogliśmy Przymierzu, ogłaszam próbę polową za udaną! Następny przystanek: Młot Agmara!', 0),
(12221, 'plPL', '<Doktor Malefious przegląda zawartość przesyłki.>$B$BWspaniale! Dokładnie według specyfikacji!$B$BOto twoja zapłata, $N. Zachowaj dla siebie to, co $gwidziałeś:widziałaś; i $gzrobiłeś:zrobiłaś;. Cała ta praca jest tajna – informacje przekazuje się tylko tym, którzy muszą je znać.', 0),
(12224, 'plPL', 'Lok\'tar ogar! Wiele o tobie słyszałem, $N. Twoje bitewne blizny są głębokie – to świadectwo twojego oddania i siły!$B$BSkoro ataki Króla Lisza na nasze flanki zostały zmiażdżone na zachodzie i na wschodzie, zostały tylko siły przy bramie. Z każdym dniem zyskujemy teren i wkrótce przebijemy się przez ten mur do Lodowej Korony!$B$BGdy powstrzymamy kościane smoki, najwyższy lord Fordragon i ja wyruszymy na pole bitwy.', 0),
(12230, 'plPL', '<Strażnik śmierci zaciera ręce w oczekiwaniu.>$B$BŚwietnie. Ich strata to mój... nasz zysk!$B$BNie $gmiałeś:miałaś; z żadną z nich kłopotów po drodze? Niektóre wyglądają na dość niestabilne. Może i jestem nieumarły, ale cenię sobie swoje istnienie!', 0),
(12232, 'plPL', 'Cóż za szczęśliwy dzień!$B$BSkoro nie zużyłem czasu i zasobów aptekarzy, żeby wykonać to zadanie, na pewno zwrócę uwagę najwyższego egzekutora!$B$BNieszablonowe myślenie – to cały ja. Tak, tak, ty też $gprzyłożyłeś:przyłożyłaś; do tego rękę.$B$BSłuchaj, jeśli coś ci dam, obiecasz, że nie wspomnisz o swoim udziale w tym wszystkim?', 0),
(12234, 'plPL', 'No, na co czekasz, $N? Dawaj je!', 0),
(12235, 'plPL', '<Urik wskazuje na gryfa.>$B$B$GLatałeś:Latałaś; kiedyś na czymś takim? To proste, $gprzyjacielu:przyjaciółko;. Po prostu wskakuj i mów mu, dokąd ma lecieć.\n', 0),
(12237, 'plPL', 'Znakomita robota, $N! Teraz, gdy nasi obywatele wrócili, możemy znów postawić tę twierdzę na nogi.', 0),
(12239, 'plPL', 'Masz wieści od mistrzyni szpiegów?$B$B<Agentka rozgląda się, by się upewnić, że nikt nie patrzy, i odkłada łopatę.>$B$BPokaż mi te plany.', 0),
(12240, 'plPL', 'Wiedziałam, że moja siostra nas nie zawiedzie.$B$BDobra robota, $N. Tartak Szturmu przez jakiś czas będzie wyłączony z użytku, a to oznacza koniec nowych budów i balist.$B$BDziękuję, że pomagasz mi przynieść chlubę rodowemu nazwisku.', 0),
(12243, 'plPL', 'Ahhahahahahahahahaha!$B$BBez locji nie mają już dokąd uciec.$B$BWygląda mi to na koniec Szkarłatnego Szturmu, i to akurat wtedy, gdy się rozkręcali. Jaka szkoda.$B$BHeh.', 0),
(12245, 'plPL', 'Co? $gSpodziewałeś:Spodziewałaś; się, że każemy ci ich ratować?$B$BA niby po co, skoro już udowodnili, że świetnie im wychodzi dawanie się złapać?$B$BPółnocna Grań to zimne miejsce, $gmłody:młoda; $N. Radzę ci do tego przywyknąć.', 0),
(12251, 'plPL', '<Halford salutuje.>$B$BWszyscy mieszkańcy wrócili do pracy? Już? Znakomicie, żołnierzu! W mgnieniu oka odbudujemy i umocnimy to miasto. Niebawem posiłki będą gotowe, by dołączyć do walki u boku lorda Fordragona przy Bramie Gniewu.$B$BOczywiście wybiegam myślami za daleko, bo zostało tu jeszcze wiele do zrobienia, zanim w ogóle pomyślimy o wysłaniu cię na pomoc Bolvarowi.\n', 0),
(12252, 'plPL', 'Wiedzieli to wszystko? I kim, do diabła, jest ten wielki admirał Zachodni Wiatr, o którym mówił?!$B$B<Najwyższy egzekutor mamrocze pod nosem, że nienawidzi niespodzianek.>$B$BLepiej wiedzieć, niż zgadywać. Mam nadzieję, że $gzostawiłeś:zostawiłaś; na nim swój... ee, mój znak.', 0),
(12253, 'plPL', '<Halford odmawia modlitwę za zmarłych.>$B$BWykonujesz dzieło Światłości, $N.$B$BObawiam się, że nasza praca dopiero się zaczęła.$B$B<Halford unosi jakiś dokument.>', 0),
(12254, 'plPL', 'Świeżo spisane błogosławieństwo na końcu księgi, mówisz?$B$B<Agentka zerka ci przez ramię, gdy przewracasz na ostatnią stronę.>$B$BNiech to szlag! To pismo wielkiego opata! Dałabym za to głowę – twoją.', 0),
(12258, 'plPL', 'Może teraz zaznają spokoju, a ich dusze wzniosą się ku Światłości.$B$BMoje myśli i modlitwy kieruję teraz ku lordowi Fordragonowi i naszym siłom przy Bramie Gniewu. Musimy tu wytrwać, choćby po to, by dać im dość czasu na pokonanie Króla Lisza. Zimowa Straż nie może upaść.', 0),
(12260, 'plPL', 'Nieźle, $N. Teraz, gdy wizerunek kapłana jest uwięziony w lustrze, mam dla ciebie kolejne zadanie.', 0),
(12261, 'plPL', 'Doskonale. Gdy zaczną uciekać w popłochu, osłona będzie tam, by czule ich pożegnać.', 0),
(12262, 'plPL', 'Błagali o swoje nędzne życie? Słabeusze.', 0),
(12263, 'plPL', 'Jesteśmy Czarnym Stadem. Od tysięcy lat sprowadzamy zagładę na ziemie Azeroth. Zgrzybiały Kult Potępionych czci śmierć, a my chętnie mu jej dostarczymy.', 0),
(12264, 'plPL', 'Słuchać ich wrzasków... patrzeć, jak ostatnia iskra życia gaśnie w ich nędznych ciałach... to orzeźwiające, prawda?$B$BRozkoszuję się tym.', 0),
(12265, 'plPL', 'Dobrze. Zostało jeszcze wiele do zrobienia.', 0),
(12266, 'plPL', 'A, to ty.$B$BMiałam nadzieję, że Serinar po prostu sam wróci, gdy skończy... Pewnie coś go rozproszyło albo znalazł sobie kolejną ofiarę. Omija go wspaniale krwawa bitwa!$B$BJeszcze tu jesteś? Skończyłam z tobą.', 0),
(12267, 'plPL', 'Kości mojego rodu zostały ocalone przed tym plugastwem. Dobrze mi $gsłużyłeś:służyłaś;, dlatego otrzymasz stosowną nagrodę.', 0),
(12269, 'plPL', '<Leoric bierze od ciebie karty.>$B$BPrzekażę je naszemu kronikarzowi i zaniosę ponure wieści rodzinom górników.$B$BZostało jeszcze wiele do zrobienia, jeśli mamy zwyciężyć tutaj, a w końcu i przy Bramie Gniewu. Lord Fordragon na nas liczy.', 0),
(12271, 'plPL', 'Mówisz, że miał ją LeCraft? To ma sens.$B$BPoznaję ją z czasów młodości, gdy byłem oprawcą na dworze króla Terenasa z upadłego Lordaeronu. Nazywa się ją różdżką przymusu.$B$B<Najwyższy egzekutor zaciera ręce w złowrogim oczekiwaniu na to, co nadejdzie.>$B$BMam pomysł, jak zrobić z niej dobry użytek!', 0),
(12272, 'plPL', 'To może być ta chwila, ta właśnie sekunda, w której szala przechyla się na niekorzyść Plagi. $GUdowodniłeś:Udowodniłaś;, że jesteś $gbohaterem:bohaterką; Przymierza, przynajmniej w moich oczach, $N.$B$BA teraz, jeśli łaska, zostaw mi trochę miejsca. Potrzebuję więcej czasu, by zbadać tę rudę, wyodrębnić zanieczyszczenia i znaleźć jej słabe punkty.$B$BRób swoje, $gsojuszniku:sojuszniczko;. Odezwę się, gdy będę coś wiedział.', 0),
(12273, 'plPL', '<Wydaje ci się, że przez twarz Wrotha przemyka cień uśmiechu, który zaraz znika.>$B$BOd teraz jesteś $gmoim ulubieńcem:moją ulubienicą;, $N. Jeśli masz ochotę, zastanów się nad wstąpieniem do Ręki Zemsty jako oficer.$B$BNa początek możemy cię przyjąć jako $gstrażnika:strażniczkę; śmierci, a za kilka dekad chyba będziesz $gmiał:miała; to, czego trzeba, by zostać młodszym egzekutorem!$B$BNie? Cóż, nie spiesz się tak z odpowiedzią... daj sobie czas i przemyśl to.', 0),
(12274, 'plPL', 'Co tu się, do diabła, dzieje?!$B$BSam skoczył? Na pewno go nie $gzepchnąłeś:zepchnęłaś;?$B$B<Agentka mruży oczy, przyglądając ci się.>$B$BNiech będzie. Najwyraźniej dzieje się tu znacznie więcej, niż początkowo sądziliśmy.', 0),
(12275, 'plPL', 'Czuję się z tym okropnie, $gprzyjacielu:przyjaciółko;. Obawiam się, że w pośpiechu, by odzyskać dziwną rudę z Kopalni Zimowej Straży, mogłem skazać agenta Slinkina na zgubę.\n', 0),
(12276, 'plPL', '<Slinkin ściska w martwej dłoni notatkę.>$B$BZapędzony w ślepy zaułek. Na razie ukryty, ale wiedzą, że tu jestem. Niedługo mnie znajdą.$B$BGórnicy niestrudzenie wydobywają dziwną rudę, która napędza machiny wojenne Plagi. Dużo gadają. Język śmierci jest dla mnie niezrozumiały, ale zdołałem rozpoznać często powtarzane dźwięki i zwroty. Słowo „Yogg-Saron” wymawiają z wielką pogardą i zwykle towarzyszą mu głośne okrzyki. Rudę nazywają „saronitem”. Co to znaczy?', 0),
(12277, 'plPL', 'Jego śmierć nie pójdzie na marne, $gprzyjacielu:przyjaciółko;. Informacje, za które zginął Slinkin, odegrają kluczową rolę w pokonaniu Króla Lisza. Obiecuję ci, że jeszcze to naprawimy.', 0),
(12281, 'plPL', '<Halford otwiera paczkę i czyta analizę.>$B$BW żadnym razie nie jestem naukowcem, $N, więc wybacz mi prostackie zrozumienie tego, co tu napisano. Otóż według tej analizy – zakładając, że rozumu mam przynajmniej tyle co uczniak – nadal nie wiemy o machinie wojennej Plagi zupełnie nic. Wiemy tylko, że Plaga wykorzystuje ten plugawy metal do wytwarzania machin oblężniczych, zbroi i broni.$B$B<Halford wydaje z siebie długie westchnienie.>', 0),
(12282, 'plPL', 'Dobra robota, $N. Jak przepowiedział los, to ty przeprowadzisz nas przez te ciężkie czasy. Teraz zaczyna się długa podróż.', 0),
(12283, 'plPL', 'Niech to szlag! Czemu nie $gmogłeś:mogłaś; przyjść do mnie z dobrymi wieściami?!', 0),
(12285, 'plPL', 'Niech spróbują ją wskrzesić bez głowy!$B$B<Śmiech najwyższego egzekutora ściąga kilka ukradkowych spojrzeń.>$B$BTrochę mnie martwi, że $gpozwoliłeś:pozwoliłaś; uciec temu wielkiemu admirałowi, ale i tak jesteś $gbohaterem:bohaterką; dnia, $N!$B$BWybieraj... $gzasłużyłeś:zasłużyłaś;!', 0),
(12287, 'plPL', 'Zelig przysłał wiadomość, $gprzyjacielu:przyjaciółko;. Spodziewaliśmy się ciebie.$B$BJestem Orik Prawe Serce, paladyn Krucjaty Argentu. Kapłanka stojąca po drugiej stronie ogniska to Tilda Darathan. Jesteśmy tu w imieniu Krucjaty Argentu – przysłano nas, byśmy uśmierzyli nieszczęsne potępione dusze, które próbują wydostać się z Zimowej Straży.', 0),
(12290, 'plPL', '<Orik bierze mroczne zielsko i zaczyna mieszać eliksir.>$B$BTo już nie potrwa długo, $N.', 0),
(12291, 'plPL', '<Oczy Orika napełniają się łzami.>$B$BOni nie wiedzą. Żaden z nich nie wie! Myślą, że Arthas był wielkim bohaterem, a przecież to Arthas kazał spalić statki. To Arthas zostawił nas wszystkich na pewną śmierć na tym zamarzniętym pustkowiu!$B$B<Orik płacze.>$B$BNie wszyscy żołnierze z floty księcia zginęli podczas mroźnej zimy. Byłem jeszcze chłopcem, gdy dano mi szansę walki z Plagą... ocalenia naszego domu przed pewną zagładą. Skorzystałem z tej szansy, $N.', 0),
(12301, 'plPL', '<Orik uśmiecha się do ciebie promiennie.>$B$B$GDokonałeś:Dokonałaś; dziś dobrego uczynku, $N. Dzięki tobie setki zagubionych dusz zostały odkupione.', 0),
(12303, 'plPL', '<Kwatermistrz aż wstrzymuje oddech, ale zaraz mruży oczy i przez chwilę ci się przygląda.>$B$BUfam, że niczego nie $godłożyłeś:odłożyłaś; na boku dla siebie? Chyba nie $gbyłbyś:byłabyś; aż tak $gsamolubny:samolubna;, gdy na szali leży los Jadozłości?$B$BZresztą i tak nagrodzę cię częścią łupu. To niewiele, ale w takich czasach wszyscy musimy się poświęcać.', 0),
(12304, 'plPL', 'Już to widzisz, $N? To będzie najmodniejszy kurort Północnej Grani!$B$BCo myślisz o nazwie „Zatoczka Hansena”? Albo może „Zatoka $N”? Całkiem chwytliwe, nie sądzisz?', 0),
(12305, 'plPL', '<Zelig się uśmiecha.>$B$BTo ja mam wobec ciebie dług wdzięczności, $gbohaterze:bohaterko;. Orik jest dla mnie jak brat. $GOdmieniłeś:Odmieniłaś; jego życie i $gdałeś:dałaś; nową nadzieję niezliczonym innym.', 0),
(12309, 'plPL', 'O rety, ale tam na dole bałagan! Ostatnim razem ledwo uszedłem z życiem – dlatego właśnie poprosiłem wielkiego komendanta o wsparcie.$B$B<Durkon mierzy cię wzrokiem od stóp do głów.>$B$BMasz w oczach ten szalony błysk. I dobrze, bo trzeba być szaleńcem, żeby zrobić to, o co zaraz cię poproszę.', 0),
(12311, 'plPL', 'Gdybyśmy teraz jeszcze zdołali powstrzymać ataki Plagi spoza twierdzy, moglibyśmy wysłać pomoc lordowi Fordragonowi przy Bramie Gniewu.', 0),
(12312, 'plPL', 'Cokolwiek zawiera ta księga, musi to być niezwykle ważne! Słyszałem wycia i zawodzenia niosące się echem po krypcie, gdy się stamtąd $gwydostawałeś:wydostawałaś;!$B$BTrzeba powiadomić wielkiego komendanta!', 0),
(12319, 'plPL', '<Oczy Halforda rozszerzają się.>$B$BLos się do nas dziś uśmiecha, $N. Wiem dokładnie, do kogo się udać w sprawie tej księgi.', 0),
(12320, 'plPL', 'Być może przy odpowiedniej motywacji Godfrey powie nam, co wie o tej księdze.$B$B<Hallard odwraca się do burmistrza Godfreya.>$B$BCzyż nie tak, burmistrzu?', 0),
(12321, 'plPL', 'Powinniśmy byli wiedzieć o tym przeklętym mauzoleum. To niedorzeczne! Książę August Wrogomłot i Ambo Cash zostaną wysłani na linię frontu, by przygotować nasze kolejne natarcie.$B$BGdy oczyścisz kopalnie, wyślę cię do Wrogomłota, abyśmy mogli rozpocząć atak na Plagę z Naxxramas!$B$BInformacje, które dotąd $gzdobyłeś:zdobyłaś;, polecą do lorda Fordragona przy Bramie Gniewu na skrzydłach naszego najlepszego gryfa!', 0),
(12325, 'plPL', 'A, oto i $gnasz znamienity bohater:nasza znamienita bohaterka;. Witaj w samym epicentrum, $N. Pozwól, że wprowadzę cię w sytuację!$B$BNajpotężniejsze siły Thel\'zana wdarły się do Mauzoleum Zimowej Straży. Przeczesują jego głębie w poszukiwaniu zwłok i dusz, które mogą posłać przeciw Zimowej Straży, a Naxxramas zrzuca na nas straszliwe machiny zarazy Plagi, by trzymać nas na dystans!$B$BMusimy uderzyć teraz i mieć nadzieję, że lord Fordragon zdoła jeszcze trochę wytrzymać przy Bramie Gniewu.\n', 0),
(12326, 'plPL', 'Dlaczego nie mam na sobie spodni, to nieważne. Powiedzmy, że oberwałem odłamkiem Plagi w niewłaściwe miejsce, i na tym poprzestańmy, dobra?$B$BA więc $gzmiotłeś:zmiotłaś; te wozy zarazy na polach i $gdowiozłeś:dowiozłaś; tu moich żołnierzy w jednym kawałku. Imponujące. Niewielu przed tobą dotarło aż tutaj, $gprzyjacielu:przyjaciółko;. Szkoda, że musisz od razu wracać na Pola Padliny. Tak, mieliśmy mały problem.\n', 0),
(12372, 'plPL', 'Niesamowite! Muszę przyznać, że wciąż zdumiewa mnie, do czego zdolne są wasze młodsze rasy.$B$BJesteśmy twoimi dłużnikami. Wrócisz jutro, by znów nam pomóc?', 0),
(12416, 'plPL', 'To obrzydliwe zadanie, ale z całego serca dziękuję ci za jego wykonanie.$B$BNie możemy pozwolić Pladze posunąć się dalej w stronę Żmijowego Spoczynku, bo z pewnością go stracimy.', 0),
(12417, 'plPL', 'W ziemi moi bracia mogą dać nowe życie. $GOcaliłeś:Ocaliłaś; ich przed losem znacznie gorszym niż śmierć.$B$BNie znam w twoim języku słowa, które wyraziłoby, ile to znaczy dla mojego gatunku. Dziękuję ci.', 0),
(12418, 'plPL', 'Dahlia... przemienili ją?$B$BDahlia była nam wierna od bardzo dawna... jeśli zdołali splugawić istotę tak oddaną, nie wróży to dobrze reszcie młodych ras. Dziękuję, że ją $guwolniłeś:uwolniłaś;. Mam nadzieję, że zaznała spokoju.$B$B$GUhonorowałeś:Uhonorowałaś; nas dziś swoją bezinteresowną pomocą. Przekażę radzie, czego dokonali tu twoi pobratymcy. Idź z naszym błogosławieństwem.', 0),
(12419, 'plPL', 'Dahlię porwała Plaga? To smutny dzień dla nas wszystkich.$B$BGdy odbijemy świątynię, poszukam nowego opiekuna. Dziękuję za twoje wysiłki... Rubinowa Smocza Świątynia to dla nas święte miejsce, a ofiary, które ponieśli twoi pobratymcy, nie zostaną łatwo zapomniane.$B$BDobrze wiedzieć, że wciąż są tacy bohaterowie jak ty – pewnego dnia cię wezwę. Do tego czasu niech twoje przygody przynoszą obfite owoce.', 0),
(12435, 'plPL', 'Ty musisz być $N. Królowa uprzedziła mnie, że przybędziesz.$B$BJeśli zechcesz, bardzo potrzebujemy twojej pomocy.', 0),
(12438, 'plPL', 'Dobra robota, $N. Powiadomię Illusię, że znalazł się bohater, który usłyszał jej wołanie o pomoc i podjął wyzwanie! Oto twoja nagroda.', 0),
(12439, 'plPL', 'Zdecydowanie nie chcemy kolejnego rozłamu, $gprzyjacielu:przyjaciółko;. Zrobię wszystko, co w mojej mocy, by pomóc ci w misji.', 0),
(12440, 'plPL', 'A więc Vas usłyszał moje wezwanie, co? W samą porę, $gprzyjacielu:przyjaciółko;.', 0),
(12441, 'plPL', 'Znakomita robota, $N! Powiadomię Drolfy\'ego, że znalazł się bohater, który podjął jego wyzwanie, i że okrutny Krwawa Łapa już nie żyje!', 0),
(12442, 'plPL', 'Przynajmniej na razie niecne plany Szkarłatnego Szturmu doznały porażki. $GOddałeś:Oddałaś; Zimowej Straży wielką przysługę, $N.\n', 0),
(12447, 'plPL', 'Próbuję rozstrzygnąć, co mnie bardziej dziwi... że naprawdę $gprzybyłeś:przybyłaś; z pomocą czarnemu smokowi, czy że po rozmowie z Nalice wciąż jesteś w jednym kawałku.$B$BJej słowa ociekają jadem, ale najwyraźniej Żmijowy Spoczynek potrafi czasem utrzymać w ryzach nawet nasz gatunek.$B$BA może to tylko zasługa armii Czerwonego Stada, które ją otaczają.', 0),
(12448, 'plPL', 'To obrzydliwe zadanie, ale dziękuję ci za jego wykonanie.$B$BNie możemy pozwolić Pladze wydostać się dalej poza świątynię, bo opanuje całe te ziemie.', 0),
(12449, 'plPL', 'W ziemi moi bracia mogą dać nowe życie. $GOcaliłeś:Ocaliłaś; ich przed losem znacznie gorszym niż śmierć.$B$BNie znam w twoim języku słowa, które wyraziłoby, ile to znaczy dla mojego gatunku. Dziękuję ci.', 0),
(12450, 'plPL', 'Dahlia... przemienili ją?$B$BDahlia była nam wierna od bardzo dawna... jeśli zdołali splugawić istotę tak oddaną, nie wróży to dobrze reszcie młodych ras. Dziękuję, że ją $guwolniłeś:uwolniłaś;. Mam nadzieję, że zaznała spokoju.$B$B$GUhonorowałeś:Uhonorowałaś; nas dziś swoją bezinteresowną pomocą. Być może nie wszyscy w Hordzie mają czarne serca swoich przodków. Przekażę radzie, czego dokonali tu twoi pobratymcy.', 0),
(12454, 'plPL', 'Nie żałuj swojego udziału w kręgu życia. Narodziny, śmierć i odrodzenie to część naturalnego porządku.', 0),
(12455, 'plPL', 'W samą porę! Kilku moich żołnierzy wykazało się nadgorliwością i postanowiło wejść do krypt tuż na wschód i zachód od nas. Rzecz jasna te bezmyślne ghule szybko ich przytłoczyły. Musimy uratować ocalałych!', 0),
(12456, 'plPL', 'Nie płacz po Alystrosie. Poświęcił swoje wieczne życie obronie Szmaragdowej Smoczej Świątyni i odrodzi się.$B$BMam nadzieję, że gdy do nas wróci, nie ogarnie go zamęt Szmaragdowego Koszmaru, który zdaje się trzymać w swych szponach Śniącą.', 0),
(12457, 'plPL', '$N, nie widziałem takiego bohaterstwa od czasów Silithusa!$B$BDopilnuję, żeby każdy z tych żołnierzy polecił lordowi Fordragonowi twój awans!$B$BA teraz do pilniejszych spraw. Nasi zwiadowcy donoszą, że Thel\'zan jest blisko.\n', 0),
(12458, 'plPL', 'Już teraz czuję w tych nasionach puls natury.$B$BMusimy zrobić z nich dobry użytek!', 0),
(12459, 'plPL', 'Doskonale. Dokładnie tak, jak od początku podejrzewałem. Będę musiał spróbować skontaktować się z Yserą i sprawdzić, czy to pochwala.$B$BO ile uda się ją wyrwać z koszmaru, rzecz jasna.$B$BDziękuję, $N. Twoja pomoc okazała się nieoceniona.', 0),
(12460, 'plPL', 'Przysłała cię ambasador Lauriel?$B$BJeśli znów z nią porozmawiasz, przekaż jej, proszę, że jesteśmy bardzo wdzięczni za jej pomoc. Walczymy na zbyt wielu frontach.', 0),
(12461, 'plPL', 'Przysłał cię ambasador Golluck?$B$BJeśli znów z nim porozmawiasz, przekaż mu, proszę, że jesteśmy bardzo wdzięczni za jego pomoc. Walczymy na zbyt wielu frontach.', 0),
(12462, 'plPL', 'To powinno dać Ambo trochę czasu, żeby wszystko poukładać.', 0),
(12463, 'plPL', '<Przy zwłokach Łupobrodego znajdujesz dziennik.>$B$BWpis pierwszy:$B$BWloką zwłoki tunelem do sali balsamowania, gdzie przeprowadzają na nich eksperymenty. W tym mauzoleum zapas jest niewyczerpany. Czego nie da się ożywić, to przerabiają na jakiś kościany konstrukt.$B$BWpis drugi:$B$BObawiam się, że ten lisz, Thel\'zan, skrywa mroczny sekret. Kim on jest? Czy kiedyś był... jednym z nas?$B$BWpis trzeci: Odkryłem, gdzie jest filakteria lisza. Znajduje się...$B$B<Pozostałe strony są wyrwane.>', 0),
(12464, 'plPL', 'Niefortunny, ale konieczny krok, który musieliśmy podjąć wobec Abbendis. W innym życiu potrafiłbym sobie wyobrazić, że walczę u jej boku.$B$B<Głos dowódcy cichnie, gdy przez chwilę się zamyśla, po czym mówi dalej.>$B$BTrochę niepokoi mnie ten wielki admirał, o którym mówisz. Barean Zachodni Wiatr, powiadasz? Nie mogę uwierzyć, że wciąż żyje. Musi być wiekowy. Tym jednak zajmiemy się później.$B$BTymczasem chyba $gzasłużyłeś:zasłużyłaś; na nagrodę i odrobinę wypoczynku.', 0),
(12465, 'plPL', '<Ambo czyta odzyskane strony dziennika.>$B$BMam dobre i złe wieści. Które chcesz najpierw?$B$BA, do diabła, po co ci dawać wybór? Dobra wiadomość jest taka, że jeśli zdobędziemy filakterię Thel\'zana, możemy go zniszczyć. Zła – że filakterię ma przy sobie dość spory żmij mrozu.', 0),
(12466, 'plPL', 'Teraz już wiesz, dlaczego nazywają to miejsce Pustkowiami Smoków. Kości tych bestii walają się, jak okiem sięgnąć.$B$BZestrzeliliśmy już chyba z tuzin żmijów mrozu, a końca wciąż nie widać. Przy tylu rozrzuconych kościach Plaga ma materiał na dziesięć tysięcy kolejnych.$B$B<Tyralion odchrząkuje.>$B$BNie chcę cię zanudzać szczegółami, $gbohaterze:bohaterko;. Mamy na celowniku żmija, którego szukasz.', 0),
(12467, 'plPL', 'Straciliśmy przez tego potwora, Thel\'zana, tylu dobrych żołnierzy. Szkoda, że nie będzie mnie tam, gdy zmiażdżysz jego filakterię na jego oczach i zakończysz jego istnienie.', 0),
(12469, 'plPL', 'Ha! Straciliśmy kolejnego, co? Te harpie robią się prawdziwym utrapieniem.$B$BNieważne! Jest robota do zrobienia. Pomożesz tu trochę, co?', 0),
(12470, 'plPL', '$GWidziałeś:Widziałaś; Nozdormu? To nie ma sensu.$B$B<Chromie przez chwilę zastanawia się nad twoimi słowami.>$B$BW sumie to świetna wiadomość! Nie mieliśmy pojęcia, dokąd ani do kiedy udał się Pan Czasu. Wiedzieliśmy tylko, że zniknął, by zająć się bardzo ważnymi sprawami.$B$BChoć więc przywódca Nieskończonego Stada się nie ujawnił, $godkryłeś:odkryłaś;, że Nozdormu żyje, ma się dobrze i stawia im opór!$B$BDziękuję, $N. Do zobaczenia wkrótce!', 0),
(12472, 'plPL', 'Gdy $gbędziesz gotów:będziesz gotowa;, umieszczę filakterię przed wrotami i wywołam Thel\'zana.', 0),
(12473, 'plPL', 'Zimowa Straż ocalała dzięki tobie, $N. Większości trudno pojąć, że $gjeden mężczyzna:jedna kobieta; $gmógł:mogła; tak szybko odwrócić losy bitwy, a jednak oto jesteśmy – zwycięscy! $GZdołałeś:Zdołałaś; przywrócić tym ludziom wiarę i $gzdobyłeś:zdobyłaś; szacunek swoich dowódców.$B$B<Halford salutuje.>$B$BLord Fordragon wrócił do Angrathar, by przygotować nasze siły do zniszczenia Bramy Gniewu, i prosi, byś do niego $gdołączył:dołączyła;! Nie mógłbym polecić do tego zadania lepszego żołnierza, $N.', 0),
(12474, 'plPL', 'To odznaczenie przyznaje się tylko tym, którzy w imię Przymierza zrobili znacznie więcej, niż nakazywał obowiązek. Mógłbym policzyć na palcach jednej ręki, ile razy je wręczałem, $N, i nikt nie zasłużył na nie bardziej niż ty! Gratulacje!$B$BA teraz spójrzmy na Bramę Gniewu. Wygląda znajomo? Powinna. Dziwna ruda, którą $gznalazłeś:znalazłaś; w Kopalni Zimowej Straży, to dokładnie ten materiał, z którego zbudowano Bramę Gniewu. Znajdziemy jej słaby punkt i obnażymy go na oczach wszystkich! Najpierw jednak...', 0),
(12475, 'plPL', 'Jaskinia? Czy to możliwe? Nie może być innego związku!', 0),
(12476, 'plPL', 'Miejmy nadzieję, że Szturm wreszcie zrozumiał przesłanie. Oby dostali takie lanie, że zwątpią, po czyjej stronie stoją.\n', 0),
(12477, 'plPL', '<Halford czyta dziennik.>$B$BAbbendis kompletnie odbiło. Teraz przemawia do niej Światłość?$B$BMimo tego niedorzecznego bełkotu dziennik pozwala nam zajrzeć do umysłów szkarłatnych fanatyków jak nigdy dotąd. To było wspaniałe znalezisko, $N. Lord Fordragon będzie zadowolony.', 0),
(12478, 'plPL', 'Muradin żyje? Czy to możliwe? Muszę natychmiast powiadomić króla Miedziobrodego!$B$BMuszę poradzić się kuli. Gdzieś muszą być dalsze informacje!\n', 0),
(12487, 'plPL', 'Kim jesteś?$B$BPowiedz mi, dlaczego nie miałabym przeciąć cię na pół tam, gdzie stoisz!', 0),
(12488, 'plPL', 'Przysłano cię z Młota Agmara? Najwyższy czas!$B$BNie, ta pomoc nie jest dla mnie. Po prostu nie mam nikogo innego do dyspozycji, ale ty się nadasz.', 0),
(12495, 'plPL', 'Przybywasz po moją radę, $gśmiertelniku:śmiertelniczko;. To wiem, ale czy ty wiesz, z czym się mierzysz?$B$B<Alexstraza wskazuje na północ.>$B$BNa północ stąd leży miejsce śmierci Galakronda – protoplasty smoczego rodu. To z Galakronda tytani stworzyli Aspekty. Wyobraź sobie zatem potęgę Galakronda. Sam jego rozmiar przewyższał wszystkie Aspekty razem wzięte! A teraz spróbuj zrozumieć, co Plaga robi na Wielkich Smoczych Pustkowiach.$B$BŻmije mrozu, $gśmiertelniku:śmiertelniczko;, powinny być najmniejszym z twoich zmartwień.', 0),
(12496, 'plPL', 'Przybywasz po moją radę, $gśmiertelniku:śmiertelniczko;. To wiem, ale czy ty wiesz, z czym się mierzysz?$B$B<Alexstraza wskazuje na północ.>$B$BNa północ stąd leży miejsce śmierci Galakronda – protoplasty smoczego rodu. To z Galakronda tytani stworzyli Aspekty. Wyobraź sobie zatem potęgę Galakronda. Sam jego rozmiar przewyższał wszystkie Aspekty razem wzięte! A teraz spróbuj zrozumieć, co Plaga robi na Wielkich Smoczych Pustkowiach.$B$BŻmije mrozu, $gśmiertelniku:śmiertelniczko;, powinny być najmniejszym z twoich zmartwień.', 0),
(12497, 'plPL', 'Odwaga śmiertelników nigdy nie przestaje mnie zdumiewać. Śmierć wbija w was swoje zimne spojrzenie, a wy w odpowiedzi stajecie, by rzucić jej wyzwanie! Dlatego wasz gatunek jest tak kochany... i tak znienawidzony.$B$BChoć Czerwone Stado jest pogrążone w wojnie z Malygosem, możemy coś zrobić, by pomóc.', 0),
(12498, 'plPL', 'Wiedziałam, że wrócisz, $N. $GPrzysłużyłeś:Przysłużyłaś; się Paktowi Żmijowego Spoczynku i $gocaliłeś:ocaliłaś; swój lud przed pewną śmiercią. Niech wszyscy się o tym dowiedzą i niech zostanie to zapisane dla potomności!', 0),
(12499, 'plPL', 'Wiedz jedno: wszystko, co $gzrobiłeś:zrobiłaś;, doprowadziło do tej chwili. Bez twoich wysiłków bylibyśmy skończeni! A teraz trzymaj straż, a ja wyruszę w pole i to zakończę!', 0),
(12500, 'plPL', 'Mój ojciec miał co do ciebie rację, $N. Wszystko, co powiedział, się spełniło – pozostał tylko jeden, ostatni obowiązek. Teraz poprowadzę Kor\'kron na linię frontu. Nadszedł czas, by zakończyć tę wojnę. Tyrania Króla Lisza kończy się dziś!$B$BZajmij teraz moje stanowisko, $N, i czuwaj nad naszymi siłami.', 0),
(12511, 'plPL', 'Prawie cię zestrzelili, co? Dzikie potwory – ta Horda.$B$BZapłacą za to, co zrobili. Przynajmniej tego możesz być $gpewien:pewna;, $N.$B$BA teraz czas zagonić cię do roboty.', 0),
(12542, 'plPL', 'Zaledwie kilka kroków stąd leży imperium Drakkarów.$B$B<Valus wskazuje na wschód.>$B$BPrzez tysiące lat Drakkarowie żyli w izolacji, woląc trzymać się w granicach swoich rozległych miast-świątyń i zikkuratów. Tym większym zaskoczeniem było natrafienie na te ruiny. Dalej, za złowieszczymi schodami prowadzącymi do Zul\'Draku, w gruzach leży Twierdza Drak\'Tharon. Cały pierwszy poziom Zul\'Draku zniszczony...$B$BDlaczego Plaga czekała z atakiem aż do teraz?', 0),
(12545, 'plPL', 'Jak widzisz, machina wojenna Plagi prze naprzód, a armie Hordy i Przymierza pozostają podzielone, przez co stają się łatwą zdobyczą. Dlatego właśnie musimy pozostać zjednoczeni.$B$B<Valus na chwilę pogrąża się w zadumie.>$B$BKrucjacie Argentu przyda się $gtaki mężczyzna:taka kobieta; jak ty. Może zechcesz przyłączyć się do naszej sprawy? Walczyć i zginąć u boku Spopielacza?', 0),
(12766, 'plPL', 'Ty musisz być $N. Mówiono mi, że przyjdziesz.$B$BMam zadanie, do którego, jak sądzę, masz wyjątkowe kwalifikacje, a wykonując je, zaskarbisz sobie przychylność tutejszych smoków.', 0),
(12767, 'plPL', 'Ty musisz być $N. Mówiono mi, że przyjdziesz.$b$b$b$bMam dla ciebie zadanie. Jeśli je wykonasz, udowodnisz swoją wartość tutejszym smokom.', 0),
(12768, 'plPL', 'Już $gwróciłeś:wróciłaś;, $N?$B$BCeristrasz uprzedził mnie o twoim przybyciu. Dziękuję za to, czego $gdokonałeś:dokonałaś; w Rubinowej Smoczej Świątyni.', 0),
(12769, 'plPL', 'Już $gwróciłeś:wróciłaś;, $N?$b$bVargastrasz uprzedził mnie o twoim przybyciu. Dziękuję za to, czego $gdokonałeś:dokonałaś; w Rubinowej Smoczej Świątyni.', 0),
(12789, 'plPL', 'Doskonale. Valus musiał otrzymać mój raport.$b$bBierzmy się do roboty.', 0),
(13077, 'plPL', 'Witaj.$B$BTroska maluje się na twojej twarzy. Powiedz mi, proszę, co cię trapi.', 0),
(13078, 'plPL', 'Z Łez Dahlii i pradawnej magii tworzę dla ciebie odrobinę nadziei dla twojego wielkiego krzyżowca.', 0),
(13079, 'plPL', 'Oddech Alexstrazy... $gudałeś:udałaś; się do samej smoczej królowej? Jestem niezmiernie wdzięczny.$B$BRozumiem ryzyko takiego oczyszczenia i jestem gotów. Zaczynaj, $N.', 0),
(13167, 'plPL', '<Wszystkie oczy Kilixa rozbłyskują gwałtownym blaskiem, gdy wpatruje się w pancerz.>$b$bDOKONAŁO SIĘ!$b$b$N! Twoje imię zostanie zapisane w historii naszego ludu.$b$bJestem twoim dłużnikiem...', 0),
(13182, 'plPL', 'Smuci mnie, że doszło do tego. Gdybyśmy tylko mogli przywrócić naszemu wielkiemu imperium dawną świetność...', 0),
(13187, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bNiech twoje czyny odnowią nadzieję naszego ludu, że pewnego dnia odzyskamy miasto naszych przodków.', 0),
(13190, 'plPL', 'Aha!$b$bNiech szydercza woń porażki zżera ich puste dusze!$b$bDziękuję, $N. Dziś $gzadałeś:zadałaś; cios nieżywym.', 0),
(13204, 'plPL', 'Czy masz pojęcie, co ze sobą nosisz, $N?$b$bJaskiniowe bestie, na które $gpolowałeś:polowałaś;, nie mają tradycyjnego sposobu wydalania odchodów. Może warto umyć ręce...$b$bDziękuję za pamięć, ale jeśli znajdziesz ich więcej, zatrzymaj je, proszę, dla siebie.', 0),
(13343, 'plPL', 'Ojej, udało ci się! Nie byłam pewna.$B$BPrzez chwilę podczas walki $gmigotałeś:migotałaś; w strumieniu czasu! Byłam pewna, że cię straciliśmy!$B$BA jednak oto jesteś, $gcały i zdrowy:cała i zdrowa;, z uratowanym dawnym „ja”, po drugiej stronie pętli czasu, w której $gtkwiłeś:tkwiłaś;.$B$BCo z ciebie za $gbohater:bohaterka; czasu, $N!', 0),
(13372, 'plPL', 'Takie klucze mają najstarsi członkowie Błękitnego Stada. Tylko im powierza je ich pan, Malygos.$b$bTo przełom, na który czekaliśmy, by uderzyć w Aspekt Magii!$b$b<Królowa smoków przez chwilę ci się przygląda.>$b$bSam klucz nie wystarczy ci, by dostać się do Skupiającej Tęczówki, ale mogę nasycić cię częścią mojej mocy, dzięki której zdołasz nim lekko uchylić tęczówkę.$b$bTo wystarczy, by ściągnąć gniew Malygosa!', 0),
(13375, 'plPL', 'Takie klucze mają najstarsi członkowie Błękitnego Stada. Tylko im powierza je ich pan, Malygos.$b$bTo przełom, na który czekaliśmy, by uderzyć w Aspekt Magii!$b$b<Królowa smoków przez chwilę ci się przygląda.>$b$bSam klucz nie wystarczy ci, by dostać się do Skupiającej Tęczówki, ale mogę nasycić cię częścią mojej mocy, dzięki której zdołasz nim lekko uchylić tęczówkę.$b$bTo wystarczy, by ściągnąć gniew Malygosa!', 0),
(13384, 'plPL', 'To bardzo smutny dzień, nie tylko dla smoczego rodu, ale dla wszystkich żywych istot Azeroth. Straciliśmy jednego z naszych najrozważniejszych, najmądrzejszych i najstarszych przyjaciół. Magia pozostała bez swojego strażnika.$b$bMiejmy nadzieję, że w nadchodzących latach okaże się to mądrą decyzją, $N. Na horyzoncie wciąż zbiera się burza, a my straciliśmy jednego z naszych najpotężniejszych obrońców.', 0),
(13385, 'plPL', 'To bardzo smutny dzień, nie tylko dla smoczego rodu, ale dla wszystkich żywych istot Azeroth. Straciliśmy jednego z naszych najrozważniejszych, najmądrzejszych i najstarszych przyjaciół. Magia pozostała bez swojego strażnika.$b$bMiejmy nadzieję, że w nadchodzących latach okaże się to mądrą decyzją, $N. Na horyzoncie wciąż zbiera się burza, a my straciliśmy jednego z naszych najpotężniejszych obrońców.', 0),
(13443, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Smoczych Pustkowiach!', 0),
(13451, 'plPL', 'Zbezcześć wielkie ognisko Hordy na Smoczych Pustkowiach!', 0),
(13487, 'plPL', 'Uczcij płomień Smoczych Pustkowi!', 0),
(13495, 'plPL', 'Uczcij płomień Smoczych Pustkowi!', 0),
(24872, 'plPL', '<Kalegos wzdycha>$B$BTyle cierpienia, tyle niepotrzebnego zniszczenia. Nie były to łaskawe czasy dla moich braci i sióstr. Ale dzięki waszym wysiłkom, dzielni poszukiwacze przygód, ta mroczna, lecz wciąż szlachetna dusza może wreszcie zaznać spokoju.$B$BOdpoczywaj teraz, Sindragoso. Jesteś w domu...', 0),
(24880, 'plPL', '<Kalegos wzdycha>$B$BTyle cierpienia, tyle niepotrzebnego zniszczenia. Nie były to łaskawe czasy dla moich braci i sióstr. Ale dzięki waszym wysiłkom, dzielni poszukiwacze przygód, ta mroczna, lecz wciąż szlachetna dusza może wreszcie zaznać spokoju.$B$BOdpoczywaj teraz, Sindragoso. Jesteś w domu...', 0),
(26012, 'plPL', 'Dziękuję, że $godpowiedziałeś:odpowiedziałaś; na wezwanie Rhonina, $gdzielny poszukiwaczu:dzielna poszukiwaczko; przygód.$B$BPozwól, że podzielę się z tobą tym, co wiemy o ostatnich wydarzeniach. Będę bardzo wdzięczny za wszelką pomoc, jaką możesz zaoferować.', 0),
(26013, 'plPL', 'Jeszcze raz dziękuję, $N, że $guratowałeś:uratowałaś; mnie ze szponów Baltharusa!$B$BWciąż jednak zostało wiele do zrobienia...', 0),
(26034, 'plPL', '<Krasus uważnie słucha twojej relacji z walki z Halionem, a na wzmiankę o Śmiercioskrzydłym jego oczy rozszerzają się.>$B$BJesteśmy ci winni wdzięczność, $gśmiertelniku:śmiertelniczko;, za wypędzenie najeźdźców z Sanktuarium. Ale te wieści o Niszczycielu są niepokojące ponad wszelkie słowa. Muszę wiele omówić z pozostałymi członkami Paktu.$B$BPrzyjmijcie to w dowód mojej wdzięczności, gdy będziecie się szykować na nadchodzącą burzę.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11958, 'plPL', 'Naturalna równowaga ostatnio raz po raz zostaje zachwiana.$B$BMam nadzieję, że pomożesz nam przetrwać ten wstrząs, który wywraca nasz sposób życia.', 0),
(11959, 'plPL', 'To krew Loguhna czy twoja, $N?', 0),
(11960, 'plPL', 'Ile szczeniąt można było ocalić w tak krótkim czasie?', 0),
(11978, 'plPL', 'Bez zbroi i broni nasi najnowsi członkowie będą bezbronni w wędrówce do Młota Agmara.', 0),
(11980, 'plPL', 'Nie okazuj litości, $N. Zabij Anub\'ar!', 0),
(11983, 'plPL', 'Wzmocnią Hordę, dowódco.', 0),
(11999, 'plPL', '$GWróciłeś:Wróciłaś;. Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12000, 'plPL', '$GWróciłeś:Wróciłaś;. Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12004, 'plPL', 'Czy $gudaremniłeś:udaremniłaś; porozumienie między Błękitnym Stadem a Eterium?', 0),
(12005, 'plPL', 'Czy $gudaremniłeś:udaremniłaś; porozumienie między Błękitnym Stadem a Eterium?', 0),
(12006, 'plPL', 'Coś mi mówi, że nie $gzabiłeś:zabiłaś; jeszcze dość tych bezcześcicieli!', 0),
(12009, 'plPL', 'Ile krabów udało ci się wyciągnąć?', 0),
(12013, 'plPL', 'Masz mnie za głupca? Arcanimus wciąż pożera dusze moich braci i sióstr, $N!', 0),
(12016, 'plPL', 'Wracasz z soczystym mięsem Kili\'ui?', 0),
(12017, 'plPL', 'Zdawało mi się, że widziałem jakieś szamotanie... czy Tu\'u\'gwar nie żyje?', 0),
(12028, 'plPL', 'Co o tym myślisz?', 0),
(12031, 'plPL', '<Starszy Mana\'loa patrzy przez ciebie na wskroś, wyczuwając, że nie $gwykonałeś:wykonałaś; jeszcze jego zadania.>', 0),
(12032, 'plPL', '$N, $gwróciłeś:wróciłaś;!', 0),
(12033, 'plPL', 'Zmiażdżymy Plagę!', 0),
(12039, 'plPL', 'Czym jest życie bez ryzyka?', 0),
(12040, 'plPL', 'Imperium Azjol znów powstanie!', 0),
(12043, 'plPL', 'Hę? Kim jesteś? Czego chcesz?', 0),
(12044, 'plPL', 'Masz rudę? Mój tragarz zaraz wróci – musimy wysłać ten transport, póki walka trwa!', 0),
(12045, 'plPL', 'Masz odłamki? Już prawie kończę główny moduł chłodzący.', 0),
(12046, 'plPL', 'Jak idą łowy? Masz moje skóry?', 0),
(12047, 'plPL', 'Udało się znaleźć jakieś drzazgi?', 0),
(12048, 'plPL', '<Borus rzuca narzędzia.>$B$BTe są bezużyteczne!', 0),
(12049, 'plPL', 'Masz wszystko? Bo cuchniesz tym na pewno.', 0),
(12050, 'plPL', 'Gdzie ten tragarz? Oby jormungary go nie dopadły. Tym razem niósł spory ładunek.', 0),
(12052, 'plPL', 'Pamiętam cię. Ty żyjesz, więc te nędzne harpie lepiej niech nie żyją.', 0),
(12053, 'plPL', 'To wyzwanie, $N!', 0),
(12056, 'plPL', 'Masz w plecaku odciętą orczą głowę, czy tylko tak się cieszysz na mój widok?', 0),
(12057, 'plPL', '<Gort unosi brew.>', 0),
(12064, 'plPL', 'Przynieś mi te fragmenty klucza!', 0),
(12065, 'plPL', 'Jakie wieści przynosisz z plaży, $N?', 0),
(12066, 'plPL', 'Jakie wieści przynosisz z plaży, $N?', 0),
(12067, 'plPL', 'List do mnie?$B$B<Komendantka przez chwilę przygląda się twojej twarzy.>$B$BChyba jednak nie... to muszą być złe wieści.', 0),
(12069, 'plPL', 'O co chodzi, $N? Jestem bardzo zajęty.', 0),
(12072, 'plPL', 'Pamiętaj, że jeźdźcy wojenni są wyszkoleni do walki tylko w Wiosce Lodowej Mgły. Spróbuj zabrać ich gdzie indziej, a cię zrzucą.', 0),
(12075, 'plPL', 'Więc $gwróciłeś:wróciłaś; z moją próbką? Cieszę się, że mróz cię nie zabrał.', 0),
(12076, 'plPL', 'Chyba masz jeszcze trochę śliny na ramieniu, $N. Uważaj, bo przeżre ci zbroję na wylot.', 0),
(12077, 'plPL', 'Konus pewnie chce, żebyśmy walczyli za niego. Oto moja zdziwiona mina.', 0),
(12078, 'plPL', '$GWróciłeś:Wróciłaś;! Masz te bestie? Muszę się stąd wynosić... Jestem prawie pewien, że Ko\'char kilka minut temu próbował mnie rozdeptać.', 0),
(12079, 'plPL', 'Bitwa trwa, przybywaj z dobrymi wieściami albo mnie zostaw, mała istoto.', 0),
(12080, 'plPL', 'Mam nadzieję, że przynosisz dobre wieści, mała istoto.', 0),
(12083, 'plPL', 'Co $gznalazłeś:znalazłaś; tam w lesie?', 0),
(12084, 'plPL', 'Co $gznalazłeś:znalazłaś; tam, w tych lasach?', 0),
(12085, 'plPL', 'Co to? Myślisz, że wyślesz sobie list?$B$BCała poczta przechodzi najpierw przeze mnie. Są wśród nas szpiedzy i zdrajcy!$B$B<Nadrządca mierzy cię wzrokiem od stóp do głów, a ty zastanawiasz się, czy nie każe cię zabić na miejscu.>$B$BNo dobrze, tylko szybko. Ale jeśli nie spodoba mi się to, co przeczytam, rzucę cię na pożarcie moim worgom.$B$B<Agmar szczerzy zęby, a Gar\'mak i Lak\'tuk odwracają się i patrzą na ciebie, jakbyś $gbył:była; ich następnym posiłkiem.>', 0),
(12089, 'plPL', '$GPrzyszedłeś:Przyszłaś; po nagrodę?', 0),
(12090, 'plPL', '$GPrzyszedłeś:Przyszłaś; po nagrodę?', 0),
(12091, 'plPL', '$GPrzyszedłeś:Przyszłaś; po nagrodę?', 0),
(12092, 'plPL', 'Dodatkową korzyścią z ocalenia pradrzewców może się okazać to, że rozważą pomoc Przymierzu w jego trudnościach. Tak czy inaczej, to po prostu słuszne.$B$BIle $gzdołałeś:zdołałaś; wzmocnić, $N?', 0),
(12096, 'plPL', 'Jeśli ocalimy pradrzewce, zanim zrobią to driady i nocne elfy ze Spoczynku Gwiazd, może zechcą sprzymierzyć się z Hordą.$B$BA przynajmniej może dwa razy się zastanowią, zanim nas zaatakują.$B$BIle $gzdołałeś:zdołałaś; ocalić do tej pory?', 0),
(12097, 'plPL', '<Gort unosi brew.>$B$BJuż z powrotem?', 0),
(12100, 'plPL', 'Zabij zwierzęta, by powstrzymać rozprzestrzenianie się zarazy, i przynieś mi organ odporny na gnicie.', 0),
(12101, 'plPL', 'Co znowu?', 0),
(12102, 'plPL', 'Masz rubinowy bez?', 0),
(12104, 'plPL', 'Masz szczepionkę?', 0),
(12107, 'plPL', 'Co się stało, $N? Jesteś $gcały rozgorączkowany:cała rozgorączkowana;.$B$BZłap chwilę oddechu.', 0),
(12110, 'plPL', 'Co się stało, $N? Jesteś $gcały rozgorączkowany:cała rozgorączkowana;.$B$BZłap chwilę oddechu.', 0),
(12115, 'plPL', 'Czego chcesz, $N?', 0),
(12119, 'plPL', 'Tak, co mogę dla ciebie zrobić, $N?', 0),
(12122, 'plPL', 'Tak, co mogę dla ciebie zrobić, $N?', 0),
(12123, 'plPL', 'Dobrze w końcu poznać cię osobiście, $N. Znam cię od czasu, zanim się $gnarodziłeś:narodziłaś;.', 0),
(12124, 'plPL', 'Dobrze w końcu poznać cię osobiście, $N. Znam cię od czasu, zanim się $gnarodziłeś:narodziłaś;.', 0),
(12125, 'plPL', 'Przynieś mi krew bezbronnych.', 0),
(12126, 'plPL', 'Napełnij klejnot mocą bezbożności!', 0),
(12127, 'plPL', 'Wszyscy tutaj, w Północnej Grani, służymy mrozowi.', 0),
(12136, 'plPL', 'Najwyższy czas! Gdzie się $gpodziewałeś:podziewałaś;?', 0),
(12140, 'plPL', 'Nie trać czasu, $N. Angrathar czeka!', 0),
(12142, 'plPL', '$GWykończyłeś:Wykończyłaś; te szkodniki?', 0),
(12145, 'plPL', 'Ty nie być prawdziwy mon, póki nie zabić smoka... mon.', 0),
(12148, 'plPL', '$GZnalazłeś:Znalazłaś; coś?', 0),
(12149, 'plPL', 'Czy $gpokonałeś:pokonałaś; magnataury?', 0),
(12150, 'plPL', 'Znasz imię? Wiesz, kto jest wodzem wojennym magnataurów?', 0),
(12151, 'plPL', 'Czy na dobre $gzażegnałeś:zażegnałaś; to zagrożenie?', 0),
(12166, 'plPL', 'Szkoda, że nie możemy uleczyć niedźwiedzi i łosi, które padły ofiarą obecności Plagi.$B$BPrzynajmniej możemy powstrzymać dalsze szerzenie się skażenia.', 0),
(12167, 'plPL', 'Kultyści to zaraza na obliczu stworzenia!', 0),
(12168, 'plPL', 'Wyczuwam w pobliżu coś plugawego.$B$BMasz to przy sobie! Co to jest, $N?', 0),
(12169, 'plPL', 'Wyczuwam, że arcykultysta Zangus wciąż żyje.$B$BCoś nie tak, $N? Może najpierw musisz odpocząć?', 0),
(12171, 'plPL', 'Witaj, $N.', 0),
(12172, 'plPL', 'Czy $gjesteś dostrojony:jesteś dostrojona;? Nie wolno ci w tej sprawie kłamać, $N.$B$BJeśli nie przygotujesz się jak należy, a ja nauczę cię zaklęcia, to gdy rzucisz je po raz pierwszy, będzie to zarazem ostatni raz, kiedy ktokolwiek cię zobaczy!', 0),
(12188, 'plPL', 'Osad posłuży jako czynnik reaktywny, który aktywuje zarazę!', 0),
(12200, 'plPL', 'Szczęście, że w pobliżu jest miejsce z nadmiarem łez szmaragdowych smoków. Inaczej musiałbym cię posłać aż do Feralas.', 0),
(12205, 'plPL', '$GPrzyszedłeś:Przyszłaś; tu marnować mój czas, $Gchłopcze:dziewczyno;, czy $gspełniłeś:spełniłaś; moją wendetę przeciw Szkarłatnemu Szturmowi?', 0),
(12206, 'plPL', '$GZrobiłeś:Zrobiłaś; to?$B$BAch, zapomniałam ci powiedzieć, że lepiej nie pozwolić, żeby to świństwo cię opryskało! Jest paskudne i nigdy nie spierzesz tych plam, nie mówiąc już o tym, ile się namęczysz, zanim zagoją się te wyżarte, bąblujące kawałki ciała.', 0),
(12209, 'plPL', 'Wezmę każdą zbroję i broń, jaką zdołasz dla mnie ukraść, świeże mięso.$B$BChoć będą gorszej jakości niż to, co mogę zrobić tutaj, lepsze to niż nic.', 0),
(12211, 'plPL', 'I jak? Zakładam, że się udało?$B$BTylko nie mów mi, że mają jakąś ochronę przed zjedzeniem przez szczury?!', 0),
(12214, 'plPL', 'Bardzo się cieszę, że się $gzjawiłeś:zjawiłaś;. Bałem się, że będę musiał sam tam pójść i je spędzić.', 0),
(12218, 'plPL', 'Ta próba będzie ostatnim eksperymentem w serii, $N.', 0),
(12221, 'plPL', 'No najwyższy czas, do diabła!', 0),
(12230, 'plPL', 'Można by pomyśleć, że pozwolą mi użyć roznosicieli zarazy... może naładować je czymś paskudnym, żeby zniszczyć balisty.$B$BAle nie, mówią mi, że są tylko do misji specjalnych.$B$BA niech tam!', 0),
(12232, 'plPL', 'Pewnego dnia zostanę głównym strażnikiem śmierci!$B$BPewnego dnia...', 0),
(12234, 'plPL', 'Jeśli będziesz się ociągać, ich dzienne plany się zmienią i być może będziemy musieli zaczynać od nowa.$B$BNie ociągaj się!', 0),
(12237, 'plPL', 'Pospiesz się, $N! Musisz ocalić bezradnych mieszkańców!', 0),
(12239, 'plPL', '<Agentka mierzy cię wzrokiem od stóp do głów, a potem bez słowa przywołuje cię gestem.>$B$BNie spal mojej przykrywki, $N!', 0),
(12240, 'plPL', 'Tęsknię za siostrą, $N. Mam nadzieję, że dobrze się miewa.', 0),
(12243, 'plPL', 'Tylko NIE mów mi, że ich żagle były jakimś cudem odporne na moją płonącą wodę!$B$BNie chciałabym musieć jej tutaj znowu testować.', 0),
(12245, 'plPL', 'To naprawdę proste. Wysyłamy cię, żebyś $gzabił:zabiła; czterech nieudolnych głupców, którzy lada chwila mogą wypaplać wszystkie nasze sekrety, a ty idziesz i to robisz.$B$B<Najwyższy egzekutor uśmiecha się złowieszczo.>', 0),
(12252, 'plPL', 'Jakie wieści przynosisz? Sukces, bez wątpienia?', 0),
(12253, 'plPL', '$GUratowałeś:Uratowałaś; naszych uwięzionych mieszkańców?', 0),
(12254, 'plPL', 'Masz modlitewnik biskupa? $GZnalazłeś:Znalazłaś; w nim coś niezwykłego?', 0),
(12258, 'plPL', 'Skróć ich cierpienia, $N.', 0),
(12260, 'plPL', 'Tylko mi nie mów, że $gstłukłeś:stłukłaś; lustro?!', 0),
(12261, 'plPL', '$GUmieściłeś:Umieściłaś; osłonę?', 0),
(12262, 'plPL', 'Widzę krew na twoich rękach... a więc stało się?', 0),
(12263, 'plPL', 'Nuży mnie ta zaraza.', 0),
(12264, 'plPL', 'Nie mogę przestać się zastanawiać, czy są na tyle naiwni, by sądzić, że będę to tolerował, czy po prostu szukają śmierci.', 0),
(12265, 'plPL', 'Moc zmarnowana na słabych i bezużytecznych.$B$BPokaż mi istotę godną życia i magii, którymi ją obdarzono, a wtedy może porozmawiamy o marnotrawstwie, zanim zgasimy jej istnienie.$B$BNie martw się, zaczekam.', 0),
(12267, 'plPL', 'Jesteś całkiem skutecznym narzędziem, $N. Doceniam twój udział w tym oczyszczeniu.', 0),
(12269, 'plPL', '$GOdzyskałeś:Odzyskałaś; ich karty?', 0),
(12271, 'plPL', '$GZdobyłeś:Zdobyłaś; różdżkę od ich oprawcy?', 0),
(12272, 'plPL', '$GZdobyłeś:Zdobyłaś; próbki dziwnej rudy?\n', 0),
(12273, 'plPL', 'No i?!', 0),
(12274, 'plPL', 'Czego się $gdowiedziałeś:dowiedziałaś;? W ogóle już z nim $grozmawiałeś:rozmawiałaś;?', 0),
(12277, 'plPL', '<Quarterflash kiwa głową.>$B$BBył dobrym gnomem, jednym z naszych najlepszych. Będzie nam brakowało Slinkina.', 0),
(12281, 'plPL', 'Słyszałem o twojej odwadze w kopalni, $N.', 0),
(12282, 'plPL', '$GOdzyskałeś:Odzyskałaś; moją wróżebną kulę?', 0),
(12283, 'plPL', 'Najwyższy czas, $N! Co cię zatrzymało?', 0),
(12285, 'plPL', 'Mam kazać moim siłom wyruszać w stronę Młota Agmara?$B$BCzy może jednak $gzdołałeś:zdołałaś; zabić najwyższą generał?', 0),
(12290, 'plPL', '$GZebrałeś:Zebrałaś; mroczne zielsko?', 0),
(12291, 'plPL', 'Mam dość mrocznego zielska, by przyrządzić więcej eliksirów, $N.', 0),
(12303, 'plPL', 'Ile tego skarbu Przymierza udało ci się zdobyć?', 0),
(12311, 'plPL', 'Amarion nie żyje?', 0),
(12312, 'plPL', 'Księga Plagi?', 0),
(12319, 'plPL', 'Nekrowładcy już nie ma?', 0),
(12320, 'plPL', 'Przychodzisz od dowództwa, $gmój synu:moja córko;?', 0),
(12326, 'plPL', 'Nazywam się Cash. Ambo Cash. A cała przyjemność po twojej stronie.', 0),
(12372, 'plPL', 'Jak przebiega walka? Spychamy ich?', 0),
(12416, 'plPL', 'Cieszę się, że wciąż jesteś z nami.', 0),
(12417, 'plPL', 'Zaczynałem się martwić, że Plaga w świątyni cię dopadła. Dobrze, że wciąż żyjesz.', 0),
(12418, 'plPL', '$GWróciłeś:Wróciłaś;! $GZrobiłeś:Zrobiłaś; to, o co prosiłem?', 0),
(12419, 'plPL', 'Witaj. Wyczuwam obecność mojej rubinowej broszy. Podaj mi ją.$B$BCo się stało z Dahlią?', 0),
(12438, 'plPL', 'Przychodzisz po nagrodę, $gsojuszniku:sojuszniczko;?', 0),
(12441, 'plPL', '$GStanąłeś:Stanęłaś; do walki z Krwawą Łapą?', 0),
(12442, 'plPL', '<Leoric zgrzyta zębami.>$B$BCzy ten nadęty głupiec nie żyje?', 0),
(12450, 'plPL', '$GWróciłeś:Wróciłaś;! $GZrobiłeś:Zrobiłaś; to, o co prosiłem?', 0),
(12454, 'plPL', 'Im szybciej uporamy się ze szmaragdowymi szponami niebios, tym szybciej Szmaragdowa Smocza Świątynia odzyska naturalną równowagę.', 0),
(12455, 'plPL', 'Gdzie moja amunicja, $gkolego:paniusiu;?', 0),
(12456, 'plPL', 'Udało ci się rozprawić z Alystrosem? Nie bój się poprosić przyjaciół o pomoc.$B$BWłaściwie, skoro zielony strażnik jest bardzo potężny, wręcz ci to zalecam!', 0),
(12457, 'plPL', '$GUratowałeś:Uratowałaś; naszych rannych żołnierzy?', 0),
(12458, 'plPL', 'A ile nasion $gzdołałeś:zdołałaś; dotąd zdobyć?', 0),
(12459, 'plPL', 'Jakie wyniki? Są zniszczeni?$B$BPotrzebuję odpowiedzi!', 0),
(12462, 'plPL', '$GUrwałeś:Urwałaś; sobie kawałek?', 0),
(12464, 'plPL', 'A więc stało się?', 0),
(12465, 'plPL', 'Jakoś nie czuję się zwycięzcą...', 0),
(12467, 'plPL', '$GOdzyskałeś:Odzyskałaś; filakterię Thel\'zana?', 0),
(12469, 'plPL', 'Witaj!', 0),
(12470, 'plPL', 'Jakie wieści przynosisz? Co się stało w Brązowej Smoczej Świątyni?$B$B$GDowiedziałeś:Dowiedziałaś; się, kto jest przywódcą Nieskończonego Stada?', 0),
(12472, 'plPL', '<Yorik oddycha z ulgą.>$B$BJuż myśleliśmy, że się nie zjawisz, $N.', 0),
(12475, 'plPL', '$GOdzyskałeś:Odzyskałaś; mapę Szturmu?', 0),
(12476, 'plPL', 'Oczyść Obóz Szturmu, $N.', 0),
(12477, 'plPL', '$GZnalazłeś:Znalazłaś; egzemplarz?', 0),
(12478, 'plPL', '$GPrzeszukałeś:Przeszukałaś; Grotę Ostrza Mrozu?', 0),
(12498, 'plPL', 'Zniszcz Plagę przy Spoczynku Galakronda, zanim będzie za późno!', 0),
(12545, 'plPL', 'Nie zostawiaj niczego, co Król Lisz mógłby wskrzesić!', 0),
(12871, 'plPL', 'Witaj!', 0),
(13078, 'plPL', 'Ach, droga Dahlio. Tak bardzo mi ciebie brakuje.', 0),
(13079, 'plPL', 'Znów $gwróciłeś:wróciłaś;, $N. Czemu tak się narażasz?', 0),
(13167, 'plPL', 'Czy to już koniec, $N? Czy król zdrajca w końcu dokonał żywota?', 0),
(13182, 'plPL', 'Udało ci się oczyścić nasz dom z jaj Plagi?', 0),
(13187, 'plPL', '$GPokonałeś:Pokonałaś; Beztwarzowych, $N?', 0),
(13190, 'plPL', 'Udało ci się spalić zwłoki Strażnika?', 0),
(13204, 'plPL', 'Na wszystko, co żyje, co to takiego?!', 0),
(13343, 'plPL', '<Chromie dziwnie ci się przygląda.>$B$BCzy my się znamy? Wyczuwam wokół ciebie aurę, jakby samo twoje istnienie się chwiało. Albo to, albo $gutknąłeś:utknęłaś; w pętli czasu.$B$BCokolwiek to jest, lepiej szybko to napraw, bo inaczej niedługo przestaniesz istnieć!', 0),
(13372, 'plPL', '$n, $gzetknąłeś:zetknęłaś; się z kluczem do Skupiającej Tęczówki! Masz go przy sobie?$b$b$b$bJak w ogóle $gwszedłeś:weszłaś; w jego posiadanie? Och, Szafiron wciąż miał swój?', 0),
(13375, 'plPL', '$n, $gzetknąłeś:zetknęłaś; się z kluczem do tęczówki! Masz go przy sobie?$b$b$b$bJak w ogóle $gwszedłeś:weszłaś; w jego posiadanie? Och, Szafiron wciąż miał swój?', 0),
(13384, 'plPL', 'Tylko Malygos nosi serce magii. To jego najcenniejszy skarb.', 0),
(13385, 'plPL', 'Tylko Malygos nosi serce magii. To jego najcenniejszy skarb.', 0),
(24872, 'plPL', 'Co trzymasz w dłoniach, $gśmiertelniku:śmiertelniczko;?', 0),
(24880, 'plPL', 'Co trzymasz w dłoniach, $gśmiertelniku:śmiertelniczko;?', 0),
(24918, 'plPL', 'Czego chcesz, $N?', 0);
