INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3067, 'plPL', 'Goramoshu,$B$Bwysyłam do ciebie przedstawiciela Eterium. Ambasador Duyheen twierdzi, że jest więcej jemu podobnych, którzy chętnie przyłączyliby się do naszej sprawy. Wybadaj go i sprawdź, czy da się go do czegoś wykorzystać.$B$BJeśli okaże się pomocny, być może rozważę przyjęcie w nasze szeregi kolejnych jego pobratymców.$B$BNie bądź idiotą; spal ten list, gdy tylko go przeczytasz!$B$BM', 0),
(3068, 'plPL', 'Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą. Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.$B$BDobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza.$B$BOd tej chwili aż do końca dni żyję i umieram – za Hordę!', 0),
(3069, 'plPL', '$N,$B$Bjeśli czytasz ten list, to znaczy, że żyjesz i jesteś w jednym kawałku – a przynajmniej wciąż masz oczy.$B$BMuszę przeprosić za tę tajemniczość. Agmar żąda, by każdą pocztę czytano przed doręczeniem – za dużo tam zdrajców i złodziei, o czym bez wątpienia świadczy list gończy. Zawarte tu sprawy są delikatne i nowa gwardia mogłaby je łatwo opacznie zrozumieć.$B$BDla żołnierza Hordy strata jest absolutna. Strata oznacza śmierć, a ze śmiercią nie ma negocjacji ani interpretacji. Można tylko mieć nadzieję, że poległy zginął z honorem.', 0),
(3070, 'plPL', 'Ale zwycięstwo... Zwycięstwo może oznaczać wiele rzeczy. Jak zapewne $gzauważyłeś:zauważyłaś;, Kor\'kron są tam w pełnej sile. Wódz przysłał swoją elitarną straż, by pomogła zapewnić zwycięstwo w Północnej Grani. Oni, wraz z tobą i innymi bohaterami, spychają Króla Lisza i jego siły ku nieuchronnemu końcowi. Z każdym pokonanym wyzwaniem jesteśmy o krok bliżej uwolnienia naszego świata od Arthasa i Plagi.$B$BI w tym właśnie tkwi dylemat. Widzisz, nasze siły w Północnej Grani działają pod egidą młodego Piekłorycza. Każde zwycięstwo podnosi morale tutejszych sił Hordy, a to udziela się reszcie Azeroth.$B', 0),
(3071, 'plPL', 'Tym bardziej szkoda, że Piekłorycz stosuje tak dzikie metody. W miarę jak zwycięstwo się zbliża, Piekłorycz zyskuje kolejne usprawiedliwienia dla swoich metod, a to z kolei przybliża nas do miejsca, w którym nie byliśmy od wielu lat: do mrocznego miejsca.$B$BWysłałem syna, by dowodził naszymi siłami pod Bramą Gniewu. Wiem, że będzie walczył z honorem, i wciąż mam nadzieję, że nasze siły dostrzegą jego odwagę i wytrwałość i pójdą za jego przykładem. On jest moim sercem i siłą tam, gdzie mnie być nie może... Ty będziesz moimi oczami i uszami. Razem naprawimy to, co złe.$B$BKrew i Grom... Oby twoje przybycie przyniosło jedno i drugie.$B$BZaurzykieł$B', 0),
(3073, 'plPL', 'Moja królowo,\nOdkryto, że skrzyżowanie linii mocy w Ogrodach Księżycowego Spoczynku zostało uwolnione przez Błękitne Stado. Jego siły użyły iglicy przypływu, by zniszczyć zwornik, ale zamiast skierować moc z powrotem do Nexusa, za pomocą szeregu ognisk nieudolnie poprowadziły ją pod ziemią i wzmocniły aż do Lazurowej Smoczej Świątyni.\nNie trzeba dodawać, że wszędzie tam, gdzie magia wystrzeliła spod ziemi, skutki były fatalne. Ucierpiały pradrzewa z lasów, Kalu\'ak i inne istoty z tego regionu. Na szczęście dla nas $N, $gstojący:stojąca; przed tobą, $godegrał:odegrała; kluczową rolę w wytropieniu i rozwiązaniu wszystkich tych problemów.\nMoim zdaniem $N może okazać się dla Żmijowego Spoczynku ogromnym wsparciem w radzeniu sobie z problemami, z jakimi mierzy się obecnie świątynia. Pokornie proszę, byś uznała $gjego:ją; za cenny nabytek – sama przekonałam się, że $gjest nieoceniony:jest nieoceniona;.\nZ niezmiennym szacunkiem\nModera\nArcymagini i członkini Sześciorga', 0),
(3074, 'plPL', 'Moja królowo,\n\nOdkryto, że skrzyżowanie linii mocy w Ogrodach Księżycowego Spoczynku zostało uwolnione przez Błękitne Stado. Jego siły użyły iglicy przypływu, by zniszczyć zwornik, ale zamiast skierować moc z powrotem do Nexusa, za pomocą szeregu ognisk nieudolnie poprowadziły ją pod ziemią i wzmocniły aż do Lazurowej Smoczej Świątyni.\n\nNie trzeba dodawać, że wszędzie tam, gdzie magia wystrzeliła spod ziemi, skutki były fatalne. Ucierpiały pradrzewa z lasów, Kalu\'ak i inne istoty z tego regionu. $N, $gstojący:stojąca; przed tobą, bardzo $gpomógł:pomogła; w wytropieniu i rozwiązaniu tych problemów.\n\nMoim zdaniem $N może się przydać Żmijowemu Spoczynkowi w radzeniu sobie z problemami, z jakimi mierzy się obecnie świątynia. Pokornie proszę, byś uznała $Gjego:ją; za użyteczny nabytek – moim zdaniem całkiem zadowalający.\n\nZ niezmiennym szacunkiem\n\nAethas Słońcobójca\nArcymag i członek Sześciorga', 0),
(3083, 'plPL', 'Spis treści$B$BRozdział 1 – Umarli i ty$B$BRozdział 2 – Ghulowa figura: siedem łatwych ćwiczeń$B$BRozdział 3 – Precz z chłodem: jak dobrać trumnę do stylu$B$BRozdział 4 – Cmentarne gwarancje: pięćdziesiąt pewnych oznak miłości$B$B<Księga jest w nienaruszonym stanie i wygląda na zupełnie nieczytaną>', 0),
(3092, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">Pamiętnik najwyższej generał Abbendis</H1>\n<BR/>\n<IMG src="Interface\\FlavorImages\\ScarletCrusadeLogo"/>\n</BODY>\n</HTML>\n', 0),
(3093, 'plPL', '<HTML>\n<BODY>\n<P>Głos szeptał: „Przyjdź do mnie”. Od samego początku wiedziałam, że to Święta Światłość przemawia do mnie w snach. Nareszcie! Po tylu latach modlitw i dobrych uczynków, oczyszczania oblicza Azeroth z zarazy nieżycia. Po wszystkich porażkach i wskrzeszeniach.</P>\n<BR/>\n<P>Nareszcie!</P>\n</BODY>\n</HTML>\n', 0),
(3094, 'plPL', '<HTML>\n<BODY>\n<P>Znowu się to stało. „Przyjdź do mnie...” – rozkazała Światłość.</P>\n<BR/>\n<P>Obudziłam się zmarznięta, choć w mojej komnacie wcale nie było zimno. Podwoję wysiłki! Jutro powiem wielkiemu opatowi, że chcę więcej modlitw. Dość półśrodków!</P>\n<BR/>\n<P>Święta Światłość dostrzegła nasze dobre dzieło. Czuję to!</P>\n</BODY>\n</HTML>\n', 0),
(3095, 'plPL', '<HTML>\n<BODY>\n<P>Tym razem byłam przytomna! Wszystko było bardzo wyraźne, a jednak przez ponad minutę, w środku ciepłego, słonecznego dnia, z moich ust unosiła się mroźna para. Jeden z kapłanów to zauważył i padł na kolana w modlitwie.</P>\n<BR/>\n<P>Nikt inny jednak nie słyszał głosu. Przynajmniej świadek dowodzi, że nie tracę zmysłów. Może powinnam poprosić Landgrena, by pomodlił się w tej sprawie?</P>\n<BR/>\n<P>Jutro każę Jordanowi i Streetowi dokładnie przyjrzeć się naborowi. Nasze szeregi rozdęły się od niewierzących, którzy pragną jedynie niszczyć nieumarłych. To za mało!</P>\n</BODY>\n</HTML>\n', 0),
(3096, 'plPL', '<HTML>\n<BODY>\n<P>Komendant i biskup przyjęli to przychylnie. Nie żeby mieli wybór. Szczególnie entuzjastyczny wydawał się biskup Street. Mówił o odrodzeniu krucjaty i przysiągł wytropić w naszych szeregach ludzi słabej wiary.</P>\n<BR/>\n<P>Kazałam mu nie przesadzać. Nie zamierzam zniszczyć Krucjaty. Podoba mi się jednak pomysł stworzenia elitarnego oddziału najwierniejszych, którzy będą wypełniać wolę Światłości w Północnej Grani. Obawiam się, że przyjaźń z LeCraftem powoli go wypacza. Obaj mają jednak swoje zastosowania.</P>\n</BODY>\n</HTML>\n', 0),
(3097, 'plPL', '<HTML>\n<BODY>\n<P>Większość Krucjaty zostawię tutaj, by dalej oczyszczała nasze podwórko z nieumarłych. Wyobrażam sobie, że gdy skończą to, co zaczęliśmy, większość się rozejdzie i wróci do domów, by żyć w pokoju.</P>\n<BR/>\n<P>To wydaje się jakoś słuszne. W najlepszych chwilach zawsze byliśmy solą ziemi – powstawaliśmy, by odebrać nasze domy plugastwu Plagi i przywrócić naszemu Lordaeronowi dawną chwałę. By wrócić do czasów sprzed Plagi, sprzed Arthasa i królobójstwa... sprzed Króla Lisza.</P>\n</BODY>\n</HTML>\n', 0),
(3098, 'plPL', '<HTML>\n<BODY>\n<P>Wśród ludzi krążą szepty o dniu, który wkrótce nadejdzie i wszystko zmieni dla Szkarłatnej Krucjaty. Biskup Street nadał mu nazwę – Karmazynowy Świt.</P>\n<BR/>\n<P>Przemyślę to, choć czuję w kościach, że to prawda. Modlę się, by przyniósł nam pomyślność, a nie niedolę.</P>\n</BODY>\n</HTML>\n', 0),
(3099, 'plPL', '<HTML>\n<BODY>\n<P>Światłość znów przemówiła, i to z wielką naglącą siłą. Obudziłam się ze snu pełna niecierpliwości. Nie zawiodę. Nie może być więcej opóźnień. Musimy wkrótce wyruszyć!</P>\n<BR/>\n<P>Cóż za wspaniały zbieg okoliczności – i musiałam się powstrzymać, by nie okazać ulgi – że tego popołudnia kapitan Shely zdobył dla nas kilka nowych statków na tę podróż. A może to wcale nie był zbieg okoliczności? Święta Światłość wyraża swą wolę w sposób, którego nie jest nam dane pojąć.</P>\n<BR/>\n<P>Moim okrętem flagowym uczynię „Szaleństwo Grzesznika”. Ta nazwa wydaje mi się jak najbardziej stosowna.</P>\n</BODY>\n</HTML>\n', 0),
(3100, 'plPL', '<HTML>\n<BODY>\n<P>Teraz już wiem, czemu Światłość tak mnie ponaglała do wyruszenia. W środku nocy na niebie nad nami pojawiła się nekropolia Plagi i wylały się z niej sługi piekieł!</P>\n<BR/>\n<P>Atak prowadzi nowy rodzaj rycerzy śmierci. Ponieśliśmy już katastrofalne straty. Skoro Plaga może uderzyć na nas z góry w dowolnym miejscu i czasie, nie widać sposobu, by zorganizować porządną obronę.</P>\n<BR/>\n<P>Obawiam się, że nasza wyprawa do Północnej Grani skończyła się, zanim się zaczęła.</P>\n</BODY>\n</HTML>\n', 0),
(3101, 'plPL', '<HTML>\n<BODY>\n<P>Doniesiono mi, że Żagiewie i okolice zaczęły już zbierać wojsko. Sam wielki komendant Galvar Czystokrwisty zamierza poprowadzić je nam na ratunek. Jego wysiłki pójdą na marne.</P>\n<BR/>\n<P>Muszę dopilnować, by moi najlepsi gońcy przedarli się przez linie wroga i go ostrzegli. Żagiewie musi przygotować się do obrony i zebrać resztę Krucjaty.</P>\n<BR/>\n<P>Przy odrobinie szczęścia przedostaną się przed zmrokiem.</P>\n</BODY>\n</HTML>\n', 0),
(3143, 'plPL', '<HTML>\n<BODY>\n<P>Tego ranka nie ma żadnych wieści od moich gońców. Jasne jest, że żaden z nich nie dotarł do Żagiewia. Plagowiska są stracone. Czystokrwisty nadejdzie ze swoimi siłami i zostaną wybici na otwartym terenie.</P>\n<BR/>\n<P>Dziś po południu otrzymałam wizję od Światłości. Ujrzałam w niej całkowite zniszczenie wszystkiego, co tu zbudowaliśmy. Przesłanie było jasne – kazano mi zabrać resztę najwierniejszych i pozostawić Krucjatę jej losowi.</P>\n</BODY>\n</HTML>\n', 0),
(3144, 'plPL', '<HTML>\n<BODY>\n<P>Landgren powiedział mi później, że miał tę samą wizję. Nie pojmuję, jak Światłość mogła nam kazać postąpić tak niehonorowo, ale nie mnie o to pytać – mam być posłuszna i posłuszna będę.</P>\n<BR/>\n<P>Z niepokojem spoglądałam na Nowy Avalon, jak przypuszczam, po raz ostatni. Nasz los leży w Północnej Grani. Z jakiegoś powodu przepełnia mnie złowrogie przeczucie. Czekająca nas misja powinna rozwiać te obawy. Wyrzucę je z myśli.</P>\n</BODY>\n</HTML>\n', 0),
(3145, 'plPL', '<HTML>\n<BODY>\n<P>Może przy odrobinie szczęścia wielki komendant Czystokrwisty jakimś cudem przetrwa i zbierze ocalałych. Jestem tchórzem – psem uciekającym z podkulonym ogonem!</P>\n<BR/>\n<P>Mówią mi, że ta podróż potrwa dwa miesiące. Pozostałe statki nie są zbudowane z myślą o prędkości, tak jak „Szaleństwo”. Wiozą większość naszych sił i sprzętu i niewiele różnią się od jednożaglowych frachtowców, ale dotrą bezpiecznie.</P>\n<BR/>\n<P>Nie cieszę się na to, ale dla Światłości zniosę chorobę morską. Po prostu nie mogę pozwolić, by inni to zobaczyli.</P>\n</BODY>\n</HTML>\n', 0),
(3146, 'plPL', '<HTML>\n<BODY>\n<P>Od dawna nic nie pisałam. Z trudem utrzymuję się na nogach i powstrzymuję mdłości. Ludzie zaczynają się zastanawiać, czemu przez większość czasu zamykam się w kajucie. Morale by nie zyskało, gdyby zobaczyli mnie w takim stanie.</P>\n<BR/>\n<P>To nie powinno już długo potrwać. Modlę się, by tak było. Minęło już sześć tygodni, a pogoda z każdym dniem wydaje się gorsza. Mogę tylko mieć nadzieję, że w samej Północnej Grani nie jest tak okropnie. Nie jestem stworzona do zimna.</P>\n<BR/>\n<P>Święta Światłość milczy od bardzo dawna.</P>\n</BODY>\n</HTML>\n', 0),
(3147, 'plPL', '<HTML>\n<BODY>\n<P>Zaatakowano nas bez żadnego ostrzeżenia! Olbrzymy w ogromnych łodziach wiosłowych wyłoniły się z mgły niczym duchy! Były ciche jak umarli.</P>\n<BR/>\n<P>Straciłam statek wraz z całą załogą. Walczyliśmy z wielką odwagą i umiejętnością, zważywszy, że mamy tylko najbardziej podstawowe przeszkolenie w walce na morzu.</P>\n<BR/>\n<P>Potem krzyki naszych ludzi pojmanych przez olbrzymy niosły się echem po wodzie. Po jakimś czasie znów zapadła cisza. Biskup Street poprowadził modlitwy.</P>\n</BODY>\n</HTML>\n', 0),
(3148, 'plPL', '<HTML>\n<BODY>\n<P>Obudziłam się dziś rano w trakcie nanoszenia poprawek na mapy. Światłość prowadziła moją rękę, pokazując mi dokładnie, dokąd musimy się udać.</P>\n<BR/>\n<P>Jesteśmy blisko!</P>\n</BODY>\n</HTML>\n', 0),
(3149, 'plPL', '<HTML>\n<BODY>\n<P>Ląd!</P>\n<BR/>\n<P>Wysiadłszy z łodzi na plażę, zatknęłam nasz sztandar i ogarnęła mnie Święta Światłość, która przemówiła przeze mnie. Dziś jest Karmazynowy Świt – wielki dzień, na który czekaliśmy. W tym miejscu powstanie Nowe Żagiewie. Nie jesteśmy już Szkarłatną Krucjatą. Jesteśmy teraz Szkarłatnym Szturmem!</P>\n<BR/>\n<P>I szturmem uderzymy na Północną Grań! Rak Plagi grozi, że wyleje się z korony świata i zatopi nas wszystkich. Nadszedł czas, by zanieść walkę pod same drzwi Króla Lisza!</P>\n</BODY>\n</HTML>', 0),
(3150, 'plPL', '<HTML>\n<BODY>\n<P>Minął już prawie miesiąc, a budowa posuwa się szybko. Byłam zbyt zajęta, by pisać. Moi zwiadowcy donoszą, że ta kraina pełna jest smoków i innych dziwnych bestii. Będziemy trzymać się na uboczu, dopóki nie będziemy gotowi.</P>\n<BR/>\n<P>Dziś w trakcie nabożeństwa wielki opat ogłosił, że wkrótce przybędzie gość – ktoś, kogo Światłość zsyła, by poprowadził nas do zwycięstwa.</P>\n<BR/>\n<P>Nie wiem, co o tym myśleć. Czemu Światłość nie powiedziała tego mnie? Czy nie służyłam wiernie? Teraz ma mnie zastąpić jakiś obcy?</P>\n</BODY>\n</HTML>\n', 0),
(3151, 'plPL', '<HTML>\n<BODY>\n<P>Admirał Barean Zachodni Wiatr zjawił się dziś wieczorem na moim progu! Według wszelkich relacji zginął u tych brzegów całe wieki temu.</P>\n<BR/>\n<P>Nie wyglądał na tak starego, a jednak wiedziałam, że to on. Twierdził, że jako jedyny przeżył zagładę swojej floty i że ocalał wyłącznie dzięki łasce Światłości.</P>\n</BODY>\n</HTML>', 0),
(3152, 'plPL', '<HTML>\n<BODY>\n<P>Rozmawialiśmy całą noc aż do rana. Zapewnił mnie, że nie zamierza zająć mojego miejsca, ale że Światłość poleciła mu przemierzyć Wielkie Smocze Pustkowia, by służyć mi jako doradca i dowódca jedynie z tytułu. Twierdził, że w Północnej Grani nadchodzą wielkie zmiany. Przymierze i Horda miały przybyć tłumnie w odpowiedzi na wielką zarazę, którą Król Lisz zamierzał na nich zesłać.</P>\n</BODY>\n</HTML>', 0),
(3153, 'plPL', '<HTML>\n<BODY>\n<P>Ludzie przyjęli wielkiego admirała z wielkim zapałem, zwłaszcza wielki opat Landgren i biskup Street. Podobno Święta Światłość wyszeptała admirałowi we śnie nowe błogosławieństwo, które przekazał Landgrenowi. Część ludzi przeszła do stanu kapłańskiego i nazywa się ich teraz „kapłanami Kruka”.</P>\n<BR/>\n<P>Tylko Jordan nie wydaje się przekonany. To chyba zrozumiałe. Pewnie uważa, że jeśli moja pozycja jest zagrożona, to jego również.</P>\n</BODY>\n</HTML>\n', 0),
(3154, 'plPL', '<HTML>\n<BODY>\n<P>Coś tu jest nie tak. Nie potrafię tego określić, ale nie umiem w pełni zaufać admirałowi. Nie zrobił nic złego. Wręcz przeciwnie! A jednak muszę zaufać przeczuciu.</P>\n<BR/>\n<P>Będę się modlić o zrozumienie. Światłość zesłała admirała, by poprowadził nas do zwycięstwa, i nie mnie kwestionować jej decyzje. Nadal będę posłuszna. Jestem wierna.</P>\n</BODY>\n</HTML>\n', 0),
(3155, 'plPL', '<HTML>\n<BODY>\n<P>Minęło kolejnych kilka miesięcy. Poczyniliśmy wielkie postępy w budowie Nowego Żagiewia. Mur jest niemal ukończony, podobnie jak koszary. Ludzie Kaleikiego czynią cuda.</P>\n<BR/>\n<P>Nie miałam serca do pisania. Z jakiegoś powodu unikam przelewania tu swoich myśli. Światłość ostatnio mnie nie nawiedza, choć admirał zapewnia, że nie ma się czym martwić.</P>\n</BODY>\n</HTML>\n', 0),
(3156, 'plPL', '<HTML>\n<BODY>\n<P>Moi ludzie donoszą, że niewielka grupa Porzuconych zaczęła budować obóz na zboczu wzgórza na północy. Po drugiej stronie wzgórza Przymierze najwyraźniej zaczęło budowę znacznie większej bazy.</P>\n<BR/>\n<P>Admirał mówi, że powinniśmy zostawić ich w spokoju. Na zachodzie zebrały się inne siły Hordy, które z pewnością przyszłyby im z pomocą, gdybyśmy zaatakowali. Nie podoba mi się to, ale dostrzegam logikę w jego rozumowaniu.</P>\n</BODY>\n</HTML>', 0),
(3558, 'plPL', '<HTML>\n<BODY>\n<P>Pierwszy etap budowy zakończony. Admirał Zachodni Wiatr rozkazał grupie moich ludzi zdobyć przyczółek dalej na północy. Nie chciał wdawać się w szczegóły, twierdząc, że jest do tego „prowadzony”.</P>\n<BR/>\n<P>Dziś po południu schwytaliśmy czterech szpiegów z miasta Porzuconych, Jadozłości. Każę LeCraftowi wydobyć z nich informacje torturami. Skoro schwytaliśmy tylko czterech, ilu jeszcze prześlizgnęło się między nas?</P>\n<BR/>\n<P>Czemu mam wrażenie, że wszystko zaczyna się sypać?</P>\n</BODY>\n</HTML>\n', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(9434, 0, 'plPL', 'To sprowadzi żmija mrozu na ziemię i położy mu kres.', ''),
(30211, 0, 'plPL', 'Pokaż mi, dokąd mogę polecieć.', ''),
(30211, 1, 'plPL', 'Potrzebuję transportu do Twierdzy Zimowej Straży.', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(26859, 0, 0, 'plPL', 'Ty się nie martwić, stary. Zostaw to Rokhanowi. Ona już lecieć.'),
(27351, 0, 2, 'plPL', 'Ooooch! Chyba temu rozsadziło głowę.'),
(27539, 0, 0, 'plPL', 'Każdy poległy wojownik to jeden więcej w naszej potężnej armii. Nie ma z nami zwycięstwa.'),
(27539, 0, 3, 'plPL', 'Nie ma nadziei. Poniesiecie klęskę.'),
(27539, 0, 5, 'plPL', 'Wasza walka nie ma sensu. Wszyscy padniecie przed niekończącą się Plagą!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4571, 'plPL', '%s warczy.', '', 0),
(25569, 'plPL', 'Nic nam tu już nie zostało.', 'Nic nam tu już nie zostało.', 0),
(25570, 'plPL', 'Moją rodzinę wyrżnięto bez litości. Nawet dzieci.', 'Moją rodzinę wyrżnięto bez litości. Nawet dzieci.', 0),
(25571, 'plPL', 'Oby Król Lisz spłonął w piekielnym ogniu za to, co ściągnął na tę krainę.', 'Oby Król Lisz spłonął w piekielnym ogniu za to, co ściągnął na tę krainę.', 0),
(25572, 'plPL', 'Jesteśmy teraz ludem bez domu, który moglibyśmy nazwać własnym.', 'Jesteśmy teraz ludem bez domu, który moglibyśmy nazwać własnym.', 0),
(25573, 'plPL', 'Plaga to nieustraszona machina, która ma położyć kres wszelkiemu życiu na tym świecie.', 'Plaga to nieustraszona machina, która ma położyć kres wszelkiemu życiu na tym świecie.', 0),
(25574, 'plPL', 'Ten, którego nazywają Piekłoryczem, może być naszą jedyną nadzieją.', 'Ten, którego nazywają Piekłoryczem, może być naszą jedyną nadzieją.', 0),
(25575, 'plPL', 'Teraz tylko Horda może nas ocalić.', 'Teraz tylko Horda może nas ocalić.', 0),
(25649, 'plPL', 'Nie martw się już, taunka. Horda ocali i ochroni ciebie i twój lud, ale najpierw musisz przysiąc wierność wodzowi, składając krwawą przysięgę Hordy.', 'Nie martw się już, taunka. Horda ocali i ochroni ciebie i twój lud, ale najpierw musisz przysiąc wierność wodzowi, składając krwawą przysięgę Hordy.', 0),
(25650, 'plPL', 'Czy Horda da mi szansę walki z Plagą?', 'Czy Horda da mi szansę walki z Plagą?', 0),
(25651, 'plPL', 'Tak, taunka. Odwet to prawo przysługujące każdemu członkowi Hordy.', 'Tak, taunka. Odwet to prawo przysługujące każdemu członkowi Hordy.', 0),
(25652, 'plPL', 'By pomścić mój lud, by wypędzić zarazę, która ogarnęła naszą ziemię – złożę twoją przysięgę. Oddam Hordzie wszystko, co mam, i wszystko, czym jestem.', 'By pomścić mój lud, by wypędzić zarazę, która ogarnęła naszą ziemię – złożę twoją przysięgę. Oddam Hordzie wszystko, co mam, i wszystko, czym jestem.', 0),
(25653, 'plPL', 'W takim razie powtarzaj za mną: „Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą. Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.\nDobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza.\nOd tej chwili aż do końca dni żyję i umieram – za Hordę!”\n', 'W takim razie powtarzaj za mną: „Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą. Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.\nDobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza.\nOd tej chwili aż do końca dni żyję i umieram – za Hordę!”', 0),
(25654, 'plPL', 'Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą. Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.$B$BDobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza.$B$BOd tej chwili aż do końca dni żyję i umieram – ZA HORDĘ!', 'Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą. Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.$B$BDobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza.$B$BOd tej chwili aż do końca dni żyję i umieram – ZA HORDĘ!', 0),
(25655, 'plPL', 'Za Hordę!\nUzbrój się z otaczających nas skrzyń i zamelduj się w Młocie Agmara, na wschód stąd. Twoją pierwszą próbą jako członka Hordy będzie przetrwanie tej podróży.\nLok\'tar ogar!', 'Za Hordę!\nUzbrój się z otaczających nas skrzyń i zamelduj się w Młocie Agmara, na wschód stąd. Twoją pierwszą próbą jako członka Hordy będzie przetrwanie tej podróży.\nLok\'tar ogar!', 0),
(25667, 'plPL', 'Zwycięstwo albo śmierć! Za Hordę!', 'Zwycięstwo albo śmierć! Za Hordę!', 0),
(25691, 'plPL', '', 'Naszym obowiązkiem jest chronić tych taunka i dać im tę odrobinę otuchy, jaką możemy zaoferować.', 0),
(25693, 'plPL', '', 'Te dzieci przeżyją. Otoczone miłością i czułością wyrosną na silnych członków Hordy, a z czasem straszne wspomnienia ich zniszczonego życia wyblakną.', 0),
(25707, 'plPL', 'Powiedz swojemu dowódcy, że nie będę czekać ani chwili dłużej! Chce tego sojuszu czy nie?!', '', 0),
(25708, 'plPL', 'Czekam tu całą wieczność od naszego ostatniego spotkania! Kiedy Goramosh wreszcie skończy ten swój rytuał?', '', 0),
(25710, 'plPL', 'To nie do zniesienia! Reprezentuję księcia Nexusa, nie wolno kazać mi czekać! To Goramosh powinien czekać na mnie!', '', 0),
(25711, 'plPL', 'Sam Malygos osobiście mnie zapewnił, że twój dowódca uczyni szczegóły tego porozumienia swoim najważniejszym zadaniem. A teraz mnie przepuść!', '', 0),
(25712, 'plPL', 'Jeśli będę musiał czekać jeszcze dłużej, będę zmuszony ponownie rozważyć proponowane porozumienie między Eterium a Błękitnym Stadem!', '', 0),
(25713, 'plPL', 'Jesteś zwykłym podwładnym! Nie będę czekać ani chwili dłużej! Natychmiast zaprowadź mnie do Goramosha!', '', 0),
(25715, 'plPL', 'Co to ma być, znowu opóźnienia?!', '', 0),
(25716, 'plPL', 'Za późno! Porozumienie zostało wynegocjowane. Zostały tylko szczegóły. Drobne szczegóły... takie jak ty!', '', 0),
(25727, 'plPL', 'Pośród tragedii i chaosu to miejsce wyzywająco stawia czoła Pladze! Dobrze jest należeć do Hordy.', 'Pośród tragedii i chaosu to miejsce wyzywająco stawia czoła Pladze! Dobrze jest należeć do Hordy.', 0),
(25735, 'plPL', 'Tak, tak, dano mi do zrozumienia, że linia mocy została już przekierowana. Nie będę dłużej czekać... natychmiast wezwij Goramosha!', '', 0),
(25736, 'plPL', 'Wasza iglica przypływu najwyraźniej zadziałała bez zarzutu. Goramosh ma już chyba czas, by dalej omówić proponowane porozumienie?', '', 0),
(25752, 'plPL', 'Port Moa\'ki ma to szczęście, że służą mu dwa wielkie żółwie morskie: Wędrowiec Fal i Zielona Wyspa. Pływają między Unu\'pe a Kamaguą.', '', 0),
(25775, 'plPL', 'Szybciej! Szybciej! To uzbrojenie musi trafić do Awangardy Kor\'kronu DZISIAJ!', '', 0),
(25776, 'plPL', 'Z radością zastąpię was wszystkich goblinami! Nie zawiedźcie mnie!', '', 0),
(25777, 'plPL', 'Nadrządca Agmar żąda od nas więcej! Nie możemy go zawieść!', '', 0),
(25778, 'plPL', 'Nie każ mi zeskakiwać z tej skrzyni! Rozbiję ci łeb, orku.', '', 0),
(25781, 'plPL', 'Hej, ślicznotko, Zebu\'tan mieć tu dwa dywany! Czemu ty nie przyjść i go nie ogrzać, co?', '', 0),
(25782, 'plPL', 'Patrz, co Zebu\'tan mieć dla ciebie! Róże dla różyczki!', '', 0),
(25784, 'plPL', '', 'Nawet gdybyś był ostatnim trollem w Azeroth!', 0),
(25785, 'plPL', '', 'Fuuuj!', 0),
(25787, 'plPL', '', 'Spadaj, oblechu!', 0),
(25788, 'plPL', '', 'Mam faceta! A teraz zmiataj!', 0),
(25789, 'plPL', 'Ten troll myśleć, że ty się w nim zabujać! Chodź tu!', '', 0),
(25790, 'plPL', 'Nie wstydź się, elficzko. Ty nie czuć tej gorącej miłości, co się rodzić między nami?', '', 0),
(25812, 'plPL', 'Poszukiwany MARTWY za zdradę i inne zdradzieckie czyny przeciw Hordzie!$B$BWszystkie nagrody wypłaca kapitan Gort.', '', 0),
(25823, 'plPL', 'Psst... Tutaj, przy skrzynce pocztowej. Przyjdź szybko i upewnij się, że nikt cię nie śledzi.', '', 0),
(25828, 'plPL', 'Puśćcie mnie, potwory!', '', 0),
(25829, 'plPL', 'Módlcie się do jakichkolwiek bogów, w których wierzycie, bym nigdy nie odzyskał wolności!', '', 0),
(25860, 'plPL', '$gPopełniłeś:Popełniłaś; fatalny błąd, śmiertelniku... Nie ma ssstąd ucieczki...', '', 0),
(25861, 'plPL', 'Zdrajcy! Nadchodzi dzień sądu, a wraz z nim wasz koniec! Zobaczymy, czy wasz Król Lisz ocali was przed wyrokiem Pradawnego! Teraz zginiecie!', '', 0),
(25871, 'plPL', 'Hę? Co?! Idź sobie.', '', 0),
(25872, 'plPL', '', 'Jeśli zbuduję nową machinę wojenną, na pewno dostanę za nią niezłą sumkę przy Bramie Gniewu.$B$BNiektóre z naszych poprzednich wersji nie były do końca... stabilne, ale moja latająca maszyna powinna się sprawdzić, jeśli tylko opracuję dla niej skuteczny system bombowy.', 0),
(25873, 'plPL', 'Tu można zarobić! Jak zawsze mawiał tata – nie ma lepszego czasu na zgarnianie forsy niż czas wojny.', '', 0),
(25912, 'plPL', 'Nie mogę.', 'Nie mogę.', 0),
(25913, 'plPL', 'Nie.', 'Nie.', 0),
(25914, 'plPL', 'Musisz uzbroić się w cierpliwość.', 'Musisz uzbroić się w cierpliwość.', 0),
(25915, 'plPL', 'Goramosh jest teraz zajęty rytuałem.', 'Goramosh jest teraz zajęty rytuałem.', 0),
(25916, 'plPL', 'Mam rozkaz, byś tu zaczekał.', 'Mam rozkaz, byś tu zaczekał.', 0),
(25917, 'plPL', 'Mistrz zaraz cię przyjmie.', 'Mistrz zaraz cię przyjmie.', 0),
(25918, 'plPL', 'To już nie potrwa długo.', 'To już nie potrwa długo.', 0),
(25919, 'plPL', 'Wybacz, ambasadorze. Moje rozkazy były całkiem jasne.', 'Wybacz, ambasadorze. Moje rozkazy były całkiem jasne.', 0),
(25920, 'plPL', 'Zmiażdżymy Arthasa! Plaga nie ma szans z potęgą Hordy!', '', 0),
(25934, 'plPL', '', 'Trzymajcie ich z dala od ogniska!', 0),
(25936, 'plPL', 'Anub\'et\'kan... wykończy cię.', '', 0),
(25937, 'plPL', 'Z radością umieram za mistrza...', '', 0),
(25938, 'plPL', 'Twoje zwycięstwo nic nie znaczy.', '', 0),
(25939, 'plPL', 'Powstanę znowu, potężniejszy... o wiele... bardziej...', '', 0),
(25950, 'plPL', 'Rozerwijcie tę żałosną wioskę na strzępy!', '', 0),
(25952, 'plPL', 'Poddaj się, taunka! Twoja wola nie oprze się Pladze!', '', 0),
(25954, 'plPL', 'Jestem... WOLNY!', '', 0),
(25955, 'plPL', 'Co oni zrobili z moim ludem...', '', 0),
(25956, 'plPL', 'Za to, co uczyniłeś, poczujesz pełną furię przodków, potworze!', '', 0),
(25957, 'plPL', 'Nadchodzi odrodzenie, bracia... Powstańcie... Powstańcie i walczcie raz jeszcze.', '', 0),
(25958, 'plPL', 'ZA LODOWĄ MGŁĘ! ZA TAUNKA!', '', 0),
(25959, 'plPL', 'Twoja wolność nie potrwa długo, Lodowa Mgło!', '', 0),
(25961, 'plPL', 'Potężny jormungar na chwilę się chwieje i szeroko otwiera paszczę.', '', 0),
(25962, 'plPL', 'Zejdź tu i stań do walki, owadzie!', '', 0),
(25963, 'plPL', 'W takim razie sam cię ściągnę! Wietrze, użycz mi skrzydeł!', '', 0),
(25964, 'plPL', 'Zuchwały śmiertelniku! Zostaniesz pożarty!', '', 0),
(25965, 'plPL', 'ARRGH!! To niemożliwe! Jak...', '', 0),
(25993, 'plPL', 'Nie trzeba było płynąć łodzią na północ, mon!', '', 0),
(25999, 'plPL', 'Anub\'et\'kan pokonany! Weź kawałek jego skorupy jako dowód zwycięstwa!', '', 0),
(26020, 'plPL', 'Pani, iglica przypływu działa już w pełni.', '', 0),
(26021, 'plPL', '', 'Dobrze się spisałeś, Keldonusie. Lord Malygos będzie bardzo zadowolony z twoich postępów.', 0),
(26022, 'plPL', 'Żyję tylko po to, by służyć mistrzowi, pani.', '', 0),
(26024, 'plPL', 'Linia mocy pod tą świątynią nocnych elfów płynie teraz do Lazurowej Smoczej Świątyni. Nasi bracia powinni mieć całą moc, jakiej potrzebują, by zmiażdżyć naszych wrogów.', '', 0),
(26025, 'plPL', '', 'Zajmij się tym intruzem, Keldonusie. Gdy skończysz, przynieś mi głowę istoty, którą nazywają $n. Ozdobię swoje komnaty $gjego:jej; czaszką.', 0),
(26026, 'plPL', '', 'Ten występek przeciw Błękitnemu Stadu został odnotowany. Z tym większą przyjemnością oddzielę energię życiową od twojego ciała!', 0),
(26031, 'plPL', 'Zrób, co do ciebie należy, by trzymać Plagę z dala, żołnierzu! Zgłaszaj wszystko, co podejrzane, i najpierw zabijaj, potem zadawaj pytania!', '', 0),
(26032, 'plPL', 'Zapamiętaj moje słowa: ci głupcy Porzuceni będą zgubą nas wszystkich!', '', 0),
(26033, 'plPL', 'Jeśli chcesz znać moje zdanie – a PYTASZ – to trzeba wybić wszystkich aptekarzy, zanim będzie za późno!', '', 0),
(26034, 'plPL', 'Horda to honor i wojna. Na pewno nie ma nic honorowego w tym, co robią ci aptekarze.', '', 0),
(26035, 'plPL', 'Mam oko na tych Porzuconych idiotów tam na dole. Przy nich nigdy dość ostrożności!', '', 0),
(26039, 'plPL', '%s dziękuje ci.', '', 0),
(26041, 'plPL', '%s odłamuje kawałek swojej kory, wręcza ci go i odchodzi.', '', 0),
(26042, 'plPL', '%s wpada w gniew z powodu twojej prośby i atakuje!', '', 0),
(26044, 'plPL', 'Jeśli masz jakieś sprawy z tamtym doktorem, uważaj. Cokolwiek oni tam knują, to nienaturalne.', '', 0),
(26045, 'plPL', 'Mon, zachodnie pustkowia tej krainy być pełne złych typów. Ty się trzymać z dala od tamtej okolicy, jeśli chcieć żyć!', '', 0),
(26059, 'plPL', 'Moje obowiązki w Młocie Agmara wykraczają daleko poza opiekę nad zwierzętami w stajniach.', '', 0),
(26079, 'plPL', 'Najwyższy czas! Bierz to drewno i ruszaj. Horda nie będzie tam walczyć wiecznie, a tu jest kasa do zgarnięcia!', '', 0),
(26080, 'plPL', 'Robią wrażenie, co? Te olbrzymy byłyby idealnym mięs... eee, idealnymi sojusznikami. Ten tu to ich przywódca, ale wciąż nie chce ze mną rozmawiać.', '', 0),
(26081, 'plPL', 'Witaj. Możesz dzielić z nami ten kanion jako schronienie przed smokami. Uważaj jednak na tego goblińskiego karła... jego pobratymcom nie można ufać.', '', 0),
(26082, 'plPL', 'Z odpowiednią ilością forsy dałoby się przejąć władzę nad światem...', '', 0),
(26096, 'plPL', 'Witaj w Świątyni Żmijowego Spoczynku, podróżniku.$B$BTu smocze stada naradzają się w pokoju pośród kości swoich czcigodnych przodków.$B$BPrzynajmniej panował tu pokój, dopóki Błękitne Stado nie przypuściło niespodziewanego ataku na samą świątynię.$B$BWejdź z naszym błogosławieństwem, lecz wiedz, że w naszych murach nie tolerujemy żadnej agresji.', '', 0),
(26099, 'plPL', '', 'Chcesz wrócić na dół, $N?$B$BMogę dopilnować, by jeden z tych smokowców bezpiecznie zabrał cię tam, dokąd musisz się udać.', 0),
(26100, 'plPL', 'Tak, proszę, chcę wrócić na sam dół świątyni.', 'Tak, proszę, chcę wrócić na sam dół świątyni.', 0),
(26101, 'plPL', 'Zostaw mnie w spokoju, głupcze!', '', 0),
(26119, 'plPL', 'Co? Chcesz się u mnie szkolić, $N? Lepiej bądź $ggotów:gotowa; na ciężką pracę.', '', 0),
(26120, 'plPL', 'Muszę wrócić do świata cieni, Koltiro. Odeślij mnie.', 'Muszę wrócić do świata cieni, Koltiro. Odeślij mnie.', 0),
(26124, 'plPL', 'Jeśli chcesz, możesz spać w koszarach. Tylko nie budź moich ludzi, bo osobiście wyrzucę cię na śnieg.', '', 0),
(26126, 'plPL', 'Dziękuję, że mnie $guratowałeś:uratowałaś;, $n. Nigdy nie zapomnę twojej odwagi i determinacji.', '', 0),
(26127, 'plPL', 'Witaj, wielki wodzu. Czy uczynisz mi ten zaszczyt i przyjmiesz moje zaproszenie do Hordy jako jej oficjalny członek i przywódca taunka?', 'Witaj, wielki wodzu. Czy uczynisz mi ten zaszczyt i przyjmiesz moje zaproszenie do Hordy jako jej oficjalny członek i przywódca taunka?', 0),
(26128, 'plPL', 'Walka u twego boku jako brat Hordy będzie dla mnie zaszczytem, $n. Przyjmuję twoją propozycję.', '', 0),
(26129, 'plPL', 'To ty czynisz mi zaszczyt, wielki wodzu. Proszę, odczytaj ten zwój. To przysięga wierności.', 'To ty czynisz mi zaszczyt, wielki wodzu. Proszę, odczytaj ten zwój. To przysięga wierności.', 0),
(26130, 'plPL', '%s odczytuje zwój, a pozostali taunka gromadzą się wokół niego.', '', 0),
(26131, 'plPL', 'Będziemy kroczyć razem, $n.', '', 0),
(26136, 'plPL', 'Zbierzcie się, bracia i siostry.', '', 0),
(26137, 'plPL', 'Lok\'tar ogar! Zwycięstwo albo śmierć – oto słowa, które wiążą mnie z Hordą! Są bowiem najświętszą i najbardziej podstawową prawdą dla każdego wojownika Hordy.', '', 0),
(26138, 'plPL', 'Dobrowolnie oddaję swoje ciało i krew wodzowi. Jestem narzędziem woli mojego wodza. Jestem bronią na rozkaz mojego wodza!', '', 0),
(26139, 'plPL', 'Od tej chwili aż do końca dni żyję i umieram – za Hordę!\n', '', 0),
(26140, 'plPL', 'Za moich braci i siostry taunka! ZA HORDĘ!\n', '', 0),
(26141, 'plPL', 'Witaj w Hordzie, wielki wodzu. Lok\'tar ogar!', '', 0),
(26142, 'plPL', 'ZA HORDĘ!', '', 0),
(26143, 'plPL', 'Ty nie być prawdziwy mężczyzna, póki nie zabić smoka... mon.', '', 0),
(26144, 'plPL', 'Nie ma większego dreszczyku emocji niż polowanie na smoka.', '', 0),
(26145, 'plPL', '', 'Witaj. Przykro mi, że widzisz naszą świętą ziemię po raz pierwszy w takim stanie.', 0),
(26162, 'plPL', 'Ha! Tym razem moi niewolnicy przynieśli prawdziwy posiłek!', '', 0),
(26168, 'plPL', 'Mam jedzenie, jeśli chce ci się jeść, a jeśli potrzebujesz odpoczynku, możesz skorzystać z mojego namiotu.', 'Mam jedzenie, jeśli chce ci się jeść, a jeśli potrzebujesz odpoczynku, możesz skorzystać z mojego namiotu.', 0),
(26186, 'plPL', 'Szukasz ich przywódcy... mała istoto, wypowiadasz wojnę klanom samego Grom\'thara Zwiastuna Gromu. Nie spiesz się tak na spotkanie śmierci.', 'Szukasz ich przywódcy... mała istoto, wypowiadasz wojnę klanom samego Grom\'thara Zwiastuna Gromu. Nie spiesz się tak na spotkanie śmierci.', 0),
(26187, 'plPL', 'Ha! Niech tak będzie. Zadmij w róg przywódcy magnataurów przy kręgu pochodni na południe od Lazurowej Smoczej Świątyni. Pogódź się ze swoimi bogami... Grom\'thar przybędzie.', 'Ha! Niech tak będzie. Zadmij w róg przywódcy magnataurów przy kręgu pochodni na południe od Lazurowej Smoczej Świątyni. Pogódź się ze swoimi bogami... Grom\'thar przybędzie.', 0),
(26188, 'plPL', 'Ha! Tym razem moi niewolnicy przynieśli prawdziwy posiłek!', '', 0),
(26227, 'plPL', '', 'Ten bezkręgowy troll zawiódł mnie po raz ostatni. Anthis! Połam mu nogi!', 0),
(26229, 'plPL', '', 'Nigdy nie widziałam, żebyś tak ochoczo chciała komuś zrobić krzywdę, siostro. Jakże miła odmiana... dobrze więc, ruszaj!', 0),
(26256, 'plPL', 'Wyczuwam w tobie skazę tej ziemi, piechurze. Zgłoś się do biskupa przed następną zmianą.', 'Wyczuwam w tobie skazę tej ziemi, piechurze. Zgłoś się do biskupa przed następną zmianą.', 0),
(26258, 'plPL', 'Wszystkie nagrody wypłaca najwyższy egzekutor Wroth po weryfikacji.$B$BPoważnie zainteresowanych prosimy do środka.$B$BAKWIZYCJA ZABRONIONA!', '', 0),
(26271, 'plPL', 'Dobrze, że tu jesteś, moje dziecko. Ochrona Światłości bardzo w tobie osłabła.', '', 0),
(26272, 'plPL', 'Gotowe. Służ dobrze Światłości.', '', 0),
(26273, 'plPL', '', 'Schlemiel!', 0),
(26275, 'plPL', '', 'Najwyraźniej sknociłeś tę partię zarazy. Co masz na swoje usprawiedliwienie?', 0),
(26277, 'plPL', 'Ale... wykonałem twoje polecenia co do joty! Przepraszam?', '', 0),
(26279, 'plPL', '', 'Przepraszam? PRZEPRASZAM?! Ja ci dam przepraszam!', 0),
(26280, 'plPL', '', 'Ups. Chyba jednak DZIAŁA! Dziwne.', 0),
(26281, 'plPL', 'Iiik!', '', 0),
(26288, 'plPL', '', 'Uważaj, gdzie stąpasz w ogrodzie Ysery, śmiertelniku. Rzeczy nie zawsze są tym, czym się wydają.', 0),
(26289, 'plPL', '', 'Potrzebuję tu kogoś do sprzątania i nowego asystenta!', 0),
(26290, 'plPL', 'Potrzebujesz czegoś? Może naprawić zbroję albo broń? Hmm?', '', 0),
(26292, 'plPL', 'Najwyższy czas!', '', 0),
(26293, 'plPL', 'Jakieś ostatnie słowa, nieczysty kundlu?', '', 0),
(26294, 'plPL', 'Po namyśle, nic mnie to nie obchodzi. Płoń w piekle, nędzniku!', '', 0),
(26295, 'plPL', 'Ha! To się nigdy nie nudzi.', '', 0),
(26327, 'plPL', 'Ojciec podarował mi swoją zbroję bojową i topór. Wkrótce zrobić z nich dobry użytek.', '', 0),
(26343, 'plPL', 'NIGDY MNIE NIE ZŁAPIECIE, POTWORY!', 'NIGDY MNIE NIE ZŁAPIECIE, POTWORY!', 0),
(26344, 'plPL', 'Na miłość Światłości, wyciągnijcie mnie stąd!', 'Na miłość Światłości, wyciągnijcie mnie stąd!', 0),
(26345, 'plPL', 'Wybrałam zły dzień na rzucenie picia!', 'Wybrałam zły dzień na rzucenie picia!', 0),
(26346, 'plPL', 'ONI CHCĄ MNIE ZABIĆ! POMOCY!', 'ONI CHCĄ MNIE ZABIĆ! POMOCY!', 0),
(26347, 'plPL', 'Prędzej umrę, niż dam się któremuś z was przemienić, potwory!', 'Prędzej umrę, niż dam się któremuś z was przemienić, potwory!', 0),
(26348, 'plPL', 'Skąd to wszystko się wzięło?! Niech ktoś pomoże!', 'Skąd to wszystko się wzięło?! Niech ktoś pomoże!', 0),
(26349, 'plPL', 'Kto by pomyślał, że znowu będziemy mieć ten problem? A, czekaj, WSZYSCY!', 'Kto by pomyślał, że znowu będziemy mieć ten problem? A, czekaj, WSZYSCY!', 0),
(26357, 'plPL', 'Dzięki za pomoc, $gbohaterze:bohaterko;!', 'Dzięki za pomoc, $gbohaterze:bohaterko;!', 0),
(26358, 'plPL', '$gUratowałeś:Uratowałaś; mi życie! Dzięki!', '$gUratowałeś:Uratowałaś; mi życie! Dzięki!', 0),
(26359, 'plPL', 'Na pewno umiesz tym latać? Trochę się chybocze.', 'Na pewno umiesz tym latać? Trochę się chybocze.', 0),
(26360, 'plPL', 'Nie chcę wyjść na niewdzięczną, ale czy $gmógłbyś:mogłabyś; lecieć trochę bliżej ziemi? Nienawidzę wysokości!', 'Nie chcę wyjść na niewdzięczną, ale czy $gmógłbyś:mogłabyś; lecieć trochę bliżej ziemi? Nienawidzę wysokości!', 0),
(26362, 'plPL', 'Jesteś moim aniołem stróżem! Niczym rycerz na białym koniu $gsfrunąłeś:sfrunęłaś; z niebios i $gwyrwałeś:wyrwałaś; mnie z otchłani potępienia!', 'Jesteś moim aniołem stróżem! Niczym rycerz na białym koniu $gsfrunąłeś:sfrunęłaś; z niebios i $gwyrwałeś:wyrwałaś; mnie z otchłani potępienia!', 0),
(26363, 'plPL', 'Jak mogę ci się za to odwdzięczyć, przyjacielu?', 'Jak mogę ci się za to odwdzięczyć, przyjacielu?', 0),
(26364, 'plPL', 'Coś mi się kręci w głowie... Uuuuf...', 'Coś mi się kręci w głowie... Uuuuf...', 0),
(26381, 'plPL', 'Nareszcie bezpieczna! Dzięki ci, $gnieznajomy:nieznajoma;!', 'Nareszcie bezpieczna! Dzięki ci, $gnieznajomy:nieznajoma;!', 0),
(26382, 'plPL', 'HURRA!', 'HURRA!', 0),
(26383, 'plPL', 'Ta osoba ma dobre serce, Uriku. Dziękuję, $gbohaterze:bohaterko;!', 'Ta osoba ma dobre serce, Uriku. Dziękuję, $gbohaterze:bohaterko;!', 0),
(26384, 'plPL', 'Udało się! Naprawdę się udało!', 'Udało się! Naprawdę się udało!', 0),
(26385, 'plPL', 'Drzwi mojego sklepu zawsze będą dla ciebie otwarte, przyjacielu.', 'Drzwi mojego sklepu zawsze będą dla ciebie otwarte, przyjacielu.', 0),
(26386, 'plPL', '', 'Nigdy nie zapomnimy twojej odwagi, $n. Zawsze będziesz $gmile widziany:mile widziana; w Zimowej Straży.$B$BCzy chcesz uczynić tę gospodę swoim domem?', 0),
(26387, 'plPL', 'Chcę obejrzeć twoje towary, Illusio.', 'Chcę obejrzeć twoje towary, Illusio.', 0),
(26388, 'plPL', 'Zybarus dziękuje ci z całego serca, $gbohaterze:bohaterko;. Gdyby nie ty, Zybarus by zginął albo, co gorsza, stałby się jednym z nich...', '', 0),
(26389, 'plPL', '%s jęczy, ale poza tym wydaje się odporny na zarazę.', '', 0),
(26390, 'plPL', 'Twoja ochrona jest silna, dziecko. Kontynuuj pracę.', 'Twoja ochrona jest silna, dziecko. Kontynuuj pracę.', 0),
(26391, 'plPL', 'Potrzebujesz błogosławieństwa biskupa. Udaj się do niego jak najszybciej.', 'Potrzebujesz błogosławieństwa biskupa. Udaj się do niego jak najszybciej.', 0),
(26393, 'plPL', 'Jesteś $gnieczysty:nieczysta;!', 'Jesteś $gnieczysty:nieczysta;!', 0),
(26399, 'plPL', 'Abbendis dopilnuje, byś $gzostał oczyszczony:została oczyszczona;!', 'Abbendis dopilnuje, byś $gzostał oczyszczony:została oczyszczona;!', 0),
(26401, 'plPL', 'Zostaniesz $goczyszczony:oczyszczona;!', 'Zostaniesz $goczyszczony:oczyszczona;!', 0),
(26402, 'plPL', 'W imię Światłości!', 'W imię Światłości!', 0),
(26403, 'plPL', 'Na Światłość!', 'Na Światłość!', 0),
(26404, 'plPL', 'Niech stal cię oczyści!', 'Niech stal cię oczyści!', 0),
(26405, 'plPL', 'Jak śmiesz przerywać nasze prawe dzieło?!', '', 0),
(26410, 'plPL', '', 'Mów ciszej, $N. Jestem w przebraniu i szpieguję dla Jadozłości.', 0),
(26418, 'plPL', 'Mój piękny tartak. Ty! Zginiesz za to!', '', 0),
(26419, 'plPL', 'Idź ze Światłością, przyjacielu.', 'Idź ze Światłością, przyjacielu.', 0),
(26421, 'plPL', 'Kiedyś byli ludźmi... A teraz? Nieumarłe potwory łaknące ludzkiego mięsa!', 'Kiedyś byli ludźmi... A teraz? Nieumarłe potwory łaknące ludzkiego mięsa!', 0),
(26423, 'plPL', 'Niech Światłość cię zabierze!', 'Niech Światłość cię zabierze!', 0),
(26438, 'plPL', '', '$gDałbyś:Dałabyś; radę mnie stąd wyciągnąć, $N?', 0),
(26439, 'plPL', 'Obawiam się, że nie, Schneider. Twój czas nadszedł!', 'Obawiam się, że nie, Schneider. Twój czas nadszedł!', 0),
(26440, 'plPL', 'O, świetnie, jesteś tu, żeby mnie uratować. No to wypuść mnie stąd!', '', 0),
(26441, 'plPL', 'Nie dzisiaj, starszy skrybo!', 'Nie dzisiaj, starszy skrybo!', 0),
(26442, 'plPL', 'Hej, $gkolego:proszę pani;. Widziałem cię tu i tam.$B$BMożesz mnie stąd wyciągnąć?', '', 0),
(26443, 'plPL', 'Obawiam się, że nie. Twoje dni jako inżyniera sanitarnego dobiegają końca.', 'Obawiam się, że nie. Twoje dni jako inżyniera sanitarnego dobiegają końca.', 0),
(26447, 'plPL', 'Nie wiem, co się stało. Dopiero co przybyłem do Jadozłości, a tu nagle budzę się w tej klatce!$B$B$gPrzyszedłeś:Przyszłaś; mnie uratować?', '', 0),
(26448, 'plPL', 'Nie, kanclerzu, trudno powiedzieć, że jestem tu, by cię „ratować”.', 'Nie, kanclerzu, trudno powiedzieć, że jestem tu, by cię „ratować”.', 0),
(26449, 'plPL', '', 'Jak to mój czas nadszedł?! Zabiję cię tam, gdzie stoisz!', 0),
(26450, 'plPL', 'Chyba nie zamierzasz... Złożę na ciebie raport, $N!', '', 0),
(26452, 'plPL', 'Bądź tak $guprzejmy:uprzejma; i wypuść mnie stąd!', '', 0),
(26453, 'plPL', 'Może ktoś mnie stąd wypuścić? Muszę wrócić do Jadozłości i dokończyć zmianę.', '', 0),
(26454, 'plPL', 'Nie! Błagam cię! Proszę, nie zabijaj mnie!', '', 0),
(26458, 'plPL', 'Co to ma znaczyć?! Przestań! Zapłacę ci dwa razy tyle, ile oni ci płacą!', '', 0),
(26459, 'plPL', 'Dopiero co przybyłem do Jadozłości. Jak mogłem cię skrzywdzić?', '', 0),
(26467, 'plPL', 'Dziękuję ci, dobra duszo.', 'Dziękuję ci, dobra duszo.', 0),
(26468, 'plPL', 'Nigdy cię nie zapomnę, przyjacielu.', 'Nigdy cię nie zapomnę, przyjacielu.', 0),
(26469, 'plPL', 'Nareszcie! $gPrzybył bohater:Przybyła bohaterka;!', 'Nareszcie! $gPrzybył bohater:Przybyła bohaterka;!', 0),
(26470, 'plPL', 'Dobrze, że jesteś, $gbohaterze:bohaterko;! Bestia już prawie mnie miała!', 'Dobrze, że jesteś, $gbohaterze:bohaterko;! Bestia już prawie mnie miała!', 0),
(26472, 'plPL', '$gPrzyszedłeś:Przyszłaś; się pobawić?', '', 0),
(26480, 'plPL', 'Au! NIC ci nie powiem, plugawy śmieciu!', '', 0),
(26481, 'plPL', 'Czekaj... CZEKAJ! Co chcesz wiedzieć?! Wiem, kim jesteś: $n, $c.', '', 0),
(26482, 'plPL', 'AU... NIE! Wiemy, że kradniecie nam zbroje, broń i konie!', '', 0),
(26483, 'plPL', 'Wiemy... że nie wiecie... czemu jesteśmy odporni... na waszą tak zwaną zarazę. Wielki admirał Zachodni Wiatr jakimś sposobem dał wielkiemu opatowi tę modlitwę. Błagam... dość już... proszę?!', '', 0),
(26484, 'plPL', 'AAAAAAAACH! Proszę... wiemy... że macie... szpiega... przebranego... za jednego z nas! No... to wszystko, co wiem. Proszę... litości... PRZESTAŃ!', '', 0),
(26496, 'plPL', 'MÓWIŁEM CI... Nie wiem... nic... więcej!', '', 0),
(26498, 'plPL', 'Proszę... przestań. Zrobię... wszystko...', '', 0),
(26499, 'plPL', 'Po prostu... skończ z tym.', '', 0),
(26501, 'plPL', 'Wszyscy... błagali... o... życie!', '', 0),
(26504, 'plPL', 'Błagam... dość już.', '', 0),
(26506, 'plPL', 'Nic... więcej... ze mnie... nie wyciągniesz!', '', 0),
(26507, 'plPL', 'AUUUUUUUU!', '', 0),
(26518, 'plPL', '', 'Szybko poznajemy cenę śmierci na tym mroźnym pustkowiu, $n. Moc Króla Lisza sięga każdego skrawka Północnej Grani i przenika samą ziemię! Obraca naszych własnych poległych przeciwko nam.$B$BZ nieba powstali jeźdźcy gryfów zasypują nas mściwymi burzowymi młotami, a na ziemi atakują nas chodzące trupy.\n', 0),
(26525, 'plPL', 'Gdzie przetrzymują starszego skrybę Barrigę?', 'Gdzie przetrzymują starszego skrybę Barrigę?', 0),
(26526, 'plPL', 'Chyba zamknęli go w klatce koło tartaku.', 'Chyba zamknęli go w klatce koło tartaku.', 0),
(26527, 'plPL', 'Wiesz, dokąd zabrali inżyniera sanitarnego Burke\'a?', 'Wiesz, dokąd zabrali inżyniera sanitarnego Burke\'a?', 0),
(26529, 'plPL', 'Chyba jest po południowej stronie opactwa.', 'Chyba jest po południowej stronie opactwa.', 0),
(26532, 'plPL', 'Masz pojęcie, gdzie trzymają strażniczkę śmierci Schneider?', 'Masz pojęcie, gdzie trzymają strażniczkę śmierci Schneider?', 0),
(26533, 'plPL', 'Chyba trzymają ją na dole, przy szubienicy.', 'Chyba trzymają ją na dole, przy szubienicy.', 0),
(26534, 'plPL', 'Możesz mi powiedzieć, gdzie zamknęli w klatce kanclerza Amai?', 'Możesz mi powiedzieć, gdzie zamknęli w klatce kanclerza Amai?', 0),
(26535, 'plPL', 'Zdaje się, że zabrali go na północną stronę opactwa, w pobliże tarcz łuczniczych.', 'Zdaje się, że zabrali go na północną stronę opactwa, w pobliże tarcz łuczniczych.', 0),
(26543, 'plPL', 'POMOCY! POMOCY! $gTEN MĘŻCZYZNA UKRADŁ:TA KOBIETA UKRADŁA; MÓJ WIZERUNEK!', 'POMOCY! POMOCY! $gTEN MĘŻCZYZNA UKRADŁ:TA KOBIETA UKRADŁA; MÓJ WIZERUNEK!', 0),
(26544, 'plPL', 'Wiem, czemu tu jesteś – jeden z tych głupich magnataurów z równin się wtrącił i zdołał wciągnąć w to smoki. Lubisz im służyć jak pies?', 'Wiem, czemu tu jesteś – jeden z tych głupich magnataurów z równin się wtrącił i zdołał wciągnąć w to smoki. Lubisz im służyć jak pies?', 0),
(26547, 'plPL', 'Głupi $Gchłopcze:dziewczyno; na posyłki... zginiesz za przerwanie mojej pracy!', '', 0),
(26555, 'plPL', 'Nie... NIE! Co ty $gnarobiłeś:narobiłaś;?! Tyle pradawnych żmijów zmarnowanych... jaka magia mogła tego dokonać?', '', 0),
(26596, 'plPL', 'Zwodzą was! Szturm to same kłamstwa! Plaga i Porzuceni nie są naszymi wrogami! Obudźcie się!', '', 0),
(26597, 'plPL', 'Najwyższa generał Abbendis osobiście mi powiedziała, że przybycie na północ było błędem i że jesteśmy zgubieni! Wzywam was wszystkich, byście złożyli broń i odeszli, zanim będzie za późno!', '', 0),
(26598, 'plPL', 'Wyrzeknijcie się Szkarłatnego Szturmu! Nie słuchajcie dłużej kłamstw najwyższej generał i wielkiego admirała!', '', 0),
(26599, 'plPL', 'Abbendis to zwykła ladacznica, a wielki admirał Zachodni Wiatr sprzedaje ją tanio, tak jak sprzedał nas!', '', 0),
(26606, 'plPL', 'Doskonale. Dopóki nie zaczniesz torować sobie drogi ostrzem, nikt nie zauważy różnicy.', '', 0),
(26610, 'plPL', 'Hej, kto zadzwonił dzwonem?', '', 0),
(26612, 'plPL', 'Tak, $gmój synu:moja córko;?', '', 0),
(26614, 'plPL', 'Wasza Eminencjo, czy mogę prosić o słowo na osobności?', 'Wasza Eminencjo, czy mogę prosić o słowo na osobności?', 0),
(26615, 'plPL', '<Wielki opat przygląda ci się przez chwilę, po czym się uśmiecha.>$B$BDobrze, znam pewne miejsce, dziecko. Pocałuj tylko mój pierścień i daj znać, kiedy będziesz $ggotów:gotowa;.', '', 0),
(26616, 'plPL', 'Jestem $ggotów:gotowa;, Ekscelencjo. <Pocałuj pierścień>', 'Jestem $ggotów:gotowa;, Ekscelencjo. <Pocałuj pierścień>', 0),
(26617, 'plPL', 'W takim razie spotkajmy się przy wejściu do opactwa. Zaraz tam będę.', '', 0),
(26624, 'plPL', 'Mam swój udział w niszczeniu całych cywilizacji... a teraz muszę się zniżać do układów z nędznym Kultem Potępionych. Budzi to we mnie obrzydzenie.', '', 0),
(26625, 'plPL', 'Agentko Skully, musisz znów użyć na mnie magicznego lustra banshee!', 'Agentko Skully, musisz znów użyć na mnie magicznego lustra banshee!', 0),
(26626, 'plPL', '', 'Dobrze, ale tym razem obchodź się z nim ostrożniej!', 0),
(26637, 'plPL', 'Ach! Co ty wyprawiasz?', 'Ach! Co ty wyprawiasz?', 0),
(26649, 'plPL', 'Nie zawracaj mi głowy drobiazgami!', '', 0),
(26655, 'plPL', 'Sam wielki admirał przybył, by sprawdzić nasze oddanie. Jeśli znów zobaczę, że obijasz się na posterunku, osobiście cię wypatroszę.', 'Sam wielki admirał przybył, by sprawdzić nasze oddanie. Jeśli znów zobaczę, że obijasz się na posterunku, osobiście cię wypatroszę.', 0),
(26660, 'plPL', 'Nie widzisz, że mam robotę?! Nigdy nie przygotujemy tej bazy na czas, na powrót księcia!', '', 0),
(26661, 'plPL', 'Gdyby nie te przeklęte bestie, które spaliły nasze statki, bylibyśmy już w domu. A teraz zostaw mnie w spokoju, muszę wracać do pracy!', '', 0),
(26662, 'plPL', 'Krucjata Argentu przybyła tu w pełnej sile, przyjacielu. Nie zamierzaliśmy oddać ci całej chwały!', '', 0),
(26663, 'plPL', 'Oriku, potrzebuję kolejnego eliksiru z mrocznego zielska.', 'Oriku, potrzebuję kolejnego eliksiru z mrocznego zielska.', 0),
(26664, 'plPL', 'Wybacz, że zawracam ci głowę, przyjacielu. Rób swoje!', 'Wybacz, że zawracam ci głowę, przyjacielu. Rób swoje!', 0),
(26669, 'plPL', 'To nie koniec... śmierć tylko... wzmacnia...', '', 0),
(26670, 'plPL', 'Ci przeklęci chłopi muszą pracować szybciej! Chcę wracać do domu, do Żelaznej Kuźni. Bardzo tęsknię za żoną i dziećmi.', '', 0),
(26671, 'plPL', 'Kapitan mówi, że jak tylko książę Arthas wróci, ruszamy z powrotem do Lordaeronu.', '', 0),
(26672, 'plPL', 'Nie wiem, co tak długo zatrzymuje młodego księcia, ale chyba już długo nie wytrzymamy. Zimno zaczyna dawać się żołnierzom we znaki.', '', 0),
(26673, 'plPL', 'Na pewno Arthas wróci lada dzień, żołnierzu. Głowa do góry!', 'Na pewno Arthas wróci lada dzień, żołnierzu. Głowa do góry!', 0),
(26674, 'plPL', 'Kiedy zobaczyliśmy, że te dzikie bestie spaliły statki, serca nam zamarły. Nigdy nie czułem się tak bezradny...', '', 0),
(26675, 'plPL', 'Wściekłość. Tak mogę podsumować, co czuję wobec całego tego bałaganu. Harowaliśmy do upadłego, przedzierając się przez lasy na wybrzeże, tylko po to, by się przekonać, że jest za późno. Nasza jedyna droga do domu została zniszczona.', '', 0),
(26676, 'plPL', 'Mimo trudów, które musieliśmy znosić na tym pustkowiu, wierzę, że młody książę poprowadzi nas do zwycięstwa. Co noc modlę się o jego bezpieczeństwo.', '', 0),
(26677, 'plPL', 'Muszę już iść, żołnierzu. Zachowaj czujność!', 'Muszę już iść, żołnierzu. Zachowaj czujność!', 0),
(26678, 'plPL', '<Zapomniany piechur kręci głową.>$B$BNie wytrzymamy tego dłużej, przyjacielu. Jeśli książę Arthas wkrótce nie wróci, wszyscy zginiemy.', '', 0),
(26679, 'plPL', 'Nigdy nie przygotujemy tych statków na czas. Nadchodzi zima, a z nią nasza zguba. Obawiam się, że młody książę skazał nas wszystkich na potępienie.', '', 0),
(26680, 'plPL', 'Arthasa i Muradina nie ma już od dawna. Mam nadzieję, że nie grozi im niebezpieczeństwo.', '', 0),
(26681, 'plPL', 'Na pewno wszystko się ułoży, piechurze.', 'Na pewno wszystko się ułoży, piechurze.', 0),
(26723, 'plPL', 'Ty kłamliwy nędzniku, Arthasie! Zgubiłeś nas wszystkich!', '', 0),
(26724, 'plPL', 'Nasz książę nas porzucił! Wszystko stracone!', '', 0),
(26725, 'plPL', 'Dałeś nam słowo, zdrajco!', '', 0),
(26726, 'plPL', 'Nasze życie było warte znacznie więcej niż twoja krwawa wendeta...', '', 0),
(26727, 'plPL', 'Ale dlaczego?', '', 0),
(26728, 'plPL', 'To wszystko były kłamstwa...', '', 0),
(26779, 'plPL', 'Umarli powstają z naszej własnej krypty!', '', 0),
(26781, 'plPL', 'Udało ci się, $gchłopcze:dziewczyno;! Byłem pewien, że już po tobie!', '', 0),
(26784, 'plPL', 'Co ty tu jeszcze robisz? Wracaj do miasta!', '', 0),
(26795, 'plPL', 'Zarządco, proszę, pozwól mi polecieć na jednym ze smokowców do komnaty królowej na szczycie świątyni.', 'Zarządco, proszę, pozwól mi polecieć na jednym ze smokowców do komnaty królowej na szczycie świątyni.', 0),
(26798, 'plPL', 'Królowa Alexstraza powierzyła mi obronę Świątyni Żmijowego Spoczynku.$B$BJak wiesz, Malygos kazał swoim siłom zniszczyć pobliską kotwicę linii mocy. Siły jego stada przekierowały następnie tę moc do Lazurowej Smoczej Świątyni.$B$BBłękitne smoki czerpią z tej mocy siłę – tak wielką, że ośmielają się atakować samą świątynię! I zaczynają wygrywać.$B$BCzy przybywasz, by nam pomóc?', '', 0),
(26800, 'plPL', 'Odsuń się, $n, bestia może się rzucić i zrobić ci krzywdę.', '', 0),
(26801, 'plPL', 'GODFREY! Słuchaj mnie, potworze! Słuchaj, bo jam jest Światłość, która przyszła wybawić cię od zła!', '', 0),
(26802, 'plPL', '%s warczy.', '', 0),
(26803, 'plPL', 'Dobrze. Zatem mam twoją uwagę, Godfreyu?', '', 0),
(26804, 'plPL', 'Możemy to załatwić na dwa sposoby, Godfreyu. Po pierwsze, po prostu cię zapytam, co znaczą bezbożne znaki wyryte na stronach tej księgi. Co ty na to?', '', 0),
(26805, 'plPL', '%s syczy!', '', 0),
(26806, 'plPL', 'Nic ci nie powiem, kaznodziejo.', '', 0),
(26807, 'plPL', 'Cóż możesz mi zrobić, czego Kel\'Thuzad nie zrobił? Czego Król Lisz nie zrobi?', '', 0),
(26808, 'plPL', 'Księga twoim zbawieniem jest, tak... ale nic się nie dowiesz! NIC NIE POWIEM! NIC!', '', 0),
(26809, 'plPL', 'W takim razie sposób drugi.', '', 0),
(26810, 'plPL', 'Zmówię teraz za ciebie modlitwę, zbłąkana duszo. Niech Światłość łaskawie cię przyjmie.', '', 0),
(26811, 'plPL', 'Niech zacznie się kazanie.', '', 0),
(26812, 'plPL', 'NIECH ŚWIATŁOŚĆ CIĘ ZABIERZE, BESTIO!', '', 0),
(26813, 'plPL', 'Moc Światłości ci rozkazuje!', '', 0),
(26814, 'plPL', 'WPUŚĆ ŚWIATŁOŚĆ, GODFREYU GOODARDZIE!', '', 0),
(26816, 'plPL', 'PŁOŃ W ŚWIĘTYM OGNIU!', '', 0),
(26822, 'plPL', 'Dość ŚWIATŁOŚCI! DOŚĆ! BŁAGAM!', '', 0),
(26823, 'plPL', 'Nigdy takiego bólu nie czułem!', '', 0),
(26824, 'plPL', 'Tak myślałem, że ujrzysz Światłość, Godfreyu... A teraz mów szybko, potworze. Co tam jest napisane?', '', 0),
(26825, 'plPL', 'Mówi o nadchodzącej apokalipsie. O tym, jak ten świat spłonie i odrodzi się ze śmierci.', '', 0),
(26826, 'plPL', 'BZDURY! Godfreyu, masz mnie za głupca? Nie pluj propagandą Plagi w twarz sługi Światłości, poganinie! Mów natychmiast, bo każę chłopom przygotować kąpiel w święconej wodzie i zanurzę cię w niej jak zapchlonego psa!', '', 0),
(26827, 'plPL', 'NIEEEE!!! Powiem! Wszystko powiem!', '', 0),
(26828, 'plPL', 'Ludzie... Pod ziemią Wioski Zimowej Straży zbudowaliście mauzoleum! Jak myślicie, czemu Naxxramas zaatakował właśnie to miejsce? Thel\'zan kryje się głęboko w waszej własnej krypcie i śle na was tysiące tysięcy trupów! Zginiecie wy, o tak...', '', 0),
(26829, 'plPL', 'Co? Pod starą wioską jest mauzoleum? Ależ z nas głupcy, że tego nie zauważyliśmy! Znajdziemy i zgładzimy teraz twojego pana, Godfreyu. Położymy kres temu koszmarowi.', '', 0),
(26830, 'plPL', 'Pozwól, że to my będziemy się martwić, jak zabić tego potwora, Godfreyu.', '', 0),
(26831, 'plPL', 'Jak? Ludzie naprawdę głupi są, tak? Thel\'zan Niosący Zmrok! Thel\'zan Lisz! Ten, który z ludzkiego ciała i kości zrodzony, wszystko dla mocy poświęcił, chroniony przez Króla Lisza!', '', 0),
(26832, 'plPL', 'Thel\'zana nie powstrzymacie! Nosi mroczny dar, którym obdarzył go sam Król Lisz!', '', 0),
(26833, 'plPL', 'Wróć do Halforda z informacjami, którymi łaskawie podzielił się z nami zacny burmistrz, $n. Ja tu dokończę i wycisnę z tego nędznika wszystko, co jeszcze wie o Thel\'zanie. Teraz pokażę Godfreyowi rzadko widywany „sposób trzeci”.', '', 0),
(26834, 'plPL', 'Pogawędźmy sobie o paru sprawach, Godfreyu.', '', 0),
(26835, 'plPL', 'Nie zaznacie spokoju w śmierci, żmije!', 'Nie zaznacie spokoju w śmierci, żmije!', 0),
(26836, 'plPL', 'Powstańcie... powstańcie i ucztujcie na ich ciałach!', 'Powstańcie... powstańcie i ucztujcie na ich ciałach!', 0),
(26837, 'plPL', 'Czas smoków dobiegł końca...', 'Czas smoków dobiegł końca...', 0),
(26841, 'plPL', 'Za Przymierze i lorda Fordragona!', 'Za Przymierze i lorda Fordragona!', 0),
(26842, 'plPL', 'HU-HA! Kawaleria przybyła!', 'HU-HA! Kawaleria przybyła!', 0),
(26843, 'plPL', 'Świetna jazda, żołnierzu! Ani jednego zadrapania!', 'Świetna jazda, żołnierzu! Ani jednego zadrapania!', 0),
(26844, 'plPL', 'Bez ciebie byśmy przepadli. Dzięki za podwózkę!', 'Bez ciebie byśmy przepadli. Dzięki za podwózkę!', 0),
(26895, 'plPL', 'Witaj.$B$BCzekaliśmy na ciebie.', '', 0),
(26896, 'plPL', 'Musimy włączyć się do walki. Możemy ruszać?', 'Musimy włączyć się do walki. Możemy ruszać?', 0),
(26897, 'plPL', 'Dobrze więc, lecimy!', '', 0),
(26908, 'plPL', 'Poprowadź nas do bitwy, $n!', '', 0),
(26910, 'plPL', 'Gryfy z gór Północnej Grani to najwytrzymalsi przedstawiciele swojego gatunku.', '', 0),
(26912, 'plPL', 'Jeźdźcy gryfów stoją dziesięć kroków od nas, przyjacielu. Zabiorą cię do Posterunku Thorsona. Ruszaj!', '', 0),
(26920, 'plPL', '', 'Nawet przez chwilę nie myśl, że twoje dawne osiągnięcia dają ci do czegokolwiek prawo, $n. Nie dają.$B$BJeśli chcesz mojego szacunku, musisz na niego zapracować. To znaczy wykonywać moje rozkazy bez dyskusji i doprowadzać je do końca... bez wyjątków.', 0),
(26936, 'plPL', 'Witaj.$B$BJeśli chcesz pomóc w obronie świątyni, porozmawiaj z lordem Afrasastraszem w środku.', '', 0),
(26954, 'plPL', 'Melduję się do służby!', 'Melduję się do służby!', 0),
(26971, 'plPL', 'Chyba widzę jeden z ich wozów zarazy!', 'Chyba widzę jeden z ich wozów zarazy!', 0),
(26972, 'plPL', 'Mówiłem wam kiedyś, żołnierze, jak zniszczyłem Most Thandol? Tak jest, żadni tam Czarnoryci tego mostu nie zniszczyli! To ja!', 'Mówiłem wam kiedyś, żołnierze, jak zniszczyłem Most Thandol? Tak jest, żadni tam Czarnoryci tego mostu nie zniszczyli! To ja!', 0),
(26973, 'plPL', 'To nie ma sensu. Czemu po prostu nie przelecą Naxxramas nad Twierdzą Zimowej Straży i jej nie wysadzą? Ja bym tak zrobił, gdybym był Kel\'Thuzadem.', 'To nie ma sensu. Czemu po prostu nie przelecą Naxxramas nad Twierdzą Zimowej Straży i jej nie wysadzą? Ja bym tak zrobił, gdybym był Kel\'Thuzadem.', 0),
(26974, 'plPL', 'Ciekawe, czy kiedyś rozwiążemy zagadkę dziwnej rudy. Musi się do czegoś nadawać!', 'Ciekawe, czy kiedyś rozwiążemy zagadkę dziwnej rudy. Musi się do czegoś nadawać!', 0),
(26975, 'plPL', 'Hej, zna ktoś z was McGoyvera z Valgardu? To mój wujek. Wiecie, jaki ma tytuł? Fachowiec. Tak, po prostu „Fachowiec”. Też chcę być fachowcem.', 'Hej, zna ktoś z was McGoyvera z Valgardu? To mój wujek. Wiecie, jaki ma tytuł? Fachowiec. Tak, po prostu „Fachowiec”. Też chcę być fachowcem.', 0),
(26976, 'plPL', 'Coś tu porządnie śmierdzi! Na pewno nie ja. Gnomy pachną masłem i słońcem. Nie to co krasnoludy, które pachną, jakby urodziły się pod pachą trogga! Nikt z was nie jest krasnoludem, co?', 'Coś tu porządnie śmierdzi! Na pewno nie ja. Gnomy pachną masłem i słońcem. Nie to co krasnoludy, które pachną, jakby urodziły się pod pachą trogga! Nikt z was nie jest krasnoludem, co?', 0),
(26977, 'plPL', 'Znałem kiedyś krasnoluda, który twierdził, że gnomy wyewoluowały spod ziemi. Że wszyscy pochodzimy od piaskowych gnomów. Co za bzdury! Piaskowe gnomy? Błagam!', 'Znałem kiedyś krasnoluda, który twierdził, że gnomy wyewoluowały spod ziemi. Że wszyscy pochodzimy od piaskowych gnomów. Co za bzdury! Piaskowe gnomy? Błagam!', 0),
(26978, 'plPL', 'Nigdy nie widziałem takiego zniszczenia...', 'Nigdy nie widziałem takiego zniszczenia...', 0),
(26979, 'plPL', 'Mniej gadania, ludzie. Musimy zachować czujność!', 'Mniej gadania, ludzie. Musimy zachować czujność!', 0),
(26980, 'plPL', 'Każdy skrawek tego miejsca cuchnie śmiercią.', 'Każdy skrawek tego miejsca cuchnie śmiercią.', 0),
(26981, 'plPL', 'Kierowco, słyszałem, że w pojedynkę $gprzetransportowałeś:przetransportowałaś; drogą powietrzną naszych wieśniaków z tej piekielnej dziury. To prawda?', 'Kierowco, słyszałem, że w pojedynkę $gprzetransportowałeś:przetransportowałaś; drogą powietrzną naszych wieśniaków z tej piekielnej dziury. To prawda?', 0),
(26982, 'plPL', 'Czy ktoś coś wie o Thel\'zanie? Kim on jest? Jak to się stało, że dowodzi lądowymi armiami Plagi?', 'Czy ktoś coś wie o Thel\'zanie? Kim on jest? Jak to się stało, że dowodzi lądowymi armiami Plagi?', 0),
(26983, 'plPL', 'Spójrzcie na to pobojowisko... Plaga za to zapłaci!', 'Spójrzcie na to pobojowisko... Plaga za to zapłaci!', 0),
(26984, 'plPL', 'Gdzie są wszystkie ciała? Co oni zrobili z naszymi ludźmi?', 'Gdzie są wszystkie ciała? Co oni zrobili z naszymi ludźmi?', 0),
(26985, 'plPL', 'Mam nadzieję, że dożyję chwili, gdy Arthas dostanie to, na co zasłużył.', 'Mam nadzieję, że dożyję chwili, gdy Arthas dostanie to, na co zasłużył.', 0),
(27042, 'plPL', 'Chcę się dostać do lorda Afrasastrasza w środkowej części świątyni.', 'Chcę się dostać do lorda Afrasastrasza w środkowej części świątyni.', 0),
(27043, 'plPL', 'Panie, muszę się dostać na szczyt świątyni.', 'Panie, muszę się dostać na szczyt świątyni.', 0),
(27045, 'plPL', 'Thel\'zan musi zginąć, choćby po to, żeby wreszcie skończyło się to nieustanne gadanie!', '', 0),
(27046, 'plPL', 'Zabierzesz mnie z powrotem na dół, lordzie Afrasastraszu?', 'Zabierzesz mnie z powrotem na dół, lordzie Afrasastraszu?', 0),
(27047, 'plPL', 'Oficjalne ogłoszenia mieszkańców i władz Zimowej Straży.', '', 0),
(27048, 'plPL', 'Czy możesz użyczyć mi smokowca, który zabierze mnie do lorda Afrasastrasza w środkowej części świątyni?', 'Czy możesz użyczyć mi smokowca, który zabierze mnie do lorda Afrasastrasza w środkowej części świątyni?', 0),
(27049, 'plPL', '', 'Czy obecność czarnego smoka cię niepokoi?$B$BTo dobrze. Powinna. Te smoki też niepokoi. Trzymają się jednak swoich pradawnych cnót – nie ośmieliłyby się mnie tu zaatakować.$B$BGłupcy.', 0),
(27050, 'plPL', 'Teraz opowiem o straszliwym skrzydle zarazy w Naxxramas, gdzie Plaga próbuje udoskonalić śmiercionośną zarazę, którą rozsiała po Lordaeronie.', '', 0),
(27051, 'plPL', 'Teraz opowiem o przeklętym skrzydle pająków w Naxxramas. To tam Plaga hoduje jeszcze bardziej jadowite i niebezpieczne odmiany swoich pobratymców.', '', 0),
(27052, 'plPL', 'Teraz opowiem o zarażonym skrzydle plugastw w Naxxramas. Tam Plaga tworzy najsilniejsze i najohydniejsze aberracje swoich armii.', '', 0),
(27053, 'plPL', 'Teraz opowiem o skrzydle rycerzy śmierci w Naxxramas. W jego splugawionych salach dzień i noc rozbrzmiewa echo bitwy, a nasi najlepsi wojownicy są tam spaczani i przemieniani w największych wojowników Plagi.', '', 0),
(27054, 'plPL', 'Teraz opowiem o najpotężniejszych istotach na szczycie Naxxramas. Zaiste, to dwa z największych zagrożeń dla całej Północnej Grani.', '', 0),
(27055, 'plPL', 'Oto Nicz Siewca Zarazy. To on stworzył proces, który destyluje dusze żywych i zamyka je w zimnej klatce nieżycia – i jak zaobserwowano, wciąż go udoskonala.', '', 0),
(27056, 'plPL', 'Spójrzcie, oto Heigan Nieczysty. Pomysłodawca kotłów zarazy, które zmieniły dzicz Azeroth w Plagowiska.', '', 0),
(27057, 'plPL', 'Mówi się, że Heigan naszpikował same ściany i podłogi Naxxramas mnóstwem pułapek, które może uruchomić w dowolnej chwili.', '', 0),
(27058, 'plPL', 'Ohydziarz. Ohydny owoc połączenia żywej zarazy z Plagowisk z bagiennymi bestiami Azeroth. Podobno panuje nad samą mocą leczenia.', '', 0),
(27059, 'plPL', 'Zostawię ten obraz, byście mogli mu się przyjrzeć. Poznajcie siłę swoich przeciwników, bo siła stworzenia może być też jego słabością.', '', 0),
(27060, 'plPL', 'Uwaga. To Instruktor Razuwiusz, wyznaczony przez Kel\'Thuzada nauczyciel wszystkich rycerzy śmierci. Mówi się, że jego technika jest tak potężna, że tylko jego uczeń mógłby oprzeć się jego sile.', '', 0),
(27061, 'plPL', 'Gotyk Żniwiarz. Mistrz nekromancji i przywoływania, podobno potrafi w mgnieniu oka wezwać legiony nieumarłych. To dzięki jego naukom nawet najsłabsi rycerze śmierci potrafią wskrzeszać zmarłych.', '', 0),
(27062, 'plPL', 'Najpotężniejszymi rycerzami śmierci w Naxxramas są Czterej Jeźdźcy. Stanowią elitę straży Kel\'Thuzada. Pierwszy z nich, Than Korth\'azz, włada mocą płomienia.', '', 0),
(27063, 'plPL', 'Następna, Lady Blaumeux, przywołuje moc cieni i wciąga dusze żywych w swe nienasycone objęcia.', '', 0),
(27064, 'plPL', 'Sir Zeliek, za życia paladyn tak silny w wierze, że nawet po śmierci moc Światłości wciąż odpowiada na jego wezwanie i razi jego wrogów w bitwie.', '', 0),
(27065, 'plPL', 'Ostatni rycerz śmierci, lord Mograine, był najlepszym wojownikiem, jakiego rycerze śmierci kiedykolwiek widzieli. Jednak po wydarzeniach w Azeroth zniknął bez śladu. Wciąż nie wiadomo, kogo Kel\'Thuzad wyznaczył na jego miejsce.', '', 0),
(27066, 'plPL', 'Anub\'Rekhan, jeden z najznamienitszych pajęczych lordów Azjol-Nerub, znalazł się pod kontrolą Plagi, gdy on i jego dawny dowódca, Anub\'arak, zostali przed wielu laty ostatecznie pokonani przez Króla Lisza. Mówi się, że był najwierniejszym z dowódców Anub\'araka.', '', 0),
(27070, 'plPL', 'Wielka Wdowa Ferlina – za życia botaniczka, po śmierci hodowczyni pajęczaków i ich opiekunka – nadzoruje skrzydło pająków, gdzie tworzy dla Króla Lisza najsilniejsze trucizny.', '', 0),
(27073, 'plPL', 'Maexxna, zrodzona przed wiekami w głębi gór Północnej Grani, została schwytana i uwięziona w upiornej cytadeli Naxxramas, gdzie wydaje na świat swój miot i karmi go zwłokami wszystkich, którzy ośmielą się zapuścić zbyt głęboko w Naxxramas.', '', 0),
(27074, 'plPL', 'Oto Łacior. Gdy wieść o jego istnieniu po raz pierwszy dotarła do Bractwa, nikt nie wierzył w opowieści o plugastwie tak niezwykle szybkim i silnym. Jeszcze mniej osób uwierzyło, gdy padł po raz pierwszy...', '', 0),
(27075, 'plPL', 'Grobulus, pierwszy z tych, którzy mieli stać się armią mięsnych olbrzymów. Nosił w sobie śluz zarazy z Naxxramas i wstrzykiwał żywy szlam w ciała wrogów. Ofiara tego plugawego zastrzyku zwykle uciekała do sojuszników i pociągała ich za sobą w zgubę.', '', 0),
(27077, 'plPL', 'Glut, plugawy pies zarazy z Naxxramas, miał podobno apetyt tak nienasycony, że nawet żywi nie wystarczali, by zaspokoić jego głód. Feugen karmił go ponoć codziennie armią zombie, przetwarzając szczątki nieumarłych zbyt słabych, by nadawali się do walki.', '', 0),
(27078, 'plPL', 'Thadius, zbudowany z ciał kobiet i dzieci. Mówi się, że ich dusze są stopione w jedność – na wieki uwięzione w tym plugawym więzieniu z ciała.', '', 0),
(27079, 'plPL', 'Szafiron. Niegdyś szlachetny błękitny smok z gór Północnej Grani, zabity przez Arthasa podczas jego kampanii na mroźnej północy. Wskrzeszony, by mu służyć, Szafiron wiecznie strzeże leża Kel\'Thuzada i czeka na tych, którzy ośmielą się naruszyć spokój jego pana.', '', 0),
(27080, 'plPL', 'Lisz Kel\'Thuzad. Bez wahania służy Królowi Liszowi. Za życia potężny nekromanta, po śmierci stał się mistrzem nekromancji. Mówi się, że jest najwierniejszym z poddanych Króla Lisza.', '', 0),
(27081, 'plPL', 'Kel\'Thuzad przetrwał próby, które dawno już złamałyby dusze nawet największych członków Bractwa. Z własnej woli oddał życie z ręki Arthasa, by później powrócić – odrodzony mocą Słonecznej Studni.', '', 0),
(27082, 'plPL', 'W Plagowiskach Kel\'Thuzad został ponownie pokonany przez agentów Argentowego Brzasku. Jego filakterium trafiło jednak do fałszywego agenta Bractwa. Wciąż nie wiemy, kto je ukradł ani dlaczego.', '', 0),
(27085, 'plPL', '', '%s przygląda się draenejskim szatom Modoru.', 0),
(27086, 'plPL', '', 'Psst. Naohainie. Czemu Modoru wciąż nosi te śmieszne szaty? Wygląda jak jakiś międzywymiarowy wieśniak, który ledwie sześć godzin temu wytoczył się z Doliny Ammen.', 0),
(27095, 'plPL', 'Dzięki za osłonę ogniową! Tam na dole jest istny DOM WARIATÓW!', 'Dzięki za osłonę ogniową! Tam na dole jest istny DOM WARIATÓW!', 0),
(27096, 'plPL', 'Rany, myślałem, że już po mnie! Dzięki, przyjacielu!', 'Rany, myślałem, że już po mnie! Dzięki, przyjacielu!', 0),
(27097, 'plPL', 'Prawie zostałem przynętą dla ghuli! Dzięki za ratunek!', 'Prawie zostałem przynętą dla ghuli! Dzięki za ratunek!', 0),
(27098, 'plPL', 'Dobrze, że tu jesteś, sojuszniku! Byliśmy już skończeni!', 'Dobrze, że tu jesteś, sojuszniku! Byliśmy już skończeni!', 0),
(27103, 'plPL', '', 'Nie możemy sobie pozwolić na przepuszczenie okazji, by zaskarbić sobie przychylność Czerwonego Stada. W obliczu czekających nas bitew taki sojusznik byłby bezcenny.', 0),
(27104, 'plPL', 'Przed laty czarnoksiężnik Nekros Miażdżyczaszka wykorzystał potężny artefakt, by zniewolić Alexstrazę i znaczną część Czerwonego Stada. Zuluhed i Nekros nie żyją, ale nasz dług wobec czerwonych smoków jest daleki od spłacenia.', '', 0),
(27107, 'plPL', 'Przymierze od pewnego czasu utrzymuje tę odległą chatę. Korzystali z niej nasi łowcy i drwale.$B$BAle skoro trwa wojna, możesz mi wierzyć, że teraz rządzi tu wojsko.', '', 0),
(27113, 'plPL', '<Komendant przerywa lekcję i odwraca się, oceniając cię wzrokiem.>$B$BPrzyda mi się ktoś taki jak ty, $N.', '', 0),
(27116, 'plPL', 'Dobrze cię znów widzieć, $n.$B$BChcesz odświeżyć wiedzę o taktyce Plagi?', '', 0),
(27120, 'plPL', 'Wypłoszę ją, $n! Ty tylko bądź $ggotów:gotowa;, kiedy nadleci!', 'Wypłoszę ją, $n! Ty tylko bądź $ggotów:gotowa;, kiedy nadleci!', 0),
(27122, 'plPL', 'Czekam na rozkazy!', '', 0),
(27123, 'plPL', 'OGNIA! OGNIA! ZESTRZELIĆ JĄ!', '', 0),
(27126, 'plPL', '„Lubimy drzewa, Fenricku. Dają osłonę”. I ścinać ich też mi nie pozwalają.', '', 0),
(27127, 'plPL', 'Czego się spodziewają, każąc nietoperzom podchodzić pod takim kątem? Skręconych karków i łykowatego gulaszu z nietoperza, ot co.', '', 0),
(27128, 'plPL', 'Ciekawe, ilu żołnierzy z posiłków musi odnieść rany, zanim pozwolą nam ściąć te idiotyczne drzewa. Kosztują nas majątek w nietoperzach. Może skombinuję uprząż albo dwie...', '', 0),
(27129, 'plPL', 'Dziś wieczorem znowu żołądki nietoperzy dla gnomów...', '', 0),
(27137, 'plPL', 'Przynęta na żmije, co? No to leć i ściągnij nam tu Lodową Burzę!', 'Przynęta na żmije, co? No to leć i ściągnij nam tu Lodową Burzę!', 0),
(27144, 'plPL', 'Wygląda jak brama do piekła!', 'Wygląda jak brama do piekła!', 0),
(27145, 'plPL', 'Jeśli nie wrócę do Zimowej Straży, powiedzcie mojej rodzinie, że dałem z siebie wszystko i że ich kocham...', 'Jeśli nie wrócę do Zimowej Straży, powiedzcie mojej rodzinie, że dałem z siebie wszystko i że ich kocham...', 0),
(27146, 'plPL', 'Czy to już koniec? Jeśli teraz powstrzymamy tego potwora, czy zwycięstwo pod Bramą Gniewu będzie pewne?', 'Czy to już koniec? Jeśli teraz powstrzymamy tego potwora, czy zwycięstwo pod Bramą Gniewu będzie pewne?', 0),
(27147, 'plPL', 'Zaczynam się trochę martwić. Gdzie ten bohater, który ma nas poprowadzić do bitwy?', 'Zaczynam się trochę martwić. Gdzie ten bohater, który ma nas poprowadzić do bitwy?', 0),
(27148, 'plPL', 'Niech wszyscy wiedzą, że walka u waszego boku była dla mnie zaszczytem i przywilejem.\n', 'Niech wszyscy wiedzą, że walka u waszego boku była dla mnie zaszczytem i przywilejem.\n', 0),
(27149, 'plPL', 'No dalej... Miejmy to już za sobą!\n', 'No dalej... Miejmy to już za sobą!\n', 0),
(27150, 'plPL', 'Śmierć w końcu przychodzi po każdego z nas, ale czasem przychodzi nieco szybciej, niż się spodziewamy. Dziś nazywamy to ślepym bohaterstwem... Jutro ktoś może nazwać to głupotą.\n', 'Śmierć w końcu przychodzi po każdego z nas, ale czasem przychodzi nieco szybciej, niż się spodziewamy. Dziś nazywamy to ślepym bohaterstwem... Jutro ktoś może nazwać to głupotą.\n', 0),
(27154, 'plPL', '', '$n, dobrze cię widzieć!$B$BA może to nasze pierwsze spotkanie?$B$BJestem teraz w tylu miejscach i czasach naraz, że czasem trudno mi się we wszystkim połapać.', 0),
(27155, 'plPL', 'Przygotujcie się, żołnierze. $n $gdostarczył:dostarczyła; nam ostatni element tej układanki. Straszliwy lisz Thel\'zan wkrótce wyjdzie z ukrycia, tylko po to, by okazać się wobec nas bezsilnym!', '', 0),
(27156, 'plPL', 'To właśnie to filakterium – filakterium Thel\'zana – jest kluczem do zwycięstwa!', '', 0),
(27158, 'plPL', 'LEGIONIE, TRZYMAĆ SZYK!', '', 0),
(27165, 'plPL', 'Zaraza, Zaraza, Zaraza... tylko o tym się tu słyszy. Tęsknię za różnorodnością!$b$bNo, no. Masz zwierzątka, tak? Oczywiście, że masz. Oczywiście. Małe zwierzątka. Mam dla nich miksturę. Zrobi z nich tru... eee, bystre i silne stworzenia, tak. Tak. Silne.$b$bSpróbuj!', '', 0),
(27166, 'plPL', 'Dobrze, wezmę tę twoją miksturę.', 'Dobrze, wezmę tę twoją miksturę.', 0),
(27167, 'plPL', 'Ostrożnie z nią. Jest niestabilna i szybko traci moc. Użyj jej prędko! I... najlepiej w zasięgu wzroku, tak...', '', 0),
(27178, 'plPL', 'To najwyższy lord!', 'To najwyższy lord!', 0),
(27196, 'plPL', 'Ściany Groty Ostrza Mrozu drżą i trzeszczą.', 'Ściany Groty Ostrza Mrozu drżą i trzeszczą.', 0),
(27289, 'plPL', 'Z tego tronu wydaję rozkazy Piekłorycza. Jego słowo jest życiem i jego słowo jest śmiercią.', '', 0),
(27352, 'plPL', 'Witaj w Świątyni Żmijowego Spoczynku. Wybacz zamieszanie na zewnątrz; po ostatnich poczynaniach Malygosa znaleźliśmy się w oblężeniu. Jeśli potrzebujesz, wciąż możesz tu odpocząć pod naszą ochroną.', '', 0),
(27354, 'plPL', 'Zabij ich, Abbendis! Nie zawiedź mnie!', '', 0),
(27355, 'plPL', 'Wielki admirał przez chwilę przygląda ci się spod przymrużonych powiek.', '', 0),
(27357, 'plPL', 'Twoja rola dobiegła końca.', '', 0),
(27358, 'plPL', 'Do zobaczenia w Lodowej Koronie, słabeuszu... jeśli pożyjesz tak długo!', '', 0),
(27373, 'plPL', 'Niezły strzał, młody.', '', 0),
(27374, 'plPL', 'Kolejny błękitny strącony. Świetna z nas drużyna!', '', 0),
(27375, 'plPL', 'Razem szybko zakończymy tę bitwę.', '', 0),
(27376, 'plPL', 'Kto by pomyślał, że polecę do bitwy z kimś z twojej rasy na grzbiecie.', '', 0),
(27377, 'plPL', 'Dobrze, że $gzauważyłeś:zauważyłaś; tamtego!', '', 0),
(27378, 'plPL', 'Trzymaj się. Przetrwamy to.', '', 0),
(27379, 'plPL', 'Czegoś takiego jeszcze tu nie było. Dobrze, że jesteś z nami.', '', 0),
(27380, 'plPL', 'Malygos najwyraźniej oszalał.', '', 0),
(27571, 'plPL', 'Jeden z kultystów chyba nadział się na moje ostrze i zginął... mogę dostać nowe przebranie? Obiecuję, że tym razem będę $gostrożniejszy:ostrożniejsza;.', 'Jeden z kultystów chyba nadział się na moje ostrze i zginął... mogę dostać nowe przebranie? Obiecuję, że tym razem będę $gostrożniejszy:ostrożniejsza;.', 0),
(27583, 'plPL', 'O co chodzi? Nie widzisz, że mam robotę?', '', 0),
(27593, 'plPL', '', 'Teraz pokażę wam PRAWDZIWĄ potęgę Szturmu!', 0),
(27596, 'plPL', '', '$gPrzyszedłeś:Przyszłaś; wystawić na próbę potęgę Szturmu?', 0),
(27597, 'plPL', '', 'Szybko zajmijcie się tym najściem. Nie mam na to czasu!', 0),
(27598, 'plPL', '', 'Lepiej przemyśl swoje postępowanie, głupcze.', 0),
(27599, 'plPL', '', 'Czy sama będę musiała zająć się tym najściem?', 0),
(28122, 'plPL', 'Wystawiasz moją cierpliwość na próbę – teraz ujrzysz prawdziwą potęgę Błękitnych.', '', 0),
(28878, 'plPL', 'Muszę się uleczyć!', '', 0),
(28879, 'plPL', 'Powinniśmy się stąd wycofać. Muszę się odnowić!', '', 0),
(28880, 'plPL', 'Chyba czas rzucić Odnowienie!', '', 0),
(29188, 'plPL', 'Chyba $gzapodziałem:zapodziałam; twoje urządzenie sterujące rozdrabniaczem... masz może drugie?', 'Chyba $gzapodziałem:zapodziałam; twoje urządzenie sterujące rozdrabniaczem... masz może drugie?', 0),
(29544, 'plPL', 'Ja... ja nie wiem.', '', 0),
(29546, 'plPL', '', 'Powiedz no, Modoru. Skąd masz te... ach... „cudowne” szaty, hmm?', 0),
(29547, 'plPL', '', 'Och. Och... rozumiem. Jak miło!', 0),
(29548, 'plPL', '', '%s z trudem powstrzymuje śmiech.', 0),
(29550, 'plPL', '%s rozpromienia się, nieświadomy, że ona sobie z niego żartuje, i odpowiada we wspólnym z silnym akcentem.', '', 0),
(29552, 'plPL', 'Ach! Widzieć, to prezent od babci Oluby. Ona tkać ręcznie z najlepszy jedwab na Draenorze! Ja bardzo dumny, tak.', '', 0),
(29553, 'plPL', '%s chichocze, wtulając się w kostki strażniczki Słodkie Źródło.', '', 0),
(29555, 'plPL', '', '%s uśmiecha się szeroko do strażniczki Bursztynowej Nici po drugiej stronie obozu, znacząco poruszając długimi brwiami.', 0),
(29557, 'plPL', '', '%s prycha z irytacją, rzuca strażniczce Słodkie Źródło krótkie, gniewne spojrzenie i odwraca się z zadartym nosem.', 0),
(29866, 'plPL', '', 'Uważaj.$b$bTu toczy się walka na śmierć i życie!', 0),
(29960, 'plPL', 'Mogę lecieć. Brońmy świątyni!', '', 0),
(29961, 'plPL', 'Nie mogę uwierzyć, że błękitni nas zaatakowali. Odpłaćmy im pięknym za nadobne!', '', 0),
(29962, 'plPL', 'Dokąd najpierw?', '', 0),
(29963, 'plPL', 'Twoja reputacja cię wyprzedza, $n. To będzie ciekawe.', '', 0),
(29964, 'plPL', 'Najpierw zdestabilizujemy świątynię czy unieszkodliwimy wroga?', '', 0),
(29965, 'plPL', 'Spodziewaliśmy się ciebie, $n. Teraz mamy przewagę.', '', 0),
(29966, 'plPL', 'Jesteś $ggotów:gotowa; do bitwy, $N?', '', 0),
(30163, 'plPL', 'Straż, na pomoc!', '', 0),
(30594, 'plPL', '', 'Witaj wśród nas, $N.', 0),
(31278, 'plPL', 'Gdzie jest Nestor Morthie?', 'Gdzie jest Nestor Morthie?', 0),
(31279, 'plPL', 'Udaj się do Spoczynku Gwiazd na Smoczych Pustkowiach, a znajdziesz tam Nestora Morthiego.', 'Udaj się do Spoczynku Gwiazd na Smoczych Pustkowiach, a znajdziesz tam Nestora Morthiego.', 0),
(31280, 'plPL', 'Gdzie jest Nestor Thoim?', 'Gdzie jest Nestor Thoim?', 0),
(31281, 'plPL', 'Nestor Thoim od wielu lat przebywa w Porcie Moa\'ki na Smoczych Pustkowiach.', 'Nestor Thoim od wielu lat przebywa w Porcie Moa\'ki na Smoczych Pustkowiach.', 0),
(31282, 'plPL', 'Gdzie jest Nestor Strażnik Nieba?', 'Gdzie jest Nestor Strażnik Nieba?', 0),
(31283, 'plPL', 'Nestor Strażnik Nieba przebywa niedaleko Młota Agmara na Smoczych Pustkowiach.', 'Nestor Strażnik Nieba przebywa niedaleko Młota Agmara na Smoczych Pustkowiach.', 0),
(31284, 'plPL', 'Gdzie jest Nestor Nurgen?', 'Gdzie jest Nestor Nurgen?', 0),
(31285, 'plPL', 'Z tego, co mi ostatnio było wiadomo, Nestor Nurgen przebywa w Azjol-Nerub.', 'Z tego, co mi ostatnio było wiadomo, Nestor Nurgen przebywa w Azjol-Nerub.', 0),
(31286, 'plPL', 'Gdzie jest Nestor Whurain?', 'Gdzie jest Nestor Whurain?', 0),
(31287, 'plPL', 'Nestora Whuraina znajdziesz w Obozie Oneqwah we Wzgórzach Grizli.', 'Nestora Whuraina znajdziesz w Obozie Oneqwah we Wzgórzach Grizli.', 0),
(32038, 'plPL', 'Moja królowo, czy oni wiedzą?', '', 0),
(32047, 'plPL', 'Nie dowiedzą się.', '', 0),
(32523, 'plPL', 'Witaj w siedzibie Kirin Toru.', '', 0),
(32596, 'plPL', 'Shgla\'yos plahf mh\'naus.', '', 0),
(32597, 'plPL', 'Ci, którzy żywią się zagubionymi duszami, znają tylko głód.', '', 0),
(32598, 'plPL', 'Ywaq ma phgwa\'cul hnakf.', '', 0),
(32599, 'plPL', 'Uulwi gag erh\'ongg w\'ssh.', '', 0),
(32600, 'plPL', 'Ywaq puul skshgn: on\'ma yeh\'glu zuq.', '', 0),
(32601, 'plPL', 'Iilth vwah, uhn\'agth fhssh za.', '', 0),
(32602, 'plPL', 'Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg\'fhn.', '', 0),
(32603, 'plPL', 'Gul\'kafh an\'shel. Yoq\'al shn ky ywaq nuul.', '', 0),
(32604, 'plPL', 'Spójrz w pustkę. To wieczność, w której oni trwają.', '', 0),
(32605, 'plPL', 'Są szeptem na drżącym wietrze.', '', 0),
(32606, 'plPL', 'Ich cień będzie dusił tę ziemię po wieczność.', '', 0),
(32607, 'plPL', 'Piją twój strach: to krew życia.', '', 0),
(32608, 'plPL', 'Gdzie jeden upadnie, wielu zajmie jego miejsce.', '', 0),
(32609, 'plPL', 'Nie umierają; nie żyją. Są poza cyklem.', '', 0),
(32820, 'plPL', '', 'Witaj, przyjacielu. Zaszczycasz mnie swoją obecnością.$B$BJak mogę ci pomóc?', 0),
(32832, 'plPL', 'O wielka Królowo smoków, jakimś sposobem $gzapodziałem:zapodziałam; swój klucz do Skupiającej Tęczówki. Czy możesz go dla mnie odnaleźć?', 'O wielka Królowo smoków, jakimś sposobem $gzapodziałem:zapodziałam; swój klucz do Skupiającej Tęczówki. Czy możesz go dla mnie odnaleźć?', 0),
(32836, 'plPL', 'O wielka Królowo smoków, jakimś sposobem $gzapodziałem:zapodziałam; swój heroiczny klucz do Skupiającej Tęczówki. Czy możesz go dla mnie odnaleźć?', 'O wielka Królowo smoków, jakimś sposobem $gzapodziałem:zapodziałam; swój heroiczny klucz do Skupiającej Tęczówki. Czy możesz go dla mnie odnaleźć?', 0),
(32915, 'plPL', '<Małżonek królowej kiwa głową na znak, że cię zauważył.>', '', 0),
(33005, 'plPL', 'Czyż to nie piękne? Widzisz ten potencjalny zysk?', '', 0),
(33083, 'plPL', 'Miej się na baczności.$b$bTo nie miejsce dla lękliwych.', '', 0),
(33982, 'plPL', 'Otrzymaliśmy wiadomość od Branna i rozpoczęliśmy przygotowania.', '', 0),
(33983, 'plPL', 'Obywatele Dalaranu! Wznieście oczy ku niebu i patrzcie!', '', 0),
(33984, 'plPL', 'Dziś zniszczenie naszego świata zostało powstrzymane wbrew woli samych naszych stwórców!', '', 0),
(33985, 'plPL', 'Algalon Obserwator, herold tytanów, został pokonany przez naszych dzielnych towarzyszy w głębinach Ulduaru, miasta tytanów.', '', 0),
(33986, 'plPL', 'Algalon został tu przysłany, by osądzić los naszego świata.', '', 0),
(33987, 'plPL', 'Znalazł planetę, której rasy odeszły od projektów tytanów. Planetę, na której nie wszystko poszło zgodnie z planem.', '', 0),
(33988, 'plPL', 'Zimna logika uznała, że nasz świat nie jest wart ocalenia. Zimna logika nie bierze jednak pod uwagę siły wolnej woli. Od każdego z nas zależy, czy udowodnimy, że ten świat jest wart ocalenia.', '', 0),
(33989, 'plPL', 'Że nasze życie... że nasze życie jest warte przeżycia.', '', 0),
(34621, 'plPL', 'Ale ci się dostało!', '', 0),
(34624, 'plPL', 'Lepiej uważaj!', '', 0),
(34635, 'plPL', '', 'Gdybym przybrała smoczą postać, nie byłoby tu miejsca dla nikogo innego, maleństwo.', 0),
(34665, 'plPL', 'Zapewniam cię, Kekeku, ona jest królową smoków. Często przybieramy postać mniejszych istot, gdy z nimi współpracujemy.', '', 0),
(35492, 'plPL', 'My zapamiętać tę wizytę, tak, tak. Nigdy nie zapomnieć, czego nauczyć cię nowy przyjaciel, mały Roo. Przed tobą wielka przyszłość.', '', 0),
(35493, 'plPL', 'Nie martwić się, Kekek. Ty dorosnąć, być silny dla Szalonego Serca. Ty poprowadzić lud z powrotem do starego domu, gdzie nie być dzieciaków wielkojęzorów.', '', 0),
(36637, 'plPL', 'Co wiesz o dawnych mieczach?', 'Co wiesz o dawnych mieczach?', 0),
(37769, 'plPL', '$gSpóźniłeś:Spóźniłaś; się, $n. Inny gość z Dalaranu pytał już o te same pryzmatyczne smocze ostrza.', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(37770, 'plPL', 'Z twojego opisu wnioskuję, że księga, którą pożyczyłem naszemu gościowi, pozwoliłaby ci łatwo rozpoznać tę broń.', '', 0),
(37772, 'plPL', 'Obawiam się, że będziesz $gmusiał:musiała; zapytać... Cóż, może Kalegos zdoła pomóc.', '', 0),
(37773, 'plPL', '$n chyba $gznalazł:znalazła; szczątki pryzmatycznego ostrza, Kalegosie. Czy zaoferujesz pomoc naszemu gościowi?', '', 0),
(37774, 'plPL', 'Czy na pewno powinieneś pomagać tym śmiertelnikom w poszukiwaniu miecza?', '', 0),
(37775, 'plPL', 'Te ostrza, Krasusie... Wykonano je dawno temu, gdy wszystko było... inne.', '', 0),
(37778, 'plPL', 'Uważasz, że nasi sojusznicy nie zdołają zapanować nad mocą tych mieczy?', '', 0),
(37781, 'plPL', '', 'Śmiertelni bohaterowie od dawna używali tej broni do walki ze złem. Nie widzę powodu, by odmawiać im mieczy w tej bitwie.', 0),
(37782, 'plPL', 'Nasi wrogowie już raz obrócili naszą najpotężniejszą broń przeciwko nam. Czemu sądzisz, że z pryzmatycznymi ostrzami będzie inaczej?', '', 0),
(37783, 'plPL', 'Jak sobie życzysz, moja królowo. Nie będę stał im na drodze, ale będę ich uważnie obserwował.', '', 0),
(37785, 'plPL', 'Jak my wszyscy.', '', 0),
(37873, 'plPL', 'Proszę, śmiertelniku, porozmawiaj z arkanistą Tybalinem w Dalaranie. Może zdoła wynegocjować ze Słońcobójcami dostęp do księgi.', '', 0),
(37874, 'plPL', 'Proszę, śmiertelniku, odszukaj magistra Hathorela w Dalaranie. Może zdoła wynegocjować ze Srebrnym Sojuszem dostęp do księgi.', '', 0),
(38509, 'plPL', 'Witaj. Wyczuwam pewną konsternację z powodu mojej obecności tutaj. Inni także żywią podejrzenia i trudno ich winić po tym, co zgotowali im moi pobratymcy.$B$BOd wydarzeń przy Słonecznej Studni wiele się wydarzyło, a mało co dobrego. I tak na mnie spada pozbieranie tego, co zostało, i próba ocalenia dumy mojego stada. Wiele jest do powiedzenia i jeszcze więcej do zrobienia, ale wiedz jedno: nie wszyscy w Błękitnym Stadzie obwiniają śmiertelne rasy Azeroth za nieszczęścia, które spadły na świat.$B$BNiektórzy z nas mają więcej rozumu.', '', 0),
(39548, 'plPL', 'Nie.', 'Nie.', 0),
(39942, 'plPL', 'Wścibskie owady! Za późno. Rubinowe Sanktuarium jest stracone!', '', 0),
(40064, 'plPL', 'Wasz świat chwieje się na krawędzi zagłady. WSZYSCY będziecie świadkami nadejścia nowej ery ZNISZCZENIA!', '', 0),
(40065, 'plPL', 'Delektujcie się tym zwycięstwem, śmiertelnicy, bo będzie waszym ostatnim. Ten świat spłonie, gdy powróci mój pan!', '', 0),
(40066, 'plPL', 'Kolejny „bohater” pada.', '', 0),
(40067, 'plPL', 'W królestwie zmierzchu znajdziecie tylko cierpienie! Wejdźcie, jeśli się odważycie!', '', 0),
(40068, 'plPL', 'Niebiosa płoną!', '', 0),
(40079, 'plPL', 'Dzięki wysiłkom twoich towarzyszy %s zostaje zepchnięty głębiej w świat materialny!', '', 0),
(40228, 'plPL', 'Dzięki twoim wysiłkom %s zostaje zepchnięty dalej poza świat materialny!', '', 0),
(40476, 'plPL', 'Bez nacisku w obu światach %s zaczyna się regenerować.', '', 0),
(40598, 'plPL', '', 'Pomocy! Jestem uwięziona w tym drzewie! Potrzebuję pomocy!', 0),
(40599, 'plPL', '', 'Dziękuję! Dłużej bym nie wytrzymała... Stało się tu coś strasznego.', 0),
(40600, 'plPL', '', 'Sądziliśmy, że Sanktuarium jest dobrze umocnione, ale nie byliśmy przygotowani na taki atak.', 0),
(40601, 'plPL', '', 'Czarni drakanie zmaterializowali się znikąd i rzucili się na nas, zanim zdążyliśmy zareagować.', 0),
(40602, 'plPL', '', 'Nie mieliśmy szans. Gdy moi pobratymcy ginęli wokół mnie, zdołałam wycofać się tutaj i zablokować wejście.', 0),
(40603, 'plPL', '', 'Wyrzynali nas z zimną skutecznością, ale tak naprawdę interesowały ich chyba jaja przechowywane tu, w Sanktuarium.', 0),
(40604, 'plPL', '', 'Siłami na ziemi dowodzi okrutny brutal imieniem Zarithrian, ale obawiam się, że działają tu potężniejsze moce.', 0),
(40605, 'plPL', '', 'Podczas pierwszego ataku dostrzegłam ich prawdziwego przywódcę – przerażającego, dorosłego smoka zmierzchu.', 0),
(40606, 'plPL', '', 'Nie znam wszystkich ich planów, bohaterowie, ale wiem jedno: nie można pozwolić, by im się udało!', 0),
(41619, 'plPL', 'Nie dość dobrze...', '', 0),
(53162, 'plPL', 'Hej, tutaj!', '', 0);
